package taproom

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const stamp = "2006-01-02 15:04 UTC"

// Render serves the board in gnoweb.
//
//	""                 the board
//	"quest/<id>"       one quest with its submissions
//	"hunter/<address>" a reputation card
//	"about"            how it works
//	"json"             the latest quests as JSON, for the web front end
func Render(path string) string {
	switch {
	case path == "":
		return renderBoard()
	case path == "json":
		return renderJSON()
	case path == "about":
		return renderAbout()
	case strings.HasPrefix(path, "quest/"):
		id, err := strconv.Atoi(strings.TrimPrefix(path, "quest/"))
		if err != nil || id < 1 || id > nextID {
			return "# Not found\n\nThere is no such quest. [Back to the board](" + self() + ")\n"
		}
		return renderQuest(mustQuest(id))
	case strings.HasPrefix(path, "hunter/"):
		a := address(strings.TrimPrefix(path, "hunter/"))
		if !a.IsValid() {
			return "# Not found\n\nThat is not a valid address. [Back to the board](" + self() + ")\n"
		}
		return renderPerson(a)
	}
	return "# Not found\n\n[Back to the board](" + self() + ")\n"
}

func self() string { return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land") }

func renderBoard() string {
	var b strings.Builder
	b.WriteString("# Taproom\n\n")
	b.WriteString("*An escrowed bounty board. Pin a quest, lock the reward, pay the best answer.*\n\n")

	open := 0
	quests.Iterate("", "", func(_ string, v any) bool {
		if v.(*quest).status == StatusOpen {
			open++
		}
		return false
	})
	b.WriteString("| Open quests | Locked in escrow | Paid to hunters | Quests pinned |\n")
	b.WriteString("| --- | --- | --- | --- |\n")
	b.WriteString("| " + strconv.Itoa(open) + " | " + gnot(totalEscrow) + " | " + gnot(totalPaid) + " | " + strconv.Itoa(nextID) + " |\n\n")

	b.WriteString("## Open quests\n\n")
	if open == 0 {
		b.WriteString("The board is empty. [Pin the first quest](" + self() + "$help&func=PostQuest).\n\n")
	} else {
		b.WriteString("| Quest | Reward | Closes | Answers |\n| --- | --- | --- | --- |\n")
		shown := 0
		quests.ReverseIterate("", "", func(_ string, v any) bool {
			q := v.(*quest)
			if q.status != StatusOpen {
				return false
			}
			b.WriteString("| [" + esc(q.title) + "](" + self() + ":quest/" + strconv.Itoa(q.id) + ") | " +
				gnot(q.reward) + " | " + q.deadline.UTC().Format(stamp) + " | " + strconv.Itoa(len(q.subs)) + " |\n")
			shown++
			return shown >= 25
		})
		b.WriteString("\n")
	}

	// recently settled
	settled := 0
	quests.Iterate("", "", func(_ string, v any) bool {
		if v.(*quest).status != StatusOpen {
			settled++
		}
		return false
	})
	if settled > 0 {
		b.WriteString("## Recently settled\n\n| Quest | Reward | Result |\n| --- | --- | --- |\n")
		shown := 0
		quests.ReverseIterate("", "", func(_ string, v any) bool {
			q := v.(*quest)
			if q.status == StatusOpen {
				return false
			}
			result := "reclaimed by poster"
			if q.status == StatusAwarded {
				result = "won by [" + short(q.winner) + "](" + self() + ":hunter/" + q.winner.String() + ")"
			}
			b.WriteString("| [" + esc(q.title) + "](" + self() + ":quest/" + strconv.Itoa(q.id) + ") | " + gnot(q.reward) + " | " + result + " |\n")
			shown++
			return shown >= 10
		})
		b.WriteString("\n")
	}

	b.WriteString("---\n\n[How it works](" + self() + ":about) · [Pin a quest](" + self() + "$help&func=PostQuest)\n")
	return b.String()
}

func renderQuest(q *quest) string {
	var b strings.Builder
	id := strconv.Itoa(q.id)
	b.WriteString("# " + esc(q.title) + "\n\n")
	b.WriteString("| Reward | Status | Closes | Posted by |\n| --- | --- | --- | --- |\n")
	b.WriteString("| **" + gnot(q.reward) + "** | " + q.status.String() + " | " + q.deadline.UTC().Format(stamp) +
		" | [" + short(q.poster) + "](" + self() + ":hunter/" + q.poster.String() + ") |\n\n")
	b.WriteString("> " + esc(q.details) + "\n\n")

	switch q.status {
	case StatusOpen:
		b.WriteString("[Submit an answer](" + self() + "$help&func=Submit&id=" + id + ")")
		b.WriteString(" · [Award (poster)](" + self() + "$help&func=Award&id=" + id + ")")
		b.WriteString(" · [Reclaim (poster)](" + self() + "$help&func=Reclaim&id=" + id + ")\n\n")
	case StatusAwarded:
		b.WriteString("**Winner:** [" + short(q.winner) + "](" + self() + ":hunter/" + q.winner.String() + ")\n\n")
	case StatusReclaimed:
		b.WriteString("The poster reclaimed the escrow.\n\n")
	}

	b.WriteString("## Answers (" + strconv.Itoa(len(q.subs)) + ")\n\n")
	if len(q.subs) == 0 {
		b.WriteString("No answers yet.\n\n")
	}
	for i, s := range q.subs {
		b.WriteString(strconv.Itoa(i+1) + ". [" + short(s.hunter) + "](" + self() + ":hunter/" + s.hunter.String() + ") · " +
			s.at.UTC().Format(stamp) + "\n   > " + esc(s.note))
		if s.link != "" {
			b.WriteString("\n   > <" + s.link + ">")
		}
		b.WriteString("\n")
	}
	b.WriteString("\n[Back to the board](" + self() + ")\n")
	return b.String()
}

func renderPerson(a address) string {
	var b strings.Builder
	b.WriteString("# " + short(a) + "\n\n`" + a.String() + "`\n\n")
	v := people.Get(a.String())
	if v == nil {
		b.WriteString("This address has not touched the board yet.\n\n[Back to the board](" + self() + ")\n")
		return b.String()
	}
	s := v.(*stats)
	b.WriteString("| Quests pinned | Paid as poster | Answers sent | Quests won | Earned as hunter |\n| --- | --- | --- | --- | --- |\n")
	b.WriteString("| " + strconv.Itoa(s.posted) + " | " + gnot(s.paidOut) + " | " + strconv.Itoa(s.submitted) +
		" | " + strconv.Itoa(s.won) + " | " + gnot(s.earned) + " |\n\n[Back to the board](" + self() + ")\n")
	return b.String()
}

func renderAbout() string {
	return `# How Taproom works

1. **Pin.** A poster calls ` + "`PostQuest`" + ` with a title, details, a window in days and at least 1 GNOT attached. The reward is locked in the realm.
2. **Answer.** Each hunter sends one answer with a note and an optional https link, until the window closes.
3. **Award.** The poster picks a winner. The escrow is paid in the same transaction.
4. **Reclaim.** With no answers the poster can withdraw any time. Once answers exist, the poster must wait for the window plus a 7-day review period, so a silent poster cannot starve hunters who delivered.

Only ugnot is accepted, only from a direct user call, and every payout is checked against the realm balance.

[Back to the board](` + self() + `)
`
}

// short renders an address as g1abcd…wxyz.
func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// esc neutralises user text so it cannot inject markdown, HTML or table breaks.
func esc(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '\n', '\r', '\t':
			b.WriteRune(' ')
		case '\\', '`', '*', '_', '[', ']', '<', '>', '|', '#', '!', '(', ')', '~', '&':
			b.WriteRune('\\')
			b.WriteRune(r)
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

const jsonLimit = 50

// renderJSON returns the newest quests (with their answers) as one JSON
// document. Times are unix seconds, amounts are ugnot, ids are numbers.
func renderJSON() string {
	var b strings.Builder
	b.WriteString(`{"realm":` + jstr(unsafe.CurrentRealm().PkgPath()))
	b.WriteString(`,"now":` + strconv.FormatInt(time.Now().Unix(), 10))
	b.WriteString(`,"count":` + strconv.Itoa(nextID))
	b.WriteString(`,"escrow":` + strconv.FormatInt(totalEscrow, 10))
	b.WriteString(`,"paid":` + strconv.FormatInt(totalPaid, 10))
	b.WriteString(`,"minReward":` + strconv.FormatInt(MinReward, 10))
	b.WriteString(`,"quests":[`)
	n := 0
	quests.ReverseIterate("", "", func(_ string, v any) bool {
		q := v.(*quest)
		if n > 0 {
			b.WriteString(",")
		}
		n++
		b.WriteString(`{"id":` + strconv.Itoa(q.id))
		b.WriteString(`,"poster":` + jstr(q.poster.String()))
		b.WriteString(`,"title":` + jstr(q.title))
		b.WriteString(`,"details":` + jstr(q.details))
		b.WriteString(`,"reward":` + strconv.FormatInt(q.reward, 10))
		b.WriteString(`,"created":` + strconv.FormatInt(q.created.Unix(), 10))
		b.WriteString(`,"deadline":` + strconv.FormatInt(q.deadline.Unix(), 10))
		b.WriteString(`,"status":` + jstr(q.status.String()))
		b.WriteString(`,"winner":` + jstr(q.winner.String()))
		b.WriteString(`,"answers":[`)
		for i, s := range q.subs {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(`{"hunter":` + jstr(s.hunter.String()) + `,"note":` + jstr(s.note) +
				`,"link":` + jstr(s.link) + `,"at":` + strconv.FormatInt(s.at.Unix(), 10) + `}`)
		}
		b.WriteString("]}")
		return n >= jsonLimit
	})
	b.WriteString("]}")
	return b.String()
}

// jstr quotes s as a JSON string.
func jstr(s string) string {
	const hex = "0123456789abcdef"
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte(hex[c>>4])
			b.WriteByte(hex[c&15])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// Package taproom is an escrowed bounty board ("quest board") for Gno.land.
//
// Anyone can pin a quest to the board and lock a GNOT reward in the realm.
// Hunters answer with one submission each. The poster picks a winner and the
// escrow is paid out in the same transaction. If nobody delivers, the poster
// gets the reward back, but only after the review window has closed, so
// hunters who did deliver cannot be starved by a poster who simply goes quiet.
//
// Design rules (each one is covered by a test in taproom_test.gno):
//
//   - Funds are only accepted from a direct user call (maketx call), because
//     OriginSend() only describes a real receipt for a pure EOA caller.
//   - Exactly one coin (ugnot) of at least MinReward is accepted per quest, so
//     nothing can be stranded in the realm.
//   - State is updated before coins move (checks, effects, interactions).
//   - totalEscrow tracks every ugnot the realm owes and is asserted against the
//     realm balance before each payout.
//   - Nothing mutable is ever returned by pointer from the public API.
package taproom

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	denom = "ugnot"

	// MinReward is 1 GNOT, expressed in ugnot.
	MinReward int64 = 1_000_000

	MaxDays        = 60
	MaxSubmissions = 100
	ReviewGrace    = 7 * 24 * time.Hour

	maxTitle   = 80
	maxDetails = 600
	maxNote    = 400
	maxLink    = 200
)

type Status int

const (
	StatusOpen Status = iota
	StatusAwarded
	StatusReclaimed
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusAwarded:
		return "awarded"
	case StatusReclaimed:
		return "reclaimed"
	}
	return "unknown"
}

type submission struct {
	hunter address
	note   string
	link   string
	at     time.Time
}

type quest struct {
	id       int
	poster   address
	title    string
	details  string
	reward   int64
	created  time.Time
	deadline time.Time
	status   Status
	winner   address
	subs     []submission
}

// stats is a per-address reputation record.
type stats struct {
	posted    int   // quests pinned
	paidOut   int64 // ugnot paid to hunters by this address as a poster
	submitted int   // submissions made
	won       int   // quests won
	earned    int64 // ugnot earned as a hunter
}

var (
	quests      avl.Tree // seqKey(id) -> *quest
	people      avl.Tree // address string -> *stats
	nextID      int
	totalEscrow int64 // ugnot currently locked in open quests
	totalPaid   int64 // ugnot ever paid out to winners
)

// PostQuest pins a new quest and locks the attached ugnot as its reward.
// Call it with -send "<amount>ugnot". days is how long hunters have to submit.
func PostQuest(cur realm, title, details string, days int) int {
	require(cur.Previous().IsUserCall(), "only a direct user call (maketx call) can fund a quest")

	title = strings.TrimSpace(title)
	details = strings.TrimSpace(details)
	require(len(title) > 0 && len(title) <= maxTitle, "title must be 1-"+strconv.Itoa(maxTitle)+" bytes")
	require(len(details) > 0 && len(details) <= maxDetails, "details must be 1-"+strconv.Itoa(maxDetails)+" bytes")
	require(days >= 1 && days <= MaxDays, "days must be between 1 and "+strconv.Itoa(MaxDays))

	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == denom, "send exactly one coin type: ugnot")
	reward := sent[0].Amount
	require(reward >= MinReward, "reward must be at least "+gnot(MinReward))

	poster := cur.Previous().Address()
	now := time.Now()
	nextID++
	q := &quest{
		id:       nextID,
		poster:   poster,
		title:    title,
		details:  details,
		reward:   reward,
		created:  now,
		deadline: now.Add(time.Duration(days) * 24 * time.Hour),
		status:   StatusOpen,
	}
	quests.Set(seqKey(q.id), q)
	totalEscrow += reward
	statsOf(poster).posted++

	chain.Emit("QuestPosted",
		"id", strconv.Itoa(q.id),
		"poster", poster.String(),
		"reward", strconv.FormatInt(reward, 10),
	)
	return q.id
}

// Submit answers an open quest. One submission per address; the poster cannot
// answer their own quest. link is optional and must be an https URL.
func Submit(cur realm, id int, note, link string) {
	q := mustQuest(id)
	hunter := cur.Previous().Address()

	require(q.status == StatusOpen, "quest is not open")
	require(!time.Now().After(q.deadline), "submission window has closed")
	require(hunter != q.poster, "poster cannot answer their own quest")
	require(q.indexOf(hunter) < 0, "you already submitted to this quest")
	require(len(q.subs) < MaxSubmissions, "this quest is full")

	note = strings.TrimSpace(note)
	link = strings.TrimSpace(link)
	require(len(note) > 0 && len(note) <= maxNote, "note must be 1-"+strconv.Itoa(maxNote)+" bytes")
	require(len(link) <= maxLink, "link too long")
	require(link == "" || safeLink(link), "link must be a plain https:// URL")

	q.subs = append(q.subs, submission{hunter: hunter, note: note, link: link, at: time.Now()})
	statsOf(hunter).submitted++

	chain.Emit("Submitted", "id", strconv.Itoa(id), "hunter", hunter.String())
}

// Award picks the winner of a quest and pays the escrow out immediately.
// Only the poster can call it, and only for an address that submitted.
func Award(cur realm, id int, hunter address) {
	q := mustQuest(id)
	caller := cur.Previous().Address()

	require(caller == q.poster, "only the poster can award this quest")
	require(q.status == StatusOpen, "quest is not open")
	require(q.indexOf(hunter) >= 0, "that address has not submitted")

	// effects
	reward := q.reward
	q.status = StatusAwarded
	q.winner = hunter
	totalEscrow -= reward
	totalPaid += reward
	ps := statsOf(q.poster)
	ps.paidOut += reward
	hs := statsOf(hunter)
	hs.won++
	hs.earned += reward

	// interaction
	pay(cur, hunter, reward)

	chain.Emit("Awarded",
		"id", strconv.Itoa(id),
		"winner", hunter.String(),
		"reward", strconv.FormatInt(reward, 10),
	)
}

// Reclaim returns the escrow to the poster.
// With no submissions the poster may withdraw at any time. Once hunters have
// delivered, the poster must wait for the deadline plus the review window.
func Reclaim(cur realm, id int) {
	q := mustQuest(id)
	caller := cur.Previous().Address()

	require(caller == q.poster, "only the poster can reclaim this quest")
	require(q.status == StatusOpen, "quest is not open")
	if len(q.subs) > 0 {
		require(time.Now().After(q.deadline.Add(ReviewGrace)),
			"hunters have submitted: wait until the review window ends")
	}

	reward := q.reward
	q.status = StatusReclaimed
	totalEscrow -= reward

	pay(cur, q.poster, reward)

	chain.Emit("Reclaimed", "id", strconv.Itoa(id), "reward", strconv.FormatInt(reward, 10))
}

// ---- read-only helpers (values only, never pointers) ----

// Count returns the number of quests ever pinned.
func Count() int { return nextID }

// TotalEscrow returns the ugnot currently locked in open quests.
func TotalEscrow() int64 { return totalEscrow }

// TotalPaid returns the ugnot ever paid out to winners.
func TotalPaid() int64 { return totalPaid }

// StatusOf returns the status string of a quest, or panics if it does not exist.
func StatusOf(id int) string { return mustQuest(id).status.String() }

// SubmissionCount returns how many hunters answered a quest.
func SubmissionCount(id int) int { return len(mustQuest(id).subs) }

// ---- internals ----

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

func seqKey(id int) string {
	// zero-padded so the AVL tree iterates in numeric order
	s := strconv.Itoa(id)
	return strings.Repeat("0", 10-len(s)) + s
}

func mustQuest(id int) *quest {
	v := quests.Get(seqKey(id))
	require(v != nil, "no such quest: "+strconv.Itoa(id))
	return v.(*quest)
}

func (q *quest) indexOf(a address) int {
	for i := range q.subs {
		if q.subs[i].hunter == a {
			return i
		}
	}
	return -1
}

func statsOf(a address) *stats {
	if v := people.Get(a.String()); v != nil {
		return v.(*stats)
	}
	s := &stats{}
	people.Set(a.String(), s)
	return s
}

// pay sends ugnot from the realm's own balance, after checking the realm can
// cover everything it owes.
func pay(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()
	// totalEscrow was already reduced for this payout, so add it back.
	require(b.GetCoin(self, denom) >= totalEscrow+amount, "escrow invariant violated")
	b.SendCoins(self, to, chain.NewCoins(chain.NewCoin(denom, amount)))
}

// safeLink accepts only plain https URLs that cannot break out of markdown.
func safeLink(s string) bool {
	if !strings.HasPrefix(s, "https://") || len(s) <= len("https://") {
		return false
	}
	for _, r := range s {
		if r <= ' ' || r >= 0x7f {
			return false
		}
		switch r {
		case '(', ')', '[', ']', '<', '>', '"', '\'', '`', '\\', '*', '|':
			return false
		}
	}
	return true
}

// gnot formats ugnot as a human-readable GNOT amount.
func gnot(u int64) string {
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		f = strings.Repeat("0", 6-len(f)) + f
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	return s + " GNOT"
}

package signals

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

func unitNormalizeInto(dst, vec []int64) error {
	if len(vec) == 0 {
		return errors.New("vector cannot be empty")
	}
	if len(dst) != len(vec) {
		return errors.New("destination vector dimension mismatch")
	}
	// Downscale if max abs coordinate exceeds 1_000_000 to prevent uint64 overflow in sum of squares.
	var maxAbs uint64
	for _, v := range vec {
		a := uint64(Abs64(v))
		if a > maxAbs {
			maxAbs = a
		}
	}
	if maxAbs == 0 {
		return errors.New("zero vector cannot be normalized")
	}

	shift := uint(0)
	for (maxAbs >> shift) > 1000000 {
		shift++
	}

	var sqSum uint64
	for _, v := range vec {
		a := uint64(Abs64(v)) >> shift
		sqSum += a * a
	}
	norm := ISqrt64(sqSum)
	if norm == 0 {
		return errors.New("zero norm after scaling")
	}

	for i, v := range vec {
		neg := v < 0
		a := uint64(Abs64(v)) >> shift
		val := int64((a * uint64(Scale)) / norm)
		if neg {
			val = -val
		}
		dst[i] = val
	}
	return nil
}

// UnitNormalizeFixed projects a non-zero integer/fixed-point vector onto the unit sphere
// of radius Scale (1_000_000), deterministically across all validators.
func UnitNormalizeFixed(vec []int64) ([]int64, error) {
	if len(vec) == 0 {
		return nil, errors.New("vector cannot be empty")
	}
	unit := make([]int64, len(vec))
	if err := unitNormalizeInto(unit, vec); err != nil {
		return nil, err
	}
	return unit, nil
}

func validateVectorSetDimensions(vectors [][]int64) (int, error) {
	if len(vectors) < 2 {
		return 0, errors.New("coherence requires at least 2 vectors")
	}
	dim := len(vectors[0])
	if dim == 0 {
		return 0, errors.New("vectors must have positive dimension")
	}
	for i := 1; i < len(vectors); i++ {
		if len(vectors[i]) != dim {
			return 0, errors.New("all vectors in set must share the same dimension")
		}
	}
	return dim, nil
}

func validateAndNormalizeSet(vectors [][]int64) ([][]int64, error) {
	if _, err := validateVectorSetDimensions(vectors); err != nil {
		return nil, err
	}
	units := make([][]int64, len(vectors))
	for i, v := range vectors {
		u, err := UnitNormalizeFixed(v)
		if err != nil {
			return nil, err
		}
		units[i] = u
	}
	return units, nil
}

// MeanResultantLengthFixed computes ||mean(unit(v_i))|| in [0, Scale].
// Strictly order-invariant and O(n * d): 1.0*Scale when all vectors align, 0 when they cancel.
func MeanResultantLengthFixed(vectors [][]int64) (int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return 0, err
	}
	n := int64(len(units))
	dim := len(units[0])
	var sqSum uint64
	for j := 0; j < dim; j++ {
		var colSum int64
		for i := 0; i < len(units); i++ {
			colSum += units[i][j]
		}
		meanJ := colSum / n
		am := uint64(Abs64(meanJ))
		sqSum += am * am
	}
	res := int64(ISqrt64(sqSum))
	if res > Scale {
		res = Scale
	}
	return res, nil
}

// MeanPairwiseCosineFixed computes the exact mean cosine over all n*(n-1) distinct pairs
// in O(n * d) using the resultant identity: (||sum(u_i)||^2 - n) / (n * (n - 1)).
// Returns fixed-point value in [-Scale, +Scale], strictly order-invariant.
func MeanPairwiseCosineFixed(vectors [][]int64) (int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return 0, err
	}
	n := int64(len(units))
	dim := len(units[0])

	// sumNormSqFixed = ||sum(u_i)||^2 / Scale (in Scale units, where each u_i has ||u_i||^2 = Scale^2).
	var sumNormSqFixed int64
	for j := 0; j < dim; j++ {
		var colSum int64
		for i := 0; i < len(units); i++ {
			colSum += units[i][j]
		}
		sumNormSqFixed += MulFixed(colSum, colSum)
	}
	// Result = (sumNormSqFixed - n*Scale) / (n * (n - 1))
	num := sumNormSqFixed - n*Scale
	den := n * (n - 1)
	res := num / den
	if res > Scale {
		res = Scale
	}
	if res < -Scale {
		res = -Scale
	}
	return res, nil
}

// CoherenceGate evaluates whether a retrieved memory / context embedding batch is coherent
// enough to inject into an agent's reasoning window (blocking cross-session memory poisoning).
func CoherenceGate(vectors [][]int64, thresholdFixed int64, usePairwise bool) (bool, int64, SignalEvidence, error) {
	var (
		score int64
		err   error
		mode  int64
	)
	if usePairwise {
		mode = 1
		score, err = MeanPairwiseCosineFixed(vectors)
	} else {
		mode = 0
		score, err = MeanResultantLengthFixed(vectors)
	}
	if err != nil {
		return false, 0, SignalEvidence{}, err
	}
	pass := score >= thresholdFixed

	// Order-invariant digest over sorted vector hashes so input digest matches set semantics.
	inDigest := digestVectorSet(vectors)
	detail := "coherent_pass"
	if !pass {
		detail = "coherence_below_threshold"
	}
	ev := SignalEvidence{
		Primitive:    "signals.coherence_gate",
		Version:      "1",
		ParamsDigest: hashInt64s("coherence_gate", thresholdFixed, mode),
		InputDigest:  inDigest,
		OutputFixed:  score,
		Alarm:        !pass,
		Detail:       detail,
	}
	return pass, score, ev, nil
}

func digestVectorSet(vectors [][]int64) [32]byte {
	// XOR-independent canonical accumulation over vector hashes sorted lexicographically.
	hashes := make([][32]byte, len(vectors))
	for i, v := range vectors {
		buf := make([]byte, 0, 8+len(v)*8)
		buf = binary.BigEndian.AppendUint64(buf, uint64(len(v)))
		for _, x := range v {
			buf = binary.BigEndian.AppendUint64(buf, uint64(x))
		}
		hashes[i] = sha256.Sum256(buf)
	}
	// Simple deterministic insertion sort on 32-byte hashes (no extra imports needed).
	for i := 1; i < len(hashes); i++ {
		key := hashes[i]
		j := i - 1
		for j >= 0 && bytesLess(key, hashes[j]) {
			hashes[j+1] = hashes[j]
			j--
		}
		hashes[j+1] = key
	}
	all := make([]byte, 0, 16+len(hashes)*32)
	all = appendStr(all, "vecset-v1")
	for _, h := range hashes {
		all = append(all, h[:]...)
	}
	return sha256.Sum256(all)
}

func bytesLess(a, b [32]byte) bool {
	for i := 0; i < 32; i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return false
}

func hashSingleVec(v []int64) [32]byte {
	buf := make([]byte, 0, 8+len(v)*8)
	buf = binary.BigEndian.AppendUint64(buf, uint64(len(v)))
	for _, x := range v {
		buf = binary.BigEndian.AppendUint64(buf, uint64(x))
	}
	return sha256.Sum256(buf)
}

// discreteMedoidIndex returns the index of the strictly order-invariant discrete L1 medoid
// of a unit vector set (minimizing sum_j ||u_i - u_j||, breaking exact-distance ties
// deterministically by canonical vector SHA-256). Eliminates the exact 180-degree cancellation
// order-dependence discovered in Experiment E7a (cross-referencing @frintroper/Symmetry-No-Symmetry).
func discreteMedoidIndex(units [][]int64) int {
	n := len(units)
	dim := len(units[0])
	bestIdx := 0
	var bestSum uint64
	var bestHash [32]byte
	haveBest := false

	for i := 0; i < n; i++ {
		var sumDist uint64
		for j := 0; j < n; j++ {
			if i == j {
				continue
			}
			var sq uint64
			for d := 0; d < dim; d++ {
				ds := uint64(Abs64(units[i][d]-units[j][d]) / 1000)
				sq += ds * ds
			}
			sumDist += ISqrt64(sq)
		}
		h := hashSingleVec(units[i])
		if !haveBest || sumDist < bestSum || (sumDist == bestSum && bytesLess(h, bestHash)) {
			haveBest = true
			bestSum = sumDist
			bestHash = h
			bestIdx = i
		}
	}
	return bestIdx
}

func geometricMedianOnUnits(units [][]int64, iters int) ([]int64, error) {
	if _, err := validateVectorSetDimensions(units); err != nil {
		return nil, err
	}
	if iters <= 0 {
		iters = 8
	}
	dim := len(units[0])
	n := len(units)

	// Allocate working buffers once outside the Weiszfeld loop.
	num := make([]int64, dim)
	med := make([]int64, dim)
	copy(med, units[discreteMedoidIndex(units)])

	const epsDist int64 = 1000 // 0.001 in Scale units prevents 0/0 singularity
	for it := 0; it < iters; it++ {
		for j := 0; j < dim; j++ {
			num[j] = 0
		}
		var den int64
		for i := 0; i < n; i++ {
			var sq uint64
			for j := 0; j < dim; j++ {
				d := Abs64(units[i][j] - med[j])
				// Scale down by 1000 so d^2 fits safely inside uint64 for high dimensions.
				ds := uint64(d / 1000)
				sq += ds * ds
			}
			dist := int64(ISqrt64(sq)) * 1000
			if dist < epsDist {
				dist = epsDist
			}
			// Inverse-distance weight w = Scale^2 / dist (clamped via epsDist <= 1e9)
			w := (Scale * 1000) / (dist / 1000)
			if w <= 0 {
				w = 1
			}
			den += w
			for j := 0; j < dim; j++ {
				num[j] += (w * units[i][j]) / Scale
			}
		}
		if den == 0 {
			break
		}
		if err := unitNormalizeInto(med, num); err != nil {
			break
		}
	}
	return med, nil
}

// GeometricMedianFixed computes the deterministic fixed-point L1 Geometric Median on the
// unit sphere via Weiszfeld's iterative reweighting initialized at the order-invariant
// discrete L1 medoid (50% breakdown point against coordinated outlier clusters; pure integer
// arithmetic, zero floats, strictly order-invariant even under exact 180-degree cancellation).
//
// Mathematical basis: Weiszfeld (1937) / Vardi & Zhang (2000), solving sum_j (u_j - m)/||u_j - m|| = 0,
// independently validated in Experiments E5 & E7 after cross-referencing pairwise unit-difference
// relational fields and 180-degree symmetry stasis (Johannes Geisen / @frintroper).
func GeometricMedianFixed(vectors [][]int64, iters int) ([]int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return nil, err
	}
	return geometricMedianOnUnits(units, iters)
}

// GeometricMedianNormalizedFixed computes the deterministic fixed-point L1 Geometric Median
// directly over pre-normalized unit vectors (each scaled to Scale), skipping redundant
// UnitNormalizeFixed allocations and square-root passes.
func GeometricMedianNormalizedFixed(units [][]int64, iters int) ([]int64, error) {
	if _, err := validateVectorSetDimensions(units); err != nil {
		return nil, err
	}
	return geometricMedianOnUnits(units, iters)
}

// AntipodalFractionFixed computes the strictly order-invariant fraction (in [0, Scale]) of
// distinct unit vector pairs whose cosine similarity is <= negThresholdFixed (default -500000 = -0.50).
// Validated in Experiment E7b (100% TPR on balanced antipodal split-brain attacks at 0% clean FPR).
func AntipodalFractionFixed(vectors [][]int64, negThresholdFixed int64) (int64, error) {
	units, err := validateAndNormalizeSet(vectors)
	if err != nil {
		return 0, err
	}
	if negThresholdFixed == 0 {
		negThresholdFixed = -500000 // -0.50 cosine floor
	}
	n := len(units)
	dim := len(units[0])
	var antipodal int64
	var pairs int64
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			pairs++
			var dot int64
			for d := 0; d < dim; d++ {
				dot += MulFixed(units[i][d], units[j][d])
			}
			if dot <= negThresholdFixed {
				antipodal++
			}
		}
	}
	if pairs == 0 {
		return 0, nil
	}
	return (antipodal * Scale) / pairs, nil
}

// AntipodalSplitGate flags coordinated 180-degree / opposing split-brain poisoning batches
// when AntipodalFractionFixed exceeds maxFractionFixed (default 100000 = 10% of pairs).
func AntipodalSplitGate(vectors [][]int64, negThresholdFixed, maxFractionFixed int64) (bool, int64, SignalEvidence, error) {
	if negThresholdFixed == 0 {
