		InputDigest:  digestVectorSet(vectors),
		OutputFixed:  frac,
		Alarm:        !pass,
		Detail:       detail,
	}
	return pass, frac, ev, nil
}

// CommonAverageReferenceDebiasFixed removes a shared anisotropic common-cone component from
// an embedding vector in pure fixed-point integer arithmetic: unit(unit(vec) - coneWeight*unit(coneRef)).
// Validated in Experiment E9 (+76.5 pts poison quarantine TPR & -87.7 pts Top-3 contamination
// under anisotropic common-cone collapse, cross-referencing Arobi Labs embedding anisotropy findings).
func CommonAverageReferenceDebiasFixed(vec, coneRef []int64, coneWeightFixed int64) ([]int64, error) {
	u, err := UnitNormalizeFixed(vec)
	if err != nil {
		return nil, err
	}
	if len(coneRef) == 0 || coneWeightFixed <= 0 {
		return u, nil
	}
	if len(coneRef) != len(u) {
		return nil, errors.New("cone reference dimension mismatch")
	}
	cUnit, err := UnitNormalizeFixed(coneRef)
	if err != nil {
		return nil, err
	}
	if coneWeightFixed > Scale {
		coneWeightFixed = Scale
	}
	debiased := make([]int64, len(u))
	for i := range u {
		debiased[i] = u[i] - MulFixed(coneWeightFixed, cUnit[i])
	}
	out, err := UnitNormalizeFixed(debiased)
	if err != nil {
		// Vector was strictly collinear with coneRef; fall back safely to unit vector.
		return u, nil
	}
	return out, nil
}

// SignedQuadranceCosSqFixed computes Wildberger's signed rational cosine-squared:
//   C_2(u, v) = sgn(u . v) * ((u . v)^2 * Scale) / (||u||^2 * ||v||^2) in [-Scale, +Scale]
// using pure integer arithmetic with ZERO square roots (ISqrt64) and ZERO slice allocations.
// By Cauchy-Schwarz, |u . v| <= max(||u||^2, ||v||^2), guaranteeing overflow-free evaluation.
// Validated in Experiment E10 (cross-referencing @frintroper/wildberger-math & Wildberger 2005).
func SignedQuadranceCosSqFixed(u, v []int64) (int64, error) {
	if len(u) == 0 || len(u) != len(v) {
		return 0, errors.New("vectors must be non-empty and share the same dimension")
	}
	var maxAbs uint64
	for i := range u {
		au := uint64(Abs64(u[i]))
		av := uint64(Abs64(v[i]))
		if au > maxAbs {
			maxAbs = au
		}
		if av > maxAbs {
			maxAbs = av
		}
	}
	if maxAbs == 0 {
		return 0, errors.New("zero vector in quadrance evaluation")
	}
	shift := uint(0)
	for (maxAbs >> shift) > 1000000 {
		shift++
	}

	var dot int64
	var qu, qv uint64
	for i := range u {
		ui := u[i] >> shift
		vi := v[i] >> shift
		dot += ui * vi
		qu += uint64(Abs64(ui)) * uint64(Abs64(ui))
		qv += uint64(Abs64(vi)) * uint64(Abs64(vi))
	}
	if qu == 0 || qv == 0 {
		return 0, errors.New("zero quadrance after scaling")
	}
	if dot == 0 {
		return 0, nil
	}

	absDot := uint64(Abs64(dot))
	qMax, qMin := qu, qv
	if qv > qu {
		qMax, qMin = qv, qu
	}
	for qMax > 100000000000 {
		absDot >>= 1
		qMax >>= 1
		qMin >>= 1
	}
	if qMin == 0 {
		return 0, nil
	}
	// By Cauchy-Schwarz, absDot <= sqrt(qu*qv) <= qMax, so ratio1 <= 10_000_000.
	const interScale uint64 = 10000000
	ratio1 := (absDot * interScale) / qMax
	c2 := int64((ratio1 * absDot) / (qMin * (interScale / uint64(Scale))))
	if c2 > Scale {
		c2 = Scale
	}
	if dot < 0 {
		return -c2, nil
	}
	return c2, nil
}

// RationalSpreadFixed computes Wildberger's Rational Spread S(u, v) = 1 - cos^2(theta)
// in [0, Scale] without square roots or trig functions (0 = collinear/antipodal, Scale = orthogonal).
func RationalSpreadFixed(u, v []int64) (int64, error) {
	c2, err := SignedQuadranceCosSqFixed(u, v)
	if err != nil {
		return 0, err
	}
	return Scale - Abs64(c2), nil
}

// RationalCosGateFixed evaluates cos(u, v) >= thresholdFixed in O(d) integer arithmetic
// with zero ISqrt64 calls and zero heap allocations by testing C_2(u, v) >= sgn(tau)*tau^2.
func RationalCosGateFixed(u, v []int64, thresholdFixed int64) (bool, int64, error) {
	c2, err := SignedQuadranceCosSqFixed(u, v)
	if err != nil {
		return false, 0, err
	}
	tauSq := MulFixed(Abs64(thresholdFixed), Abs64(thresholdFixed))
	if thresholdFixed < 0 {
		tauSq = -tauSq
	}
	return c2 >= tauSq, c2, nil
}

// CalibrateThresholdYoudenFixed finds the optimal fixed-point decision threshold maximizing
// Youden's J = TPR - FPR (where cleanScores >= threshold and attackScores < threshold) and
// computes the exact Mann-Whitney / Wilcoxon ROC-AUC in [0, Scale] with zero floats.
// Validated in Experiment E11b (cross-referencing Arobi Labs arobi-primitives/coherence.py).
func CalibrateThresholdYoudenFixed(cleanScores, attackScores []int64) (bestThresholdFixed, youdenJFixed, rocAucFixed int64, err error) {
	nc := len(cleanScores)
	na := len(attackScores)
	if nc == 0 || na == 0 {
		return 0, 0, 0, errors.New("calibration requires non-empty clean and attack score slices")
	}

	// 1. Exact Mann-Whitney ROC-AUC: P(clean > attack) + 0.5*P(clean == attack)
	var halfWins int64
	for i := 0; i < nc; i++ {
		cs := cleanScores[i]
		for j := 0; j < na; j++ {
			as := attackScores[j]
			if cs > as {
				halfWins += 2
			} else if cs == as {
				halfWins += 1
			}
		}
	}
	rocAucFixed = (halfWins * Scale) / int64(2*nc*na)

	// 2. Evaluate Youden's J(t) = TPR(t) - FPR(t) across all candidate thresholds.
	bestJ := int64(-2 * Scale)
	bestT := cleanScores[0]
	for idx := 0; idx < nc+na; idx++ {
		var t int64
		if idx < nc {
			t = cleanScores[idx]
		} else {
			t = attackScores[idx-nc]
		}
		var cHits, aFalse int64
		for i := 0; i < nc; i++ {
			if cleanScores[i] >= t {
				cHits++
			}
		}
		for j := 0; j < na; j++ {
			if attackScores[j] >= t {
				aFalse++
			}
		}
		tpr := (cHits * Scale) / int64(nc)
		fpr := (aFalse * Scale) / int64(na)
		jStat := tpr - fpr
		if jStat > bestJ || (jStat == bestJ && t > bestT) {
			bestJ = jStat
			bestT = t
		}
	}
	return bestT, bestJ, rocAucFixed, nil
}

// CosineFixed computes the deterministic fixed-point dot product of two unit-normalized
// vectors (each scaled to Scale), clamped to [-Scale, +Scale].
func CosineFixed(u, w []int64) (int64, error) {
	if len(u) == 0 || len(u) != len(w) {
		return 0, errors.New("vectors must be non-empty and have matching dimensions")
	}
	var sum int64
	for i := range u {
		sum += MulFixed(u[i], w[i])
	}
	if sum > Scale {
		sum = Scale
	}
	if sum < -Scale {
		sum = -Scale
	}
	return sum, nil
}

// HubStatsFixed stores a memory record's background cosine affinity distribution (mean, std)
// over a calibration query block (Radovanovic et al., JMLR 2010; Arobi Labs Utah P3 primitive).
// Validated in Experiment E13a.
type HubStatsFixed struct {
	MeanFixed int64
	StdFixed  int64
	Samples   int
}

// FitHubStatsFixed computes deterministic fixed-point mean and standard deviation of
// cosine similarity between memoryUnit and a calibration block of unit query vectors.
// If excludeSelfIdx >= 0, calibrationUnits[excludeSelfIdx] is omitted (leave-one-out).
func FitHubStatsFixed(calibrationUnits [][]int64, memoryUnit []int64, excludeSelfIdx int, minStdFixed int64) (HubStatsFixed, error) {
	if len(memoryUnit) == 0 {
		return HubStatsFixed{}, errors.New("empty memory vector")
	}
	if minStdFixed <= 0 {
		minStdFixed = 50000 // 0.05 floor prevents division-by-zero on degenerate hubs
	}
	scores := make([]int64, 0, len(calibrationUnits))
	var sum int64
	for i, cu := range calibrationUnits {
		if i == excludeSelfIdx {
			continue
		}
		if len(cu) != len(memoryUnit) {
			return HubStatsFixed{}, errors.New("calibration vector dimension mismatch")
		}
		c, err := CosineFixed(cu, memoryUnit)
		if err != nil {
			return HubStatsFixed{}, err
		}
		scores = append(scores, c)
		sum += c
	}
	n := len(scores)
	if n == 0 {
		return HubStatsFixed{MeanFixed: 0, StdFixed: minStdFixed, Samples: 0}, nil
	}
	mean := sum / int64(n)
	var varSum uint64
	for _, s := range scores {
		d := s - mean
		if d < 0 {
			d = -d
		}
		varSum += uint64(d) * uint64(d)
	}
	std := int64(ISqrt64(varSum / uint64(n)))
	if std < minStdFixed {
		std = minStdFixed
	}
	return HubStatsFixed{
		MeanFixed: mean,
		StdFixed:  std,
		Samples:   n,
	}, nil
}

// HubNormalizeScoreFixed returns the standardized hubness z-score in Scale units:
//
//	z(q, m) = ((cos(q, m) - mean) * Scale) / max(std, minStdFixed)
//
// Universal hubs with high background similarity (high mean, tiny variance) collapse to z ~ 0,
// while query-specific target memories spike to z >> 2*Scale.
func HubNormalizeScoreFixed(queryUnit, memoryUnit []int64, stats HubStatsFixed, minStdFixed int64) (int64, error) {
	cos, err := CosineFixed(queryUnit, memoryUnit)
	if err != nil {
		return 0, err
	}
	if minStdFixed <= 0 {
		minStdFixed = 50000
	}
	denom := stats.StdFixed
	if denom < minStdFixed {
		denom = minStdFixed
	}
	return ((cos - stats.MeanFixed) * Scale) / denom, nil
}

package signals

import "errors"

// Baseline holds fixed-point reference mean and standard deviation estimated from a quiet window.
type Baseline struct {
	MeanFixed int64
	SDFixed   int64
}

// BaselineFromSlice computes the sample mean and unbiased sample SD (ddof=1) in fixed-point.
func BaselineFromSlice(quiet []int64) (Baseline, error) {
	n := len(quiet)
	if n < 10 {
		return Baseline{}, errors.New("baseline requires at least 10 samples")
	}
	var sum int64
	for _, v := range quiet {
		sum += v
	}
	mean := sum / int64(n)

	var sqSum uint64
	for _, v := range quiet {
		d := Abs64(v - mean)
		// Compute (d*d)/Scale carefully in uint64 to retain full fixed-point variance precision.
		ud := uint64(d)
		s := uint64(Scale)
		dh, dl := ud/s, ud%s
		sqFixed := dh*dh*s + 2*dh*dl + (dl*dl)/s
		sqSum += sqFixed
	}
	varFixed := int64(sqSum / uint64(n-1))
	sd := SqrtFixed(varFixed)
	if sd < MinSDFixed {
		sd = MinSDFixed
	}
	return Baseline{MeanFixed: mean, SDFixed: sd}, nil
}

// CusumDetector implements deterministic one-sided upper CUSUM on standardized fixed-point samples:
//   z = (x - mean) / sd
//   S = max(0, S + z - k)
//   alarm when S > h
// Default k = 1*Scale targets 2-sigma upward shifts.
type CusumDetector struct {
	base   Baseline
	hFixed int64
	kFixed int64
	stat   int64
	alarms uint64
	steps  uint64
}

func NewCusum(base Baseline, hFixed, kFixed int64) (*CusumDetector, error) {
	if base.SDFixed <= 0 {
		return nil, errors.New("baseline SDFixed must be > 0")
	}
	if hFixed <= 0 {
		return nil, errors.New("threshold hFixed must be > 0")
	}
	if kFixed <= 0 {
		kFixed = Scale // default 1.0 sigma
	}
	return &CusumDetector{
		base:   base,
		hFixed: hFixed,
		kFixed: kFixed,
	}, nil
}

func (c *CusumDetector) Update(xFixed int64) (bool, int64, SignalEvidence) {
	c.steps++
	z := DivFixed(xFixed-c.base.MeanFixed, c.base.SDFixed)
	next := c.stat + z - c.kFixed
	if next < 0 {
		next = 0
	}
	c.stat = next
	alarm := c.stat > c.hFixed
	detail := "within_bound"
	if alarm {
		c.alarms++
		detail = "cusum_drift_alarm"
	}
	ev := SignalEvidence{
		Primitive:    "signals.cusum",
		Version:      "1",
		ParamsDigest: hashInt64s("cusum", c.base.MeanFixed, c.base.SDFixed, c.hFixed, c.kFixed),
		InputDigest:  hashInt64s("in", xFixed),
		OutputFixed:  c.stat,
		Alarm:        alarm,
		Detail:       detail,
	}
	return alarm, c.stat, ev
}

func (c *CusumDetector) Statistic() int64 { return c.stat }
func (c *CusumDetector) Alarms() uint64   { return c.alarms }
func (c *CusumDetector) Reset()           { c.stat = 0 }

// PageHinkleyDetector implements deterministic Page-Hinkley upward shift detection:
//   runningMean += (z - runningMean) / n
//   m += z - runningMean - delta
//   mMin = min(mMin, m)
//   alarm when (m - mMin) > lambda
type PageHinkleyDetector struct {
	base        Baseline
	lambdaFixed int64
	deltaFixed  int64
	n           int64
	runningMean int64
	m           int64
	mMin        int64
	alarms      uint64
}

func NewPageHinkley(base Baseline, lambdaFixed, deltaFixed int64) (*PageHinkleyDetector, error) {
	if base.SDFixed <= 0 {
		return nil, errors.New("baseline SDFixed must be > 0")
	}
	if lambdaFixed <= 0 {
		return nil, errors.New("lambdaFixed must be > 0")
	}
	if deltaFixed <= 0 {
		deltaFixed = 500000 // default 0.5 sigma
	}
	return &PageHinkleyDetector{
		base:        base,
		lambdaFixed: lambdaFixed,
		deltaFixed:  deltaFixed,
	}, nil
}

func (p *PageHinkleyDetector) Update(xFixed int64) (bool, int64, SignalEvidence) {
	z := DivFixed(xFixed-p.base.MeanFixed, p.base.SDFixed)
	p.n++
	p.runningMean += (z - p.runningMean) / p.n
	p.m += z - p.runningMean - p.deltaFixed
	if p.m < p.mMin {
		p.mMin = p.m
	}
	stat := p.m - p.mMin
	alarm := stat > p.lambdaFixed
	detail := "within_bound"
	if alarm {
		p.alarms++
		detail = "page_hinkley_drift_alarm"
	}
	ev := SignalEvidence{
		Primitive:    "signals.page_hinkley",
		Version:      "1",
		ParamsDigest: hashInt64s("page_hinkley", p.base.MeanFixed, p.base.SDFixed, p.lambdaFixed, p.deltaFixed),
		InputDigest:  hashInt64s("in", xFixed),
		OutputFixed:  stat,
		Alarm:        alarm,
		Detail:       detail,
	}
	return alarm, stat, ev
}

func (p *PageHinkleyDetector) Statistic() int64 { return p.m - p.mMin }
func (p *PageHinkleyDetector) Reset() {
	p.n, p.runningMean, p.m, p.mMin = 0, 0, 0, 0
}

// HampelCusumDetector composes a causal Hampel spike filter ahead of a standardized CUSUM
// detector. Isolated +/-10sigma oracle or sensor spikes are clamped before entering CUSUM,
// eliminating transient false circuit-breaker trips while still catching sustained shifts.
type HampelCusumDetector struct {
	smoother *RobustSmoother
	cusum    *CusumDetector
}

func NewHampelCusum(base Baseline, hFixed, kFixed int64, window int, hampelKFixed int64) (*HampelCusumDetector, error) {
	sm, err := NewRobustSmoother(window, hampelKFixed, Scale)
	if err != nil {
		return nil, err
	}
	cu, err := NewCusum(base, hFixed, kFixed)
	if err != nil {
		return nil, err
	}
	return &HampelCusumDetector{smoother: sm, cusum: cu}, nil
}

func (hc *HampelCusumDetector) Update(xFixed int64) (alarm bool, stat int64, spikeClamped bool, ev SignalEvidence) {
	cleaned, replaced := hc.smoother.HampelOnly(xFixed)
	alarm, stat, ev = hc.cusum.Update(cleaned)
	ev.Primitive = "signals.hampel_cusum"
	ev.InputDigest = hashInt64s("in", xFixed)
	if replaced && !alarm {
		ev.Detail = "spike_clamped_no_drift"
	}
	return alarm, stat, replaced, ev
}

func (hc *HampelCusumDetector) Statistic() int64     { return hc.cusum.Statistic() }
func (hc *HampelCusumDetector) SpikesClamped() uint64 { return hc.smoother.Replaced() }
func (hc *HampelCusumDetector) Reset()               { hc.cusum.Reset() }

// OpacityAwareHampelCusumDetector closes the Filter Opacity blindspot discovered in
// Experiment E8b (cross-referencing @frintroper/Astrometric-Filter-Opacity):
//   - Channel A (HampelCusum): catches sustained sub-cap +2sigma drift while staying immune
//     to isolated +/-10sigma transient spikes.
//   - Channel B (Innovation Clip Counter): tracks positive Hampel-clipped bursts exceeding
//     clipSigmaFixed (default 4*Scale) inside a bounded sliding window (default 24 steps),
//     alarming when >= minClips (default 3) occur. Eliminates periodic filter-evading bursts
//     (period P > Hampel window w: 72.3% -> 100% TPR) with +0.0% clean or single-spike FPR.
type OpacityAwareHampelCusumDetector struct {
	base           Baseline
	hc             *HampelCusumDetector
	clipSigmaFixed int64
	clipWindow     int
	minClips       int
	clipRing       []bool
	ringPos        int
	ringCount      int
	ringFilled     int
}

func NewOpacityAwareHampelCusum(
	base Baseline,
	hFixed, kFixed int64,
	window int,
	hampelKFixed int64,
	clipSigmaFixed int64,
	clipWindow int,
	minClips int,
) (*OpacityAwareHampelCusumDetector, error) {
	hc, err := NewHampelCusum(base, hFixed, kFixed, window, hampelKFixed)
	if err != nil {
		return nil, err
	}
	if clipSigmaFixed <= 0 {
		clipSigmaFixed = 4 * Scale
	}
	if clipWindow <= 0 {
		clipWindow = 24
	}
	if minClips <= 0 {
		minClips = 3
	}
	return &OpacityAwareHampelCusumDetector{
		base:           base,
		hc:             hc,
		clipSigmaFixed: clipSigmaFixed,
		clipWindow:     clipWindow,
		minClips:       minClips,
		clipRing:       make([]bool, clipWindow),
	}, nil
}

func (oa *OpacityAwareHampelCusumDetector) Update(xFixed int64) (alarm bool, stat int64, channel string, ev SignalEvidence) {
	cuAlarm, stat, replaced, ev := oa.hc.Update(xFixed)
	z := DivFixed(xFixed-oa.base.MeanFixed, oa.base.SDFixed)
	posClip := replaced && z > oa.clipSigmaFixed

	if oa.ringFilled < oa.clipWindow {
		oa.clipRing[oa.ringPos] = posClip
		if posClip {
			oa.ringCount++
		}
		oa.ringPos = (oa.ringPos + 1) % oa.clipWindow
		oa.ringFilled++
	} else {
		if oa.clipRing[oa.ringPos] {
			oa.ringCount--
		}
		oa.clipRing[oa.ringPos] = posClip
		if posClip {
			oa.ringCount++
		}
		oa.ringPos = (oa.ringPos + 1) % oa.clipWindow
	}

	opacityAlarm := oa.ringCount >= oa.minClips
	alarm = cuAlarm || opacityAlarm
	ev.Primitive = "signals.opacity_aware_hampel_cusum"
	ev.Alarm = alarm
	switch {
	case cuAlarm && opacityAlarm:
		channel = "dual_cusum_and_opacity"
		ev.Detail = "dual_drift_and_pulsed_opacity_alarm"
	case opacityAlarm:
		channel = "opacity_innovation_channel"
		ev.Detail = "pulsed_filter_opacity_alarm"
	case cuAlarm:
		channel = "hampel_cusum_channel"
		ev.Detail = "cusum_drift_alarm"
	default:
		channel = "none"
		if replaced {
			ev.Detail = "spike_clamped_no_drift"
		} else {
			ev.Detail = "within_bound"
		}
	}
	return alarm, stat, channel, ev
}

func (oa *OpacityAwareHampelCusumDetector) ClipCount() int   { return oa.ringCount }
func (oa *OpacityAwareHampelCusumDetector) Statistic() int64 { return oa.hc.Statistic() }
func (oa *OpacityAwareHampelCusumDetector) Reset() {
	oa.hc.Reset()
	for i := range oa.clipRing {
		oa.clipRing[i] = false
	}
	oa.ringPos, oa.ringCount, oa.ringFilled = 0, 0, 0
}

// EstimateAR1Fixed computes the fixed-point Baseline (mean, SD) and clamped lag-1 autocorrelation
// rhoFixed in [-900000, +900000] ([-0.90, +0.90]) from a quiet reference window (n >= 10).
// Validated in Experiment E11a (cross-referencing Arobi Labs arobi-primitives/drift.py).
func EstimateAR1Fixed(quiet []int64) (Baseline, int64, error) {
	base, err := BaselineFromSlice(quiet)
	if err != nil {
		return Baseline{}, 0, err
	}
	n := len(quiet)
	var num, den int64
	for i := 0; i < n; i++ {
		zi := DivFixed(quiet[i]-base.MeanFixed, base.SDFixed)
		den += MulFixed(zi, zi)
		if i+1 < n {
			zNext := DivFixed(quiet[i+1]-base.MeanFixed, base.SDFixed)
			num += MulFixed(zi, zNext)
		}
	}
	if den <= 0 {
		return base, 0, nil
	}
	rho := DivFixed(num, den)
	if rho > 900000 {
		rho = 900000
	}
	if rho < -900000 {
		rho = -900000
	}
	return base, rho, nil
}

// AR1PrewhitenedHampelCusumDetector prewhitens positively/negatively autocorrelated agent
// telemetry streams into causal one-step AR(1) innovations after Hampel spike clamping:
//   e_t = (z_t - rho * z_{t-1}) / sqrt(1 - rho^2)
// Eliminates the 4x-10x false-alarm inflation suffered by white-noise CUSUM on autocorrelated
// streams (rho in [0.5, 0.8]) while preserving spike immunity and Channel-B Opacity detection.
type AR1PrewhitenedHampelCusumDetector struct {
	base           Baseline
	rhoFixed       int64
	innovScale     int64 // sqrt(Scale^2 - rho^2) in Scale units
	smoother       *RobustSmoother
	cusum          *CusumDetector
	prevZ          int64
	hasPrevZ       bool
	clipSigmaFixed int64
	clipWindow     int
	minClips       int
	clipRing       []bool
	ringPos        int
	ringCount      int
	ringFilled     int
}

func NewAR1PrewhitenedHampelCusum(
	base Baseline,
	rhoFixed int64,
	hFixed, kFixed int64,
	window int,
	hampelKFixed int64,
	clipSigmaFixed int64,
	clipWindow int,
	minClips int,
) (*AR1PrewhitenedHampelCusumDetector, error) {
	if rhoFixed > 900000 {
		rhoFixed = 900000
	}
	if rhoFixed < -900000 {
		rhoFixed = -900000
	}
	sm, err := NewRobustSmoother(window, hampelKFixed, Scale)
	if err != nil {
		return nil, err
	}
	// Standardized innovation baseline: mean = 0, SD = Scale
	cu, err := NewCusum(Baseline{MeanFixed: 0, SDFixed: Scale}, hFixed, kFixed)
	if err != nil {
		return nil, err
	}
	oneMinusRhoSq := Scale - MulFixed(rhoFixed, rhoFixed)
	if oneMinusRhoSq < 10000 {
		oneMinusRhoSq = 10000
	}
	innovScale := SqrtFixed(oneMinusRhoSq)
	if innovScale < 1 {
		innovScale = 1
	}
	if clipSigmaFixed <= 0 {
		clipSigmaFixed = 4 * Scale
	}
	if clipWindow <= 0 {
		clipWindow = 24
	}
	if minClips <= 0 {
		minClips = 3
	}
	return &AR1PrewhitenedHampelCusumDetector{
		base:           base,
		rhoFixed:       rhoFixed,
		innovScale:     innovScale,
		smoother:       sm,
		cusum:          cu,
		clipSigmaFixed: clipSigmaFixed,
		clipWindow:     clipWindow,
		minClips:       minClips,
		clipRing:       make([]bool, clipWindow),
	}, nil
}

func (ar *AR1PrewhitenedHampelCusumDetector) Update(xFixed int64) (alarm bool, stat int64, channel string, ev SignalEvidence) {
	cleaned, replaced := ar.smoother.HampelOnly(xFixed)
	zClean := DivFixed(cleaned-ar.base.MeanFixed, ar.base.SDFixed)
	var innovFixed int64
	if !ar.hasPrevZ {
		innovFixed = zClean
		ar.hasPrevZ = true
	} else {
		innovFixed = DivFixed(zClean-MulFixed(ar.rhoFixed, ar.prevZ), ar.innovScale)
	}
	ar.prevZ = zClean

	cuAlarm, stat, ev := ar.cusum.Update(innovFixed)

	zRaw := DivFixed(xFixed-ar.base.MeanFixed, ar.base.SDFixed)
	posClip := replaced && zRaw > ar.clipSigmaFixed
	if ar.ringFilled < ar.clipWindow {
		ar.clipRing[ar.ringPos] = posClip
		if posClip {
			ar.ringCount++
		}
		ar.ringPos = (ar.ringPos + 1) % ar.clipWindow
		ar.ringFilled++
	} else {
		if ar.clipRing[ar.ringPos] {
			ar.ringCount--
		}
		ar.clipRing[ar.ringPos] = posClip
		if posClip {
			ar.ringCount++
		}
		ar.ringPos = (ar.ringPos + 1) % ar.clipWindow
	}

	opacityAlarm := ar.ringCount >= ar.minClips
	alarm = cuAlarm || opacityAlarm
	ev.Primitive = "signals.ar1_prewhitened_hampel_cusum"
	ev.InputDigest = hashInt64s("in", xFixed)
	ev.Alarm = alarm
	switch {
	case cuAlarm && opacityAlarm:
		channel = "dual_ar1_cusum_and_opacity"
		ev.Detail = "dual_ar1_drift_and_opacity_alarm"
	case opacityAlarm:
		channel = "opacity_innovation_channel"
		ev.Detail = "pulsed_filter_opacity_alarm"
	case cuAlarm:
		channel = "ar1_cusum_channel"
		ev.Detail = "ar1_prewhitened_cusum_alarm"
	default:
		channel = "none"
		if replaced {
			ev.Detail = "spike_clamped_no_drift"
		} else {
			ev.Detail = "within_bound"
		}
	}
	return alarm, stat, channel, ev
}

func (ar *AR1PrewhitenedHampelCusumDetector) Statistic() int64 { return ar.cusum.Statistic() }
func (ar *AR1PrewhitenedHampelCusumDetector) ClipCount() int   { return ar.ringCount }
func (ar *AR1PrewhitenedHampelCusumDetector) Reset() {
	ar.cusum.Reset()
	ar.prevZ = 0
	ar.hasPrevZ = false
	for i := range ar.clipRing {
		ar.clipRing[i] = false
	}
	ar.ringPos, ar.ringCount, ar.ringFilled = 0, 0, 0
}

package signals

import "errors"

// CausalMedian computes the trailing-window median causally (each output depends only
// on the current and past samples; initial samples warm up using the first value).
type CausalMedian struct {
	window int
	buf    []int64
}

func NewCausalMedian(window int) (*CausalMedian, error) {
	if window < 1 {
		return nil, errors.New("window must be >= 1")
	}
	return &CausalMedian{window: window}, nil
}

func (m *CausalMedian) Update(x int64) (int64, SignalEvidence) {
	if len(m.buf) == 0 {
		m.buf = make([]int64, m.window)
		for i := range m.buf {
			m.buf[i] = x
		}
	} else {
		copy(m.buf, m.buf[1:])
		m.buf[len(m.buf)-1] = x
	}
	y := MedianFixed(m.buf)
	ev := SignalEvidence{
		Primitive:    "signals.causal_median",
		Version:      "1",
		ParamsDigest: hashInt64s("causal_median", int64(m.window)),
		InputDigest:  hashInt64s("in", x),
		OutputFixed:  y,
		Alarm:        false,
		Detail:       "ok",
	}
	return y, ev
}

// RobustSmoother implements Arobi's measured-best causal filter for spiky telemetry:
// Hampel outlier rejection (default window=5, k=3.0*Scale) followed by EMA (alpha=0.2*Scale).
// Streaming Update() is bit-for-bit identical to batch Hampel -> EMA.
type RobustSmoother struct {
	window     int
	kFixed     int64
	alphaFixed int64
	buf        []int64
	hasY       bool
	y          int64
	replaced   uint64
	count      uint64
}

// NewRobustSmoother creates a deterministic causal Hampel + EMA filter.
// Defaults when zeros are passed: window=5, k=3*Scale, alpha=200_000 (0.2).
func NewRobustSmoother(window int, kFixed, alphaFixed int64) (*RobustSmoother, error) {
	if window == 0 {
		window = 5
	}
	if kFixed == 0 {
		kFixed = 3 * Scale
	}
	if alphaFixed == 0 {
		alphaFixed = 200000 // 0.2
	}
	if window < 2 {
		return nil, errors.New("window must be >= 2")
	}
	if kFixed <= 0 {
		return nil, errors.New("kFixed must be > 0")
	}
	if alphaFixed <= 0 || alphaFixed > Scale {
		return nil, errors.New("alphaFixed must be in (0, Scale]")
	}
	return &RobustSmoother{
		window:     window,
		kFixed:     kFixed,
		alphaFixed: alphaFixed,
	}, nil
}

// Update processes one fixed-point sample x and returns (smoothedY, wasOutlier, SignalEvidence).
func (r *RobustSmoother) Update(x int64) (int64, bool, SignalEvidence) {
	if len(r.buf) == 0 {
		r.buf = make([]int64, r.window)
		for i := range r.buf {
			r.buf[i] = x
		}
	} else {
		copy(r.buf, r.buf[1:])
		r.buf[len(r.buf)-1] = x
	}
	r.count++

	med := MedianFixed(r.buf)
	absDevs := make([]int64, len(r.buf))
	for i, v := range r.buf {
		absDevs[i] = Abs64(v - med)
	}
	mad := MulFixed(MADScale, MedianFixed(absDevs))
	if mad < MinSDFixed {
		mad = MinSDFixed
	}
	thresh := MulFixed(r.kFixed, mad)

	cleaned := x
	outlier := Abs64(x-med) > thresh
	if outlier {
		cleaned = med
		r.replaced++
	}

	if !r.hasY {
		r.y = cleaned
		r.hasY = true
	} else {
		// y_t = alpha*cleaned + (1 - alpha)*y_{t-1}
		r.y = MulFixed(r.alphaFixed, cleaned) + MulFixed(Scale-r.alphaFixed, r.y)
	}

	detail := "clean"
	if outlier {
		detail = "spike_replaced"
	}
	ev := SignalEvidence{
		Primitive:    "signals.robust_smooth",
		Version:      "1",
		ParamsDigest: hashInt64s("robust_smooth", int64(r.window), r.kFixed, r.alphaFixed),
		InputDigest:  hashInt64s("in", x),
		OutputFixed:  r.y,
		Alarm:        outlier,
		Detail:       detail,
	}
	return r.y, outlier, ev
}

// HampelOnly processes one sample through the Hampel spike gate without EMA lag.
// Ideal as a spike-resistant pre-filter ahead of CUSUM drift detection.
func (r *RobustSmoother) HampelOnly(x int64) (int64, bool) {
	if len(r.buf) == 0 {
		r.buf = make([]int64, r.window)
		for i := range r.buf {
			r.buf[i] = x
		}
	} else {
		copy(r.buf, r.buf[1:])
		r.buf[len(r.buf)-1] = x
	}
	r.count++
	med := MedianFixed(r.buf)
	absDevs := make([]int64, len(r.buf))
	for i, v := range r.buf {
		absDevs[i] = Abs64(v - med)
	}
	mad := MulFixed(MADScale, MedianFixed(absDevs))
	if mad < MinSDFixed {
		mad = MinSDFixed
	}
	if Abs64(x-med) > MulFixed(r.kFixed, mad) {
		r.replaced++
		return med, true
	}
	return x, false
}

// Replaced returns how many spike samples were replaced so far.
func (r *RobustSmoother) Replaced() uint64 {
	return r.replaced
}

// Value returns the latest smoothed output.
func (r *RobustSmoother) Value() int64 {
	return r.y
}

// BatchRobustSmooth applies RobustSmoother across an entire slice and returns the smoothed series.
func BatchRobustSmooth(series []int64, window int, kFixed, alphaFixed int64) ([]int64, uint64, error) {
	if len(series) == 0 {
		return nil, 0, errors.New("series cannot be empty")
	}
	sm, err := NewRobustSmoother(window, kFixed, alphaFixed)
	if err != nil {
		return nil, 0, err
	}
	out := make([]int64, len(series))
	for i, v := range series {
		y, _, _ := sm.Update(v)
		out[i] = y
	}
	return out, sm.Replaced(), nil
}

package signals

import "errors"

// KalmanRWGainFixed computes the exact steady-state algebraic Riccati Kalman gain K*
// in fixed-point units [0, Scale] for a scalar random-walk state-space model:
//
//	x_t = x_{t-1} + w_t,  Var(w_t) = qFixed / Scale
//	y_t = x_t     + v_t,  Var(v_t) = rFixed / Scale
//
// Closed-form solution (Kalman 1960; Wu et al. NeurIPS 2002; Arobi Labs Utah P6 primitive):
//
//	P^+ = (q + sqrt(q^2 + 4*q*r)) / 2
//	K*  = P^+ / (P^+ + r)
//
// Solved once in pure integer arithmetic via ISqrt64 (zero floats, zero per-step roots).
// Validated in Experiment E13b.
func KalmanRWGainFixed(qFixed, rFixed int64) (int64, error) {
	if qFixed <= 0 || rFixed <= 0 {
		return 0, errors.New("kalman variances qFixed and rFixed must be positive")
	}
	// Scale down (q, r) if necessary so q^2 + 4*q*r fits comfortably inside uint64 without overflow.
	// Note that K*(q, r) depends only on the ratio q/r, so scaling q and r by the same factor is exact!
	q := uint64(qFixed)
	r := uint64(rFixed)
	// Multiply up to preserve precision for tiny q, or shift down for huge q/r.
	// Target max(q, r) in [10^6, 10^8] so disc = q^2 + 4*q*r <= 5*10^16 << 1.8*10^19 (uint64 max).
	for q < 1000000 && r < 1000000 {
		q *= 10
		r *= 10
	}
	for q > 100000000 || r > 100000000 {
		q /= 2
		r /= 2
		if q == 0 {
			q = 1
		}
		if r == 0 {
			r = 1
		}
	}
	disc := q*q + 4*q*r
	root := ISqrt64(disc)
	// P^+ = (q + root) / 2; compute K* = (P^+ * Scale) / (P^+ + r) using 2*P^+ = q + root
	// to avoid losing the 0.5 truncation bit: K* = ((q + root) * Scale) / (q + root + 2*r).
	num := q + root
	den := num + 2*r
	if den == 0 {
		return Scale, nil
	}
	// Multiply num * Scale safely (num <= ~4.5*10^8, num * 10^6 <= 4.5*10^14 << uint64 max).
	k := (num * uint64(Scale) + den/2) / den
	if k > uint64(Scale) {
		k = uint64(Scale)
	}
	return int64(k), nil
}

// KalmanRWTracker is a deterministic O(1) fixed-point scalar random-walk Kalman tracker
// for noisy latent agent telemetry (cost-per-turn, latency, gas drift).
// After initialization, each Update uses one subtraction, one multiply, and one shift/div
// (zero ISqrt64 calls and zero heap allocations per step).
type KalmanRWTracker struct {
	gainFixed   int64
	stateFixed  int64
	initialized bool
	steps       int64
}

// NewKalmanRWTracker constructs a steady-state random-walk Kalman tracker with exact
// integer Riccati gain K*(qFixed, rFixed).
func NewKalmanRWTracker(qFixed, rFixed int64) (*KalmanRWTracker, error) {
	k, err := KalmanRWGainFixed(qFixed, rFixed)
	if err != nil {
		return nil, err
	}
	return &KalmanRWTracker{
		gainFixed: k,
	}, nil
}

// Update ingests one fixed-point observation obsFixed and returns the filtered state estimate
// and its innovation (obsFixed - priorState).
func (t *KalmanRWTracker) Update(obsFixed int64) (stateFixed, innovationFixed int64) {
	t.steps++
	if !t.initialized {
		t.stateFixed = obsFixed
		t.initialized = true
		return t.stateFixed, 0
	}
	innov := obsFixed - t.stateFixed
	t.stateFixed += MulFixed(t.gainFixed, innov)
	return t.stateFixed, innov
}

// GainFixed returns the steady-state Riccati Kalman gain in [0, Scale].
func (t *KalmanRWTracker) GainFixed() int64 { return t.gainFixed }

// StateFixed returns the current filtered state estimate in Scale units.
