			status := "ACTIVE"
			if pp.Revoked {
				status = "REVOKED"
			}
			tip := sdk.Hex(pp.LastRoot)[:16] + "..."
			b.WriteString("| [" + pp.AgentID + "](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2:agent/" + pp.AgentID + ") | " +
