	ErrNodeLocked        = errors.New("tributary: node graph is permanently locked")
	ErrInvalidAddress    = errors.New("tributary: invalid address")
	ErrInvalidBPS        = errors.New("tributary: edge bps must be 1..10000 and total <= 10000")
	ErrDuplicateEdge     = errors.New("tributary: duplicate upstream target in split set")
	ErrTooManyEdges      = errors.New("tributary: exceeds max upstream edges per node")
	ErrCycleDetected     = errors.New("tributary: cycle detected in dependency graph")
	ErrMaxDepthExceeded  = errors.New("tributary: dependency graph exceeds max depth")
	ErrInvalidAmount     = errors.New("tributary: amount must be positive")
	ErrNothingToClaim    = errors.New("tributary: no claimable balance for address")
)

// Engine is a deterministic, cycle-proof, zero-dust DAG revenue waterfall ledger.
// It is pure state + accounting so any realm can embed it and pair it with
// its own chain/banker escrow under strict Checks-Effects-Interactions.
type Engine struct {
	nodes         *avl.Tree // nodeID -> *Node
	pending       *avl.Tree // addr.String() -> int64
	claimed       *avl.Tree // addr.String() -> int64
	receipts      []DepositReceipt
	nextSeq       int64
	totalRouted   int64
	totalClaimed  int64
	lockedCount   int
}

// NewEngine initializes an empty Tributary DAG engine.
func NewEngine() *Engine {
	return &Engine{
		nodes:   avl.NewTree(),
		pending: avl.NewTree(),
		claimed: avl.NewTree(),
	}
}

// ValidateID checks that id is a clean URL-safe slug (2..40 chars, lowercase alnum/-/_).
func ValidateID(id string) bool {
	if len(id) < 2 || len(id) > 40 {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
		if !ok {
			return false
		}
	}
	return true
}

// RegisterNode creates a new node in the dependency graph.
func (e *Engine) RegisterNode(id, title, pkgRef string, owner, beneficiary address, height int64) (*Node, error) {
	if !ValidateID(id) {
		return nil, ErrInvalidID
	}
	if e.nodes.Has(id) {
		return nil, ErrNodeExists
	}
	if !owner.IsValid() || !beneficiary.IsValid() {
		return nil, ErrInvalidAddress
	}
	cleanTitle := strings.TrimSpace(title)
	if cleanTitle == "" {
		cleanTitle = id
	}
	n := &Node{
		ID:            id,
		Title:         cleanTitle,
		PkgRef:        strings.TrimSpace(pkgRef),
		Owner:         owner,
		Beneficiary:   beneficiary,
		CreatedHeight: height,
	}
	e.nodes.Set(id, n)
	return n, nil
}

// GetNode returns a node by ID, or nil if absent.
func (e *Engine) GetNode(id string) *Node {
	v := e.nodes.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Node)
}

// NodeCount returns the total number of registered nodes.
func (e *Engine) NodeCount() int {
	return e.nodes.Size()
}

// LockedCount returns how many nodes have cryptographically frozen splits.
func (e *Engine) LockedCount() int {
	return e.lockedCount
}

// TotalRouted returns cumulative ugnot routed across all deposits.
func (e *Engine) TotalRouted() int64 {
	return e.totalRouted
}

// TotalClaimed returns cumulative ugnot withdrawn by beneficiaries.
func (e *Engine) TotalClaimed() int64 {
	return e.totalClaimed
}

// EscrowedTotal returns total ugnot currently held pending claim across all addresses.
func (e *Engine) EscrowedTotal() int64 {
	return e.totalRouted - e.totalClaimed
}

// PendingOf returns the claimable balance for an address.
func (e *Engine) PendingOf(addr address) int64 {
	v := e.pending.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// ClaimedOf returns cumulative claimed amount for an address.
func (e *Engine) ClaimedOf(addr address) int64 {
	v := e.claimed.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// SetBeneficiary updates a node's beneficiary address (only when unlocked and called by owner).
func (e *Engine) SetBeneficiary(id string, caller, newBeneficiary address) error {
	n := e.GetNode(id)
	if n == nil {
		return ErrNodeNotFound
	}
	if n.Owner != caller {
		return ErrUnauthorized
	}
	if n.Locked {
		return ErrNodeLocked
	}
	if !newBeneficiary.IsValid() {
		return ErrInvalidAddress
	}
	n.Beneficiary = newBeneficiary
	return nil
}

// SetSplits atomically replaces the upstream dependency edges of node id.
// Enforces: owner auth, unlocked check, valid BPS (sum <= 10000), no duplicates,
// strict acyclicity (DFS), and bounded graph depth (<= MaxDepth).
func (e *Engine) SetSplits(id string, caller address, edges []Edge) error {
	n := e.GetNode(id)
	if n == nil {
		return ErrNodeNotFound
	}
	if n.Owner != caller {
		return ErrUnauthorized
	}
	if n.Locked {
		return ErrNodeLocked
	}
	if len(edges) > MaxEdgesPerNode {
		return ErrTooManyEdges
	}

	seen := make(map[string]bool, len(edges))
	var sumBPS int64
	cleaned := make([]Edge, 0, len(edges))

	for _, ed := range edges {
		if ed.BPS <= 0 || ed.BPS > ScaleBPS {
			return ErrInvalidBPS
		}
		if ed.TargetID == id {
			return ErrCycleDetected
		}
		if seen[ed.TargetID] {
			return ErrDuplicateEdge
		}
		target := e.GetNode(ed.TargetID)
		if target == nil {
			return ErrNodeNotFound
		}
		// Cycle check: if target can already reach id, adding id -> target creates a cycle.
		if e.canReach(ed.TargetID, id) {
			return ErrCycleDetected
		}
		seen[ed.TargetID] = true
		sumBPS += ed.BPS
		if sumBPS > ScaleBPS {
			return ErrInvalidBPS
		}
		cleaned = append(cleaned, Edge{
			TargetID: ed.TargetID,
			BPS:      ed.BPS,
			Label:    strings.TrimSpace(ed.Label),
		})
	}

	// Temporarily apply to check depth invariant across the full DAG, rollback if exceeded.
	prev := n.Edges
	n.Edges = cleaned
	if e.maxDepthFromAnyAncestor(id) > MaxDepth {
		n.Edges = prev
		return ErrMaxDepthExceeded
	}
	return nil
}

// Lock permanently freezes a node's beneficiary and upstream splits so downstream
// funders have an immutable on-chain guarantee that royalty shares cannot be rug-pulled.
func (e *Engine) Lock(id string, caller address) error {
	n := e.GetNode(id)
	if n == nil {
		return ErrNodeNotFound
	}
	if n.Owner != caller {
		return ErrUnauthorized
	}
	if n.Locked {
		return nil
	}
	n.Locked = true
	e.lockedCount++
	return nil
}

// canReach reports whether start can reach goal along directed upstream edges.
func (e *Engine) canReach(start, goal string) bool {
	visited := make(map[string]bool)
	stack := []string{start}
	for len(stack) > 0 {
		cur := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if cur == goal {
			return true
		}
		if visited[cur] {
			continue
		}
		visited[cur] = true
		node := e.GetNode(cur)
		if node == nil {
			continue
		}
		for _, ed := range node.Edges {
			if !visited[ed.TargetID] {
				stack = append(stack, ed.TargetID)
			}
		}
	}
	return false
}

// subgraphDepth computes longest directed path length starting at root.
func (e *Engine) subgraphDepth(root string, memo map[string]int) int {
	if d, ok := memo[root]; ok {
		return d
	}
	n := e.GetNode(root)
	if n == nil || len(n.Edges) == 0 {
		memo[root] = 0
		return 0
	}
	best := 0
	for _, ed := range n.Edges {
		d := 1 + e.subgraphDepth(ed.TargetID, memo)
		if d > best {
			best = d
		}
	}
	memo[root] = best
	return best
}

// maxDepthFromAnyAncestor checks longest chain passing through or rooted at any node
// that can reach changedID (keeps total DAG depth <= MaxDepth).
func (e *Engine) maxDepthFromAnyAncestor(changedID string) int {
	memo := make(map[string]int)
	best := e.subgraphDepth(changedID, memo)
	e.nodes.Iterate("", "", func(k string, _ any) bool {
		if k == changedID || e.canReach(k, changedID) {
			d := e.subgraphDepth(k, memo)
			if d > best {
				best = d
			}
		}
		return false
	})
	return best
}

// TopologicalOrder collects all nodes reachable from rootID in topological order
// (downstream before upstream), ensuring diamond-DAG convergence is exact in one pass.
func (e *Engine) TopologicalOrder(rootID string) []string {
	// Step 1: collect reachable subgraph and compute in-degrees within subgraph.
	reachable := make(map[string]bool)
	inDeg := make(map[string]int)
	queue := []string{rootID}
	reachable[rootID] = true
	inDeg[rootID] = 0

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		n := e.GetNode(cur)
		if n == nil {
			continue
		}
		for _, ed := range n.Edges {
			if !reachable[ed.TargetID] {
				reachable[ed.TargetID] = true
				queue = append(queue, ed.TargetID)
			}
			inDeg[ed.TargetID]++
		}
	}

	// Step 2: Kahn's algorithm with deterministic lexicographical tie-breaking.
	ready := make([]string, 0)
	for id := range reachable {
		if inDeg[id] == 0 {
			ready = append(ready, id)
		}
	}
	sort.Strings(ready)

	order := make([]string, 0, len(reachable))
	for len(ready) > 0 {
		cur := ready[0]
		ready = ready[1:]
		order = append(order, cur)
		n := e.GetNode(cur)
		if n == nil {
			continue
		}
		added := false
		for _, ed := range n.Edges {
			inDeg[ed.TargetID]--
			if inDeg[ed.TargetID] == 0 {
				ready = append(ready, ed.TargetID)
				added = true
			}
		}
		if added {
			sort.Strings(ready)
		}
	}
	return order
}

// Route cascades amount deterministically from entryID through its entire upstream DAG
// in topological order. Every single integer truncation remainder stays with the node's
// beneficiary so total credited == amount with ZERO dust ever lost.
func (e *Engine) Route(entryID string, depositor address, amount int64, height int64, memo string) (DepositReceipt, []TraceStep, error) {
	if amount <= 0 {
		return DepositReceipt{}, nil, ErrInvalidAmount
	}
	if e.GetNode(entryID) == nil {
		return DepositReceipt{}, nil, ErrNodeNotFound
	}

	order := e.TopologicalOrder(entryID)
	inflow := make(map[string]int64, len(order))
	inflow[entryID] = amount

	traces := make([]TraceStep, 0, len(order)*2)
	creditedAddrs := make(map[address]bool)
	hops := 0

	for _, id := range order {
		amt := inflow[id]
		if amt <= 0 {
			continue
		}
		n := e.GetNode(id)
		n.TotalInflow += amt

		var forwarded int64
		for _, ed := range n.Edges {
			share := (amt * ed.BPS) / ScaleBPS
			if share > 0 {
				inflow[ed.TargetID] += share
				forwarded += share
				hops++
				traces = append(traces, TraceStep{
					FromID: id,
					ToID:   ed.TargetID,
					Amount: share,
					BPS:    ed.BPS,
				})
			}
		}

		// Zero-dust conservation: any integer rounding remainder stays cleanly with n.Beneficiary.
		retained := amt - forwarded
		n.TotalForwarded += forwarded
		n.TotalRetained += retained

		if retained > 0 {
			e.credit(n.Beneficiary, retained)
			creditedAddrs[n.Beneficiary] = true
			traces = append(traces, TraceStep{
				FromID: id,
				ToID:   "",
				Amount: retained,
				BPS:    n.RetainedBPS(),
			})
		}
	}

	e.nextSeq++
	e.totalRouted += amount
	rcpt := DepositReceipt{
		Seq:       e.nextSeq,
		EntryID:   entryID,
		Depositor: depositor,
		Amount:    amount,
		Height:    height,
		Hops:      hops,
		Credits:   len(creditedAddrs),
		Memo:      strings.TrimSpace(memo),
	}
	e.receipts = append(e.receipts, rcpt)
	if len(e.receipts) > MaxReceiptsStored {
		e.receipts = e.receipts[len(e.receipts)-MaxReceiptsStored:]
	}
	return rcpt, traces, nil
}

// EffectiveShares simulates routing 10,000 BPS (100.00%) into rootID and returns
// the exact effective basis-point share received by every node in the DAG.
func (e *Engine) EffectiveShares(rootID string) []ShareEntry {
	if e.GetNode(rootID) == nil {
		return nil
	}
	order := e.TopologicalOrder(rootID)
	inflow := make(map[string]int64, len(order))
	inflow[rootID] = ScaleBPS

	out := make([]ShareEntry, 0, len(order))
	for _, id := range order {
		amt := inflow[id]
		n := e.GetNode(id)
		var forwarded int64
		for _, ed := range n.Edges {
			share := (amt * ed.BPS) / ScaleBPS
			inflow[ed.TargetID] += share
			forwarded += share
		}
		retained := amt - forwarded
		out = append(out, ShareEntry{
			NodeID:       n.ID,
			Title:        n.Title,
			Beneficiary:  n.Beneficiary,
			EffectiveBPS: retained,
		})
	}
	return out
}

// DeductClaim atomically zeroes addr's pending balance and records it as claimed.
// Call this BEFORE Banker.SendCoins to uphold strict Checks-Effects-Interactions.
func (e *Engine) DeductClaim(addr address) (int64, error) {
	if !addr.IsValid() {
		return 0, ErrInvalidAddress
	}
	amt := e.PendingOf(addr)
	if amt <= 0 {
		return 0, ErrNothingToClaim
	}
	key := addr.String()
	e.pending.Set(key, int64(0))
	e.claimed.Set(key, e.ClaimedOf(addr)+amt)
	e.totalClaimed += amt
	return amt, nil
}

// ListNodes returns all registered nodes in deterministic alphabetical order.
func (e *Engine) ListNodes() []*Node {
	out := make([]*Node, 0, e.nodes.Size())
	e.nodes.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*Node))
		return false
	})
	return out
}

// RecentReceipts returns stored deposit receipts (newest first).
func (e *Engine) RecentReceipts() []DepositReceipt {
	n := len(e.receipts)
	out := make([]DepositReceipt, n)
	for i := 0; i < n; i++ {
		out[i] = e.receipts[n-1-i]
	}
	return out
}

func (e *Engine) credit(addr address, amt int64) {
	key := addr.String()
	e.pending.Set(key, e.PendingOf(addr)+amt)
}

package tributary

import (
	"sort"

	"gno.land/p/nt/svg/v0"
	"gno.land/p/nt/ufmt/v0"
)

type nodePos struct {
	x int
	y int
}

// RenderGraphSVG builds a pure on-chain SVG dependency waterfall diagram for rootID
// using gno.land/p/nt/svg/v0, ready to embed directly in gnoweb Markdown.
func (e *Engine) RenderGraphSVG(rootID string) string {
	root := e.GetNode(rootID)
	if root == nil {
		return ""
	}

	order := e.TopologicalOrder(rootID)
	if len(order) == 0 {
		return ""
	}

	// Assign longest-path layer (column) to each node in the reachable subgraph.
	layer := make(map[string]int, len(order))
	maxLayer := 0
	for _, id := range order {
		curL := layer[id]
		if curL > maxLayer {
			maxLayer = curL
		}
		n := e.GetNode(id)
		for _, ed := range n.Edges {
			if layer[ed.TargetID] < curL+1 {
				layer[ed.TargetID] = curL + 1
			}
		}
	}

	columns := make([][]string, maxLayer+1)
	for _, id := range order {
		l := layer[id]
		columns[l] = append(columns[l], id)
	}
	maxRows := 1
	for i := range columns {
		sort.Strings(columns[i])
		if len(columns[i]) > maxRows {
			maxRows = len(columns[i])
		}
	}

	const (
		boxW    = 176
		boxH    = 64
		colGap  = 90
		rowGap  = 34
		padX    = 28
		padY    = 46
	)

	width := padX*2 + (maxLayer+1)*boxW + maxLayer*colGap
	if width < 560 {
		width = 560
	}
	height := padY*2 + maxRows*boxH + (maxRows-1)*rowGap + 24
	if height < 220 {
		height = 220
	}

	pos := make(map[string]nodePos, len(order))
	for c, col := range columns {
		colH := len(col)*boxH + (len(col)-1)*rowGap
		startY := padY + ((height - padY*2 - 20) - colH)/2
		if startY < padY {
			startY = padY
		}
		x := padX + c*(boxW+colGap)
		for r, id := range col {
			pos[id] = nodePos{
				x: x,
				y: startY + r*(boxH+rowGap),
			}
		}
	}

	canvas := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)

	// Dark obsidian backdrop
	bg := svg.NewRectangle(0, 0, width, height, "#0B1120")
	bg.RX = 12
	bg.RY = 12
	bg.Attr.Stroke = "#1E293B"
	bg.Attr.StrokeWidth = "2"
	canvas.Append(bg)

	// Header banner text
	hdr := svg.NewText(24, 28, "TRIBUTARY WATERFALL DAG :: "+root.Title, "#38BDF8")
	hdr.Attr.Style = "font-family:monospace;font-size:13px;font-weight:bold"
	canvas.Append(hdr)

	sub := svg.NewText(width-24, 28, ufmt.Sprintf("Routed: %d ugnot", root.TotalInflow), "#10B981")
	sub.Attr.Style = "font-family:monospace;font-size:12px;text-anchor:end"
	canvas.Append(sub)

	// Draw directed cubic Bezier flow pipes first (underneath nodes)
	for _, id := range order {
		n := e.GetNode(id)
		from := pos[id]
		x1 := from.x + boxW
		y1 := from.y + boxH/2
		for _, ed := range n.Edges {
			to := pos[ed.TargetID]
			x2 := to.x
			y2 := to.y + boxH/2
			mx := (x1 + x2) / 2

			strokeW := 2
			if ed.BPS >= 2500 {
				strokeW = 4
			} else if ed.BPS >= 1000 {
				strokeW = 3
			}

			d := ufmt.Sprintf("M %d %d C %d %d, %d %d, %d %d", x1, y1, mx, y1, mx, y2, x2, y2)
			pipe := svg.NewPath(d, "none")
			pipe.Attr.Stroke = "#22D3EE"
			pipe.Attr.StrokeWidth = ufmt.Sprintf("%d", strokeW)
			pipe.Attr.Opacity = "0.78"
			canvas.Append(pipe)

			// Arrow dot at target ingress
			dot := svg.NewCircle(x2, y2, 4, "#10B981")
			canvas.Append(dot)

			// Percentage pill at midpoint
			lblX := mx
			lblY := (y1+y2)/2 - 6
			pill := svg.NewRectangle(lblX-24, lblY-11, 48, 16, "#0F172A")
			pill.RX = 4
			pill.RY = 4
			pill.Attr.Stroke = "#22D3EE"
			pill.Attr.StrokeWidth = "1"
			canvas.Append(pill)

			pct := svg.NewText(lblX, lblY+1, formatBPS(ed.BPS), "#E0F2FE")
			pct.Attr.Style = "font-family:monospace;font-size:10px;text-anchor:middle"
			canvas.Append(pct)
		}
	}

	// Draw node cards on top
	for _, id := range order {
		n := e.GetNode(id)
		p := pos[id]

		fill := "#111827"
		stroke := "#38BDF8"
		if id == rootID {
			fill = "#0F2942"
			stroke = "#22D3EE"
		} else if len(n.Edges) == 0 {
			fill = "#0D2622"
			stroke = "#10B981"
		}

		card := svg.NewRectangle(p.x, p.y, boxW, boxH, fill)
		card.RX = 8
		card.RY = 8
		card.Attr.Stroke = stroke
		card.Attr.StrokeWidth = "2"
		canvas.Append(card)

		title := trimLabel(n.Title, 20)
		if n.Locked {
			title = title + " [LOCK]"
		}
		t1 := svg.NewText(p.x+10, p.y+21, title, "#F8FAFC")
		t1.Attr.Style = "font-family:monospace;font-size:11px;font-weight:bold"
		canvas.Append(t1)

		t2 := svg.NewText(p.x+10, p.y+39, ufmt.Sprintf("keep %s | fwd %s", formatBPS(n.RetainedBPS()), formatBPS(n.ForwardedBPS())), "#94A3B8")
		t2.Attr.Style = "font-family:monospace;font-size:10px"
		canvas.Append(t2)

		t3 := svg.NewText(p.x+10, p.y+54, ufmt.Sprintf("earned: %d ugnot", n.TotalRetained), "#34D399")
		t3.Attr.Style = "font-family:monospace;font-size:10px"
		canvas.Append(t3)
	}

	// Footer legend
	foot := svg.NewText(24, height-12, "Blue: Entry Realm  |  Slate: Midstream Lib  |  Green: Upstream Leaf  |  Zero-Dust Integer Conservation", "#64748B")
	foot.Attr.Style = "font-family:monospace;font-size:10px"
	canvas.Append(foot)

	return canvas.Render("Tributary DAG: " + root.ID)
}

func formatBPS(bps int64) string {
	whole := bps / 100
	frac := bps % 100
	if frac == 0 {
		return ufmt.Sprintf("%d%%", whole)
	}
	if frac < 10 {
		return ufmt.Sprintf("%d.0%d%%", whole, frac)
	}
	return ufmt.Sprintf("%d.%d%%", whole, frac)
}

func trimLabel(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-2] + ".."
}

package tributary

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func TestDiamondDAGZeroDustConservation(t *testing.T) {
	eng := NewEngine()
	aApp := testutils.TestAddress("app")
	aAuth := testutils.TestAddress("auth")
	aUI := testutils.TestAddress("ui")
	aCore := testutils.TestAddress("core")
	aDonor := testutils.TestAddress("donor")

	if _, err := eng.RegisterNode("core-crypto", "CoreCrypto", "gno.land/p/demo/core", aCore, aCore, 100); err != nil {
		t.Fatalf("register core: %v", err)
	}
	if _, err := eng.RegisterNode("auth-lib", "AuthLib", "gno.land/p/demo/auth", aAuth, aAuth, 101); err != nil {
		t.Fatalf("register auth: %v", err)
	}
	if _, err := eng.RegisterNode("ui-svg", "UISVG", "gno.land/p/demo/ui", aUI, aUI, 102); err != nil {
		t.Fatalf("register ui: %v", err)
	}
	if _, err := eng.RegisterNode("dex-app", "DexApp", "gno.land/r/demo/dex", aApp, aApp, 103); err != nil {
		t.Fatalf("register app: %v", err)
	}

	// Diamond DAG:
	// dex-app -> 20% auth-lib, 15% ui-svg (keeps 65%)
	// auth-lib -> 30% core-crypto (keeps 70%)
	// ui-svg -> 20% core-crypto (keeps 80%)
	if err := eng.SetSplits("auth-lib", aAuth, []Edge{{TargetID: "core-crypto", BPS: 3000, Label: "hashing"}}); err != nil {
		t.Fatalf("splits auth: %v", err)
	}
	if err := eng.SetSplits("ui-svg", aUI, []Edge{{TargetID: "core-crypto", BPS: 2000, Label: "math"}}); err != nil {
		t.Fatalf("splits ui: %v", err)
	}
	if err := eng.SetSplits("dex-app", aApp, []Edge{
		{TargetID: "auth-lib", BPS: 2000, Label: "auth"},
		{TargetID: "ui-svg", BPS: 1500, Label: "render"},
	}); err != nil {
		t.Fatalf("splits app: %v", err)
	}

	// Deposit a prime number to stress-test zero-dust integer conservation!
	const deposit int64 = 999997
	rcpt, traces, err := eng.Route("dex-app", aDonor, deposit, 200, "launch fees")
	if err != nil {
		t.Fatalf("route: %v", err)
	}
	if rcpt.Amount != deposit || rcpt.Credits != 4 || rcpt.Hops != 4 {
		t.Fatalf("unexpected receipt: %+v", rcpt)
	}
	if len(traces) < 6 {
		t.Fatalf("expected >= 6 trace steps, got %d", len(traces))
	}

	totalPending := eng.PendingOf(aApp) + eng.PendingOf(aAuth) + eng.PendingOf(aUI) + eng.PendingOf(aCore)
	if totalPending != deposit {
		t.Fatalf("ZERO-DUST VIOLATION: sum(pending)=%d != deposit=%d", totalPending, deposit)
	}

	// Verify core-crypto received contributions from BOTH auth-lib (6%) and ui-svg (3%) = ~9% (~89,998 ugnot)
	coreGot := eng.PendingOf(aCore)
	if coreGot < 89990 || coreGot > 90010 {
		t.Fatalf("expected core-crypto ~90000 ugnot from diamond convergence, got %d", coreGot)
	}

	// Claim and verify accounting
	claimed, err := eng.DeductClaim(aCore)
	if err != nil || claimed != coreGot {
		t.Fatalf("deduct claim: got %d, %v", claimed, err)
	}
	if eng.PendingOf(aCore) != 0 || eng.ClaimedOf(aCore) != coreGot {
		t.Fatalf("post-claim accounting mismatch")
	}
	if _, err := eng.DeductClaim(aCore); err != ErrNothingToClaim {
		t.Fatalf("expected ErrNothingToClaim on double claim, got %v", err)
	}

	// Verify effective shares sum to exactly 10,000 BPS
	shares := eng.EffectiveShares("dex-app")
	var sumEff int64
	for _, s := range shares {
		sumEff += s.EffectiveBPS
	}
	if sumEff != ScaleBPS {
		t.Fatalf("effective shares sum=%d != 10000", sumEff)
	}

	// Verify SVG rendering produces a valid data URI image with node names
	svgMD := eng.RenderGraphSVG("dex-app")
	if !strings.HasPrefix(svgMD, "![Tributary DAG: dex-app](data:image/svg+xml;base64,") {
		t.Fatalf("unexpected SVG markdown prefix: %s", svgMD[:60])
	}
}

func TestCycleAndLockGuards(t *testing.T) {
	eng := NewEngine()
	u := testutils.TestAddress("owner")
	other := testutils.TestAddress("other")

	_, _ = eng.RegisterNode("n1", "N1", "", u, u, 1)
	_, _ = eng.RegisterNode("n2", "N2", "", u, u, 1)
	_, _ = eng.RegisterNode("n3", "N3", "", u, u, 1)

	// Self-loop rejected
	if err := eng.SetSplits("n1", u, []Edge{{TargetID: "n1", BPS: 1000}}); err != ErrCycleDetected {
		t.Fatalf("expected ErrCycleDetected on self-loop, got %v", err)
	}

	// Build n1 -> n2 -> n3
	if err := eng.SetSplits("n1", u, []Edge{{TargetID: "n2", BPS: 5000}}); err != nil {
		t.Fatalf("n1->n2 failed: %v", err)
	}
	if err := eng.SetSplits("n2", u, []Edge{{TargetID: "n3", BPS: 5000}}); err != nil {
		t.Fatalf("n2->n3 failed: %v", err)
	}

	// Indirect 3-node cycle n3 -> n1 MUST be rejected
	if err := eng.SetSplits("n3", u, []Edge{{TargetID: "n1", BPS: 1000}}); err != ErrCycleDetected {
		t.Fatalf("expected ErrCycleDetected on n3->n1, got %v", err)
	}

	// Unauthorized update rejected
	if err := eng.SetSplits("n1", other, []Edge{{TargetID: "n3", BPS: 1000}}); err != ErrUnauthorized {
		t.Fatalf("expected ErrUnauthorized, got %v", err)
	}

	// Over-10000 BPS rejected
	if err := eng.SetSplits("n1", u, []Edge{
		{TargetID: "n2", BPS: 6000},
		{TargetID: "n3", BPS: 5000},
	}); err != ErrInvalidBPS {
		t.Fatalf("expected ErrInvalidBPS, got %v", err)
	}

	// Lock freezes splits and beneficiary permanently
	if err := eng.Lock("n1", u); err != nil {
		t.Fatalf("lock failed: %v", err)
	}
	if err := eng.SetSplits("n1", u, nil); err != ErrNodeLocked {
		t.Fatalf("expected ErrNodeLocked after lock, got %v", err)
	}
	if err := eng.SetBeneficiary("n1", u, other); err != ErrNodeLocked {
		t.Fatalf("expected ErrNodeLocked on beneficiary change, got %v", err)
	}
}

func TestMaxDepthGuard(t *testing.T) {
	eng := NewEngine()
	u := testutils.TestAddress("owner")

	// Create 10 nodes d0..d9 (depth 9 exceeds MaxDepth=8)
	ids := []string{"d0", "d1", "d2", "d3", "d4", "d5", "d6", "d7", "d8", "d9"}
	for _, id := range ids {
		if _, err := eng.RegisterNode(id, id, "", u, u, 1); err != nil {
			t.Fatalf("register %s: %v", id, err)
		}
	}
	for i := 0; i < 8; i++ {
		if err := eng.SetSplits(ids[i], u, []Edge{{TargetID: ids[i+1], BPS: 5000}}); err != nil {
			t.Fatalf("edge %d->%d failed: %v", i, i+1, err)
		}
	}
	// Adding the 9th hop must fail with ErrMaxDepthExceeded
	if err := eng.SetSplits("d8", u, []Edge{{TargetID: "d9", BPS: 5000}}); err != ErrMaxDepthExceeded {
		t.Fatalf("expected ErrMaxDepthExceeded at depth 9, got %v", err)
	}
}

package tributary

const (
	// ScaleBPS is 100.00% expressed in basis points.
	ScaleBPS int64 = 10000
	// MaxEdgesPerNode bounds fan-out per node for deterministic gas usage.
	MaxEdgesPerNode = 12
	// MaxDepth bounds DAG traversal depth to guarantee bounded execution.
	MaxDepth = 8
	// MaxReceiptsStored keeps recent deposit trace history bounded on-chain.
	MaxReceiptsStored = 25
)

// Edge defines a directed revenue-sharing split from a downstream node
// to an upstream dependency node.
type Edge struct {
	TargetID string
	BPS      int64 // 1..10000 (100 BPS = 1.00%)
	Label    string
}

// Node represents a package, realm, creator, or collective inside the DAG.
type Node struct {
	ID             string
	Title          string
	PkgRef         string
	Owner          address
	Beneficiary    address
	Edges          []Edge
	Locked         bool
	TotalInflow    int64
	TotalRetained  int64
	TotalForwarded int64
	CreatedHeight  int64
}

// TraceStep records one exact integer transfer along the waterfall during a deposit.
type TraceStep struct {
	FromID string
	ToID   string // empty when retained by FromID's beneficiary
	Amount int64
	BPS    int64
}

// DepositReceipt captures an auditable summary of one routed deposit.
type DepositReceipt struct {
	Seq       int64
	EntryID   string
	Depositor address
	Amount    int64
	Height    int64
	Hops      int
	Credits   int // distinct beneficiaries credited
	Memo      string
}

// ShareEntry summarizes the effective end-to-end share a beneficiary receives
// per 10,000 BPS deposited into a given root node.
type ShareEntry struct {
	NodeID      string
	Title       string
	Beneficiary address
	EffectiveBPS int64
}

// ForwardedBPS returns the sum of all outgoing split basis points for this node.
func (n *Node) ForwardedBPS() int64 {
	var sum int64
	for _, e := range n.Edges {
		sum += e.BPS
	}
	return sum
}

// RetainedBPS returns the share kept directly by this node's beneficiary.
func (n *Node) RetainedBPS() int64 {
	return ScaleBPS - n.ForwardedBPS()
}

package tributary

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	ptrib "gno.land/p/g196fz02krdlf6fc7a7p2w8e4rkywepwn5c9nh63/tributary"
)

const denom = "ugnot"

var engine = ptrib.NewEngine()

// Register creates a new waterfall node owned by the direct caller.
// If beneficiary is empty, defaults to caller's address.
func Register(cur realm, id, title, pkgRef string, beneficiary address) {
	caller := cur.Previous().Address()
	if beneficiary == "" {
		beneficiary = caller
	}
	if _, err := engine.RegisterNode(id, title, pkgRef, caller, beneficiary, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("TributaryRegister",
		"id", id,
		"owner", caller.String(),
		"beneficiary", beneficiary.String(),
		"pkgRef", pkgRef,
	)
}

// SetSplits configures upstream dependencies for node id using compact spec syntax:
//
//	"targetA:2000:auth,targetB:1500:ui"
//
// where BPS is 1..10000 (100 = 1.00%) and label is optional.
// Empty spec clears all outgoing splits. Rejects cycles, >10000 BPS, locked nodes, and >8 hops.
func SetSplits(cur realm, id, splitsSpec string) {
	caller := cur.Previous().Address()
	edges, err := parseSplitsSpec(splitsSpec)
	if err != nil {
		panic(err.Error())
	}
	if err := engine.SetSplits(id, caller, edges); err != nil {
		panic(err.Error())
	}
	chain.Emit("TributarySplitsUpdated",
		"id", id,
		"owner", caller.String(),
		"edges", strconv.Itoa(len(edges)),
	)
}

// SetBeneficiary updates the payout address of an unlocked node.
func SetBeneficiary(cur realm, id string, newBeneficiary address) {
	caller := cur.Previous().Address()
	if err := engine.SetBeneficiary(id, caller, newBeneficiary); err != nil {
		panic(err.Error())
	}
	chain.Emit("TributaryBeneficiaryUpdated",
		"id", id,
		"beneficiary", newBeneficiary.String(),
	)
}

// Lock permanently freezes a node's upstream splits and beneficiary so donors
// and downstream realms get an immutable on-chain guarantee against rug-pulls.
func Lock(cur realm, id string) {
	caller := cur.Previous().Address()
	if err := engine.Lock(id, caller); err != nil {
		panic(err.Error())
	}
	chain.Emit("TributaryLocked",
		"id", id,
		"owner", caller.String(),
	)
}

// Deposit routes attached ugnot deterministically through nodeID's entire upstream
// dependency DAG in topological order with zero-dust integer conservation.
// Paired Gno v1.8.0 security guard: requires direct EOA call (IsUserCall) so
// OriginSend is guaranteed to have landed at this realm's escrow address.
func Deposit(cur realm, nodeID, memo string) {
	if !cur.Previous().IsUserCall() {
		panic("tributary: Deposit requires a direct user call (use DepositWithBanker from realms)")
	}
	amt := unsafe.OriginSend().AmountOf(denom)
	if amt <= 0 {
		panic("tributary: attach positive ugnot coins to Deposit")
	}
	caller := cur.Previous().Address()
	rcpt, _, err := engine.Route(nodeID, caller, amt, runtime.ChainHeight(), memo)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("TributaryDeposit",
		"seq", strconv.FormatInt(rcpt.Seq, 10),
		"entry", nodeID,
		"depositor", caller.String(),
		"amount", strconv.FormatInt(amt, 10),
		"hops", strconv.Itoa(rcpt.Hops),
		"credits", strconv.Itoa(rcpt.Credits),
	)
}

// DepositWithBanker lets another Gno realm forward ugnot programmatically into
// any Tributary DAG using its canonical RealmSend banker (checked via banker.IsCanonical).
func DepositWithBanker(cur realm, nodeID, memo string, senderBanker banker.Banker, amt int64) {
	if !banker.IsCanonical(senderBanker) {
		panic("tributary: non-canonical banker rejected")
	}
	if amt <= 0 {
		panic("tributary: amount must be positive")
	}
	caller := cur.Previous().Address()
	// Pull coins from caller realm into Tributary escrow before crediting ledger.
	senderBanker.SendCoins(caller, cur.Address(), chain.NewCoins(chain.NewCoin(denom, amt)))
	rcpt, _, err := engine.Route(nodeID, caller, amt, runtime.ChainHeight(), memo)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("TributaryDeposit",
		"seq", strconv.FormatInt(rcpt.Seq, 10),
		"entry", nodeID,
		"depositor", caller.String(),
		"amount", strconv.FormatInt(amt, 10),
		"hops", strconv.Itoa(rcpt.Hops),
		"credits", strconv.Itoa(rcpt.Credits),
	)
}

// Claim withdraws all pending ugnot accrued to the caller across every upstream
// and downstream graph they participate in. Strictly follows Checks-Effects-Interactions.
func Claim(cur realm) int64 {
	caller := cur.Previous().Address()
	return claimFor(cur, caller)
}

// ClaimFor permissionlessly flushes a beneficiary's accrued ugnot directly to
// their own address (useful for keepers or sponsors paying gas for maintainers).
func ClaimFor(cur realm, beneficiary address) int64 {
	return claimFor(cur, beneficiary)
}

func claimFor(cur realm, beneficiary address) int64 {
	// Effects BEFORE interaction (CEI): zero pending balance first.
	amt, err := engine.DeductClaim(beneficiary)
	if err != nil {
		panic(err.Error())
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), beneficiary, chain.NewCoins(chain.NewCoin(denom, amt)))
	chain.Emit("TributaryClaim",
		"beneficiary", beneficiary.String(),
		"amount", strconv.FormatInt(amt, 10),
	)
	return amt
}

// Read-only query helpers for off-chain indexers, RPC clients, and tests.
func PendingBalance(addr address) int64 { return engine.PendingOf(addr) }
func ClaimedBalance(addr address) int64 { return engine.ClaimedOf(addr) }
func TotalRouted() int64                { return engine.TotalRouted() }
func TotalClaimed() int64               { return engine.TotalClaimed() }
func NodeCount() int                    { return engine.NodeCount() }
func LockedCount() int                  { return engine.LockedCount() }

func parseSplitsSpec(spec string) ([]ptrib.Edge, error) {
	trimmed := strings.TrimSpace(spec)
	if trimmed == "" {
		return nil, nil
	}
	parts := strings.Split(trimmed, ",")
	edges := make([]ptrib.Edge, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		fields := strings.Split(part, ":")
		if len(fields) < 2 || len(fields) > 3 {
			return nil, ptrib.ErrInvalidBPS
		}
		bps, err := strconv.ParseInt(strings.TrimSpace(fields[1]), 10, 64)
		if err != nil {
			return nil, ptrib.ErrInvalidBPS
		}
		lbl := ""
		if len(fields) == 3 {
			lbl = strings.TrimSpace(fields[2])
		}
		edges = append(edges, ptrib.Edge{
			TargetID: strings.TrimSpace(fields[0]),
			BPS:      bps,
			Label:    lbl,
		})
	}
	return edges, nil
}

package tributary

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
