	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	rtrib "gno.land/r/g196fz02krdlf6fc7a7p2w8e4rkywepwn5c9nh63/tributary"
)

func TestCrossRealmDepositWithBanker(cur realm, t *testing.T) {
	aApp := testutils.TestAddress("demo_app")
	aCore := testutils.TestAddress("demo_core")
	aTrader := testutils.TestAddress("demo_trader")

	demoAddr := chain.PackageAddress("gno.land/r/g196fz02krdlf6fc7a7p2w8e4rkywepwn5c9nh63/tributary_demo")

	// Set up a 2-node DAG in r/tributary: swap-ui -> 30% core-lib
	testing.SetRealm(testing.NewUserRealm(aCore))
	testing.SetOriginCaller(aCore)
	rtrib.Register(cross(cur), "core-lib", "CoreLib", "gno.land/p/demo/core", aCore)

	testing.SetRealm(testing.NewUserRealm(aApp))
	testing.SetOriginCaller(aApp)
	rtrib.Register(cross(cur), "swap-ui", "SwapUI", "gno.land/r/demo/swap", aApp)
	rtrib.SetSplits(cross(cur), "swap-ui", "core-lib:3000:core")

	// Simulate user sending 100,000 ugnot to SwapDemo:
	// 10% (10,000 ugnot) streams cross-realm into r/tributary (7,000 app + 3,000 core), 90,000 refunded to trader!
	const sent int64 = 100000
	testing.IssueCoins(demoAddr, chain.NewCoins(chain.NewCoin(denom, sent)))
	testing.SetRealm(testing.NewUserRealm(aTrader))
	testing.SetOriginCaller(aTrader)
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(denom, sent)))

	fee := SwapDemo(cross(cur), "live cross-realm test")
	if fee != 10000 {
		t.Fatalf("fee=%d want 10000", fee)
	}

	ro := banker.NewReadonlyBanker()
	if bal := ro.GetCoin(aTrader, denom); bal != 90000 {
		t.Fatalf("trader refund=%d want 90000", bal)
	}
	if got := rtrib.PendingBalance(aApp); got != 7000 {
		t.Fatalf("app pending=%d want 7000", got)
	}
	if got := rtrib.PendingBalance(aCore); got != 3000 {
		t.Fatalf("core pending=%d want 3000", got)
	}

	out := Render("")
	if !strings.Contains(out, "Auto-Streamed to Upstream OSS DAG") || !strings.Contains(out, "10000 ugnot") {
		t.Fatalf("unexpected Render output: %s", out)
	}
}

package guardianvault

// VaultState 是金库的状态机。v1 只有两态，刻意保持单线：
//
//	ACTIVE ──RequestRecovery──▶ RECOVERING ──Execute──▶ ACTIVE（归属已转移）
//	   ▲                             │
//	   └──────CancelRecovery─────────┘
//
// 没有 PAUSED / FROZEN / DISPUTED。每多一态，就要多定义「谁能从这一态
// 走到哪一态」，而本项目的目标是把一条路径做对，不是把状态图铺满。
type VaultState int

const (
	ACTIVE VaultState = iota
	RECOVERING
)

// 参数边界。三条都是「不设就会静默失效」的类型，而不是锦上添花：
//
//   - WindowSecs 若允许 0，时间锁整层消失，否决权退化为与守护人抢速度；
//   - Guardians 若允许重复地址，threshold 可能高于去重后人数，
//     恢复在数学上永远不可达 —— 一次永久且无声的死锁；
//   - MaxGuardians 防的是「名单长到没法逐个核对」这种可用性陷阱。
const (
	MinWindowSecs = int64(3600)    // 1 小时
	MaxWindowSecs = int64(2592000) // 30 天
	MaxGuardians  = 10
)

// Vault 是一个金库的全部状态。
//
// 余额用内部 int64 记账，而不是持有 token 句柄或去问 banker —— 这不是
// 风格选择，而是唯一正确做法：同一 realm 下的所有 vault 共用一个 realm
// 地址，banker.GetCoin(realmAddr) 拿到的是合计值，无法区分单个 vault。
//
// 本类型在 /r/ 中声明，任何对外边界都不得以指针形式返回它。
type Vault struct {
	ID         int
	Owner      address
	BackupAddr address
	Guardians  []address
	Threshold  int
	WindowSecs int64
	Balance    int64 // ugnot

	State       VaultState
	Requestor   address
	RequestedAt int64 // unix 秒，取自 time.Now().Unix()
	Votes       []address

	RecoveryCount   int
	LastRecoveredAt int64
}

// vaults 是唯一的状态容器。未导出，外部只能经函数访问。
//
// ID == 索引，且只增不删（Execute 是重置不是删除），所以 vaults[id]
// 恒成立，mustGet 只需一次边界检查。省掉一张 map，也省掉「map 与 slice
// 不一致」这类状态 bug。
var vaults []*Vault

// mustGet 按 ID 取金库，越界即 panic。
func mustGet(id int) *Vault {
	if id < 0 || id >= len(vaults) {
		panic("no such vault")
	}
	return vaults[id]
}

// requireOwner 断言调用者是 owner。
// 身份只从 cur.Previous() 派生，从不接受地址参数。
func requireOwner(cur realm, v *Vault) {
	if cur.Previous().Address() != v.Owner {
		panic("caller is not the owner")
	}
}

// isGuardian 报告 addr 是否在该金库的守护人名单内。
func (v *Vault) isGuardian(addr address) bool {
	for _, g := range v.Guardians {
		if g == addr {
			return true
		}
	}
	return false
}

// hasVoted 报告 addr 是否已投过票。
// 投票按地址去重，因此名单里若出现重复地址，threshold 可能永不可达 ——
// 这正是 validateGuardians 必须去重的原因。
func (v *Vault) hasVoted(addr address) bool {
	for _, a := range v.Votes {
		if a == addr {
			return true
		}
	}
	return false
}

// validateGuardians 校验守护人名单与阈值。
//
// 阈值是调用方给的自由参数，只约束「凑得满」，不按人数推导公式：多数派 /
// 2/3 / n-1 在 n=3 上都是 2，公式在最常用的配置上没有任何收益，却在 n=2 时
// 要求全票（一人失联即死锁）、n=5 时要求 4 票（形同不可用）。取舍理由见
// README §3 与 OPEN-QUESTIONS D8。这里只守两条硬线：区间合法、名单去重。
//
// 去重是这里最要紧的一条：投票按地址去重（hasVoted），若名单含重复地址
// 且 threshold 高于去重后人数，恢复将永远凑不满票 —— 金库永久死锁，
// 且创建时不会有任何报错，只有真出事那天才暴露。
func validateGuardians(guardians []address, threshold int) {
	n := len(guardians)
	if n < 1 || n > MaxGuardians {
		panic("guardian count must be 1..10")
	}
	if threshold < 1 || threshold > n {
		panic("threshold must be within 1..len(guardians)")
	}
	for i := 0; i < n; i++ {
		if guardians[i] == address("") {
			panic("guardian must not be zero address")
		}
		for j := i + 1; j < n; j++ {
			if guardians[i] == guardians[j] {
				panic("duplicate guardian address")
			}
		}
	}
}

// validateWindow 校验恢复窗口长度。
// 下限 1 小时、上限 30 天：0 会让时间锁整体失效，过长则守护人自己也记不住。
func validateWindow(windowSecs int64) {
	if windowSecs < MinWindowSecs || windowSecs > MaxWindowSecs {
		panic("windowSecs must be within 3600..2592000")
	}
}

package guardianvault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// receivedUgnot 读取「本次交易实际付给本 realm」的 ugnot 数量。
//
// 守卫只需一条，但选哪一条是经过实测比较的，不是随手取一个：
//
//	cur.Previous().IsUserCall() —— 要求上一跳是纯 EOA（PkgPath == ""）。
//
// 它挡住两类攻击：
//   - 中间 realm 代为转发：信封可能已被中间层消费，而本 realm 仍看到原金额；
//   - MsgRun 的临时 realm（PkgPath = <domain>/e/<addr>/run，非空）。
//
// 为什么不用 IsUser()：它同时接受上述临时 realm，正是要挡的载体之一。
//
// 为什么不用 runtime.AssertOriginCall()：它确实更强，还能挡住
// `var X = other.Deposit` 这类「消息的币记给 A、执行的代码属于 B」的
// 别名转发。但它在单元测试里与 cur.Previous() 互斥 —— AssertOriginCall
// 要求调用方是直接 MsgCall（测试里等价于非 cross 调用），而
// cur.Previous() 在非 cross 调用下会因 prev 为 truly-nil 而 panic。
// 二者不可兼得，而身份正确性（owner 归属）是本项目的承重设计，必须可测。
// 别名转发的前提是 realm 自身存在 `var X = other.Y` 的写法，本项目没有。
// 完整实测记录见 OPEN-QUESTIONS F16。
//
// 本文件是全项目唯一 import chain/runtime/unsafe 的地方。unsafe 在这里
// 只用于读信封金额，绝不用于派生身份 —— 身份一律来自 cur。
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payment must come from a direct EOA call")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// payUgnot 从本 realm 的地址转出 ugnot。
//
// 红线：banker 即用即弃。BankerTypeRealmSend 是对 realm 地址的**永久**
// 花钱授权，没有过期、没有撤销、也不重新检查活性。一旦把它存进状态、
// 当作参数传出、或作为返回值交给调用方，等于把 realm 地址上**所有**
// 金库的钱一次性交出去 —— 所有 vault 共用同一个 realm 地址。
//
// 因此：只在函数局部创建，只在本函数内使用，用完即弃。
func payUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package guardianvault

import "strconv"

// Render 是 gnoweb 的入口。path 是 realm 之后的 URL 路径：
//
//	""     → 索引页，列出所有金库
//	"<id>" → 单个金库的详情页
//
// 界面直接由状态算出，没有前端、没有缓存、没有第二份真相。
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	id, err := strconv.Atoi(path)
	if err != nil {
		return "# GuardianVault\n\nPath must be a vault ID, got `" + path + "`.\n"
	}
	return renderVault(id)
}

func renderIndex() string {
	out := "# GuardianVault\n\n"
	out += "A social-recovery vault: guardians can return your funds to the "
	out += "backup address you registered before losing your key — "
	out += "and can never send them anywhere else.\n\n"

	if len(vaults) == 0 {
		return out + "*No vaults yet.*\n"
	}

	out += "**Vaults:** " + strconv.Itoa(len(vaults)) + "\n\n"
	out += "| ID | Owner | Balance (ugnot) | State |\n"
	out += "| --- | --- | --- | --- |\n"
	for _, v := range vaults {
		out += "| [" + strconv.Itoa(v.ID) + "](" + strconv.Itoa(v.ID) + ") "
		out += "| `" + shortAddr(v.Owner) + "` "
		out += "| " + strconv.FormatInt(v.Balance, 10) + " "
		out += "| " + stateName(v.State) + " |\n"
	}
	return out
}

func renderVault(id int) string {
	if id < 0 || id >= len(vaults) {
		return "# Vault not found\n\nNo vault with ID " + strconv.Itoa(id) + ".\n"
	}
	v := vaults[id]

	out := "# Vault #" + strconv.Itoa(v.ID) + "\n\n"
	out += "| Field | Value |\n"
	out += "| --- | --- |\n"
	out += "| Owner | `" + v.Owner.String() + "` |\n"
	out += "| Backup address | `" + v.BackupAddr.String() + "` |\n"
	out += "| Balance | " + strconv.FormatInt(v.Balance, 10) + " ugnot |\n"
	out += "| State | " + stateName(v.State) + " |\n"
	out += "| Guardians | " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Threshold | " + strconv.Itoa(v.Threshold) + " of " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Recovery window | " + windowText(v.WindowSecs) + " |\n"
	out += "| Completed recoveries | " + strconv.Itoa(v.RecoveryCount) + " |\n"

	out += "\n## Guardians\n\n"
	for _, g := range v.Guardians {
		out += "- `" + g.String() + "`\n"
	}

	if v.State == RECOVERING {
		out += "\n## Recovery in progress\n\n"
		out += "| Field | Value |\n| --- | --- |\n"
		out += "| Requested by | `" + v.Requestor.String() + "` |\n"
		out += "| Votes | " + strconv.Itoa(len(v.Votes)) + " of " + strconv.Itoa(v.Threshold) + " required |\n"
	}

	return out
}

// stateName 把状态机取值转成可读文本。
func stateName(s VaultState) string {
	if s == ACTIVE {
		return "ACTIVE"
	}
	return "RECOVERING"
}

// windowText 把秒数转成可读时长。
//
// 不能简单地写 secs/3600 + " hours"：windowSecs 允许任意秒数（只限区间），
// 5400 秒会被截断显示成「1 hours」—— 界面上的数字与真实窗口不一致，
// 而恢复窗口正是用户判断「我还有多久能否决」的唯一依据。单数也不该写成
// 「1 hours」。
func windowText(secs int64) string {
	h := secs / 3600
	m := (secs % 3600) / 60
	s := secs % 60

	if m == 0 && s == 0 {
		if h == 1 {
			return "1 hour"
		}
		return strconv.FormatInt(h, 10) + " hours"
	}

	out := strconv.FormatInt(h, 10) + "h"
	if m > 0 {
		out += " " + strconv.FormatInt(m, 10) + "m"
	}
	if s > 0 {
		out += " " + strconv.FormatInt(s, 10) + "s"
	}
	return out
}

// shortAddr 把长地址压缩成 `g1abc…wxyz` 形式，用于表格列。
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package guardianvault

import "time"

// 本文件是全部对外 crossing 函数，也是唯一的鉴权点。
//
// 三条贯穿始终的规矩：
//   - 每个函数第一行都是 cur.IsCurrent()，挡「伪装成本 realm 的中间层」；
//   - 身份只从 cur.Previous().Address() 派生，没有任何函数接受地址参数来
//     识别调用者 —— 地址只作为数据出现；
//   - 校验全部前置，任何一条不满足都在写状态之前 panic，不留半成品。
//
// 共 10 个函数，按职责分四组：
//   - 创建：CreateVault
//   - 资金：Deposit / Withdraw
//   - 配置：AddGuardian / SetGuardians / SetBackup
//   - 恢复：RequestRecovery / Vote / CancelRecovery / Execute

// CreateVault 创建一个新金库，调用者成为 owner，返回金库 ID。
//
// 参数校验全部前置：任何一条不满足都不留下半成品状态。
// 校验项与 README §3 的接口表逐条对应，没有「顺手多校验」也没有遗漏。
//
// guardians 是变参且必须放在最后，这不是风格选择，是链上调用机制的硬约束：
// MsgCall 的参数转换只支持原生类型与 []byte，`[]address` 会直接 panic
// （unexpected slice type in contract arg），用户用 gnokey / gnoweb 都调不动。
// 改用变参后，重复传入的 `-args` 正好对应变参列表，实测可用。
// 详见 OPEN-QUESTIONS F12 / F13。
func CreateVault(cur realm, threshold int, backup address, windowSecs int64, guardians ...address) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}

	owner := cur.Previous().Address()
	if owner == address("") {
		panic("owner must not be zero address")
	}
	validateGuardians(guardians, threshold)
	if backup == address("") {
		panic("backup address must not be zero")
	}
	validateWindow(windowSecs)

	// 复制入参 slice。调用方仍持有底层数组，若直接存引用，
	// 它可以在创建后改动名单，绕过「守护人名单变更需走 SetGuardians」。
	g := make([]address, len(guardians))
	copy(g, guardians)

	id := len(vaults)
	vaults = append(vaults, &Vault{
		ID:         id,
		Owner:      owner,
		BackupAddr: backup,
		Guardians:  g,
		Threshold:  threshold,
		WindowSecs: windowSecs,
		State:      ACTIVE,
	})
	return id
}

// Deposit 把本次交易附带的 ugnot 记入金库。
//
// 金额不是参数，只取自交易信封 —— 这样「存多少」由链上实际转账决定，
// 不存在「声称存了 100 实际转了 0」的空间。
func Deposit(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	amt := receivedUgnot(cur)
	if amt <= 0 {
		panic("no ugnot sent")
	}
	v.Balance += amt
}

// Withdraw 由 owner 取回 ugnot。
//
// 这是 D1 补上的出口：没有它，一个金库只能在「假装丢私钥、走一遍恢复」
// 之后才能取出钱，那不叫钱包。
//
// 恢复期间（RECOVERING）禁止取款：否则 owner 可以在守护人已经投满票之后
// 把余额转空，让 Execute 变成一次空转 —— 投票结果就必须被执行，不能因为
// 主人临时改主意而作废。
func Withdraw(cur realm, id int, to address, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if to == address("") {
		panic("recipient must not be zero address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > v.Balance {
		panic("insufficient balance")
	}

	// 先记账再转账。payUgnot 若 panic，整笔交易回滚，不会留下「钱出去了、
	// 账没减」的中间态；反过来写则多一个失败窗口。
	v.Balance -= amount
	payUgnot(cur, to, amount)
}

// AddGuardian 往名单末尾追加一个守护人，阈值不变。
//
// 为什么值得单独一条入口：建库时就把所有守护人凑齐，在现实中很难 ——
// 家人、朋友、同事的地址往往要陆续才拿得到，而 SetGuardians 要求一次性
// 交齐整份名单，中途加一个人就得把全部地址重新抄一遍，抄错一个就是一次
// 永久性配置错误。追加是高频操作，值得最省的那条路径。
//
// 为什么这条捷径不违反「阈值必须与名单共同提交」：追加只会让 N 变大、
// M 原地不动，因此 threshold <= N 依然成立 —— 它只会让「凑得满票」更
// 容易，绝不会更难。真正危险的方向是删除：把 N 减到低于 M 就是一次永久
// 死锁。所以删除与批量替换只走 SetGuardians（整体提交、整体校验），
// 增与减刻意不对称（OPEN-QUESTIONS D9）。
//
// 副作用提醒（已知且接受）：原本 M == N 的「全票」配置，加人之后会变成
// 「容错一人」。这是 owner 亲手点下这一笔的结果，不做二次确认 —— 链上
// 没有对话框，能做的只有把语义写清楚。
func AddGuardian(cur realm, id int, guardian address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if guardian == address("") {
		panic("guardian must not be zero address")
	}
	// 重复地址是这里唯一的死锁来源：投票按地址去重，名单里出现两个相同
	// 地址不会让票数变多，只会让 threshold 的可达性悄悄变差。
	if v.isGuardian(guardian) {
		panic("already a guardian")
	}
	if len(v.Guardians) >= MaxGuardians {
		panic("guardian count would exceed 10")
	}

	v.Guardians = append(v.Guardians, guardian)
}

// SetGuardians 整体替换守护人名单与阈值。
//
// 这是「批量 / 删除」的唯一入口：删除必须与新的阈值一起提交，否则
// threshold 可能高于剩余人数，恢复永远凑不满票。
func SetGuardians(cur realm, id int, threshold int, guardians ...address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	validateGuardians(guardians, threshold)

	g := make([]address, len(guardians))
	copy(g, guardians)
	v.Guardians = g
	v.Threshold = threshold
}

// SetBackup 替换备用地址。
//
// 允许改，是因为人可能换钱包、换设备；但恢复一旦开始就冻结 —— 否则
// 守护人可以在投票中途把目的地改到自己账上，第①层「目的地封闭」直接失效。
func SetBackup(cur realm, id int, backup address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if backup == address("") {
		panic("backup address must not be zero")
	}
	v.BackupAddr = backup
}

// RequestRecovery 开启恢复窗口，任何人可调。
//
// 为什么不是「仅守护人」：发现 owner 失联的第一个人未必是守护人，而发起
// 本身不产生任何权限增量 —— 它只把状态切到 RECOVERING、记下时间，真正
// 能改变归属的仍然是 M 票 + 窗口期满。多一道身份限制只会让流程更容易卡住。
//
// 发起者不会自动获得一票：投票是一条独立的、可审计的动作，藏在发起里会
// 让「谁真的投了票」变得含糊。
func RequestRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != ACTIVE {
		panic("vault is not active")
	}

	v.State = RECOVERING
	v.Requestor = cur.Previous().Address()
	v.RequestedAt = time.Now().Unix()
	v.Votes = nil
}

// Vote 由守护人投一票。
//
// 票数达到 threshold 后拒绝新票：让 Votes 恒 <= Threshold（不变量 I4），
// 也让「票够了」在界面上有确定含义，不会出现 5/3 这种读数。
func Vote(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	caller := cur.Previous().Address()
	if !v.isGuardian(caller) {
		panic("not a guardian")
	}
	if v.hasVoted(caller) {
		panic("already voted")
	}
	if len(v.Votes) >= v.Threshold {
		panic("enough votes already")
	}

	v.Votes = append(v.Votes, caller)
}

// CancelRecovery 由 owner 一票否决，回到 ACTIVE 并清空票数。
//
// 任何时刻可调、不需要理由：这是 owner 私钥还在手上时的唯一自保手段。
// 若给它加延迟或条件，等于把「抢跑」合法化。
func CancelRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	v.State = ACTIVE
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
}

// Execute 把余额付给 BackupAddr，并把所有权移交给它。
//
// 任何人可调，且不产生权限增量：目的地已在注册时锁死，阈值与窗口已满足，
// owner 也已经放弃了否决。限定调用者只会让「已经投过票的守护人」再多发
// 一笔交易来收尾。
//
// 执行完不是回到原样，而是回到「未配置」的初始态：守护人清空、阈值归零。
// 旧 owner 的私钥已经不可用，这些守护人继续挂在这个金库上没有任何意义；
// 新 owner 若想再受保护，需要自己重新 AddGuardian / SetGuardians。
func Execute(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}
	if len(v.Votes) < v.Threshold {
		panic("threshold not reached")
	}

	now := time.Now().Unix()
	if now < v.RequestedAt+v.WindowSecs {
		panic("recovery window has not elapsed")
	}

	amt := v.Balance
	v.Balance = 0
	// 余额为零时不碰 banker：一笔 0 ugnot 的转账没有意义，而跨账户的零额
	// 转账在某些实现下会被拒绝，白搭一次失败。
	if amt > 0 {
		payUgnot(cur, v.BackupAddr, amt)
	}

	v.Owner = v.BackupAddr
	v.Guardians = nil
	v.Threshold = 0
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
	v.State = ACTIVE

	v.RecoveryCount++
	v.LastRecoveredAt = now
}

package vault

// VaultState 是金库的状态机。v1 只有两态，刻意保持单线：
//
//	ACTIVE ──RequestRecovery──▶ RECOVERING ──Execute──▶ ACTIVE（归属已转移）
//	   ▲                             │
//	   └──────CancelRecovery─────────┘
//
// 没有 PAUSED / FROZEN / DISPUTED。每多一态，就要多定义「谁能从这一态
// 走到哪一态」，而本项目的目标是把一条路径做对，不是把状态图铺满。
type VaultState int

const (
	ACTIVE VaultState = iota
	RECOVERING
)

// 参数边界。三条都是「不设就会静默失效」的类型，而不是锦上添花：
//
//   - WindowSecs 若允许 0，时间锁整层消失，否决权退化为与守护人抢速度；
//   - Guardians 若允许重复地址，threshold 可能高于去重后人数，
//     恢复在数学上永远不可达 —— 一次永久且无声的死锁；
//   - MaxGuardians 防的是「名单长到没法逐个核对」这种可用性陷阱。
const (
	MinWindowSecs = int64(3600)    // 1 小时
	MaxWindowSecs = int64(2592000) // 30 天
	MaxGuardians  = 10
)

// Vault 是一个金库的全部状态。
//
// 余额用内部 int64 记账，而不是持有 token 句柄或去问 banker —— 这不是
// 风格选择，而是唯一正确做法：同一 realm 下的所有 vault 共用一个 realm
// 地址，banker.GetCoin(realmAddr) 拿到的是合计值，无法区分单个 vault。
//
// 本类型在 /r/ 中声明，任何对外边界都不得以指针形式返回它。
type Vault struct {
	ID         int
	Owner      address
	BackupAddr address
	Guardians  []address
	Threshold  int
	WindowSecs int64
	Balance    int64 // ugnot

	State       VaultState
	Requestor   address
	RequestedAt int64 // unix 秒，取自 time.Now().Unix()
	Votes       []address

	RecoveryCount   int
	LastRecoveredAt int64
}

// vaults 是唯一的状态容器。未导出，外部只能经函数访问。
//
// ID == 索引，且只增不删（Execute 是重置不是删除），所以 vaults[id]
// 恒成立，mustGet 只需一次边界检查。省掉一张 map，也省掉「map 与 slice
// 不一致」这类状态 bug。
var vaults []*Vault

// mustGet 按 ID 取金库，越界即 panic。
func mustGet(id int) *Vault {
	if id < 0 || id >= len(vaults) {
		panic("no such vault")
	}
	return vaults[id]
}

// requireOwner 断言调用者是 owner。
// 身份只从 cur.Previous() 派生，从不接受地址参数。
func requireOwner(cur realm, v *Vault) {
	if cur.Previous().Address() != v.Owner {
		panic("caller is not the owner")
	}
}

// isGuardian 报告 addr 是否在该金库的守护人名单内。
func (v *Vault) isGuardian(addr address) bool {
	for _, g := range v.Guardians {
		if g == addr {
			return true
		}
	}
	return false
}

// hasVoted 报告 addr 是否已投过票。
// 投票按地址去重，因此名单里若出现重复地址，threshold 可能永不可达 ——
// 这正是 validateGuardians 必须去重的原因。
func (v *Vault) hasVoted(addr address) bool {
	for _, a := range v.Votes {
		if a == addr {
			return true
		}
	}
	return false
}

// validateGuardians 校验守护人名单与阈值。
//
// 阈值是调用方给的自由参数，只约束「凑得满」，不按人数推导公式：多数派 /
// 2/3 / n-1 在 n=3 上都是 2，公式在最常用的配置上没有任何收益，却在 n=2 时
// 要求全票（一人失联即死锁）、n=5 时要求 4 票（形同不可用）。取舍理由见
// README §3 与 OPEN-QUESTIONS D8。这里只守两条硬线：区间合法、名单去重。
//
// 去重是这里最要紧的一条：投票按地址去重（hasVoted），若名单含重复地址
// 且 threshold 高于去重后人数，恢复将永远凑不满票 —— 金库永久死锁，
// 且创建时不会有任何报错，只有真出事那天才暴露。
func validateGuardians(guardians []address, threshold int) {
	n := len(guardians)
	if n < 1 || n > MaxGuardians {
		panic("guardian count must be 1..10")
	}
	if threshold < 1 || threshold > n {
		panic("threshold must be within 1..len(guardians)")
	}
	for i := 0; i < n; i++ {
		if guardians[i] == address("") {
			panic("guardian must not be zero address")
		}
		for j := i + 1; j < n; j++ {
			if guardians[i] == guardians[j] {
				panic("duplicate guardian address")
			}
		}
	}
}

// validateWindow 校验恢复窗口长度。
// 下限 1 小时、上限 30 天：0 会让时间锁整体失效，过长则守护人自己也记不住。
func validateWindow(windowSecs int64) {
	if windowSecs < MinWindowSecs || windowSecs > MaxWindowSecs {
		panic("windowSecs must be within 3600..2592000")
	}
}

package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// receivedUgnot 读取「本次交易实际付给本 realm」的 ugnot 数量。
//
// 守卫只需一条，但选哪一条是经过实测比较的，不是随手取一个：
//
//	cur.Previous().IsUserCall() —— 要求上一跳是纯 EOA（PkgPath == ""）。
//
// 它挡住两类攻击：
//   - 中间 realm 代为转发：信封可能已被中间层消费，而本 realm 仍看到原金额；
//   - MsgRun 的临时 realm（PkgPath = <domain>/e/<addr>/run，非空）。
//
// 为什么不用 IsUser()：它同时接受上述临时 realm，正是要挡的载体之一。
//
// 为什么不用 runtime.AssertOriginCall()：它确实更强，还能挡住
// `var X = other.Deposit` 这类「消息的币记给 A、执行的代码属于 B」的
// 别名转发。但它在单元测试里与 cur.Previous() 互斥 —— AssertOriginCall
// 要求调用方是直接 MsgCall（测试里等价于非 cross 调用），而
// cur.Previous() 在非 cross 调用下会因 prev 为 truly-nil 而 panic。
// 二者不可兼得，而身份正确性（owner 归属）是本项目的承重设计，必须可测。
// 别名转发的前提是 realm 自身存在 `var X = other.Y` 的写法，本项目没有。
// 完整实测记录见 OPEN-QUESTIONS F16。
//
// 本文件是全项目唯一 import chain/runtime/unsafe 的地方。unsafe 在这里
// 只用于读信封金额，绝不用于派生身份 —— 身份一律来自 cur。
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payment must come from a direct EOA call")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// payUgnot 从本 realm 的地址转出 ugnot。
//
// 红线：banker 即用即弃。BankerTypeRealmSend 是对 realm 地址的**永久**
// 花钱授权，没有过期、没有撤销、也不重新检查活性。一旦把它存进状态、
// 当作参数传出、或作为返回值交给调用方，等于把 realm 地址上**所有**
// 金库的钱一次性交出去 —— 所有 vault 共用同一个 realm 地址。
//
// 因此：只在函数局部创建，只在本函数内使用，用完即弃。
func payUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package vault

import "strconv"

// Render 是 gnoweb 的入口。path 是 realm 之后的 URL 路径：
//
//	""     → 索引页，列出所有金库
//	"<id>" → 单个金库的详情页
//
// 界面直接由状态算出，没有前端、没有缓存、没有第二份真相。
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	id, err := strconv.Atoi(path)
	if err != nil {
		return "# GuardianVault\n\nPath must be a vault ID, got `" + path + "`.\n"
	}
	return renderVault(id)
}

func renderIndex() string {
	out := "# GuardianVault\n\n"
	out += "A social-recovery vault: guardians can return your funds to the "
	out += "backup address you registered before losing your key — "
	out += "and can never send them anywhere else.\n\n"

	if len(vaults) == 0 {
		return out + "*No vaults yet.*\n"
	}

	out += "**Vaults:** " + strconv.Itoa(len(vaults)) + "\n\n"
	out += "| ID | Owner | Balance (ugnot) | State |\n"
	out += "| --- | --- | --- | --- |\n"
	for _, v := range vaults {
		out += "| [" + strconv.Itoa(v.ID) + "](" + strconv.Itoa(v.ID) + ") "
		out += "| `" + shortAddr(v.Owner) + "` "
		out += "| " + strconv.FormatInt(v.Balance, 10) + " "
		out += "| " + stateName(v.State) + " |\n"
	}
	return out
}

func renderVault(id int) string {
	if id < 0 || id >= len(vaults) {
		return "# Vault not found\n\nNo vault with ID " + strconv.Itoa(id) + ".\n"
	}
	v := vaults[id]

	out := "# Vault #" + strconv.Itoa(v.ID) + "\n\n"
	out += "| Field | Value |\n"
	out += "| --- | --- |\n"
	out += "| Owner | `" + v.Owner.String() + "` |\n"
	out += "| Backup address | `" + v.BackupAddr.String() + "` |\n"
	out += "| Balance | " + strconv.FormatInt(v.Balance, 10) + " ugnot |\n"
	out += "| State | " + stateName(v.State) + " |\n"
	out += "| Guardians | " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Threshold | " + strconv.Itoa(v.Threshold) + " of " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Recovery window | " + windowText(v.WindowSecs) + " |\n"
	out += "| Completed recoveries | " + strconv.Itoa(v.RecoveryCount) + " |\n"

	out += "\n## Guardians\n\n"
	for _, g := range v.Guardians {
		out += "- `" + g.String() + "`\n"
	}

	if v.State == RECOVERING {
		out += "\n## Recovery in progress\n\n"
		out += "| Field | Value |\n| --- | --- |\n"
		out += "| Requested by | `" + v.Requestor.String() + "` |\n"
		out += "| Votes | " + strconv.Itoa(len(v.Votes)) + " of " + strconv.Itoa(v.Threshold) + " required |\n"
	}

	return out
}

// stateName 把状态机取值转成可读文本。
func stateName(s VaultState) string {
	if s == ACTIVE {
		return "ACTIVE"
	}
	return "RECOVERING"
}

// windowText 把秒数转成可读时长。
//
// 不能简单地写 secs/3600 + " hours"：windowSecs 允许任意秒数（只限区间），
// 5400 秒会被截断显示成「1 hours」—— 界面上的数字与真实窗口不一致，
// 而恢复窗口正是用户判断「我还有多久能否决」的唯一依据。单数也不该写成
// 「1 hours」。
func windowText(secs int64) string {
	h := secs / 3600
	m := (secs % 3600) / 60
	s := secs % 60

	if m == 0 && s == 0 {
		if h == 1 {
			return "1 hour"
		}
		return strconv.FormatInt(h, 10) + " hours"
	}

	out := strconv.FormatInt(h, 10) + "h"
	if m > 0 {
		out += " " + strconv.FormatInt(m, 10) + "m"
	}
	if s > 0 {
		out += " " + strconv.FormatInt(s, 10) + "s"
	}
	return out
}

// shortAddr 把长地址压缩成 `g1abc…wxyz` 形式，用于表格列。
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package vault

import "time"

// 本文件是全部对外 crossing 函数，也是唯一的鉴权点。
//
// 三条贯穿始终的规矩：
//   - 每个函数第一行都是 cur.IsCurrent()，挡「伪装成本 realm 的中间层」；
//   - 身份只从 cur.Previous().Address() 派生，没有任何函数接受地址参数来
//     识别调用者 —— 地址只作为数据出现；
//   - 校验全部前置，任何一条不满足都在写状态之前 panic，不留半成品。
//
// 共 10 个函数，按职责分四组：
//   - 创建：CreateVault
//   - 资金：Deposit / Withdraw
//   - 配置：AddGuardian / SetGuardians / SetBackup
//   - 恢复：RequestRecovery / Vote / CancelRecovery / Execute

// CreateVault 创建一个新金库，调用者成为 owner，返回金库 ID。
//
// 参数校验全部前置：任何一条不满足都不留下半成品状态。
// 校验项与 README §3 的接口表逐条对应，没有「顺手多校验」也没有遗漏。
//
// guardians 是变参且必须放在最后，这不是风格选择，是链上调用机制的硬约束：
// MsgCall 的参数转换只支持原生类型与 []byte，`[]address` 会直接 panic
// （unexpected slice type in contract arg），用户用 gnokey / gnoweb 都调不动。
// 改用变参后，重复传入的 `-args` 正好对应变参列表，实测可用。
// 详见 OPEN-QUESTIONS F12 / F13。
func CreateVault(cur realm, threshold int, backup address, windowSecs int64, guardians ...address) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}

	owner := cur.Previous().Address()
	if owner == address("") {
		panic("owner must not be zero address")
	}
	validateGuardians(guardians, threshold)
	if backup == address("") {
		panic("backup address must not be zero")
	}
	validateWindow(windowSecs)

	// 复制入参 slice。调用方仍持有底层数组，若直接存引用，
	// 它可以在创建后改动名单，绕过「守护人名单变更需走 SetGuardians」。
	g := make([]address, len(guardians))
	copy(g, guardians)

	id := len(vaults)
	vaults = append(vaults, &Vault{
		ID:         id,
		Owner:      owner,
		BackupAddr: backup,
		Guardians:  g,
		Threshold:  threshold,
		WindowSecs: windowSecs,
		State:      ACTIVE,
	})
	return id
}

// Deposit 把本次交易附带的 ugnot 记入金库。
//
// 金额不是参数，只取自交易信封 —— 这样「存多少」由链上实际转账决定，
// 不存在「声称存了 100 实际转了 0」的空间。
func Deposit(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	amt := receivedUgnot(cur)
	if amt <= 0 {
		panic("no ugnot sent")
	}
	v.Balance += amt
}

// Withdraw 由 owner 取回 ugnot。
//
// 这是 D1 补上的出口：没有它，一个金库只能在「假装丢私钥、走一遍恢复」
// 之后才能取出钱，那不叫钱包。
//
// 恢复期间（RECOVERING）禁止取款：否则 owner 可以在守护人已经投满票之后
// 把余额转空，让 Execute 变成一次空转 —— 投票结果就必须被执行，不能因为
// 主人临时改主意而作废。
func Withdraw(cur realm, id int, to address, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if to == address("") {
		panic("recipient must not be zero address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > v.Balance {
		panic("insufficient balance")
	}

	// 先记账再转账。payUgnot 若 panic，整笔交易回滚，不会留下「钱出去了、
	// 账没减」的中间态；反过来写则多一个失败窗口。
	v.Balance -= amount
	payUgnot(cur, to, amount)
}

// AddGuardian 往名单末尾追加一个守护人，阈值不变。
//
// 为什么值得单独一条入口：建库时就把所有守护人凑齐，在现实中很难 ——
// 家人、朋友、同事的地址往往要陆续才拿得到，而 SetGuardians 要求一次性
// 交齐整份名单，中途加一个人就得把全部地址重新抄一遍，抄错一个就是一次
// 永久性配置错误。追加是高频操作，值得最省的那条路径。
//
// 为什么这条捷径不违反「阈值必须与名单共同提交」：追加只会让 N 变大、
// M 原地不动，因此 threshold <= N 依然成立 —— 它只会让「凑得满票」更
// 容易，绝不会更难。真正危险的方向是删除：把 N 减到低于 M 就是一次永久
// 死锁。所以删除与批量替换只走 SetGuardians（整体提交、整体校验），
// 增与减刻意不对称（OPEN-QUESTIONS D9）。
//
// 副作用提醒（已知且接受）：原本 M == N 的「全票」配置，加人之后会变成
// 「容错一人」。这是 owner 亲手点下这一笔的结果，不做二次确认 —— 链上
// 没有对话框，能做的只有把语义写清楚。
func AddGuardian(cur realm, id int, guardian address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if guardian == address("") {
		panic("guardian must not be zero address")
	}
	// 重复地址是这里唯一的死锁来源：投票按地址去重，名单里出现两个相同
	// 地址不会让票数变多，只会让 threshold 的可达性悄悄变差。
	if v.isGuardian(guardian) {
		panic("already a guardian")
	}
	if len(v.Guardians) >= MaxGuardians {
		panic("guardian count would exceed 10")
	}

	v.Guardians = append(v.Guardians, guardian)
}

// SetGuardians 整体替换守护人名单与阈值。
//
// 这是「批量 / 删除」的唯一入口：删除必须与新的阈值一起提交，否则
// threshold 可能高于剩余人数，恢复永远凑不满票。
func SetGuardians(cur realm, id int, threshold int, guardians ...address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	validateGuardians(guardians, threshold)

	g := make([]address, len(guardians))
	copy(g, guardians)
	v.Guardians = g
	v.Threshold = threshold
}

// SetBackup 替换备用地址。
//
// 允许改，是因为人可能换钱包、换设备；但恢复一旦开始就冻结 —— 否则
// 守护人可以在投票中途把目的地改到自己账上，第①层「目的地封闭」直接失效。
func SetBackup(cur realm, id int, backup address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if backup == address("") {
		panic("backup address must not be zero")
	}
	v.BackupAddr = backup
}

// RequestRecovery 开启恢复窗口，任何人可调。
//
// 为什么不是「仅守护人」：发现 owner 失联的第一个人未必是守护人，而发起
// 本身不产生任何权限增量 —— 它只把状态切到 RECOVERING、记下时间，真正
// 能改变归属的仍然是 M 票 + 窗口期满。多一道身份限制只会让流程更容易卡住。
//
// 发起者不会自动获得一票：投票是一条独立的、可审计的动作，藏在发起里会
// 让「谁真的投了票」变得含糊。
func RequestRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != ACTIVE {
		panic("vault is not active")
	}

	v.State = RECOVERING
	v.Requestor = cur.Previous().Address()
	v.RequestedAt = time.Now().Unix()
	v.Votes = nil
}

// Vote 由守护人投一票。
//
// 票数达到 threshold 后拒绝新票：让 Votes 恒 <= Threshold（不变量 I4），
// 也让「票够了」在界面上有确定含义，不会出现 5/3 这种读数。
func Vote(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	caller := cur.Previous().Address()
	if !v.isGuardian(caller) {
		panic("not a guardian")
	}
	if v.hasVoted(caller) {
		panic("already voted")
	}
	if len(v.Votes) >= v.Threshold {
		panic("enough votes already")
	}

	v.Votes = append(v.Votes, caller)
}

// CancelRecovery 由 owner 一票否决，回到 ACTIVE 并清空票数。
//
// 任何时刻可调、不需要理由：这是 owner 私钥还在手上时的唯一自保手段。
// 若给它加延迟或条件，等于把「抢跑」合法化。
func CancelRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	v.State = ACTIVE
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
}

// Execute 把余额付给 BackupAddr，并把所有权移交给它。
//
// 任何人可调，且不产生权限增量：目的地已在注册时锁死，阈值与窗口已满足，
// owner 也已经放弃了否决。限定调用者只会让「已经投过票的守护人」再多发
// 一笔交易来收尾。
//
// 执行完不是回到原样，而是回到「未配置」的初始态：守护人清空、阈值归零。
// 旧 owner 的私钥已经不可用，这些守护人继续挂在这个金库上没有任何意义；
// 新 owner 若想再受保护，需要自己重新 AddGuardian / SetGuardians。
func Execute(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}
	if len(v.Votes) < v.Threshold {
		panic("threshold not reached")
	}

	now := time.Now().Unix()
	if now < v.RequestedAt+v.WindowSecs {
		panic("recovery window has not elapsed")
	}

	amt := v.Balance
	v.Balance = 0
	// 余额为零时不碰 banker：一笔 0 ugnot 的转账没有意义，而跨账户的零额
	// 转账在某些实现下会被拒绝，白搭一次失败。
	if amt > 0 {
		payUgnot(cur, v.BackupAddr, amt)
	}

	v.Owner = v.BackupAddr
	v.Guardians = nil
	v.Threshold = 0
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
	v.State = ACTIVE

	v.RecoveryCount++
	v.LastRecoveredAt = now
}

package vault

// VaultState 是金库的状态机。v1 只有两态，刻意保持单线：
//
//	ACTIVE ──RequestRecovery──▶ RECOVERING ──Execute──▶ ACTIVE（归属已转移）
//	   ▲                             │
//	   └──────CancelRecovery─────────┘
//
// 没有 PAUSED / FROZEN / DISPUTED。每多一态，就要多定义「谁能从这一态
// 走到哪一态」，而本项目的目标是把一条路径做对，不是把状态图铺满。
type VaultState int

const (
	ACTIVE VaultState = iota
	RECOVERING
)

// 参数边界。三条都是「不设就会静默失效」的类型，而不是锦上添花：
//
//   - WindowSecs 若允许 0，时间锁整层消失，否决权退化为与守护人抢速度；
//   - Guardians 若允许重复地址，threshold 可能高于去重后人数，
//     恢复在数学上永远不可达 —— 一次永久且无声的死锁；
//   - MaxGuardians 防的是「名单长到没法逐个核对」这种可用性陷阱。
const (
	MinWindowSecs = int64(3600)    // 1 小时
	MaxWindowSecs = int64(2592000) // 30 天
	MaxGuardians  = 10
)

// Vault 是一个金库的全部状态。
//
// 余额用内部 int64 记账，而不是持有 token 句柄或去问 banker —— 这不是
// 风格选择，而是唯一正确做法：同一 realm 下的所有 vault 共用一个 realm
// 地址，banker.GetCoin(realmAddr) 拿到的是合计值，无法区分单个 vault。
//
// 本类型在 /r/ 中声明，任何对外边界都不得以指针形式返回它。
type Vault struct {
	ID         int
	Owner      address
	BackupAddr address
	Guardians  []address
	Threshold  int
	WindowSecs int64
	Balance    int64 // ugnot

	State       VaultState
	Requestor   address
	RequestedAt int64 // unix 秒，取自 time.Now().Unix()
	Votes       []address

	RecoveryCount   int
	LastRecoveredAt int64
}

// vaults 是唯一的状态容器。未导出，外部只能经函数访问。
//
// ID == 索引，且只增不删（Execute 是重置不是删除），所以 vaults[id]
// 恒成立，mustGet 只需一次边界检查。省掉一张 map，也省掉「map 与 slice
// 不一致」这类状态 bug。
var vaults []*Vault

// mustGet 按 ID 取金库，越界即 panic。
func mustGet(id int) *Vault {
	if id < 0 || id >= len(vaults) {
		panic("no such vault")
	}
	return vaults[id]
}

// requireOwner 断言调用者是 owner。
// 身份只从 cur.Previous() 派生，从不接受地址参数。
func requireOwner(cur realm, v *Vault) {
	if cur.Previous().Address() != v.Owner {
		panic("caller is not the owner")
	}
}

// isGuardian 报告 addr 是否在该金库的守护人名单内。
func (v *Vault) isGuardian(addr address) bool {
	for _, g := range v.Guardians {
		if g == addr {
			return true
		}
	}
	return false
}

// hasVoted 报告 addr 是否已投过票。
// 投票按地址去重，因此名单里若出现重复地址，threshold 可能永不可达 ——
// 这正是 validateGuardians 必须去重的原因。
func (v *Vault) hasVoted(addr address) bool {
	for _, a := range v.Votes {
		if a == addr {
			return true
		}
	}
	return false
}

// validateGuardians 校验守护人名单与阈值。
//
// 阈值是调用方给的自由参数，只约束「凑得满」，不按人数推导公式：多数派 /
// 2/3 / n-1 在 n=3 上都是 2，公式在最常用的配置上没有任何收益，却在 n=2 时
// 要求全票（一人失联即死锁）、n=5 时要求 4 票（形同不可用）。取舍理由见
// README §3 与 OPEN-QUESTIONS D8。这里只守两条硬线：区间合法、名单去重。
//
// 去重是这里最要紧的一条：投票按地址去重（hasVoted），若名单含重复地址
// 且 threshold 高于去重后人数，恢复将永远凑不满票 —— 金库永久死锁，
// 且创建时不会有任何报错，只有真出事那天才暴露。
func validateGuardians(guardians []address, threshold int) {
	n := len(guardians)
	if n < 1 || n > MaxGuardians {
		panic("guardian count must be 1..10")
	}
	if threshold < 1 || threshold > n {
		panic("threshold must be within 1..len(guardians)")
	}
	for i := 0; i < n; i++ {
		if guardians[i] == address("") {
			panic("guardian must not be zero address")
		}
		for j := i + 1; j < n; j++ {
			if guardians[i] == guardians[j] {
				panic("duplicate guardian address")
			}
		}
	}
}

// validateWindow 校验恢复窗口长度。
// 下限 1 小时、上限 30 天：0 会让时间锁整体失效，过长则守护人自己也记不住。
func validateWindow(windowSecs int64) {
	if windowSecs < MinWindowSecs || windowSecs > MaxWindowSecs {
		panic("windowSecs must be within 3600..2592000")
	}
}

package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// receivedUgnot 读取「本次交易实际付给本 realm」的 ugnot 数量。
//
// 守卫只需一条，但选哪一条是经过实测比较的，不是随手取一个：
//
//	cur.Previous().IsUserCall() —— 要求上一跳是纯 EOA（PkgPath == ""）。
//
// 它挡住两类攻击：
//   - 中间 realm 代为转发：信封可能已被中间层消费，而本 realm 仍看到原金额；
//   - MsgRun 的临时 realm（PkgPath = <domain>/e/<addr>/run，非空）。
//
// 为什么不用 IsUser()：它同时接受上述临时 realm，正是要挡的载体之一。
//
// 为什么不用 runtime.AssertOriginCall()：它确实更强，还能挡住
// `var X = other.Deposit` 这类「消息的币记给 A、执行的代码属于 B」的
// 别名转发。但它在单元测试里与 cur.Previous() 互斥 —— AssertOriginCall
// 要求调用方是直接 MsgCall（测试里等价于非 cross 调用），而
// cur.Previous() 在非 cross 调用下会因 prev 为 truly-nil 而 panic。
// 二者不可兼得，而身份正确性（owner 归属）是本项目的承重设计，必须可测。
// 别名转发的前提是 realm 自身存在 `var X = other.Y` 的写法，本项目没有。
// 完整实测记录见 OPEN-QUESTIONS F16。
//
// 本文件是全项目唯一 import chain/runtime/unsafe 的地方。unsafe 在这里
// 只用于读信封金额，绝不用于派生身份 —— 身份一律来自 cur。
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payment must come from a direct EOA call")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// payUgnot 从本 realm 的地址转出 ugnot。
//
// 红线：banker 即用即弃。BankerTypeRealmSend 是对 realm 地址的**永久**
// 花钱授权，没有过期、没有撤销、也不重新检查活性。一旦把它存进状态、
// 当作参数传出、或作为返回值交给调用方，等于把 realm 地址上**所有**
// 金库的钱一次性交出去 —— 所有 vault 共用同一个 realm 地址。
//
// 因此：只在函数局部创建，只在本函数内使用，用完即弃。
func payUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package vault

import "strconv"

// Render 是 gnoweb 的入口。path 是 realm 之后的 URL 路径：
//
//	""     → 索引页，列出所有金库
//	"<id>" → 单个金库的详情页
//
// 界面直接由状态算出，没有前端、没有缓存、没有第二份真相。
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	id, err := strconv.Atoi(path)
	if err != nil {
		return "# GuardianVault\n\nPath must be a vault ID, got `" + path + "`.\n"
	}
	return renderVault(id)
}

func renderIndex() string {
	out := "# GuardianVault\n\n"
	out += "A social-recovery vault: guardians can return your funds to the "
	out += "backup address you registered before losing your key — "
	out += "and can never send them anywhere else.\n\n"

	if len(vaults) == 0 {
		return out + "*No vaults yet.*\n"
	}

	out += "**Vaults:** " + strconv.Itoa(len(vaults)) + "\n\n"
	out += "| ID | Owner | Balance (ugnot) | State |\n"
	out += "| --- | --- | --- | --- |\n"
	for _, v := range vaults {
		out += "| [" + strconv.Itoa(v.ID) + "](" + strconv.Itoa(v.ID) + ") "
		out += "| `" + shortAddr(v.Owner) + "` "
		out += "| " + strconv.FormatInt(v.Balance, 10) + " "
		out += "| " + stateName(v.State) + " |\n"
	}
	return out
}

func renderVault(id int) string {
	if id < 0 || id >= len(vaults) {
		return "# Vault not found\n\nNo vault with ID " + strconv.Itoa(id) + ".\n"
	}
	v := vaults[id]

	out := "# Vault #" + strconv.Itoa(v.ID) + "\n\n"
	out += "| Field | Value |\n"
	out += "| --- | --- |\n"
	out += "| Owner | `" + v.Owner.String() + "` |\n"
	out += "| Backup address | `" + v.BackupAddr.String() + "` |\n"
	out += "| Balance | " + strconv.FormatInt(v.Balance, 10) + " ugnot |\n"
	out += "| State | " + stateName(v.State) + " |\n"
	out += "| Guardians | " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Threshold | " + strconv.Itoa(v.Threshold) + " of " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Recovery window | " + windowText(v.WindowSecs) + " |\n"
	out += "| Completed recoveries | " + strconv.Itoa(v.RecoveryCount) + " |\n"

	out += "\n## Guardians\n\n"
	for _, g := range v.Guardians {
		out += "- `" + g.String() + "`\n"
	}

	if v.State == RECOVERING {
		out += "\n## Recovery in progress\n\n"
		out += "| Field | Value |\n| --- | --- |\n"
		out += "| Requested by | `" + v.Requestor.String() + "` |\n"
		out += "| Votes | " + strconv.Itoa(len(v.Votes)) + " of " + strconv.Itoa(v.Threshold) + " required |\n"
	}

	return out
}

// stateName 把状态机取值转成可读文本。
func stateName(s VaultState) string {
	if s == ACTIVE {
		return "ACTIVE"
	}
	return "RECOVERING"
}

// windowText 把秒数转成可读时长。
//
// 不能简单地写 secs/3600 + " hours"：windowSecs 允许任意秒数（只限区间），
// 5400 秒会被截断显示成「1 hours」—— 界面上的数字与真实窗口不一致，
// 而恢复窗口正是用户判断「我还有多久能否决」的唯一依据。单数也不该写成
// 「1 hours」。
func windowText(secs int64) string {
	h := secs / 3600
	m := (secs % 3600) / 60
	s := secs % 60

	if m == 0 && s == 0 {
		if h == 1 {
			return "1 hour"
		}
		return strconv.FormatInt(h, 10) + " hours"
	}

	out := strconv.FormatInt(h, 10) + "h"
	if m > 0 {
		out += " " + strconv.FormatInt(m, 10) + "m"
	}
	if s > 0 {
		out += " " + strconv.FormatInt(s, 10) + "s"
	}
	return out
}

// shortAddr 把长地址压缩成 `g1abc…wxyz` 形式，用于表格列。
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package vault

import "time"

// 本文件是全部对外 crossing 函数，也是唯一的鉴权点。
//
// 三条贯穿始终的规矩：
//   - 每个函数第一行都是 cur.IsCurrent()，挡「伪装成本 realm 的中间层」；
//   - 身份只从 cur.Previous().Address() 派生，没有任何函数接受地址参数来
//     识别调用者 —— 地址只作为数据出现；
//   - 校验全部前置，任何一条不满足都在写状态之前 panic，不留半成品。
//
// 共 10 个函数，按职责分四组：
//   - 创建：CreateVault
//   - 资金：Deposit / Withdraw
//   - 配置：AddGuardian / SetGuardians / SetBackup
//   - 恢复：RequestRecovery / Vote / CancelRecovery / Execute

// CreateVault 创建一个新金库，调用者成为 owner，返回金库 ID。
//
// 参数校验全部前置：任何一条不满足都不留下半成品状态。
// 校验项与 README §3 的接口表逐条对应，没有「顺手多校验」也没有遗漏。
//
// guardians 是变参且必须放在最后，这不是风格选择，是链上调用机制的硬约束：
// MsgCall 的参数转换只支持原生类型与 []byte，`[]address` 会直接 panic
// （unexpected slice type in contract arg），用户用 gnokey / gnoweb 都调不动。
// 改用变参后，重复传入的 `-args` 正好对应变参列表，实测可用。
// 详见 OPEN-QUESTIONS F12 / F13。
func CreateVault(cur realm, threshold int, backup address, windowSecs int64, guardians ...address) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}

	owner := cur.Previous().Address()
	if owner == address("") {
		panic("owner must not be zero address")
	}
	validateGuardians(guardians, threshold)
	if backup == address("") {
		panic("backup address must not be zero")
	}
	validateWindow(windowSecs)

	// 复制入参 slice。调用方仍持有底层数组，若直接存引用，
	// 它可以在创建后改动名单，绕过「守护人名单变更需走 SetGuardians」。
	g := make([]address, len(guardians))
	copy(g, guardians)

	id := len(vaults)
	vaults = append(vaults, &Vault{
		ID:         id,
		Owner:      owner,
		BackupAddr: backup,
		Guardians:  g,
		Threshold:  threshold,
		WindowSecs: windowSecs,
		State:      ACTIVE,
	})
	return id
}

// Deposit 把本次交易附带的 ugnot 记入金库。
//
// 金额不是参数，只取自交易信封 —— 这样「存多少」由链上实际转账决定，
// 不存在「声称存了 100 实际转了 0」的空间。
func Deposit(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	amt := receivedUgnot(cur)
	if amt <= 0 {
		panic("no ugnot sent")
	}
	v.Balance += amt
}

// Withdraw 由 owner 取回 ugnot。
//
// 这是 D1 补上的出口：没有它，一个金库只能在「假装丢私钥、走一遍恢复」
// 之后才能取出钱，那不叫钱包。
//
// 恢复期间（RECOVERING）禁止取款：否则 owner 可以在守护人已经投满票之后
// 把余额转空，让 Execute 变成一次空转 —— 投票结果就必须被执行，不能因为
// 主人临时改主意而作废。
func Withdraw(cur realm, id int, to address, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if to == address("") {
		panic("recipient must not be zero address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > v.Balance {
		panic("insufficient balance")
	}

	// 先记账再转账。payUgnot 若 panic，整笔交易回滚，不会留下「钱出去了、
	// 账没减」的中间态；反过来写则多一个失败窗口。
	v.Balance -= amount
	payUgnot(cur, to, amount)
}

// AddGuardian 往名单末尾追加一个守护人，阈值不变。
//
// 为什么值得单独一条入口：建库时就把所有守护人凑齐，在现实中很难 ——
// 家人、朋友、同事的地址往往要陆续才拿得到，而 SetGuardians 要求一次性
// 交齐整份名单，中途加一个人就得把全部地址重新抄一遍，抄错一个就是一次
// 永久性配置错误。追加是高频操作，值得最省的那条路径。
//
// 为什么这条捷径不违反「阈值必须与名单共同提交」：追加只会让 N 变大、
// M 原地不动，因此 threshold <= N 依然成立 —— 它只会让「凑得满票」更
// 容易，绝不会更难。真正危险的方向是删除：把 N 减到低于 M 就是一次永久
// 死锁。所以删除与批量替换只走 SetGuardians（整体提交、整体校验），
// 增与减刻意不对称（OPEN-QUESTIONS D9）。
//
// 副作用提醒（已知且接受）：原本 M == N 的「全票」配置，加人之后会变成
// 「容错一人」。这是 owner 亲手点下这一笔的结果，不做二次确认 —— 链上
// 没有对话框，能做的只有把语义写清楚。
func AddGuardian(cur realm, id int, guardian address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if guardian == address("") {
		panic("guardian must not be zero address")
	}
	// 重复地址是这里唯一的死锁来源：投票按地址去重，名单里出现两个相同
	// 地址不会让票数变多，只会让 threshold 的可达性悄悄变差。
	if v.isGuardian(guardian) {
		panic("already a guardian")
	}
	if len(v.Guardians) >= MaxGuardians {
		panic("guardian count would exceed 10")
	}

	v.Guardians = append(v.Guardians, guardian)
}

// SetGuardians 整体替换守护人名单与阈值。
//
// 这是「批量 / 删除」的唯一入口：删除必须与新的阈值一起提交，否则
// threshold 可能高于剩余人数，恢复永远凑不满票。
func SetGuardians(cur realm, id int, threshold int, guardians ...address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	validateGuardians(guardians, threshold)

	g := make([]address, len(guardians))
	copy(g, guardians)
	v.Guardians = g
	v.Threshold = threshold
}

// SetBackup 替换备用地址。
//
// 允许改，是因为人可能换钱包、换设备；但恢复一旦开始就冻结 —— 否则
// 守护人可以在投票中途把目的地改到自己账上，第①层「目的地封闭」直接失效。
func SetBackup(cur realm, id int, backup address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if backup == address("") {
		panic("backup address must not be zero")
	}
	v.BackupAddr = backup
}

// RequestRecovery 开启恢复窗口，任何人可调。
//
// 为什么不是「仅守护人」：发现 owner 失联的第一个人未必是守护人，而发起
// 本身不产生任何权限增量 —— 它只把状态切到 RECOVERING、记下时间，真正
// 能改变归属的仍然是 M 票 + 窗口期满。多一道身份限制只会让流程更容易卡住。
//
// 发起者不会自动获得一票：投票是一条独立的、可审计的动作，藏在发起里会
// 让「谁真的投了票」变得含糊。
func RequestRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != ACTIVE {
		panic("vault is not active")
	}

	v.State = RECOVERING
	v.Requestor = cur.Previous().Address()
	v.RequestedAt = time.Now().Unix()
	v.Votes = nil
}

// Vote 由守护人投一票。
//
// 票数达到 threshold 后拒绝新票：让 Votes 恒 <= Threshold（不变量 I4），
// 也让「票够了」在界面上有确定含义，不会出现 5/3 这种读数。
func Vote(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	caller := cur.Previous().Address()
	if !v.isGuardian(caller) {
		panic("not a guardian")
	}
	if v.hasVoted(caller) {
		panic("already voted")
	}
	if len(v.Votes) >= v.Threshold {
		panic("enough votes already")
	}

	v.Votes = append(v.Votes, caller)
}

// CancelRecovery 由 owner 一票否决，回到 ACTIVE 并清空票数。
//
// 任何时刻可调、不需要理由：这是 owner 私钥还在手上时的唯一自保手段。
// 若给它加延迟或条件，等于把「抢跑」合法化。
func CancelRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	v.State = ACTIVE
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
}

// Execute 把余额付给 BackupAddr，并把所有权移交给它。
//
// 任何人可调，且不产生权限增量：目的地已在注册时锁死，阈值与窗口已满足，
// owner 也已经放弃了否决。限定调用者只会让「已经投过票的守护人」再多发
// 一笔交易来收尾。
//
// 执行完不是回到原样，而是回到「未配置」的初始态：守护人清空、阈值归零。
// 旧 owner 的私钥已经不可用，这些守护人继续挂在这个金库上没有任何意义；
// 新 owner 若想再受保护，需要自己重新 AddGuardian / SetGuardians。
func Execute(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}
	if len(v.Votes) < v.Threshold {
		panic("threshold not reached")
	}

	now := time.Now().Unix()
	if now < v.RequestedAt+v.WindowSecs {
		panic("recovery window has not elapsed")
	}

	amt := v.Balance
	v.Balance = 0
	// 余额为零时不碰 banker：一笔 0 ugnot 的转账没有意义，而跨账户的零额
	// 转账在某些实现下会被拒绝，白搭一次失败。
	if amt > 0 {
		payUgnot(cur, v.BackupAddr, amt)
	}

	v.Owner = v.BackupAddr
	v.Guardians = nil
	v.Threshold = 0
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
	v.State = ACTIVE

	v.RecoveryCount++
	v.LastRecoveredAt = now
}

package vault

// VaultState 是金库的状态机。v1 只有两态，刻意保持单线：
//
//	ACTIVE ──RequestRecovery──▶ RECOVERING ──Execute──▶ ACTIVE（归属已转移）
//	   ▲                             │
//	   └──────CancelRecovery─────────┘
//
// 没有 PAUSED / FROZEN / DISPUTED。每多一态，就要多定义「谁能从这一态
// 走到哪一态」，而本项目的目标是把一条路径做对，不是把状态图铺满。
type VaultState int

const (
	ACTIVE VaultState = iota
	RECOVERING
)

// 参数边界。三条都是「不设就会静默失效」的类型，而不是锦上添花：
//
//   - WindowSecs 若允许 0，时间锁整层消失，否决权退化为与守护人抢速度；
//   - Guardians 若允许重复地址，threshold 可能高于去重后人数，
//     恢复在数学上永远不可达 —— 一次永久且无声的死锁；
//   - MaxGuardians 防的是「名单长到没法逐个核对」这种可用性陷阱。
const (
	MinWindowSecs = int64(3600)    // 1 小时
	MaxWindowSecs = int64(2592000) // 30 天
	MaxGuardians  = 10
)

// Vault 是一个金库的全部状态。
//
// 余额用内部 int64 记账，而不是持有 token 句柄或去问 banker —— 这不是
// 风格选择，而是唯一正确做法：同一 realm 下的所有 vault 共用一个 realm
// 地址，banker.GetCoin(realmAddr) 拿到的是合计值，无法区分单个 vault。
//
// 本类型在 /r/ 中声明，任何对外边界都不得以指针形式返回它。
type Vault struct {
	ID         int
	Owner      address
	BackupAddr address
	Guardians  []address
	Threshold  int
	WindowSecs int64
	Balance    int64 // ugnot

	State       VaultState
	Requestor   address
	RequestedAt int64 // unix 秒，取自 time.Now().Unix()
	Votes       []address

	RecoveryCount   int
	LastRecoveredAt int64
}

// vaults 是唯一的状态容器。未导出，外部只能经函数访问。
//
// ID == 索引，且只增不删（Execute 是重置不是删除），所以 vaults[id]
// 恒成立，mustGet 只需一次边界检查。省掉一张 map，也省掉「map 与 slice
// 不一致」这类状态 bug。
var vaults []*Vault

// mustGet 按 ID 取金库，越界即 panic。
func mustGet(id int) *Vault {
	if id < 0 || id >= len(vaults) {
		panic("no such vault")
	}
	return vaults[id]
}

// requireOwner 断言调用者是 owner。
// 身份只从 cur.Previous() 派生，从不接受地址参数。
func requireOwner(cur realm, v *Vault) {
	if cur.Previous().Address() != v.Owner {
		panic("caller is not the owner")
	}
}

// isGuardian 报告 addr 是否在该金库的守护人名单内。
func (v *Vault) isGuardian(addr address) bool {
	for _, g := range v.Guardians {
		if g == addr {
			return true
		}
	}
	return false
}

// hasVoted 报告 addr 是否已投过票。
// 投票按地址去重，因此名单里若出现重复地址，threshold 可能永不可达 ——
// 这正是 validateGuardians 必须去重的原因。
func (v *Vault) hasVoted(addr address) bool {
	for _, a := range v.Votes {
		if a == addr {
			return true
		}
	}
	return false
}

// validateGuardians 校验守护人名单与阈值。
//
// 阈值是调用方给的自由参数，只约束「凑得满」，不按人数推导公式：多数派 /
// 2/3 / n-1 在 n=3 上都是 2，公式在最常用的配置上没有任何收益，却在 n=2 时
// 要求全票（一人失联即死锁）、n=5 时要求 4 票（形同不可用）。取舍理由见
// README §3 与 OPEN-QUESTIONS D8。这里只守两条硬线：区间合法、名单去重。
//
// 去重是这里最要紧的一条：投票按地址去重（hasVoted），若名单含重复地址
// 且 threshold 高于去重后人数，恢复将永远凑不满票 —— 金库永久死锁，
// 且创建时不会有任何报错，只有真出事那天才暴露。
func validateGuardians(guardians []address, threshold int) {
	n := len(guardians)
	if n < 1 || n > MaxGuardians {
		panic("guardian count must be 1..10")
	}
	if threshold < 1 || threshold > n {
		panic("threshold must be within 1..len(guardians)")
	}
	for i := 0; i < n; i++ {
		if guardians[i] == address("") {
			panic("guardian must not be zero address")
		}
		for j := i + 1; j < n; j++ {
			if guardians[i] == guardians[j] {
				panic("duplicate guardian address")
			}
		}
	}
}

// validateWindow 校验恢复窗口长度。
// 下限 1 小时、上限 30 天：0 会让时间锁整体失效，过长则守护人自己也记不住。
func validateWindow(windowSecs int64) {
	if windowSecs < MinWindowSecs || windowSecs > MaxWindowSecs {
		panic("windowSecs must be within 3600..2592000")
	}
}

package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// receivedUgnot 读取「本次交易实际付给本 realm」的 ugnot 数量。
//
// 守卫只需一条，但选哪一条是经过实测比较的，不是随手取一个：
//
//	cur.Previous().IsUserCall() —— 要求上一跳是纯 EOA（PkgPath == ""）。
//
// 它挡住两类攻击：
//   - 中间 realm 代为转发：信封可能已被中间层消费，而本 realm 仍看到原金额；
//   - MsgRun 的临时 realm（PkgPath = <domain>/e/<addr>/run，非空）。
//
// 为什么不用 IsUser()：它同时接受上述临时 realm，正是要挡的载体之一。
//
// 为什么不用 runtime.AssertOriginCall()：它确实更强，还能挡住
// `var X = other.Deposit` 这类「消息的币记给 A、执行的代码属于 B」的
// 别名转发。但它在单元测试里与 cur.Previous() 互斥 —— AssertOriginCall
// 要求调用方是直接 MsgCall（测试里等价于非 cross 调用），而
// cur.Previous() 在非 cross 调用下会因 prev 为 truly-nil 而 panic。
// 二者不可兼得，而身份正确性（owner 归属）是本项目的承重设计，必须可测。
// 别名转发的前提是 realm 自身存在 `var X = other.Y` 的写法，本项目没有。
// 完整实测记录见 OPEN-QUESTIONS F16。
//
// 本文件是全项目唯一 import chain/runtime/unsafe 的地方。unsafe 在这里
// 只用于读信封金额，绝不用于派生身份 —— 身份一律来自 cur。
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payment must come from a direct EOA call")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// payUgnot 从本 realm 的地址转出 ugnot。
//
// 红线：banker 即用即弃。BankerTypeRealmSend 是对 realm 地址的**永久**
// 花钱授权，没有过期、没有撤销、也不重新检查活性。一旦把它存进状态、
// 当作参数传出、或作为返回值交给调用方，等于把 realm 地址上**所有**
// 金库的钱一次性交出去 —— 所有 vault 共用同一个 realm 地址。
//
// 因此：只在函数局部创建，只在本函数内使用，用完即弃。
func payUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package vault

import "strconv"

// CodeVersion 是链上代码的版本标记，随每次重部署递增。
//
// 它存在的理由是「可观测」：private realm 允许原地覆盖（见 scripts/deploy.sh），
// 而 gnoweb 不会告诉你当前看到的是第几版代码 —— 覆盖是否真的生效，
// 只能靠渲染输出里这个字符串来证明。评审与复查都能据此对齐链上代码与仓库 commit。
const CodeVersion = "0.1.0"

// Render 是 gnoweb 的入口。path 是 realm 之后的 URL 路径：
//
//	""     → 索引页，列出所有金库
//	"<id>" → 单个金库的详情页
//
// 界面直接由状态算出，没有前端、没有缓存、没有第二份真相。
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	id, err := strconv.Atoi(path)
	if err != nil {
		return "# GuardianVault\n\nPath must be a vault ID, got `" + path + "`.\n"
	}
	return renderVault(id)
}

func renderIndex() string {
	out := "# GuardianVault\n\n"
	out += "A social-recovery vault: guardians can return your funds to the "
	out += "backup address you registered before losing your key — "
	out += "and can never send them anywhere else.\n\n"

	if len(vaults) == 0 {
		return out + "*No vaults yet.*\n" + versionLine()
	}

	out += "**Vaults:** " + strconv.Itoa(len(vaults)) + "\n\n"
	out += "| ID | Owner | Balance (ugnot) | State |\n"
	out += "| --- | --- | --- | --- |\n"
	for _, v := range vaults {
		out += "| [" + strconv.Itoa(v.ID) + "](" + strconv.Itoa(v.ID) + ") "
		out += "| `" + shortAddr(v.Owner) + "` "
		out += "| " + strconv.FormatInt(v.Balance, 10) + " "
		out += "| " + stateName(v.State) + " |\n"
	}
	return out + versionLine()
}

// versionLine 把链上代码版本附在页面末尾，用来分辨覆盖是否生效。
func versionLine() string {
	return "\n---\n\n_Live code: " + CodeVersion + "_\n"
}

func renderVault(id int) string {
	if id < 0 || id >= len(vaults) {
		return "# Vault not found\n\nNo vault with ID " + strconv.Itoa(id) + ".\n"
	}
	v := vaults[id]

	out := "# Vault #" + strconv.Itoa(v.ID) + "\n\n"
	out += "| Field | Value |\n"
	out += "| --- | --- |\n"
	out += "| Owner | `" + v.Owner.String() + "` |\n"
	out += "| Backup address | `" + v.BackupAddr.String() + "` |\n"
	out += "| Balance | " + strconv.FormatInt(v.Balance, 10) + " ugnot |\n"
	out += "| State | " + stateName(v.State) + " |\n"
	out += "| Guardians | " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Threshold | " + strconv.Itoa(v.Threshold) + " of " + strconv.Itoa(len(v.Guardians)) + " |\n"
	out += "| Recovery window | " + windowText(v.WindowSecs) + " |\n"
	out += "| Completed recoveries | " + strconv.Itoa(v.RecoveryCount) + " |\n"

	out += "\n## Guardians\n\n"
	for _, g := range v.Guardians {
		out += "- `" + g.String() + "`\n"
	}

	if v.State == RECOVERING {
		out += "\n## Recovery in progress\n\n"
		out += "| Field | Value |\n| --- | --- |\n"
		out += "| Requested by | `" + v.Requestor.String() + "` |\n"
		out += "| Votes | " + strconv.Itoa(len(v.Votes)) + " of " + strconv.Itoa(v.Threshold) + " required |\n"
	}

	return out
}

// stateName 把状态机取值转成可读文本。
func stateName(s VaultState) string {
	if s == ACTIVE {
		return "ACTIVE"
	}
	return "RECOVERING"
}

// windowText 把秒数转成可读时长。
//
// 不能简单地写 secs/3600 + " hours"：windowSecs 允许任意秒数（只限区间），
// 5400 秒会被截断显示成「1 hours」—— 界面上的数字与真实窗口不一致，
// 而恢复窗口正是用户判断「我还有多久能否决」的唯一依据。单数也不该写成
// 「1 hours」。
func windowText(secs int64) string {
	h := secs / 3600
	m := (secs % 3600) / 60
	s := secs % 60

	if m == 0 && s == 0 {
		if h == 1 {
			return "1 hour"
		}
		return strconv.FormatInt(h, 10) + " hours"
	}

	out := strconv.FormatInt(h, 10) + "h"
	if m > 0 {
		out += " " + strconv.FormatInt(m, 10) + "m"
	}
	if s > 0 {
		out += " " + strconv.FormatInt(s, 10) + "s"
	}
	return out
}

// shortAddr 把长地址压缩成 `g1abc…wxyz` 形式，用于表格列。
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package vault

import "time"

// 本文件是全部对外 crossing 函数，也是唯一的鉴权点。
//
// 三条贯穿始终的规矩：
//   - 每个函数第一行都是 cur.IsCurrent()，挡「伪装成本 realm 的中间层」；
//   - 身份只从 cur.Previous().Address() 派生，没有任何函数接受地址参数来
//     识别调用者 —— 地址只作为数据出现；
//   - 校验全部前置，任何一条不满足都在写状态之前 panic，不留半成品。
//
// 共 10 个函数，按职责分四组：
//   - 创建：CreateVault
//   - 资金：Deposit / Withdraw
//   - 配置：AddGuardian / SetGuardians / SetBackup
//   - 恢复：RequestRecovery / Vote / CancelRecovery / Execute

// CreateVault 创建一个新金库，调用者成为 owner，返回金库 ID。
//
// 参数校验全部前置：任何一条不满足都不留下半成品状态。
// 校验项与 README §3 的接口表逐条对应，没有「顺手多校验」也没有遗漏。
//
// guardians 是变参且必须放在最后，这不是风格选择，是链上调用机制的硬约束：
// MsgCall 的参数转换只支持原生类型与 []byte，`[]address` 会直接 panic
// （unexpected slice type in contract arg），用户用 gnokey / gnoweb 都调不动。
// 改用变参后，重复传入的 `-args` 正好对应变参列表，实测可用。
// 详见 OPEN-QUESTIONS F12 / F13。
func CreateVault(cur realm, threshold int, backup address, windowSecs int64, guardians ...address) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}

	owner := cur.Previous().Address()
	if owner == address("") {
		panic("owner must not be zero address")
	}
	validateGuardians(guardians, threshold)
	if backup == address("") {
		panic("backup address must not be zero")
	}
	validateWindow(windowSecs)

	// 复制入参 slice。调用方仍持有底层数组，若直接存引用，
	// 它可以在创建后改动名单，绕过「守护人名单变更需走 SetGuardians」。
	g := make([]address, len(guardians))
	copy(g, guardians)

	id := len(vaults)
	vaults = append(vaults, &Vault{
		ID:         id,
		Owner:      owner,
		BackupAddr: backup,
		Guardians:  g,
		Threshold:  threshold,
		WindowSecs: windowSecs,
		State:      ACTIVE,
	})
	return id
}

// Deposit 把本次交易附带的 ugnot 记入金库。
//
// 金额不是参数，只取自交易信封 —— 这样「存多少」由链上实际转账决定，
// 不存在「声称存了 100 实际转了 0」的空间。
func Deposit(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	amt := receivedUgnot(cur)
	if amt <= 0 {
		panic("no ugnot sent")
	}
	v.Balance += amt
}

// Withdraw 由 owner 取回 ugnot。
//
// 这是 D1 补上的出口：没有它，一个金库只能在「假装丢私钥、走一遍恢复」
// 之后才能取出钱，那不叫钱包。
//
// 恢复期间（RECOVERING）禁止取款：否则 owner 可以在守护人已经投满票之后
// 把余额转空，让 Execute 变成一次空转 —— 投票结果就必须被执行，不能因为
// 主人临时改主意而作废。
func Withdraw(cur realm, id int, to address, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if to == address("") {
		panic("recipient must not be zero address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > v.Balance {
		panic("insufficient balance")
	}

	// 先记账再转账。payUgnot 若 panic，整笔交易回滚，不会留下「钱出去了、
	// 账没减」的中间态；反过来写则多一个失败窗口。
	v.Balance -= amount
	payUgnot(cur, to, amount)
}

// AddGuardian 往名单末尾追加一个守护人，阈值不变。
//
// 为什么值得单独一条入口：建库时就把所有守护人凑齐，在现实中很难 ——
// 家人、朋友、同事的地址往往要陆续才拿得到，而 SetGuardians 要求一次性
// 交齐整份名单，中途加一个人就得把全部地址重新抄一遍，抄错一个就是一次
// 永久性配置错误。追加是高频操作，值得最省的那条路径。
//
// 为什么这条捷径不违反「阈值必须与名单共同提交」：追加只会让 N 变大、
// M 原地不动，因此 threshold <= N 依然成立 —— 它只会让「凑得满票」更
// 容易，绝不会更难。真正危险的方向是删除：把 N 减到低于 M 就是一次永久
// 死锁。所以删除与批量替换只走 SetGuardians（整体提交、整体校验），
// 增与减刻意不对称（OPEN-QUESTIONS D9）。
//
// 副作用提醒（已知且接受）：原本 M == N 的「全票」配置，加人之后会变成
// 「容错一人」。这是 owner 亲手点下这一笔的结果，不做二次确认 —— 链上
// 没有对话框，能做的只有把语义写清楚。
func AddGuardian(cur realm, id int, guardian address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if guardian == address("") {
		panic("guardian must not be zero address")
	}
	// 重复地址是这里唯一的死锁来源：投票按地址去重，名单里出现两个相同
	// 地址不会让票数变多，只会让 threshold 的可达性悄悄变差。
	if v.isGuardian(guardian) {
		panic("already a guardian")
	}
	if len(v.Guardians) >= MaxGuardians {
		panic("guardian count would exceed 10")
	}

	v.Guardians = append(v.Guardians, guardian)
}

// SetGuardians 整体替换守护人名单与阈值。
//
// 这是「批量 / 删除」的唯一入口：删除必须与新的阈值一起提交，否则
// threshold 可能高于剩余人数，恢复永远凑不满票。
func SetGuardians(cur realm, id int, threshold int, guardians ...address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	validateGuardians(guardians, threshold)

	g := make([]address, len(guardians))
	copy(g, guardians)
	v.Guardians = g
	v.Threshold = threshold
}

// SetBackup 替换备用地址。
//
// 允许改，是因为人可能换钱包、换设备；但恢复一旦开始就冻结 —— 否则
// 守护人可以在投票中途把目的地改到自己账上，第①层「目的地封闭」直接失效。
func SetBackup(cur realm, id int, backup address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if backup == address("") {
		panic("backup address must not be zero")
	}
	v.BackupAddr = backup
}

// RequestRecovery 开启恢复窗口，任何人可调。
//
// 为什么不是「仅守护人」：发现 owner 失联的第一个人未必是守护人，而发起
// 本身不产生任何权限增量 —— 它只把状态切到 RECOVERING、记下时间，真正
// 能改变归属的仍然是 M 票 + 窗口期满。多一道身份限制只会让流程更容易卡住。
//
// 发起者不会自动获得一票：投票是一条独立的、可审计的动作，藏在发起里会
// 让「谁真的投了票」变得含糊。
func RequestRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != ACTIVE {
		panic("vault is not active")
	}

	v.State = RECOVERING
	v.Requestor = cur.Previous().Address()
	v.RequestedAt = time.Now().Unix()
	v.Votes = nil
}

// Vote 由守护人投一票。
//
// 票数达到 threshold 后拒绝新票：让 Votes 恒 <= Threshold（不变量 I4），
// 也让「票够了」在界面上有确定含义，不会出现 5/3 这种读数。
func Vote(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	caller := cur.Previous().Address()
	if !v.isGuardian(caller) {
		panic("not a guardian")
	}
	if v.hasVoted(caller) {
		panic("already voted")
	}
	if len(v.Votes) >= v.Threshold {
		panic("enough votes already")
	}

	v.Votes = append(v.Votes, caller)
}

// CancelRecovery 由 owner 一票否决，回到 ACTIVE 并清空票数。
//
// 任何时刻可调、不需要理由：这是 owner 私钥还在手上时的唯一自保手段。
// 若给它加延迟或条件，等于把「抢跑」合法化。
func CancelRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	v.State = ACTIVE
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
}

// Execute 把余额付给 BackupAddr，并把所有权移交给它。
//
// 任何人可调，且不产生权限增量：目的地已在注册时锁死，阈值与窗口已满足，
// owner 也已经放弃了否决。限定调用者只会让「已经投过票的守护人」再多发
// 一笔交易来收尾。
//
// 执行完不是回到原样，而是回到「未配置」的初始态：守护人清空、阈值归零。
// 旧 owner 的私钥已经不可用，这些守护人继续挂在这个金库上没有任何意义；
// 新 owner 若想再受保护，需要自己重新 AddGuardian / SetGuardians。
func Execute(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}
	if len(v.Votes) < v.Threshold {
		panic("threshold not reached")
	}

	now := time.Now().Unix()
	if now < v.RequestedAt+v.WindowSecs {
		panic("recovery window has not elapsed")
	}

	amt := v.Balance
	v.Balance = 0
	// 余额为零时不碰 banker：一笔 0 ugnot 的转账没有意义，而跨账户的零额
	// 转账在某些实现下会被拒绝，白搭一次失败。
	if amt > 0 {
		payUgnot(cur, v.BackupAddr, amt)
	}

	v.Owner = v.BackupAddr
	v.Guardians = nil
	v.Threshold = 0
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
	v.State = ACTIVE

	v.RecoveryCount++
	v.LastRecoveredAt = now
}

// Package feedmath is the oracle's pure-math core: fixed-point prices,
// median-of-N aggregation, the deviation guard, and the staleness predicate.
//
// It is a /p/ package, not a realm: no persistent state, no caller context, no
// chain access. That split is deliberate. Every rule the feed depends on lives
// here so it can be tested exhaustively and cheaply, and so the realm layer
// holds only plumbing (authorization, storage, events).
//
// Facts verified 2026-11-25 against gnolang/gno tag v1.8.0 (primary sources):
//
//   - gnovm/stdlibs/chain/runtime/native.gno declares `ChainHeight() int64`,
//     so block heights are int64 everywhere in this project (the master doc's
//     earlier "uint64" note was wrong and has been corrected).
//   - No float type appears in this file: on-chain floats are forbidden
//     (ledger O7) because their rounding is not reproducible across nodes.
//   - Sorting is hand-rolled insertion sort rather than stdlib `sort`: n is the
//     number of registered sources (3 today, single digits ever), where
//     insertion sort is cheaper and avoids reflection-driven gas.
//   - examples/gno.land/p/nt/avl/v0/tree_test.gno confirms pure-package tests
//     take `(t *testing.T)` with no realm parameter; revive() for panic
//     assertions follows examples/gno.land/p/nt/grc20/v0/token_test.gno.
package feedmath

// Price is a USD price in fixed point, scaled by Scale:
//
//	$0.04905   ->        49050
//	$1.00      ->      1000000
//	$100000.00 -> 100000000000
//
// Integers only. One unit is one millionth of a dollar, which is far finer
// than any exchange quotes GNOT at, so no real precision is lost.
type Price int64

const (
	// Scale is the fixed-point multiplier: Price = USD * Scale.
	Scale = int64(1000000)

	// BpsScale is the denominator for basis-point thresholds. One basis point
	// is 0.01%, so a 10% guard is 1000 bps.
	BpsScale = int64(10000)

	// MaxThresholdBps caps tunable deviation thresholds at 100%. A guard wider
	// than 100% would accept a price of $0 against a reference of $1, which is
	// not a guard at all.
	MaxThresholdBps = int64(10000)

	// MaxPrice bounds every accepted price. Two reasons:
	//
	//  1. It keeps the deviation guard's intermediate products inside int64.
	//     The widest possible gap is MaxPrice-1, and (MaxPrice-1)*BpsScale is
	//     about 1e18 versus an int64 limit near 9.22e18 - roughly 9x headroom.
	//  2. It rejects nonsense quotes early instead of letting them corrupt a
	//     published median.
	//
	// 1e14 units == $100,000,000 at Scale: comfortably above any real asset
	// price, so the bound costs nothing in practice.
	MaxPrice = Price(100000000000000)
)

// ---- Validation ----------------------------------------------------------

// ValidPrice reports whether p may enter the system: strictly positive and
// within the overflow-safe bound.
//
// Zero is invalid on purpose. A "price" of $0 is not a quote, it is a missing
// or broken quote, and letting it into a median would drag the published feed
// toward zero - exactly the failure mode an oracle must never have.
func ValidPrice(p Price) bool {
	return p > 0 && p <= MaxPrice
}

// MustValidPrice panics unless ValidPrice(p) holds.
//
// Call it on every price crossing into the system. On-chain, a panic reverts
// the whole transaction and rolls back its state changes, which is precisely
// what a malformed submission deserves: it is a rejected transaction, not a
// stored bad number.
func MustValidPrice(p Price) {
	if !ValidPrice(p) {
		panic("feedmath: price must be > 0 and <= MaxPrice")
	}
}

// AbsDiff returns |a - b| for two valid prices.
//
// Validity is what makes this safe: with both operands in (0, MaxPrice], the
// subtraction can never overflow, so no wider intermediate type is needed.
func AbsDiff(a, b Price) Price {
	MustValidPrice(a)
	MustValidPrice(b)
	if a >= b {
		return a - b
	}
	return b - a
}

// ---- Aggregation (ledger O3: median of fresh submissions) ----------------

// Median3 returns the median of exactly three prices: the middle value once
// they are ordered.
//
// Median, not mean. A mean can be pulled arbitrarily far by one outlier - a
// single bogus $9999 quote among two honest ones wrecks the average. A median
// of three cannot be moved at all by one bad value: the two honest ones still
// outvote it. That resistance is the whole reason the aggregation rule is a
// median.
//
// Panics if any input is not a valid price.
func Median3(a, b, c Price) Price {
	MustValidPrice(a)
	MustValidPrice(b)
	MustValidPrice(c)

	// Middle-of-three by comparison. Cheaper and more predictable in gas than
	// building a slice and sorting it, and trivially checkable by hand.
	if a > b {
		a, b = b, a // now a <= b
	}
	if b > c {
		b = c // now b = min(b, c)
	}
	if a > b {
		b = a // now b = max(a, b), i.e. the middle of the three
	}
	return b
}

// MedianN returns the median of any non-empty slice of prices.
//
// Even-length inputs have no single middle element. By convention this returns
// the floor of the average of the two middle prices - integer division, so the
// result is at most one unit ($0.000001) below the true midpoint. The oracle
// only ever feeds an odd number of sources today, but the even case is defined
// rather than left to chance.
//
// The midpoint is computed as lo + (hi-lo)/2 rather than the more obvious
// (lo+hi)/2. Given ValidPrice's cap, both are safe today - but the first stays
// correct even if MaxPrice were ever raised toward the int64 limit, so the
// average can never become the thing that overflows. Same result, no trap
// waiting on a future constant change.
//
// The input slice is copied and never reordered - a caller's slice is not ours
// to mutate. Panics on an empty slice or any invalid price.
func MedianN(ps []Price) Price {
	if len(ps) == 0 {
		panic("feedmath: MedianN needs at least one price")
	}

	sorted := make([]Price, len(ps))
	copy(sorted, ps)
	for i := 0; i < len(sorted); i++ {
		MustValidPrice(sorted[i])
	}
	insertionSort(sorted)

	mid := len(sorted) / 2
	if len(sorted)%2 == 1 {
		return sorted[mid]
	}
	lo, hi := sorted[mid-1], sorted[mid]
	return lo + (hi-lo)/2
}

// insertionSort orders prices ascending, in place.
//
// Insertion sort because n is the count of registered sources: at that size it
// beats every general-purpose sort on both speed and gas, has no reflection,
// and is short enough to verify by reading it once.
func insertionSort(ps []Price) {
	for i := 1; i < len(ps); i++ {
		v := ps[i]
		j := i - 1
		for j >= 0 && ps[j] > v {
			ps[j+1] = ps[j]
			j--
		}
		ps[j+1] = v
	}
}

package feedmath

import "testing"

// ---- shared panic helpers ------------------------------------------------
//
// These use plain defer/recover, NOT the test-mode revive() builtin, and the
// distinction matters:
//
//   - revive() exists for panics that cross a REALM boundary, where Go's
//     recover() cannot see them. examples/gno.land/p/nt/grc20/v0/token_test.gno
//     needs it because it wraps every call in cross(...).
//   - feedmath is a pure package that never crosses a boundary, so its panics
//     are ordinary Go panics and recover() catches them - the same pattern as
//     examples/gno.land/r/nt/commondao/v0/reentrancy_test.gno and
//     examples/gno.land/r/nt/grc20reg/v0/grc20reg_test.gno.
//
// (Verified the hard way: an earlier version of these helpers used revive()
// and every panic test failed because revive let the panic through.)
//
// They assert only THAT a panic happened, not its message: the chain wraps
// panic strings, so message equality would be brittle.

// didPanic runs fn and reports whether it panicked.
func didPanic(fn func()) (did bool) {
	defer func() {
		if recover() != nil {
			did = true
		}
	}()
	fn()
	return false
}

func mustPanic(t *testing.T, label string, fn func()) {
	t.Helper()
	if !didPanic(fn) {
		t.Errorf("%s: expected a panic, got none", label)
	}
}

func mustNotPanic(t *testing.T, label string, fn func()) {
	t.Helper()
	if didPanic(fn) {
		t.Errorf("%s: unexpected panic", label)
	}
}

// ---- validation ----------------------------------------------------------

func TestValidPrice(t *testing.T) {
	cases := []struct {
		name string
		p    Price
		want bool
	}{
		{"zero is not a quote", 0, false},
		{"negative", -1, false},
		{"most negative int64", Price(-9223372036854775808), false},
		{"smallest positive", 1, true},
		{"real GNOT quote ($0.049050)", 49050, true},
		{"exactly one dollar", Price(Scale), true},
		{"at the cap", MaxPrice, true},
		{"one above the cap", MaxPrice + 1, false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := ValidPrice(c.p); got != c.want {
				t.Errorf("ValidPrice(%d) = %v, want %v", c.p, got, c.want)
			}
		})
	}
}

func TestMustValidPrice(t *testing.T) {
	mustNotPanic(t, "valid mid price", func() { MustValidPrice(49050) })
	mustNotPanic(t, "valid at cap", func() { MustValidPrice(MaxPrice) })
	mustPanic(t, "zero", func() { MustValidPrice(0) })
	mustPanic(t, "negative", func() { MustValidPrice(-5) })
	mustPanic(t, "above cap", func() { MustValidPrice(MaxPrice + 1) })
}

func TestAbsDiff(t *testing.T) {
	cases := []struct {
		name string
		a, b Price
		want Price
	}{
		{"equal", 100, 100, 0},
		{"a above b", 150, 100, 50},
		{"b above a", 100, 150, 50},
		{"adjacent", 101, 100, 1},
		{"widest possible gap", MaxPrice, 1, MaxPrice - 1},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := AbsDiff(c.a, c.b); got != c.want {
				t.Errorf("AbsDiff(%d, %d) = %d, want %d", c.a, c.b, got, c.want)
			}
		})
	}
	mustPanic(t, "zero operand", func() { AbsDiff(0, 5) })
	mustPanic(t, "over-cap operand", func() { AbsDiff(MaxPrice+1, 5) })
}

// ---- Median3 -------------------------------------------------------------

func TestMedian3(t *testing.T) {
	cases := []struct {
		name    string
		a, b, c Price
		want    Price
	}{
		{"already sorted", 1, 2, 3, 2},
		{"reverse sorted", 3, 2, 1, 2},
		{"median first", 2, 1, 3, 2},
		{"median last", 1, 3, 2, 2},
		{"median in middle slot, high pair", 3, 1, 2, 2},
		{"two low duplicates", 5, 5, 9, 5},
		{"two high duplicates", 5, 9, 9, 9},
		{"all equal", 7, 7, 7, 7},
		{"outlier high cannot move median", 49000, 49100, 999999999, 49100},
		{"outlier low cannot move median", 1, 49000, 49100, 49000},
		{"realistic GNOT spread", 48900, 49050, 49200, 49050},
		{"cap values", MaxPrice, 1, MaxPrice, MaxPrice},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := Median3(tc.a, tc.b, tc.c); got != tc.want {
				t.Errorf("Median3(%d, %d, %d) = %d, want %d", tc.a, tc.b, tc.c, got, tc.want)
			}
		})
	}
}

// TestMedian3AllPermutations is the ordering property for three sources: the
// median must not depend on which source happened to submit first. Submission
// order on-chain is arbitrary, so this is the property that makes the guard and
// the median order-independent (the invariant named in the master doc S9.2).
func TestMedian3AllPermutations(t *testing.T) {
	vals := []Price{48900, 49050, 99200}
	want := Median3(vals[0], vals[1], vals[2])

	orders := [][3]int{
		{0, 1, 2}, {0, 2, 1}, {1, 0, 2},
		{1, 2, 0}, {2, 0, 1}, {2, 1, 0},
	}
	for _, o := range orders {
		got := Median3(vals[o[0]], vals[o[1]], vals[o[2]])
		if got != want {
			t.Errorf("permutation %v gave %d, want %d", o, got, want)
		}
	}
}

func TestMedian3RejectsInvalid(t *testing.T) {
	mustPanic(t, "zero first", func() { Median3(0, 2, 3) })
	mustPanic(t, "zero second", func() { Median3(1, 0, 3) })
	mustPanic(t, "zero third", func() { Median3(1, 2, 0) })
	mustPanic(t, "negative", func() { Median3(1, -2, 3) })
	mustPanic(t, "over cap", func() { Median3(1, 2, MaxPrice+1) })
}

// ---- MedianN -------------------------------------------------------------

func TestMedianN(t *testing.T) {
	cases := []struct {
		name string
		in   []Price
		want Price
	}{
		{"single element", []Price{42}, 42},
		{"two, floor of average", []Price{1, 2}, 1},
		{"two, exact average", []Price{2, 4}, 3},
		{"two equal", []Price{9, 9}, 9},
		{"three unsorted", []Price{3, 1, 2}, 2},
		{"four, floor of middle pair", []Price{1, 2, 3, 4}, 2},
		{"five unsorted", []Price{5, 1, 3, 2, 4}, 3},
		{"duplicates dominate", []Price{9, 9, 9, 1}, 9},
		{"all equal", []Price{5, 5, 5}, 5},
		{"outlier excluded", []Price{49000, 49100, 999999999}, 49100},
		{"at the cap", []Price{MaxPrice, MaxPrice}, MaxPrice},
		{"one below cap pair", []Price{MaxPrice - 1, MaxPrice}, MaxPrice - 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := MedianN(tc.in); got != tc.want {
				t.Errorf("MedianN(%v) = %d, want %d", tc.in, got, tc.want)
			}
		})
	}
}

// TestMedianNDoesNotMutateInput guards the documented promise that a caller's
// slice is copied, not reordered - the realm keeps its submission slices alive
// for rendering after computing a median.
func TestMedianNDoesNotMutateInput(t *testing.T) {
	in := []Price{5, 1, 4, 2, 3}
	before := make([]Price, len(in))
	copy(before, in)

	_ = MedianN(in)

	for i := range in {
		if in[i] != before[i] {
			t.Fatalf("MedianN reordered the caller's slice: got %v, want %v", in, before)
		}
	}
}

func TestMedianNAgreesWithMedian3(t *testing.T) {
	triples := [][3]Price{
		{1, 2, 3}, {3, 2, 1}, {2, 1, 3},
		{5, 5, 9}, {5, 9, 9}, {7, 7, 7},
		{48900, 49050, 49200}, {1, 49000, 49100},
	}
	for _, tr := range triples {
		want := Median3(tr[0], tr[1], tr[2])
		got := MedianN([]Price{tr[0], tr[1], tr[2]})
		if got != want {
			t.Errorf("MedianN(%v) = %d but Median3 = %d", tr, got, want)
		}
	}
}

func TestMedianNRejectsInvalid(t *testing.T) {
	mustPanic(t, "empty slice", func() { MedianN([]Price{}) })
	mustPanic(t, "nil slice", func() { MedianN(nil) })
	mustPanic(t, "contains zero", func() { MedianN([]Price{1, 0, 3}) })
	mustPanic(t, "contains negative", func() { MedianN([]Price{1, -3}) })
	mustPanic(t, "contains over-cap", func() { MedianN([]Price{1, MaxPrice + 1}) })
}

package feedmath

// This file holds the two predicates that decide whether a price may be
// trusted and published: the deviation guard (ledger O5) and the staleness
// rule (ledger O6). Both are pure - they answer a question and change nothing.

// ---- Deviation guard (ledger O5) -----------------------------------------

// DeviationOK reports whether candidate is close enough to reference to be
// trusted, where closeness is thresholdBps basis points (1 bp = 0.01%, so the
// shipped 10% guard is 1000 bps).
//
// The comparison uses multiplication only, never division:
//
//	|candidate - reference| / reference <= bps / 10000
//	is equivalent to
//	|candidate - reference| * 10000 <= bps * reference
//
// The second form is what we compute. Integer division truncates, so the first
// form would make the guard silently stricter or looser than documented
// depending on the numbers; the multiplied form is exact.
//
// Boundary behaviour: a deviation of EXACTLY the threshold is accepted. The
// guard rejects only strictly greater deviation, matching O5's wording
// ("reject a submission deviating > 10%").
//
// Safety: both products stay inside int64 because ValidPrice bounds prices by
// MaxPrice (MaxPrice * BpsScale is about 1e18, versus an int64 limit near
// 9.22e18) and thresholdBps is capped at MaxThresholdBps.
//
// Panics if either price is invalid or thresholdBps is outside
// [0, MaxThresholdBps] - those are programming errors, not market conditions.
func DeviationOK(candidate, reference Price, thresholdBps int64) bool {
	MustValidPrice(candidate)
	MustValidPrice(reference)
	if thresholdBps < 0 || thresholdBps > MaxThresholdBps {
		panic("feedmath: thresholdBps must be within [0, 10000]")
	}

	diff := int64(AbsDiff(candidate, reference))
	return diff*BpsScale <= thresholdBps*int64(reference)
}

// DeviationBps returns how far candidate sits from reference, in basis points,
// rounded down. It exists so a rejection can be reported in words a human can
// read - "deviated 1340 bps, limit 1000" - instead of just "rejected".
//
// Deliberately separate from DeviationOK: this one divides and therefore
// truncates, which is fine for a message but would be wrong for a decision.
// Deciding and explaining are different jobs, so they are different functions.
func DeviationBps(candidate, reference Price) int64 {
	MustValidPrice(candidate)
	MustValidPrice(reference)

	diff := int64(AbsDiff(candidate, reference))
	return diff * BpsScale / int64(reference)
}

// ---- Staleness (ledger O6) -----------------------------------------------

// IsFresh reports whether a value submitted at submittedHeight still counts as
// current at currentHeight, given a staleness window measured in blocks
// (the shipped default is 300 blocks).
//
// Age is measured in blocks, not wall-clock seconds: a realm cannot read a
// clock on-chain, and block height is the only time the chain itself agrees on.
//
// A submission dated in the future (submittedHeight > currentHeight) is NEVER
// fresh. That cannot happen honestly, so refusing it is free - and it closes a
// real hole: without this check a crafted far-future height would age to
// negative, clamp to zero, and make a source look permanently fresh.
//
// A window of 0 is allowed and means "only the current block counts".
// Panics on a negative window, which is a programming error.
func IsFresh(submittedHeight, currentHeight, window int64) bool {
	if window < 0 {
		panic("feedmath: staleness window cannot be negative")
	}
	if submittedHeight > currentHeight {
		return false
	}
	return currentHeight-submittedHeight <= window
}

// BlockAge returns how many blocks old a submission is, clamped to 0 when the
// submission is dated at or after currentHeight.
//
// This is a DISPLAY helper for the dashboard, which wants to print an age
// rather than a verdict - and printing "0 blocks" for an impossible
// future-dated row is harmless. It is deliberately NOT the trust decision:
// IsFresh is the authority on whether a source counts, and it rejects
// future-dated heights outright.
func BlockAge(submittedHeight, currentHeight int64) int64 {
	age := currentHeight - submittedHeight
	if age < 0 {
		return 0
	}
	return age
}

package feedmath

import "testing"

// The arithmetic behind every expected value below is written out, because the
// whole point of these tests is to be an independent check on the code rather
// than a restatement of it. DeviationOK compares:
//
//	diff * BpsScale <= thresholdBps * reference
//
// so with reference = 1000000 ($1.00) and a 1000 bps (10%) threshold the
// allowance is 1000 * 1000000 / 10000 = 100000 units, i.e. exactly $0.10.

func TestDeviationOK(t *testing.T) {
	const ref = Price(1000000) // $1.00

	cases := []struct {
		name      string
		candidate Price
		reference Price
		bps       int64
		want      bool
	}{
		// ---- 10% guard, the shipped default ----
		{"identical", ref, ref, 1000, true},
		{"exactly +10% (boundary, accepted)", 1100000, ref, 1000, true},
		{"one unit over +10% (rejected)", 1100001, ref, 1000, false},
		{"exactly -10% (boundary, accepted)", 900000, ref, 1000, true},
		{"one unit under -10% (rejected)", 899999, ref, 1000, false},
		{"well inside", 1050000, ref, 1000, true},
		{"way outside", 2000000, ref, 1000, false},

		// ---- other thresholds ----
		{"zero bps, identical", ref, ref, 0, true},
		{"zero bps, off by one", ref + 1, ref, 0, false},
		{"one bp, inside", ref + 99, ref, 1, true}, // 99*10000 < 1*1000000
		{"one bp, exactly at limit", ref + 100, ref, 1, true},
		{"one bp, over", ref + 101, ref, 1, false}, // 101*10000 > 1*1000000
		{"100% guard accepts double", ref * 2, ref, 10000, true},
		{"100% guard accepts zero-ish low", 1, ref, 10000, true},

		// ---- realistic GNOT numbers ($0.0489 - $0.0492) ----
		{"honest kucoin vs kraken", 48900, 49050, 1000, true},   // 30 bps apart
		{"honest spread wide side", 49200, 49050, 1000, true},   // 30 bps apart
		{"poisoned source rejected", 99200, 49050, 1000, false}, // ~102% off
		{"poisoned low rejected", 4000, 49050, 1000, false},     // ~92% off
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := DeviationOK(tc.candidate, tc.reference, tc.bps); got != tc.want {
				t.Errorf("DeviationOK(%d, %d, %d) = %v, want %v",
					tc.candidate, tc.reference, tc.bps, got, tc.want)
			}
		})
	}
}

// TestDeviationOKIsSymmetric: the guard must behave the same whether the
// candidate sits above or below the reference by the same amount. A one-sided
// guard would let cheap manipulation through in one direction only.
func TestDeviationOKIsSymmetric(t *testing.T) {
	const ref = Price(1000000)
	for _, delta := range []int64{1, 100, 99999, 100000, 100001, 500000} {
		up := DeviationOK(ref+Price(delta), ref, 1000)
		down := DeviationOK(ref-Price(delta), ref, 1000)
		if up != down {
			t.Errorf("asymmetric at delta %d: above=%v below=%v", delta, up, down)
		}
	}
}

func TestDeviationOKRejectsInvalidInput(t *testing.T) {
	const ref = Price(1000000)
	mustPanic(t, "zero candidate", func() { DeviationOK(0, ref, 1000) })
	mustPanic(t, "zero reference", func() { DeviationOK(ref, 0, 1000) })
	mustPanic(t, "negative candidate", func() { DeviationOK(-1, ref, 1000) })
	mustPanic(t, "over-cap candidate", func() { DeviationOK(MaxPrice+1, ref, 1000) })
	mustPanic(t, "negative threshold", func() { DeviationOK(ref, ref, -1) })
	mustPanic(t, "threshold over 100%", func() { DeviationOK(ref, ref, 10001) })
	mustNotPanic(t, "threshold at 100%", func() { DeviationOK(ref, ref, 10000) })
	mustNotPanic(t, "threshold zero", func() { DeviationOK(ref, ref, 0) })
}

func TestDeviationBps(t *testing.T) {
	const ref = Price(1000000)
	cases := []struct {
		name      string
		candidate Price
		reference Price
		want      int64
	}{
		{"identical", ref, ref, 0},
		{"exactly 10%", 1100000, ref, 1000},
		{"exactly 10% below", 900000, ref, 1000},
		{"one unit over truncates down", 1100001, ref, 1000}, // 1000.01 -> 1000
		{"one bp", ref + 100, ref, 1},
		{"sub-bp deviation truncates to zero", ref + 99, ref, 0},
		{"realistic GNOT 30 bps", 48900, 49050, 30},
		{"poisoned source over 100%", 99200, 49050, 10224},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := DeviationBps(tc.candidate, tc.reference); got != tc.want {
				t.Errorf("DeviationBps(%d, %d) = %d, want %d",
					tc.candidate, tc.reference, got, tc.want)
			}
		})
	}
}

// TestDeviationBpsAgreesWithGuard: the number we show a human in a rejection
// reason must not contradict the decision the guard actually made.
//
// The two directions are NOT symmetric, and the asymmetry is real rather than
// sloppy:
//
//   - accepted  =>  reported bps <= limit   (always: the guard's exact product
//     test is at least as strict as the truncated report)
//   - rejected  =>  reported bps >= limit   (NOT "> limit": DeviationBps floors,
//     so a price rejected by a hair still reports exactly the limit - e.g.
//     against a 49050 reference, 53956 is rejected yet reads as 1000 bps)
//
// Asserting "> limit" on the reject side would be asserting something false
// about our own arithmetic, so it is not asserted.
func TestDeviationBpsAgreesWithGuard(t *testing.T) {
	const ref = Price(49050)
	const bps = int64(1000)
	for _, cand := range []Price{48000, 48600, 48900, 49050, 49200, 49540, 49541, 53955, 53956, 99200} {
		ok := DeviationOK(cand, ref, bps)
		got := DeviationBps(cand, ref)
		if ok && got > bps {
			t.Errorf("accepted %d but reported %d bps > limit %d", cand, got, bps)
		}
		if !ok && got < bps {
			t.Errorf("rejected %d but reported only %d bps < limit %d", cand, got, bps)
		}
	}
}

// ---- staleness -----------------------------------------------------------

func TestIsFresh(t *testing.T) {
	const now = int64(1390523) // a real Onyx height from the M1 deploy

	cases := []struct {
		name      string
		submitted int64
		current   int64
		window    int64
		want      bool
	}{
		{"same block", now, now, 300, true},
		{"one block old", now - 1, now, 300, true},
		{"exactly at window (boundary, fresh)", now - 300, now, 300, true},
		{"one past window (stale)", now - 301, now, 300, false},
		{"very old", now - 1000000, now, 300, false},
		{"zero window, same block", now, now, 0, true},
		{"zero window, one block old", now - 1, now, 0, false},
		{"genesis submission", 0, now, 300, false},
		{"FUTURE dated is never fresh", now + 1, now, 300, false},
		{"FAR future dated is never fresh", now + 99999999, now, 300, false},
		{"chain at height zero", 0, 0, 300, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := IsFresh(tc.submitted, tc.current, tc.window)
			if got != tc.want {
				t.Errorf("IsFresh(%d, %d, %d) = %v, want %v",
					tc.submitted, tc.current, tc.window, got, tc.want)
			}
		})
	}
}

func TestIsFreshRejectsNegativeWindow(t *testing.T) {
	mustPanic(t, "window -1", func() { IsFresh(10, 20, -1) })
	mustNotPanic(t, "window 0", func() { IsFresh(10, 20, 0) })
}

func TestBlockAge(t *testing.T) {
	cases := []struct {
		name      string
		submitted int64
		current   int64
		want      int64
	}{
		{"same block", 100, 100, 0},
		{"normal age", 100, 400, 300},
		{"future clamps to zero (display only)", 500, 100, 0},
		{"far future clamps to zero", 99999999, 100, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := BlockAge(tc.submitted, tc.current); got != tc.want {
				t.Errorf("BlockAge(%d, %d) = %d, want %d",
					tc.submitted, tc.current, got, tc.want)
			}
		})
	}
}

package oracle

import (
	"strconv"

	"chain"
	"chain/runtime"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
)

// admin is the only address allowed to register sources, change configuration,
// or pause the feed.
//
// It is a literal rather than something captured at initialization, and that is
// a deliberate choice forced by how this testnet works. Onyx runs the "inert"
// code-submission policy: MsgAddPackage stores a package inert - in the words of
// contribs/gpao/README.md, "not typechecked, not executed, not importable" - and
// it only becomes active when an address in the chain's PkgApprovers sends
// MsgEnablePackage. Package-level initialization therefore runs inside the
// APPROVER's transaction, not the deployer's, so the usual
// `var admin = unsafe.OriginCaller()` trick would hand control of this feed to
// the testnet's approval daemon.
//
// The address is alice, the deployer key (master doc §5). On a mainnet or
// multi-operator deployment this should become a governance realm or a
// multisig; for a single-operator testnet feed, a literal is honest and
// auditable, and §1.3's caveats already say the deployment is single-operator.
var admin = address("g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh")

// assertAdmin panics unless the caller is the admin signing directly.
//
// IsUserCall() is required, not optional: without it another realm could call
// an admin function and pass its own user's identity along, which is the
// confused-deputy hole. Checking it makes admin actions wallet-only.
func assertAdmin(cur realm) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("oracle: admin functions require a direct user call")
	}
	if caller.Address() != admin {
		panic("oracle: caller is not the admin")
	}
}

// Admin exposes the current admin address so anyone can check who controls the
// feed without reading source. Read-only, so it takes no caller context.
func Admin() address {
	return admin
}

// RegisterSource adds a source and binds it to the one key allowed to submit
// for it (ledger O2). The binding is the real authentication: submitting is
// only possible with that key's signature, so a compromised source cannot be
// impersonated by anyone holding a different key.
//
// Registering the same source id twice panics - silently overwriting the key
// would let an admin mistake (or a stolen admin key) redirect a source without
// a visible removal.
func RegisterSource(cur realm, sourceID, asset string, keyAddr address) {
	assertAdmin(cur)

	if sourceID == "" {
		panic("oracle: source id cannot be empty")
	}
	if asset == "" {
		panic("oracle: asset cannot be empty")
	}
	if keyAddr == address("") {
		panic("oracle: source key cannot be empty")
	}

	f := getFeed(asset)
	if f == nil {
		f = &feed{asset: asset}
		feeds.Set(asset, f)
	}
	if f.getSource(sourceID) != nil {
		panic("oracle: source already registered")
	}

	f.sources.Set(sourceID, &source{
		id:      sourceID,
		asset:   asset,
		keyAddr: keyAddr,
	})

	chain.Emit(
		SourceRegisteredEvent,
		"asset", asset,
		"source", sourceID,
		"key", keyAddr.String(),
	)
}

// RemoveSource unregisters a source. Its price history goes with it.
//
// Removal can drop the feed below quorum, which makes GetPrice revert. That is
// the intended failure direction: losing a source should freeze the feed, never
// quietly let the remaining ones publish an under-supported number.
func RemoveSource(cur realm, sourceID, asset string) {
	assertAdmin(cur)

	f := mustFeed(asset)
	if f.getSource(sourceID) == nil {
		panic("oracle: unknown source")
	}
	f.sources.Remove(sourceID)

	// Republish from whatever is left; recompute() declines unless a quorum of
	// sources is still fresh.
	f.recompute(runtime.ChainHeight())

	chain.Emit(
		SourceRemovedEvent,
		"asset", asset,
		"source", sourceID,
	)
}

// SetConfig retunes the rules without a redeploy (ledger O5/O6 both call for
// admin-tunable thresholds, and M5's burn-in depends on it).
//
// Validation rejects values that would make the math unsafe or the feed
// meaningless: a negative staleness window, a deviation threshold outside
// feedmath's basis-point range, or a quorum below 1.
//
// Setting minFreshSources ABOVE the number of registered sources is allowed and
// simply freezes the feed - GetPrice reverts until enough sources exist. That is
// fail-safe rather than fail-open, so it is the admin's call, not a panic.
func SetConfig(cur realm, stalenessBlocks, deviationBps int64, minFreshSources int) {
	assertAdmin(cur)

	if stalenessBlocks < 0 {
		panic("oracle: staleness window cannot be negative")
	}
	if deviationBps < 0 || deviationBps > feedmath.MaxThresholdBps {
		panic("oracle: deviation threshold must be within [0, 10000] bps")
	}
	if minFreshSources < 1 {
		panic("oracle: quorum must be at least 1 source")
	}

	cfg.stalenessBlocks = stalenessBlocks
	cfg.deviationBps = deviationBps
	cfg.minFreshSources = minFreshSources

	chain.Emit(
		ConfigChangedEvent,
		"staleness_blocks", strconv.FormatInt(stalenessBlocks, 10),
		"deviation_bps", strconv.FormatInt(deviationBps, 10),
		"min_fresh_sources", strconv.Itoa(minFreshSources),
	)
}

// Pause is the emergency stop. While paused every mutator and every read
// reverts, which is the point: if a source is compromised or the bot misbehaves,
// the admin can make the feed refuse to speak at all until it is fixed.
func Pause(cur realm, paused bool) {
	assertAdmin(cur)
	cfg.paused = paused
	chain.Emit(PausedEvent, "paused", strconv.FormatBool(paused))
}

// Config exposes the live settings for dashboards and consumers.
func Config() (stalenessBlocks int64, deviationBps int64, minFreshSources int, paused bool) {
	return cfg.stalenessBlocks, cfg.deviationBps, cfg.minFreshSources, cfg.paused
}

package oracle

import (
	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
)

// This file holds the two decisions that protect the published number: which
// reference price the deviation guard compares against, and whether enough
// sources are fresh to answer at all. Both are read-only - they inspect state
// and change nothing.

// freshPrices collects the accepted prices of every source whose last
// submission is still inside the staleness window, skipping the source named by
// excludeID (pass "" to skip nobody).
//
// The order of the returned slice follows the avl tree's key order, which is
// sourceID sorted alphabetically. That is deterministic across nodes, which
// matters: a median must not depend on map iteration luck. MedianN copies and
// sorts anyway, so the incoming order cannot change the answer.
func (f *feed) freshPrices(excludeID string, atHeight int64) []feedmath.Price {
	out := []feedmath.Price{}
	f.sources.Iterate("", "", func(sourceID string, value any) bool {
		s, ok := value.(*source)
		if !ok {
			return false // keep going; a malformed entry must not stop the scan
		}
		if sourceID == excludeID {
			return false
		}
		if s.isFresh(atHeight) {
			out = append(out, s.price)
		}
		return false // false = do not stop early
	})
	return out
}

// countFresh returns how many sources currently count, per ledger O6.
func (f *feed) countFresh(atHeight int64) int {
	n := 0
	f.sources.Iterate("", "", func(_ string, value any) bool {
		if s, ok := value.(*source); ok && s.isFresh(atHeight) {
			n++
		}
		return false
	})
	return n
}

// consistentSubset culls prices that disagree with the group (ledger O19).
//
// The anchor is the set's own median: any price deviating from it by more than
// thresholdBps is dropped. A single pass, deliberately - with three sources an
// iterate-to-fixpoint cull could not change the outcome, and one pass is easy
// to reason about.
//
// Why the median is the right anchor: it takes a majority to move it. With one
// wild price among honest ones, the median stays inside the honest cluster and
// the wild one is culled. With a wildly disagreeing PAIR there is no majority:
// the midpoint sits >threshold away from both (once they are more than 2x the
// threshold apart), so both are culled and nothing is trustworthy - which is
// the honest answer. A coin-flip midpoint is worse than "no data" (O12).
//
// The known limit, unchanged and unfixable by any median-style rule: two
// compromised sources that agree with each other outvote one honest one.
func consistentSubset(prices []feedmath.Price, thresholdBps int64) []feedmath.Price {
	if len(prices) == 0 {
		return prices
	}
	anchor := feedmath.MedianN(prices)
	out := []feedmath.Price{}
	for _, p := range prices {
		if feedmath.DeviationOK(p, anchor, thresholdBps) {
			out = append(out, p)
		}
	}
	return out
}

// consistentFresh returns the fresh prices that agree with each other: the
// fresh set minus anyone culled by consistentSubset.
func (f *feed) consistentFresh(atHeight int64) []feedmath.Price {
	return consistentSubset(f.freshPrices("", atHeight), cfg.deviationBps)
}

// deviationReference picks the price a new submission is judged against.
//
// Ledger O5 as refined by O19, in order of preference:
//
//  1. The median of the CONSISTENT subset of the OTHER fresh sources.
//     "Other" - never a set including the candidate - stops a submitter from
//     anchoring the reference to its own lie. "Consistent" stops a stored
//     poison value (accepted during a no-reference bootstrap window) from
//     anchoring the reference against the honest majority.
//  2. Otherwise, if fewer than two others survive the cull, the last published
//     median. A single honest source is too thin to judge by on its own, but a
//     median that already commanded a quorum is a reasonable bar.
//  3. Otherwise, no reference at all - the bootstrap case. Blocking here would
//     make the feed impossible to start, so the guard stands aside. This can
//     only happen before the FIRST publication: from then on step 2 always has
//     a median to offer, so the window never reopens (an outage falls back to
//     the last published number rather than to nothing).
//
// The second return value reports whether a reference exists. Callers must
// check it rather than comparing against a meaningless zero price.
func (f *feed) deviationReference(excludeID string, atHeight int64) (feedmath.Price, bool) {
	others := f.freshPrices(excludeID, atHeight)
	survivors := consistentSubset(others, cfg.deviationBps)
	if len(survivors) >= 2 {
		return feedmath.MedianN(survivors), true
	}
	if f.published {
		return f.median, true
	}
	return 0, false
}

// hasQuorum reports whether enough sources are fresh to publish an answer.
func (f *feed) hasQuorum(atHeight int64) bool {
	return f.countFresh(atHeight) >= cfg.minFreshSources
}

// recompute republishes the median from the currently fresh sources.
//
// Ledger O19: only the CONSISTENT subset publishes. Fresh sources whose prices
// disagree with the fresh set's own median are culled, and quorum is then
// required among the SURVIVORS - so a compromised source can never contribute
// to the published number, and a wildly disagreeing pair freezes the feed
// instead of publishing a coin-flip midpoint.
//
// It only writes when a quorum of survivors exists. Falling below quorum does
// NOT erase the last median: the number stays on the dashboard as history, and
// GetPrice refuses to serve it because its freshness/quorum checks fail at
// read time. Erasing it would destroy the evidence of what the feed last
// believed, which is exactly what an operator debugging an outage needs.
//
// Returns true when the published median changed.
func (f *feed) recompute(atHeight int64) bool {
	survivors := f.consistentFresh(atHeight)
	if len(survivors) < cfg.minFreshSources {
		return false
	}
	median := feedmath.MedianN(survivors)

	changed := !f.published || f.median != median || f.included != len(survivors)
	f.median = median
	f.medianAt = atHeight
	f.included = len(survivors)
	f.published = true
	return changed
}

// isOutlier reports whether s is fresh but culled from the consistent subset -
// the dashboard marks such a source OUTLIER so an operator can see at a glance
// that it is stored and fresh yet excluded from the published median (a
// compromised or badly broken feeder looks exactly like this).
func (f *feed) isOutlier(s *source, atHeight int64) bool {
	if !s.isFresh(atHeight) {
		return false
	}
	prices := f.freshPrices("", atHeight)
	if len(prices) == 0 {
		return false
	}
	anchor := feedmath.MedianN(prices)
	return !feedmath.DeviationOK(s.price, anchor, cfg.deviationBps)
}

// Tests for the oracle's guards: the deviation rule (O5), the quorum/staleness
// rules (O6), and - most importantly - whether submission ORDER can change what
// gets published. §9.2 of the master doc names that as a required property.
package oracle

import (
	"testing"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
)

// ---- the deviation guard in steady state ---------------------------------

func TestDeviationGuardRejectsOutlier(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)

	// ~102% above the other two: far outside the 10% guard.
	submitAs(cur, coingeckoK, "coingecko", 99200)

	s := f.getSource("coingecko")
	if s.hasSubmission {
		t.Fatal("an outlier must not be stored")
	}
	if s.rejected != 1 {
		t.Errorf("rejection count = %d, want 1", s.rejected)
	}
	if s.lastRejectBps < 10000 {
		t.Errorf("last rejection should read as >100%% off, got %d bps", s.lastRejectBps)
	}
}

// TestRejectedPriceNeverEntersMedian is the invariant §9.2 calls out by name:
// a rejected price must not influence the published number at all.
func TestRejectedPriceNeverEntersMedian(cur realm, t *testing.T) {
	setup(cur, 100)

	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	before, _ := GetPrice(asset)

	submitAs(cur, coingeckoK, "coingecko", 99200) // rejected

	after, _ := GetPrice(asset)
	if before != after {
		t.Fatalf("a rejected submission moved the median: %d -> %d", before, after)
	}
	if after != 48975 {
		t.Fatalf("median = %d, want 48975 (floor of the two honest prices)", after)
	}
}

func TestDeviationGuardAcceptsHonestSpread(cur realm, t *testing.T) {
	setup(cur, 100)

	// Real GNOT quotes from the three sources sit within a few tenths of a
	// percent of each other; the 10% guard must never fire on honest noise.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49200)

	f := mustFeedFor(t, asset)
	for _, id := range []string{"kucoin", "kraken", "coingecko"} {
		if s := f.getSource(id); s.rejected != 0 || !s.hasSubmission {
			t.Errorf("%s: honest spread was rejected (rejected=%d stored=%v)",
				id, s.rejected, s.hasSubmission)
		}
	}
	if price, _ := GetPrice(asset); price != 49050 {
		t.Fatalf("median = %d, want 49050", price)
	}
}

// TestDeviationGuardBoundaryAtExactlyTenPercent pins the documented edge: a
// deviation of exactly the threshold is accepted, one unit beyond is not.
func TestDeviationGuardBoundaryAtExactlyTenPercent(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	// Two anchors at 50000, so the reference the third source is judged
	// against is exactly 50000. Ten percent of that is 5000 units.
	submitAs(cur, kucoinKey, "kucoin", 50000)
	submitAs(cur, krakenKey, "kraken", 50000)

	submitAs(cur, coingeckoK, "coingecko", 55000) // exactly +10%
	if s := f.getSource("coingecko"); !s.hasSubmission || s.rejected != 0 {
		t.Errorf("exactly at the threshold must be ACCEPTED (stored=%v rejected=%d)",
			s.hasSubmission, s.rejected)
	}

	// Reset the same source and try one unit further out.
	submitAs(cur, coingeckoK, "coingecko", 55001) // +10.0002%
	if s := f.getSource("coingecko"); s.rejected != 1 {
		t.Errorf("one unit past the threshold must be REJECTED (rejected=%d)", s.rejected)
	}
	if s := f.getSource("coingecko"); s.price != 55000 {
		t.Errorf("the rejected price must not overwrite the stored one, got %d", s.price)
	}
}

// TestDeviationReferenceExcludesSubmitter proves a source cannot anchor the
// reference to its own previous (possibly wrong) number: the guard judges a
// candidate against the OTHERS only.
func TestDeviationReferenceExcludesSubmitter(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	submitAs(cur, kucoinKey, "kucoin", 49050)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49050)

	// kucoin now doubles its quote. The reference must come from kraken and
	// coingecko (49050), NOT include kucoin's own 49050 or its new number.
	submitAs(cur, kucoinKey, "kucoin", 98100)

	if s := f.getSource("kucoin"); s.rejected != 1 {
		t.Errorf("kucoin's doubled quote should be rejected, rejections = %d", s.rejected)
	}
	if s := f.getSource("kucoin"); s.price != 49050 {
		t.Errorf("kucoin's stored price should still be 49050, got %d", s.price)
	}
	if price, _ := GetPrice(asset); price != 49050 {
		t.Errorf("published median moved to %d, want 49050", price)
	}
	_ = f
}

func TestDeviationGuardStandsAsideAtBootstrap(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	// The very first submission has nothing to be judged against. Blocking it
	// would make the feed impossible to start, so the guard stands aside.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	if s := f.getSource("kucoin"); !s.hasSubmission {
		t.Fatal("the first submission must be accepted")
	}
	if f.published {
		t.Fatal("one source is below quorum, nothing should be published yet")
	}

	// The second still has only one other source and nothing published, so the
	// guard stands aside again - but now quorum is met and a median publishes.
	submitAs(cur, krakenKey, "kraken", 49050)
	if s := f.getSource("kraken"); !s.hasSubmission {
		t.Fatal("the second submission must be accepted at bootstrap")
	}
	if !f.published {
		t.Fatal("two fresh sources must publish")
	}
}

// ---- ordering ------------------------------------------------------------

// TestOrderIndependence_HonestPrices is the §9.2 property test: no matter what
// order the three sources submit in, the published median must be the same.
// Submission order on a live chain is arbitrary, so an order-dependent result
// would be a consensus-level bug.
func TestOrderIndependence_HonestPrices(cur realm, t *testing.T) {
	type sub struct {
		key   address
		id    string
		price feedmath.Price
	}
	subs := []sub{
		{kucoinKey, "kucoin", 48900},
		{krakenKey, "kraken", 49050},
		{coingeckoK, "coingecko", 49200},
	}
	orders := [][3]int{
		{0, 1, 2}, {0, 2, 1}, {1, 0, 2},
		{1, 2, 0}, {2, 0, 1}, {2, 1, 0},
	}

	var want feedmath.Price = -1
	for _, o := range orders {
		setup(cur, 100)
		for _, i := range o {
			submitAs(cur, subs[i].key, subs[i].id, subs[i].price)
		}
		got, _ := GetPrice(asset)
		if want == -1 {
			want = got
			continue
		}
		if got != want {
			t.Errorf("order %v published %d, but another order published %d", o, got, want)
		}
	}
	if want != 49050 {
		t.Errorf("published median = %d, want 49050", want)
	}
}

// TestBootstrapPoisoningIsDefeated is the regression test for ledger O19
// (owner-approved 2026-11-25). It replays the exact attack the weakness
// described - one compromised key striking during the bootstrap window, when
// nothing is published and the deviation guard has no reference - and asserts
// the consistent-subset fix defeats it at every step:
//
//  1. The attacker submits a wild price first. It is ACCEPTED (a lone first
//     submission has nothing to be judged against - unavoidable), but nothing
//     publishes: one fresh source is below quorum.
//  2. An honest source submits. The wild+honest pair disagrees by more than
//     the threshold, so the consistency cull drops BOTH (each is >10% from
//     their own midpoint) -> no quorum among survivors -> the feed STAYS
//     FROZEN. Before the fix, the midpoint of {wild, honest} published here
//     and GetPrice served it.
//  3. The second honest source submits. The provisional median now sits in the
//     honest cluster; the attacker is the sole cull; the honest pair meets
//     quorum -> the HONEST median publishes and GetPrice serves it. The guard
//     let this submission in because the wild+honest pair culls to nothing,
//     leaving no reference - standing aside, not anchoring on poison.
//  4. The attacker resubmits: judged against the consistent honest reference
//     -> REJECTED by the deviation guard. The feed has self-healed.
//
// Note what step 1 leaves behind: the attacker's price stays STORED (it was
// legitimately accepted when no reference existed) and shows as an outlier on
// the dashboard, but it is permanently culled from the median for as long as
// it disagrees with the honest cluster. Erasing it would hide evidence.
func TestBootstrapPoisoningIsDefeated(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	// 1. compromised coingecko strikes first with ~2x the real price.
	submitAs(cur, coingeckoK, "coingecko", 99200)
	if s := f.getSource("coingecko"); !s.hasSubmission {
		t.Fatal("the first-ever submission cannot be judged and must be accepted")
	}
	if f.published {
		t.Fatal("a lone source is below quorum; nothing may publish")
	}

	// 2. honest kucoin. The disagreeing pair culls to nothing -> frozen.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	if f.published {
		t.Fatalf("a wild+honest pair must not publish (got median %d); the feed must freeze", f.median)
	}
	mustPanic(t, "GetPrice during the frozen bootstrap", func() { GetPrice(asset) })

	// 3. honest kraken -> the honest cluster wins and publishes.
	submitAs(cur, krakenKey, "kraken", 49050)
	if !f.published {
		t.Fatal("two consistent sources must publish once the attacker is culled")
	}
	price, _ := GetPrice(asset)
	if price != 48975 {
		t.Fatalf("published %d, want 48975 (median of the honest pair)", price)
	}
	if f.included != 2 {
		t.Fatalf("median built from %d sources, want 2 (the attacker must be culled)", f.included)
	}

	// 4. the attacker retries and is now rejected by the guard.
	submitAs(cur, coingeckoK, "coingecko", 99200)
	s := f.getSource("coingecko")
	if s.rejected != 1 {
		t.Errorf("attacker rejections = %d, want 1", s.rejected)
	}
	if s.price != 99200 {
		t.Errorf("the rejected retry must not change the stored price, got %d", s.price)
	}
	if price2, _ := GetPrice(asset); price2 != 48975 {
		t.Errorf("median moved to %d after the attack was repelled, want 48975", price2)
	}
}

// TestDisagreeingPairFreezesNotMidpoint pins the deliberate behaviour change
// O19 made for exactly two fresh sources.
//
// If they are more than 2x the threshold apart, each sits >10% from their own
// midpoint, the cull drops both, and the feed publishes NOTHING instead of a
// coin-flip midpoint (O12: freeze rather than serve a rotten number). If they
// are within 2x the threshold, both survive the cull and the midpoint still
// publishes - the honest two-source bootstrap is unchanged.
func TestDisagreeingPairFreezesNotMidpoint(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	// 48900 vs 60000 is ~22.7% apart: midpoint 54450, each ~10.2% from it.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 60000)

	if f.published {
		t.Fatalf("a wildly disagreeing pair must not publish their midpoint (got %d)", f.median)
	}
	mustPanic(t, "GetPrice on a disagreeing pair", func() { GetPrice(asset) })

	// A third source siding with one cluster resolves the disagreement.
	submitAs(cur, coingeckoK, "coingecko", 48950)
	if !f.published {
		t.Fatal("two consistent sources out of three must publish")
	}
	price, _ := GetPrice(asset)
	if price != 48925 {
		t.Fatalf("published %d, want 48925 (median of the consistent pair)", price)
	}
	if f.included != 2 {
		t.Fatalf("median built from %d sources, want 2 (kraken culled)", f.included)
	}
}

// TestNearPairStillPublishesMidpoint is the OTHER side of the O19 boundary:
// two sources within 2x the threshold of each other agree on a midpoint (each
// is within the threshold of it), so the honest two-source bootstrap publishes
// exactly as it did before the fix. 48900 vs 55000 is ~12.5% apart: midpoint
// 51950, each ~5.9% from it -> both survive -> midpoint publishes.
func TestNearPairStillPublishesMidpoint(cur realm, t *testing.T) {
	setup(cur, 100)

	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 55000)

	price, _ := GetPrice(asset)
	if price != 51950 {
		t.Fatalf("published %d, want 51950 (midpoint of a near-enough pair)", price)
	}
}

// ---- quorum / staleness interaction --------------------------------------

func TestQuorumIsRecomputedNotCached(cur realm, t *testing.T) {
	setup(cur, 1000)
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49200)
	mustNotPanic(t, "read with three fresh", func() { GetPrice(asset) })

	// Everyone goes quiet. Nothing was erased, but the answer must stop.
	testing.SetHeight(1000 + DefaultStalenessBlocks + 1)
	mustPanic(t, "read after every source went stale", func() { GetPrice(asset) })

	// Two sources come back and the feed answers again without any admin action.
	submitAs(cur, kucoinKey, "kucoin", 48950)
	submitAs(cur, krakenKey, "kraken", 49050)
	mustNotPanic(t, "read after quorum recovered", func() { GetPrice(asset) })

	price, _ := GetPrice(asset)
	if price != 49000 {
		t.Fatalf("median after recovery = %d, want 49000", price)
	}
}

func TestRaisingQuorumAboveSourcesFreezesFeed(cur realm, t *testing.T) {
	setup(cur, 100)
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	mustNotPanic(t, "read at quorum 2", func() { GetPrice(asset) })

	testing.SetRealm(testing.NewUserRealm(alice))
	SetConfig(cross(cur), DefaultStalenessBlocks, DefaultDeviationBps, 4)

	// Quorum 4 with 3 registered sources can never be met: the feed must refuse
	// rather than answer. Fail-safe, not fail-open.
	mustPanic(t, "read with quorum above the source count", func() { GetPrice(asset) })
}

package oracle

import (
	"strconv"

	"chain"
	"chain/runtime"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
)

// ---- Submissions ---------------------------------------------------------

// SubmitPrice records a price for one source. It is a crossing function: the
// `cur realm` parameter is how v1.8.0 hands a realm its caller context, and
// cur.Previous() is the caller one frame back - for a direct transaction from a
// wallet, that is the signer.
//
// Two outcomes are possible and they are deliberately different:
//
//   - A submission from the WRONG KEY, an unknown source, an invalid price, or
//     while paused PANICS. The transaction fails and every state change rolls
//     back. Nothing about that call was legitimate, so nothing is remembered.
//   - A submission that is legitimate but OUTLIER-priced is REJECTED without
//     panicking: the rejection is counted, an event is emitted, the price is
//     not stored, and the transaction succeeds. The feeder still paid gas, and
//     the feed keeps a public record that it refused a number and why. A revert
//     would hide exactly the evidence an operator needs during an incident.
//
// Argument order matches the master doc's quick reference: source, asset, price.
func SubmitPrice(cur realm, sourceID, asset string, price feedmath.Price) {
	if cfg.paused {
		panic("oracle: feed is paused")
	}

	f := mustFeed(asset)
	s := f.getSource(sourceID)
	if s == nil {
		panic("oracle: unknown source")
	}

	// Authorization (ledger O2): the signer must be the key registered for THIS
	// source. IsUserCall() is checked first so that another realm cannot call us
	// on a user's behalf and impersonate a feeder - the confused-deputy hole.
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("oracle: SubmitPrice requires a direct user call")
	}
	if caller.Address() != s.keyAddr {
		panic("oracle: caller is not the registered key for this source")
	}

	// Reject nonsense numbers before they can touch state. Panicking here is
	// right: a non-positive or absurd price is a broken feeder, not a market
	// condition, and it must not be stored or counted as a rejection.
	feedmath.MustValidPrice(price)

	height := runtime.ChainHeight()

	// Deviation guard (ledger O5, refined by O19): judged against the
	// CONSISTENT subset of the OTHER fresh sources - never a set including the
	// candidate, never anchored by a stored outlier.
	if ref, ok := f.deviationReference(sourceID, height); ok {
		if !feedmath.DeviationOK(price, ref, cfg.deviationBps) {
			bps := feedmath.DeviationBps(price, ref)
			s.rejected++
			s.lastRejectBps = bps
			chain.Emit(
				PriceRejectedEvent,
				"asset", asset,
				"source", sourceID,
				"price", strconv.FormatInt(int64(price), 10),
				"reference", strconv.FormatInt(int64(ref), 10),
				"deviation_bps", strconv.FormatInt(bps, 10),
				"limit_bps", strconv.FormatInt(cfg.deviationBps, 10),
			)
			return
		}
	}

	// Accepted: store it, then republish the median if a quorum is fresh.
	s.price = price
	s.height = height
	s.hasSubmission = true

	chain.Emit(
		PriceSubmittedEvent,
		"asset", asset,
		"source", sourceID,
		"price", strconv.FormatInt(int64(price), 10),
		"height", strconv.FormatInt(height, 10),
	)

	if f.recompute(height) {
		chain.Emit(
			MedianUpdatedEvent,
			"asset", asset,
			"median", strconv.FormatInt(int64(f.median), 10),
			"included", strconv.Itoa(f.included),
			"height", strconv.FormatInt(height, 10),
		)
	}
}

// ---- Reads ---------------------------------------------------------------

// GetPrice returns the published median for an asset and the height at which it
// was published.
//
// IT PANICS INSTEAD OF GUESSING. That is the product's central promise (ledger
// O12): a consumer that asks for a price while the feed is paused, has no
// quorum, or is stale gets a hard failure rather than a number that looks fine.
// Serving a rotten price quietly is how lending protocols get drained; refusing
// loudly is recoverable.
//
// Callers must handle the failure. In Gno that means the calling transaction
// reverts unless it isolates the call, so the consumer demo realm (O14) shows
// the frozen state explicitly rather than pretending the read always works.
//
// Freshness is re-checked HERE, at read time, from the stored per-source
// heights - not trusted from cached fields. A median published an hour ago from
// sources that have since gone quiet must not be servable, and only a read-time
// check guarantees that.
func GetPrice(asset string) (feedmath.Price, int64) {
	if cfg.paused {
		panic("oracle: feed is paused")
	}

	f := mustFeed(asset)
	if !f.published {
		panic("oracle: no price published yet")
	}

	height := runtime.ChainHeight()
	if !f.hasQuorum(height) {
		panic("oracle: not enough fresh sources to answer")
	}
	if !feedmath.IsFresh(f.medianAt, height, cfg.stalenessBlocks) {
		panic("oracle: published median is stale")
	}
	return f.median, f.medianAt
}

// GetSources returns a one-line-per-source status snapshot as text: id, last
// price, age in blocks, and whether it counts as fresh.
//
// Text rather than structs on purpose. A consumer realm reading this gets a
// stable string it cannot misinterpret, and it avoids exporting struct types
// across a realm boundary, which is a compatibility trap for v0.
func GetSources(asset string) string {
	f := mustFeed(asset)
	height := runtime.ChainHeight()

	lines := []string{}
	f.sources.Iterate("", "", func(sourceID string, value any) bool {
		s, ok := value.(*source)
		if !ok {
			return false
		}
		status := "NO DATA"
		age := int64(-1)
		if s.hasSubmission {
			age = feedmath.BlockAge(s.height, height)
			switch {
			case !s.isFresh(height):
				status = "STALE"
			case f.isOutlier(s, height):
				status = "OUTLIER" // fresh but culled from the median (O19)
			default:
				status = "FRESH"
			}
		}
		line := sourceID +
			" price=" + formatUSD(s.price) +
			" age=" + formatAge(age) +
			" status=" + status +
			" rejected=" + strconv.FormatInt(s.rejected, 10)
		lines = append(lines, line)
		return false
	})

	header := "asset=" + asset +
		" fresh=" + strconv.Itoa(f.countFresh(height)) +
		"/" + strconv.Itoa(f.sources.Size()) +
		" quorum=" + strconv.Itoa(cfg.minFreshSources)
	if len(lines) == 0 {
		return header + "\n(no sources registered)"
	}
	out := header
	for _, l := range lines {
		out += "\n" + l
	}
	return out
}

// Tests for the oracle realm.
//
// Harness pattern verified against gnolang/gno tag v1.8.0:
//
//	examples/gno.land/r/demo/profile/profile_test.gno and our own M1 counter
//	tests - testing.SetRealm(testing.NewUserRealm(addr)) + testing.SetHeight(n),
//	then call the crossing function as Fn(cross(cur), ...).
//	gnovm/tests/stdlibs/testing/context_testing.gno - SetRealm / SetHeight /
//	NewUserRealm / NewCodeRealm / SetOriginCaller / SkipHeights.
//
// TWO panic-catching mechanisms, and using the wrong one is a real bug:
//
//   - A call that goes through cross(cur) into a CROSSING function panics
//     ACROSS a realm boundary. Per docs/resources/gno-interrealm-v2.md §9, only
//     the test-mode builtin revive(fn) can catch that; a plain defer/recover
//     lets it abort the whole test binary. -> mustAbort / mustNotAbort.
//     (examples/gno.land/p/nt/grc20/v0/token_test.gno uses revive for exactly
//     this reason; grc20reg uses urequire.AbortsContains, which is revive-based.)
//
//   - A call to a PLAIN function (GetPrice, GetSources, Config, Render) stays
//     inside one realm-context, so its panic is an ordinary Go panic and
//     defer/recover catches it. revive() does NOT - wrapping a plain call in
//     revive let the panic escape and crash the run. -> mustPanic / mustNotPanic.
//     (examples/gno.land/r/nt/grc20reg/v0/grc20reg_test.gno catches the plain
//     validateSlug panic with defer/recover.)
//
// Getting this backwards cost a full failing run on 2026-11-25; the split is
// recorded here so it is not relearned.
package oracle

import (
	"strings"
	"testing"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
	"gno.land/p/nt/avl/v0"
)

// The real testnet keys from §5 of the master doc. Using the genuine addresses
// means a test that passes here also passes against the deployed feeders.
var (
	alice      = address("g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh") // admin
	kucoinKey  = address("g1dg7cgrdevgt80c7m5x3vy6k2dywts9hkrptpw0")
	krakenKey  = address("g1lhmlntfyxgtax4hwrtwtts80qga5h3m0e892kh")
	coingeckoK = address("g1kenddl5kj9x67vu65gp2zx6yfyy9fqgq7nutcw")
	stranger   = address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
)

const asset = "GNOT"

// resetState gives each test a clean slate: realm package vars are shared by
// every test in the package, exactly like on-chain state is shared by every tx.
func resetState() {
	feeds = avl.Tree{}
	cfg = config{
		stalenessBlocks: DefaultStalenessBlocks,
		deviationBps:    DefaultDeviationBps,
		minFreshSources: DefaultMinFreshSources,
		paused:          false,
	}
}

// setup registers the three real sources as admin at the given height.
func setup(cur realm, height int64) {
	resetState()
	testing.SetHeight(height)
	testing.SetRealm(testing.NewUserRealm(alice))
	RegisterSource(cross(cur), "coingecko", asset, coingeckoK)
	RegisterSource(cross(cur), "kraken", asset, krakenKey)
	RegisterSource(cross(cur), "kucoin", asset, kucoinKey)
}

// ---- panic helpers: CROSSING calls (revive) ------------------------------

// mustAbort asserts fn aborted with a panic that crossed a realm boundary, i.e.
// fn calls a crossing function via cross(cur). revive is the only mechanism that
// sees such a panic (interrealm v2 §9).
func mustAbort(t *testing.T, label string, fn func()) {
	t.Helper()
	if r := revive(fn); r == nil {
		t.Errorf("%s: expected an abort, got none", label)
	}
}

func mustNotAbort(t *testing.T, label string, fn func()) {
	t.Helper()
	if r := revive(fn); r != nil {
		t.Errorf("%s: unexpected abort: %v", label, r)
	}
}

// ---- panic helpers: PLAIN calls (defer/recover) --------------------------

// didPanic runs fn and reports whether it panicked, using ordinary Go recover.
// Correct only for functions that do NOT cross a realm boundary.
func didPanic(fn func()) (did bool) {
	defer func() {
		if recover() != nil {
			did = true
		}
	}()
	fn()
	return false
}

func mustPanic(t *testing.T, label string, fn func()) {
	t.Helper()
	if !didPanic(fn) {
		t.Errorf("%s: expected a panic, got none", label)
	}
}

func mustNotPanic(t *testing.T, label string, fn func()) {
	t.Helper()
	if didPanic(fn) {
		t.Errorf("%s: unexpected panic", label)
	}
}

// submitAs signs a submission as the given key. Crossing: SubmitPrice takes
// cross(cur). An honest, in-guard submission returns normally (no panic), so it
// is safe to call unwrapped; only outlier submissions return normally too (they
// are rejected without panicking), so submitAs itself never needs a wrapper.
func submitAs(cur realm, key address, sourceID string, price feedmath.Price) {
	testing.SetRealm(testing.NewUserRealm(key))
	SubmitPrice(cross(cur), sourceID, asset, price)
}

// ---- registration / authorization ----------------------------------------

func TestRegisterSourceIsAdminOnly(cur realm, t *testing.T) {
	resetState()
	testing.SetHeight(10)

	testing.SetRealm(testing.NewUserRealm(stranger))
	mustAbort(t, "stranger registering a source", func() {
		RegisterSource(cross(cur), "kucoin", asset, kucoinKey)
	})

	if feeds.Size() != 0 {
		t.Fatalf("a rejected registration must not create state, got %d feeds", feeds.Size())
	}

	testing.SetRealm(testing.NewUserRealm(alice))
	mustNotAbort(t, "admin registering a source", func() {
		RegisterSource(cross(cur), "kucoin", asset, kucoinKey)
	})

	f := mustFeedFor(t, asset)
	if f.sources.Size() != 1 {
		t.Fatalf("expected 1 source, got %d", f.sources.Size())
	}
}

// TestRegisterSourceRejectsRealmCall covers the confused-deputy hole: another
// realm calling us must not be able to act as its user. IsUserCall() is false
// for a code realm, so this must abort even when the address matches admin.
func TestRegisterSourceRejectsRealmCall(cur realm, t *testing.T) {
	resetState()
	testing.SetHeight(10)
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/evil/impersonator/v0"))

	mustAbort(t, "a code realm calling an admin function", func() {
		RegisterSource(cross(cur), "kucoin", asset, kucoinKey)
	})
}

func TestSubmitPriceRejectsRealmCall(cur realm, t *testing.T) {
	setup(cur, 100)
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/evil/impersonator/v0"))

	mustAbort(t, "a code realm submitting a price", func() {
		SubmitPrice(cross(cur), "kucoin", asset, 49050)
	})
}

func TestRegisterSourceValidation(cur realm, t *testing.T) {
	resetState()
	testing.SetHeight(10)
	testing.SetRealm(testing.NewUserRealm(alice))

	mustAbort(t, "empty source id", func() {
		RegisterSource(cross(cur), "", asset, kucoinKey)
	})
	mustAbort(t, "empty asset", func() {
		RegisterSource(cross(cur), "kucoin", "", kucoinKey)
	})
	mustAbort(t, "empty key", func() {
		RegisterSource(cross(cur), "kucoin", asset, address(""))
	})
