// ---- formatting helpers --------------------------------------------------
//
// Integer math only. These exist so neither the dashboard nor GetSources can
// drift from how a price really is encoded.

// formatUSD renders a scaled price as dollars, e.g. 49050 -> "$0.049050".
// A non-positive price is not a quote, so it renders as "n/a" rather than $0.
func formatUSD(p feedmath.Price) string {
	if p <= 0 {
		return "n/a"
	}
	whole := int64(p) / feedmath.Scale
	frac := int64(p) % feedmath.Scale
	return "$" + strconv.FormatInt(whole, 10) + "." + padLeft(frac, 6)
}

// formatBps renders basis points as a percentage, e.g. 1000 -> "10.00%".
func formatBps(bps int64) string {
	whole := bps / 100
	frac := bps % 100
	if frac < 0 {
		frac = -frac
	}
	return strconv.FormatInt(whole, 10) + "." + padLeft(frac, 2) + "%"
}

// formatAge renders a block age, or "n/a" when there is nothing to date from.
func formatAge(age int64) string {
	if age < 0 {
		return "n/a"
	}
	return strconv.FormatInt(age, 10)
}

// padLeft zero-pads n to width digits. Needed because a fractional part loses
// its leading zeros when formatted as a plain integer: 49050 % 1e6 = 49050,
// which must print as "049050", not "49050".
func padLeft(n int64, width int) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

// M3 scenario tests: multi-act stories played out by moving the chain clock
// with testing.SkipHeights (signature verified against
// gnovm/tests/stdlibs/testing/context_testing.gno: advances Height by count
// and Time by 5s per block; usage precedent:
// examples/quarantined/gno.land/r/tests/vm/skipheight/skiptime_test.gno).
//
// These are the §14 M3 "source death" and "poisoned source" scenarios. The
// unit tests prove individual rules; these prove the rules compose into sane
// behaviour over time, which is what an operator actually experiences.
package oracle

import (
	"testing"
)

// TestScenario_SourceDeath plays a full feeder-failure story:
//
//	Act 1  all three sources healthy -> median 49050 published, ANSWERING.
//	Act 2  kucoin's feeder dies (stops submitting). After its prices go stale,
//	       kraken+coingecko keep the feed alive: quorum degrades 3->2, median
//	       49125, still ANSWERING. Graceful degradation, not an outage.
//	Act 3  kraken dies too. One fresh source is below quorum -> GetPrice
//	       REFUSES. The last median is NOT erased (f.published stays true,
//	       f.median stays 49125) - the dashboard keeps the evidence of what
//	       the feed last believed while refusing to serve it as current.
//	Act 4  everyone comes back -> full quorum, median 49050, ANSWERING.
//
// Staleness boundary is exact (feedmath: age == window is fresh, window+1 is
// stale, cross-checked in Python): skips of 301 blocks against the 300-block
// default window.
func TestScenario_SourceDeath(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)

	// Act 1: healthy.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49200)
	if p, _ := GetPrice(asset); p != 49050 {
		t.Fatalf("act 1: published %d, want 49050", p)
	}
	if f.included != 3 {
		t.Fatalf("act 1: included %d, want 3", f.included)
	}

	// Act 2: kucoin dies at h100; at h401 its age is 301 > 300 -> stale.
	testing.SkipHeights(301)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49200)
	if p, _ := GetPrice(asset); p != 49125 {
		t.Fatalf("act 2: published %d, want 49125 (median of the surviving pair)", p)
	}
	if f.included != 2 {
		t.Fatalf("act 2: included %d, want 2 (kucoin must be culled by staleness)", f.included)
	}

	// Act 3: kraken dies too. Only coingecko keeps submitting.
	testing.SkipHeights(301) // h702: kucoin+kraken ages 602/301 -> stale
	submitAs(cur, coingeckoK, "coingecko", 49200)
	mustPanic(t, "act 3: GetPrice below quorum", func() { GetPrice(asset) })
	if !f.published || f.median != 49125 {
		t.Fatalf("act 3: last median erased (published=%v median=%d); evidence must survive", f.published, f.median)
	}

	// Act 4: full recovery, all three fresh again at h702.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	p, h := GetPrice(asset)
	if p != 49050 || h != 702 {
		t.Fatalf("act 4: got (%d, %d), want (49050, 702)", p, h)
	}
	if f.included != 3 {
		t.Fatalf("act 4: included %d, want 3", f.included)
	}
}

// TestScenario_PoisonedSourceDuringOutage is the OTHER half of O19: the
// bootstrap window can never REOPEN once something has been published.
//
//	Act 1  honest cluster publishes 49050.
//	Act 2  total outage: all sources go stale, feed refuses (correct).
//	Act 3  a compromised coingecko spams 99200 through the outage. Every
//	       submission is REJECTED by the deviation guard, whose reference is
//	       the last published median (deviationReference step 2) - the wild
//	       price is never stored, never published, and the rejection counter
//	       keeps public evidence. Pre-O19 reasoning said "no reference during
//	       an outage"; that is only true before the FIRST publication.
//	Act 4  honest sources return; they are judged against the last published
//	       median, accepted, and the feed republishes the honest number while
//	       the attacker's stale entry sits visibly in the table.
//	Act 5  one more attack attempt -> still rejected, now against the fresh
//	       consistent reference. Median never moved to poison at any point.
func TestScenario_PoisonedSourceDuringOutage(cur realm, t *testing.T) {
	setup(cur, 100)
	f := mustFeedFor(t, asset)
	coingecko := f.getSource("coingecko")

	// Act 1: honest publication.
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	submitAs(cur, coingeckoK, "coingecko", 49200)
	if p, _ := GetPrice(asset); p != 49050 {
		t.Fatalf("act 1: published %d, want 49050", p)
	}

	// Act 2: outage - everyone goes stale.
	testing.SkipHeights(301) // h401
	mustPanic(t, "act 2: GetPrice during a total outage", func() { GetPrice(asset) })

	// Act 3: attacker spams through the outage, time passing between shots.
	for i := int64(1); i <= 3; i++ {
		submitAs(cur, coingeckoK, "coingecko", 99200)
		if coingecko.rejected != i {
			t.Fatalf("act 3 shot %d: rejected=%d, want %d", i, coingecko.rejected, i)
		}
		if coingecko.price != 49200 {
			t.Fatalf("act 3 shot %d: rejected price was STORED (%d)", i, coingecko.price)
		}
		if f.median != 49050 {
			t.Fatalf("act 3 shot %d: median moved to %d under attack", i, f.median)
		}
		mustPanic(t, "act 3: GetPrice must keep refusing while only poison is fresh-lacking",
			func() { GetPrice(asset) })
		testing.SkipHeights(50)
	}

	// Act 4: honest majority returns (h551 after the skips above).
	submitAs(cur, kucoinKey, "kucoin", 48900)
	submitAs(cur, krakenKey, "kraken", 49050)
	p, _ := GetPrice(asset)
	if p != 48975 {
		t.Fatalf("act 4: published %d, want 48975 (median of the honest pair)", p)
	}
	if f.included != 2 {
		t.Fatalf("act 4: included %d, want 2", f.included)
	}
	if coingecko.hasSubmission && coingecko.isFresh(551) {
		t.Fatal("act 4: the attacker's stale entry must not count as fresh")
	}

	// Act 5: attack again against the fresh consistent reference.
	submitAs(cur, coingeckoK, "coingecko", 99200)
	if coingecko.rejected != 4 {
		t.Fatalf("act 5: rejected=%d, want 4", coingecko.rejected)
	}
	if p2, _ := GetPrice(asset); p2 != 48975 {
		t.Fatalf("act 5: median moved to %d, want 48975", p2)
	}
}

// Package oracle is a multi-source GNOT/USD price feed for gno.land.
//
// Three registered sources (one exchange/API each) submit prices from their own
// keys. The feed publishes the MEDIAN of the submissions that are still fresh,
// and refuses to answer at all when it cannot be trusted - rather than serving a
// stale or under-supported number.
//
// Design decisions, all owner-approved and recorded in the master build doc:
//
//	O2  one key per source, enforced on-chain (a wrong key cannot submit)
//	O3  aggregate by median, not mean (one bad quote cannot move it)
//	O5  reject a submission deviating > 10% from the other fresh sources
//	O6  a source is fresh for 300 blocks; answering needs >= 2 of 3 fresh
//	O7  prices are integers scaled by 1e6 - no floats on-chain
//	O11 no "anyone may set any price" switch, not even for demos
//	O19 only a mutually CONSISTENT subset of the fresh sources publishes or
//	    anchors the guard: sources disagreeing with the fresh set's median are
//	    culled, so one compromised key cannot poison the median during a
//	    no-reference window, and a disagreeing pair freezes instead of
//	    publishing a coin-flip midpoint
//
// Everything numeric lives in the feedmath package. This realm holds state,
// authorization and events only: if a rule about prices is wrong, the bug is in
// feedmath and its tests catch it there.
//
// API verified 2026-11-25 against gnolang/gno tag v1.8.0:
//
//	examples/gno.land/p/nt/avl/v0        Tree zero value is usable; Get returns
//	                                     nil when absent; values are `any`
//	examples/gno.land/r/archive/boards   the nested-tree pattern used here:
//	                                     outer tree stores *struct, inner
//	                                     avl.Tree is a value field
//	gnovm/stdlibs/chain/emit_event.gno   chain.Emit(typ string, attrs ...string),
//	                                     attrs are key/value pairs
//	gnovm/stdlibs/chain/runtime          ChainHeight() int64, Realm.Previous(),
//	                                     IsUserCall(), Address()
package oracle

import (
	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
	"gno.land/p/nt/avl/v0"
)

// ---- Event names ---------------------------------------------------------
//
// chain.Emit takes a type string plus an even number of attribute strings,
// read as key/value pairs. Events are how an off-chain watcher (or the feeder
// bot's own logs) can see what the feed did without parsing Render output.

const (
	PriceSubmittedEvent   = "PriceSubmitted"
	PriceRejectedEvent    = "PriceRejected"
	MedianUpdatedEvent    = "MedianUpdated"
	SourceRegisteredEvent = "SourceRegistered"
	SourceRemovedEvent    = "SourceRemoved"
	ConfigChangedEvent    = "ConfigChanged"
	PausedEvent           = "Paused"
)

// ---- Types ---------------------------------------------------------------

// source is one registered price source: who is allowed to speak for it, and
// what it last said.
//
// Stored as a POINTER inside feed.sources. That matters: avl.Tree values are
// `any`, so storing a struct by value would hand back a copy and mutations
// would silently vanish. The pointer is what makes updates stick, and it is the
// same pattern r/archive/boards uses.
type source struct {
	id      string  // "kucoin", "kraken", "coingecko"
	asset   string  // "GNOT"
	keyAddr address // the ONLY address that may submit for this source

	price         feedmath.Price // last ACCEPTED price
	height        int64          // block height of that acceptance
	hasSubmission bool           // false until the first accepted price

	rejected      int64 // how many submissions the deviation guard refused
	lastRejectBps int64 // deviation of the most recent refusal, in basis points
}

// feed is everything the oracle knows about one asset.
//
// sources is an avl.Tree rather than a slice so that looking one source up by
// id costs O(log n) storage reads instead of loading the whole list - cheap now
// with three sources, and it does not degrade if assets or sources are added.
type feed struct {
	asset   string
	sources avl.Tree // sourceID -> *source

	// The published answer. It is only rewritten when a submission arrives and
	// at least minFreshSources sources are fresh; GetPrice re-checks freshness
	// at read time rather than trusting these fields blindly.
	median    feedmath.Price
	medianAt  int64 // height at which the median was last published
	included  int   // how many fresh sources went into it
	published bool  // false until the first quorum is reached
}

// config holds the tunable rules. Every field is admin-settable so the
// thresholds can be retuned during burn-in without redeploying the realm.
type config struct {
	stalenessBlocks int64 // O6: how long a submission stays fresh
	deviationBps    int64 // O5: rejection threshold, basis points
	minFreshSources int   // O6: quorum needed to answer at all
	paused          bool  // emergency stop: everything reverts
}

// Shipped defaults, matching ledger O5/O6.
const (
	DefaultStalenessBlocks = int64(300)
	DefaultDeviationBps    = int64(1000) // 10%
	DefaultMinFreshSources = 2           // of 3 registered sources
)

// ---- State ---------------------------------------------------------------
//
// Package-level vars in a realm are stored on-chain and survive between
// transactions, paid for by the realm's storage deposit.

var feeds avl.Tree // asset -> *feed

var cfg = config{
	stalenessBlocks: DefaultStalenessBlocks,
	deviationBps:    DefaultDeviationBps,
	minFreshSources: DefaultMinFreshSources,
	paused:          false,
}

// ---- Lookups -------------------------------------------------------------

// getFeed returns the feed for an asset, or nil when the asset is unknown.
func getFeed(asset string) *feed {
	f, ok := feeds.Get(asset).(*feed)
	if !ok {
		return nil
	}
	return f
}

// mustFeed returns the feed for an asset or panics. A caller naming an asset
// the oracle was never told about is a mistake, not a market condition, so it
// gets a clear revert instead of a silent zero.
func mustFeed(asset string) *feed {
	f := getFeed(asset)
	if f == nil {
		panic("oracle: unknown asset")
	}
	return f
}

// getSource returns one registered source, or nil.
func (f *feed) getSource(sourceID string) *source {
	s, ok := f.sources.Get(sourceID).(*source)
	if !ok {
		return nil
	}
	return s
}

// isFresh reports whether this source's last accepted submission still counts,
// per ledger O6. A source that has never submitted is never fresh.
func (s *source) isFresh(atHeight int64) bool {
	if !s.hasSubmission {
		return false
	}
	return feedmath.IsFresh(s.height, atHeight, cfg.stalenessBlocks)
}

// Read API for the web frontend.
//
// The frontend talks to the realm through the testnet RPC `vm/qeval`
// endpoint, which returns values in Gno syntax. These helpers return
// plain JSON strings instead, so the browser can parse them with
// JSON.parse after stripping the outer Gno string quoting.
//
// This mirrors the pattern other Gno.land projects use (a dedicated
// read API for the frontend); the functions are read-only and change
// no state.
package tavernquest

import "strconv"

// jsonEscape escapes a string for inclusion in a JSON string value.
// Tavern text uses only plain letters, apostrophes and punctuation,
// but escaping keeps the output valid whatever the input holds.
func jsonEscape(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			out += "\\\""
		case '\\':
			out += "\\\\"
		case '\n':
			out += "\\n"
		default:
			out += string(c)
		}
	}
	return out
}

// StatsJSON returns the tavern scoreboard as JSON.
func StatsJSON() string {
	s := Stats()
	return "{\"adventurers\":" + strconv.Itoa(s.Adventurers) +
		",\"questsDone\":" + strconv.Itoa(s.QuestsDone) +
		",\"goldTipped\":" + strconv.Itoa(s.GoldTipped) +
