package galcredentials

import "chain/runtime"

// ApprovalStatus is the lifecycle state of a spend approval.
type ApprovalStatus string

const (
	// ApprovalPending: created, awaiting the owner's decision.
	ApprovalPending ApprovalStatus = "pending"
	// ApprovalApproved: approved once by the owner; the amount was counted.
	ApprovalApproved ApprovalStatus = "approved"
	// ApprovalRejected: rejected by the owner; nothing was counted.
	ApprovalRejected ApprovalStatus = "rejected"
)

// Approval is one over-limit spend waiting for (or decided by) the owner.
type Approval struct {
	ID int64
	Agent address
	Amount int64
	Status ApprovalStatus
	// CreatedHeight is the block height the approval was requested at.
	CreatedHeight int64
	// ExpiresHeight is the last block height at which the approval may
	// still be approved. After that height it is permanently unusable.
	// Expired approvals stay stored as "pending" but the expiry check in
	// Approve always fails for them, so they can never be used.
	ExpiresHeight int64
}

// approvalWindowBlocks is how long a pending approval stays usable:
// 1000 blocks from creation. That is long enough for an owner to see the
// request and act on it, and short enough that an approval created in the
// moment cannot be replayed much later.
const approvalWindowBlocks = 1000

var approvals = map[int64]*Approval{}
var nextApprovalID int64 = 1

// RequestApproval asks the owner to approve a spend that is over the
// per-transaction limit. It mirrors the needs-approval branch of
// AuthorizeSpend: the credential must exist and be active, the amount
// must be positive, over the per-transaction limit, and still within the
// daily limit (after the daily rollover). Anything else panics, so no
// approval record is created for a spend that would be denied outright.
// Requesting creates no spending power and counts nothing; only the
// owner can approve (Approve) or reject (Reject). Any caller may
// request, typically the agent itself or the app acting for it.
// It returns the approval ID.
func RequestApproval(cur realm, agent address, amount int64) int64 {
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Status != StatusActive {
		panic("credential not active")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	rolloverDay(cred)
	if amount <= cred.PerTxLimit {
		panic("spend does not need approval")
	}
	if cred.SpentToday+amount > cred.DailyLimit {
		panic("spend exceeds daily limit")
	}
	id := nextApprovalID
	nextApprovalID++
	height := runtime.ChainHeight()
	approvals[id] = &Approval{
		ID:            id,
		Agent:         agent,
		Amount:        amount,
		Status:        ApprovalPending,
		CreatedHeight: height,
		ExpiresHeight: height + approvalWindowBlocks,
	}
	return id
}

// GetApproval returns a copy of the approval for an ID, or false if
// there is none. A copy is returned so callers cannot mutate realm state.
func GetApproval(approvalID int64) (Approval, bool) {
	ap, ok := approvals[approvalID]
	if !ok {
		return Approval{}, false
	}
	return *ap, true
}

// Approve authorizes a pending spend, exactly once. Only the credential
// owner may call it (caller from the crossing frame). The amount is
// counted into SpentToday at approve time, and only if the credential
// is still active and the amount still fits the daily limit then —
// other spends since the request may have eaten the budget, so the
// check is re-run here, after the daily rollover. Every failure panics
// (which rolls back state in Gno), so a failed approve counts nothing:
// unknown ID, non-owner, already decided, expired, suspended/revoked
// credential, or an amount that no longer fits the daily limit.
func Approve(cur realm, approvalID int64) {
	ap, ok := approvals[approvalID]
	if !ok {
		panic("approval not found")
	}
	cred, ok := credentials[ap.Agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if ap.Status != ApprovalPending {
		panic("approval not pending")
	}
	if runtime.ChainHeight() > ap.ExpiresHeight {
		panic("approval expired")
	}
	if cred.Status != StatusActive {
		panic("credential not active")
	}
	rolloverDay(cred)
	if cred.SpentToday+ap.Amount > cred.DailyLimit {
		panic("spend exceeds daily limit")
	}
	cred.SpentToday += ap.Amount
	ap.Status = ApprovalApproved
}

// Reject closes a pending approval without authorizing the spend:
// nothing is counted. Only the credential owner may call it (caller
// from the crossing frame). Rejecting an already-decided approval
// panics. Rejecting an expired approval is allowed: it is already dead,
// and closing it just tidies the record.
func Reject(cur realm, approvalID int64) {
	ap, ok := approvals[approvalID]
	if !ok {
		panic("approval not found")
	}
	cred, ok := credentials[ap.Agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if ap.Status != ApprovalPending {
		panic("approval not pending")
	}
	ap.Status = ApprovalRejected
}

package galcredentials

// GALcredentials is an Agent Passport / spending guard for AI agents on
// Gno.land. Tickets 02-06 add minting, spending limits, approval gate,
// kill switch and human proof.

package galcredentials

// AttachHumanProof attaches a human-proof record to a credential: a hash
// and a signature that were verified off-chain (for example an X account
// bound to the owner's wallet, as in Xaverus). The realm stores the
// record and shows it on the credential detail page; it does NOT verify
// the outside account itself, because a Gno realm cannot make HTTP
// calls. Both values are plain strings: the hash is expected in hex
// (e.g. a 64-character sha256 digest) and the signature in base64.
// Only the credential owner may call it (caller from the crossing
// frame). The credential must exist, and the hash must not be empty.
// Attaching again replaces the previous proof. Attaching a proof changes
// nothing else about the credential: not its limits, its spent total,
// or its status.
func AttachHumanProof(cur realm, agent address, proofHash string, proofSig string) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if proofHash == "" {
		panic("human proof hash must not be empty")
	}
	cred.HumanProofHash = proofHash
	cred.HumanProofSig = proofSig
}

package galcredentials

// Suspend pauses a credential: while suspended, IsActive reports false
// and AuthorizeSpend denies every spend, and pending approvals cannot be
// approved (Approve checks the status). Only the credential owner may
// call it (caller from the crossing frame). The credential must exist
// and be active; suspending an already-suspended or revoked credential
// panics, so a failed suspend changes nothing.
func Suspend(cur realm, agent address) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if cred.Status != StatusActive {
		panic("credential not active")
	}
	cred.Status = StatusSuspended
}

// Reactivate brings a suspended credential back to active, so the agent
// may spend again under its limits (spending already counted before the
// suspension is kept). Only the credential owner may call it. The
// credential must exist and be suspended; reactivating an active or
// revoked credential panics.
func Reactivate(cur realm, agent address) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if cred.Status != StatusSuspended {
		panic("credential not suspended")
	}
	cred.Status = StatusActive
}

// Revoke is the kill switch: it permanently disables a credential. A
// revoked credential can never spend again, can never be reactivated,
// and can never be suspended. Only the credential owner may call it.
// The credential must exist and not already be revoked; revoking an
// already-revoked credential panics. A suspended credential may be
// revoked directly, without reactivating it first.
func Revoke(cur realm, agent address) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	if cred.Status == StatusRevoked {
		panic("credential already revoked")
	}
	cred.Status = StatusRevoked
}

package galcredentials

import "time"

// Mint creates a credential for one agent address. The caller becomes the
// owner. Caller identity comes from the crossing frame, never from a
// parameter.
func Mint(cur realm, agent address, perTxLimit int64, dailyLimit int64, runtime string) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	if _, exists := credentials[agent]; exists {
		panic("credential already exists")
	}
	owner := cur.Previous().Address()
	credentials[agent] = &Credential{
		Agent:      agent,
		Owner:      owner,
		PerTxLimit: perTxLimit,
		DailyLimit: dailyLimit,
		SpentToday: 0,
		LastSpendDay: currentDay(),
		Status:     StatusActive,
		Runtime:    runtime,
		CreatedAt:  time.Now().Unix(),
	}
}

// SetLimits changes the spending limits of a credential. Only the
// credential owner may call it.
func SetLimits(cur realm, agent address, perTxLimit int64, dailyLimit int64) {
	if !cur.IsCurrent() {
		panic("not a live realm call")
	}
	cred, ok := credentials[agent]
	if !ok {
		panic("credential not found")
	}
	if cred.Owner != cur.Previous().Address() {
		panic("not credential owner")
	}
	cred.PerTxLimit = perTxLimit
	cred.DailyLimit = dailyLimit
}

// Get returns a copy of the credential for an agent address, or false if
// there is none. A copy is returned so callers cannot mutate realm state.
func Get(agent address) (Credential, bool) {
	cred, ok := credentials[agent]
	if !ok {
		return Credential{}, false
	}
	return *cred, true
}

package galcredentials

import (
	"strconv"
	"strings"
)

const homeHeader = "# GALcredentials\n\nAgent Passport / spending guard for AI agents on Gno.land.\n\n"

// Render shows the realm in gnoweb. "" or "/" lists all credentials;
// "/<agent>" or ":<agent>" shows one credential. gnoweb links detail
// pages with the ":" form (…/galcredentials/v0:<agent>), so both are
// accepted.
func Render(path string) string {
	agent := strings.Trim(path, "/:")
	if agent == "" {
		if len(credentials) == 0 {
			return homeHeader + "No credentials yet.\n"
		}
		out := homeHeader + "## Credentials\n\n"
		for _, cred := range credentials {
			out += "- " + string(cred.Agent) + ": " + string(cred.Status) +
				", per-tx " + strconv.FormatInt(cred.PerTxLimit, 10) +
				", daily " + strconv.FormatInt(cred.DailyLimit, 10) + "\n"
		}
		return out
	}
	cred, ok := Get(address(agent))
	if !ok {
		return homeHeader + "Credential not found.\n"
	}
	out := homeHeader + "## Credential " + string(cred.Agent) + "\n\n" +
		"- Owner: " + string(cred.Owner) + "\n" +
		"- Status: " + string(cred.Status) + "\n" +
		"- Per-transaction limit: " + strconv.FormatInt(cred.PerTxLimit, 10) + "\n" +
		"- Daily limit: " + strconv.FormatInt(cred.DailyLimit, 10) + "\n" +
		"- Spent today: " + strconv.FormatInt(cred.SpentToday, 10) + "\n" +
		"- Runtime: " + cred.Runtime + "\n"
	if cred.HumanProofHash != "" {
		// The hash is shown in full: it is expected to be a short hex
		// digest. The signature is not printed in full — it can be long
		// (e.g. base64) — only whether one is present is shown.
		out += "- Human proof: " + cred.HumanProofHash + "\n"
		if cred.HumanProofSig != "" {
			out += "- Human proof signature: present\n"
		} else {
			out += "- Human proof signature: absent\n"
		}
	}
	return out
}

package galcredentials

import "time"

// SpendDecision is the answer AuthorizeSpend gives to a caller (another
// realm or an off-chain client). It is a plain string so it reads clearly
// in `gnokey` output and in gnoweb, and so another realm can compare it
// directly: `AuthorizeSpend(...) == SpendAllowed`.
type SpendDecision string

const (
	// SpendAllowed: the spend fits the limits and has been counted.
	SpendAllowed SpendDecision = "allowed"
	// SpendDenied: the spend is refused (unknown/suspended/revoked agent,
	// non-positive amount, or over the daily limit). Nothing is counted.
	SpendDenied SpendDecision = "denied"
	// SpendNeedsApproval: the spend is over the per-transaction limit but
	// within the daily limit. Nothing is counted yet; the owner must
	// approve it first (ticket 04).
	SpendNeedsApproval SpendDecision = "needs_approval"
)

const secondsPerDay = 86400

// currentDay is the current block day: block timestamp (time.Now() is the
// block timestamp in Gno) divided into whole days since the Unix epoch.
func currentDay() int64 {
	return time.Now().Unix() / secondsPerDay
}

// rolloverDay resets a credential's daily total when the block day has
// changed since its last spend. This is day-boundary bookkeeping, not
// part of any spend, so it runs before every limit check.
func rolloverDay(cred *Credential) {
	today := currentDay()
	if cred.LastSpendDay != today {
		cred.SpentToday = 0
		cred.LastSpendDay = today
	}
}

// IsActive reports whether an agent has a credential that is currently
// usable. Unknown agents and suspended/revoked credentials are inactive.
// This is the read-only half of the public seam for other realms; it
// never changes state.
func IsActive(agent address) bool {
	cred, ok := credentials[agent]
	if !ok {
		return false
	}
	return cred.Status == StatusActive
}

// AuthorizeSpend is the spending-guard half of the public seam: any other
// realm (or an off-chain caller via `gnokey maketx call`) asks it before
// letting an agent spend, and branches on the answer.
//
//   - SpendAllowed: the spend fits the limits. It is counted in
//     SpentToday immediately, so a second call sees the updated total.
//     (Ticket 03 semantics: the spend is recorded when allowed. The
//     confirm-after-transfer pattern, where a failed transfer must not
//     eat the budget, is a later concern, not this ticket.)
//   - SpendNeedsApproval: over the per-transaction limit but within the
//     daily limit. Nothing is counted; the owner must approve it first
//     (ticket 04 creates the approval record).
//   - SpendDenied: unknown, suspended or revoked agent, a non-positive
//     amount, or a spend that would pass the daily limit. Denied spends
//     never count and never change state (except the day rollover below).
//
// The daily total resets automatically when the block day changes: if the
// stored LastSpendDay differs from today, SpentToday is zeroed first.
// A denied spend on a new day still performs that reset, because the
// reset is day-boundary bookkeeping, not part of the spend itself.
func AuthorizeSpend(cur realm, agent address, amount int64) SpendDecision {
	cred, ok := credentials[agent]
	if !ok {
		return SpendDenied
	}
	if cred.Status != StatusActive {
		return SpendDenied
	}
	if amount <= 0 {
		return SpendDenied
	}
	rolloverDay(cred)
	if amount > cred.PerTxLimit {
		if cred.SpentToday+amount > cred.DailyLimit {
			return SpendDenied
		}
		return SpendNeedsApproval
	}
	if cred.SpentToday+amount > cred.DailyLimit {
		return SpendDenied
	}
	cred.SpentToday += amount
	return SpendAllowed
}

package galcredentials

// Status is the lifecycle state of a credential.
type Status string

const (
	StatusActive    Status = "active"
	StatusSuspended Status = "suspended"
	StatusRevoked   Status = "revoked"
)

// Credential is one agent's passport: who owns it, what the agent may
// spend, and whether it is currently usable.
type Credential struct {
	Agent      address
	Owner      address
	PerTxLimit int64
	DailyLimit int64
	SpentToday int64
	// LastSpendDay is the block day (block timestamp / 86400) the
	// SpentToday amount belongs to. When the day changes, AuthorizeSpend
	// resets SpentToday to zero before checking the limits.
	LastSpendDay int64
	Status       Status
	Runtime    string
	CreatedAt  int64
	// HumanProofHash is the off-chain-verified human-proof hash (plain
	// string, e.g. hex) attached by the owner, empty when no proof has
	// been attached. HumanProofSig is the matching signature (plain
	// string, e.g. base64), empty when no signature was attached.
	HumanProofHash string
	HumanProofSig  string
}

// credentials holds one credential per agent address.
//
// NOTE (ticket 02 follow-up): the spec prefers an AVL tree
// (gno.land/p/nt/avl/v0) so lookups stay O(log n) as the registry grows.
// A plain map is used for now because `gno test` in this VM cannot download
// gno.land/p/... packages: the Go RPC client cannot complete TLS through the
// egress proxy (gnokey query fails the same way against both mainnet and
// Onyx RPCs), and the AVL package also pulls in ufmt. The map is
// deterministic (insertion order) in Gno. Switch to AVL before mainnet, once
// the registry is expected to grow past ~250 entries.
var credentials = map[address]*Credential{}

// Package arisan holds the stateless building blocks of an arisan: the
// Indonesian rotating savings circle (a ROSCA). Every round each member puts
// the same amount into the pot and one member who has not won yet takes the
// whole pot home, until everybody has had a turn.
//
// The package keeps no state. It only provides the pieces any realm needs to
// run a circle, so other realms can reuse them with their own storage, token
// or rules:
//
//   - Mode, ParseMode: how the next winner is chosen (giliran / kocok)
//   - MixEntropy, PickIndex, PickWinner: deterministic, auditable selection
//   - FormatGNOT, ShortAddr, ProgressBar: small rendering helpers
//   - Wheel: an SVG "arisan wheel" that gnoweb renders inline
//
// The reference realm built on it is r/<namespace>/arisanku.
package arisan

import (
	"crypto/sha256"
	"strconv"
	"strings"
)

// Mode decides how the winner of a round is chosen.
type Mode int

const (
	// ModeGiliran ("taking turns"): the earliest-joined eligible member who
	// has not won yet receives the pot. Fully predictable, zero trust.
	ModeGiliran Mode = iota
	// ModeKocok ("shake the jar"): the winner is drawn among eligible members
	// from on-chain entropy, like shaking the rolled-up names in a glass jar.
	ModeKocok
)

// String returns the canonical, lowercase name of the mode.
func (m Mode) String() string {
	switch m {
	case ModeGiliran:
		return "giliran"
	case ModeKocok:
		return "kocok"
	}
	return "unknown"
}

// Label returns a human label for UIs, in Indonesian with an English gloss.
func (m Mode) Label() string {
	switch m {
	case ModeGiliran:
		return "Giliran (fixed turns)"
	case ModeKocok:
		return "Kocok (random draw)"
	}
	return "Unknown"
}

// ParseMode accepts "giliran"/"rotation"/"turns" and "kocok"/"draw"/"random"
// (case-insensitive). ok is false for anything else.
func ParseMode(s string) (m Mode, ok bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "giliran", "rotation", "turns", "turn", "0":
		return ModeGiliran, true
	case "kocok", "draw", "random", "lottery", "1":
		return ModeKocok, true
	}
	return ModeGiliran, false
}

// MixEntropy folds parts into the previous seed with SHA-256 and returns the
// new 32-byte seed. Feeding every payment (payer, height, time) into the seed
// makes the final draw depend on the whole round's history, not on a single
// caller.
func MixEntropy(prev []byte, parts ...string) []byte {
	buf := make([]byte, 0, len(prev)+64)
	buf = append(buf, prev...)
	for _, p := range parts {
		// length-prefix every part so ("ab","c") != ("a","bc")
		buf = append(buf, []byte(strconv.Itoa(len(p)))...)
		buf = append(buf, ':')
		buf = append(buf, []byte(p)...)
	}
	sum := sha256.Sum256(buf)
	return sum[:]
}

// PickIndex maps a seed to an index in [0, n). It uses the first 8 bytes of
// the seed as a big-endian uint64. It panics if n <= 0.
func PickIndex(seed []byte, n int) int {
	if n <= 0 {
		panic("arisan: PickIndex needs n > 0")
	}
	var x uint64
	for i := 0; i < 8 && i < len(seed); i++ {
		x = x<<8 | uint64(seed[i])
	}
	return int(x % uint64(n))
}

// PickWinner returns one element of candidates (member indexes, in join
// order). In ModeGiliran it is the first candidate; in ModeKocok it is chosen
// by PickIndex(seed). It returns -1 when there is no candidate.
func PickWinner(mode Mode, candidates []int, seed []byte) int {
	if len(candidates) == 0 {
		return -1
	}
	if mode == ModeKocok {
		return candidates[PickIndex(seed, len(candidates))]
	}
	return candidates[0]
}

// FormatGNOT renders an amount of ugnot as GNOT with up to 6 decimals and no
// trailing zeros: 1500000 -> "1.5 GNOT", 250 -> "0.00025 GNOT".
func FormatGNOT(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	if neg {
		s = "-" + s
	}
	return s + " GNOT"
}

// ShortAddr shortens a bech32 address for display: g1abcd…wxyz.
func ShortAddr(addr string) string {
	if len(addr) <= 13 {
		return addr
	}
	return addr[:6] + "…" + addr[len(addr)-4:]
}

// ProgressBar renders done/total as a fixed-width text bar, e.g.
// ProgressBar(2, 5, 10) == "▰▰▰▰▱▱▱▱▱▱".
func ProgressBar(done, total, width int) string {
	if width <= 0 {
		return ""
	}
	if total <= 0 {
		return strings.Repeat("▱", width)
	}
	if done < 0 {
		done = 0
	}
	if done > total {
		done = total
	}
	filled := done * width / total
	return strings.Repeat("▰", filled) + strings.Repeat("▱", width-filled)
}

package arisan

import (
	"strings"
	"testing"
)

func TestParseMode(t *testing.T) {
	cases := []struct {
		in   string
		want Mode
		ok   bool
	}{
		{"giliran", ModeGiliran, true},
		{" Rotation ", ModeGiliran, true},
		{"KOCOK", ModeKocok, true},
		{"draw", ModeKocok, true},
		{"random", ModeKocok, true},
		{"", ModeGiliran, false},
		{"auction", ModeGiliran, false},
	}
	for _, c := range cases {
		got, ok := ParseMode(c.in)
		if got != c.want || ok != c.ok {
			t.Errorf("ParseMode(%q) = %v,%v want %v,%v", c.in, got, ok, c.want, c.ok)
		}
	}
	if ModeGiliran.String() != "giliran" || ModeKocok.String() != "kocok" || Mode(9).String() != "unknown" {
		t.Errorf("unexpected Mode.String values")
	}
}

func TestMixEntropyDeterministicAndSensitive(t *testing.T) {
	a := MixEntropy(nil, "g1alice", "100")
	b := MixEntropy(nil, "g1alice", "100")
	if string(a) != string(b) {
		t.Fatalf("MixEntropy must be deterministic")
	}
	if len(a) != 32 {
		t.Fatalf("want 32-byte seed, got %d", len(a))
	}
	// length prefixing: ("ab","c") must differ from ("a","bc")
	if string(MixEntropy(nil, "ab", "c")) == string(MixEntropy(nil, "a", "bc")) {
		t.Fatalf("parts must be length-prefixed")
	}
	// chaining depends on previous seed
	if string(MixEntropy(a, "x")) == string(MixEntropy(nil, "x")) {
		t.Fatalf("previous seed must matter")
	}
}

func TestPickIndexRangeAndSpread(t *testing.T) {
	counts := make([]int, 5)
	seed := []byte("seed")
	for i := 0; i < 500; i++ {
		seed = MixEntropy(seed, "round")
		idx := PickIndex(seed, 5)
		if idx < 0 || idx >= 5 {
			t.Fatalf("index out of range: %d", idx)
		}
		counts[idx]++
	}
	for i, c := range counts {
		// expected 100 each; a fair hash never lands this far off
		if c < 60 || c > 140 {
			t.Errorf("bucket %d has %d hits, distribution looks broken: %v", i, c, counts)
		}
	}
}

func TestPickIndexPanicsOnZero(t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Fatalf("expected panic for n=0")
		}
	}()
	PickIndex([]byte{1}, 0)
}

func TestPickWinner(t *testing.T) {
	if PickWinner(ModeGiliran, nil, nil) != -1 {
		t.Fatalf("no candidates must return -1")
	}
	if got := PickWinner(ModeGiliran, []int{3, 1, 4}, []byte("anything")); got != 3 {
		t.Fatalf("giliran must take the first candidate, got %d", got)
	}
	seed := MixEntropy(nil, "fixed")
	cands := []int{2, 5, 7}
	got := PickWinner(ModeKocok, cands, seed)
	if got != cands[PickIndex(seed, 3)] {
		t.Fatalf("kocok must follow PickIndex")
	}
}

func TestFormatGNOT(t *testing.T) {
	cases := map[int64]string{
		0:          "0 GNOT",
		1000000:    "1 GNOT",
		1500000:    "1.5 GNOT",
		250:        "0.00025 GNOT",
		123456789:  "123.456789 GNOT",
		-2000000:   "-2 GNOT",
		1000000001: "1000.000001 GNOT",
	}
	for in, want := range cases {
		if got := FormatGNOT(in); got != want {
			t.Errorf("FormatGNOT(%d) = %q want %q", in, got, want)
		}
	}
}

func TestShortAddrAndProgress(t *testing.T) {
	a := "g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y"
	if got := ShortAddr(a); got != "g19py8…w56y" {
		t.Errorf("ShortAddr = %q", got)
	}
	if ShortAddr("g1short") != "g1short" {
		t.Errorf("short addresses must be unchanged")
	}
	if got := ProgressBar(2, 5, 10); got != "▰▰▰▰▱▱▱▱▱▱" {
		t.Errorf("ProgressBar = %q", got)
	}
	if got := ProgressBar(9, 5, 4); got != "▰▰▰▰" {
		t.Errorf("ProgressBar clamps: %q", got)
	}
	if got := ProgressBar(1, 0, 3); got != "▱▱▱" {
		t.Errorf("ProgressBar zero total: %q", got)
	}
}

func TestWheel(t *testing.T) {
	slots := []Slot{
		{Label: "1", Caption: "Rizki", State: SlotWon},
		{Label: "2", Caption: "<script>", State: SlotPaid},
		{Label: "3", Caption: "Ayu", State: SlotWinner},
		{Label: "4", Caption: "Budi", State: SlotLate},
	}
	svg := Wheel(slots, "4 GNOT", "Putaran 2 / 4")
	if !strings.HasPrefix(svg, "<svg") || !strings.HasSuffix(svg, "</svg>") {
		t.Fatalf("not an svg document")
	}
	if strings.Contains(svg, "<script>") {
		t.Fatalf("captions must be escaped")
	}
	if !strings.Contains(svg, "&lt;script") {
		t.Fatalf("escaped caption missing")
	}
	if strings.Count(svg, `r="26"`) != 4 {
		t.Fatalf("want 4 seats")
	}
	img := WheelImage("wheel", slots, "4 GNOT", "Putaran 2 / 4")
	if !strings.HasPrefix(img, "![wheel](data:image/svg+xml;base64,") {
		t.Fatalf("bad markdown image: %.60s", img)
	}
	if empty := Wheel(nil, "0 GNOT", ""); !strings.Contains(empty, "no members yet") {
		t.Fatalf("empty wheel should say so")
	}
}

package arisan

import (
	"encoding/base64"
	"html"
	"math"
	"strconv"
	"strings"
)

// SlotState is the state of one member seat on the arisan wheel.
type SlotState int

const (
	SlotWaiting SlotState = iota // has not paid this round yet
	SlotPaid                     // paid this round, still waiting for a turn
	SlotWon                      // already received a pot in an earlier round
	SlotWinner                   // the member highlighted as latest winner
	SlotLate                     // has an unpaid debt (missed a round)
)

// Slot is one seat on the wheel. Label is drawn inside the seat (keep it to
// 1-3 characters, e.g. the join number); Caption is drawn under it.
type Slot struct {
	Label   string
	Caption string
	State   SlotState
}

type slotStyle struct{ fill, stroke, text string }

func styleOf(s SlotState) slotStyle {
	switch s {
	case SlotPaid:
		return slotStyle{"#2f9e6b", "#7ee2b0", "#ffffff"}
	case SlotWon:
		return slotStyle{"#8a6d1f", "#e8c25a", "#fff6d8"}
	case SlotWinner:
		return slotStyle{"#f2b632", "#fff1b8", "#3a2a00"}
	case SlotLate:
		return slotStyle{"#9e2f3c", "#f08a97", "#ffffff"}
	}
	return slotStyle{"#3a3330", "#8c7f77", "#e9e1da"}
}

// Wheel draws the circle as an SVG: one seat per member around a ring, with
// title (e.g. the pot) and subtitle (e.g. "Putaran 2 / 5") in the middle and a
// colour legend underneath. It returns raw SVG markup.
func Wheel(slots []Slot, title, subtitle string) string {
	const (
		w, h   = 420, 470
		cx, cy = 210, 215
		ring   = 150.0
		seatR  = 26
	)
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="420" height="470" viewBox="0 0 420 470" font-family="Inter,Segoe UI,Helvetica,Arial,sans-serif">`)
	b.WriteString(`<defs><radialGradient id="bg" cx="50%" cy="45%" r="70%"><stop offset="0" stop-color="#3b2a20"/><stop offset="1" stop-color="#17110d"/></radialGradient>`)
	b.WriteString(`<radialGradient id="pot" cx="50%" cy="40%" r="60%"><stop offset="0" stop-color="#fbe3a1"/><stop offset="1" stop-color="#c8902a"/></radialGradient></defs>`)
	b.WriteString(`<rect x="0" y="0" width="420" height="470" rx="22" fill="url(#bg)"/>`)
	// ring
	b.WriteString(`<circle cx="210" cy="215" r="150" fill="none" stroke="#6b5444" stroke-width="2" stroke-dasharray="4 6"/>`)
	// pot in the middle
	b.WriteString(`<circle cx="210" cy="215" r="78" fill="url(#pot)" stroke="#fff1c4" stroke-width="3"/>`)
	b.WriteString(`<text x="210" y="208" text-anchor="middle" font-size="20" font-weight="700" fill="#3a2600">` + esc(clip(title, 16)) + `</text>`)
	b.WriteString(`<text x="210" y="234" text-anchor="middle" font-size="13" fill="#5a3d08">` + esc(clip(subtitle, 22)) + `</text>`)

	n := len(slots)
	for i, s := range slots {
		ang := -math.Pi/2 + 2*math.Pi*float64(i)/float64(max1(n))
		x := cx + int(math.Round(ring*math.Cos(ang)))
		y := cy + int(math.Round(ring*math.Sin(ang)))
		st := styleOf(s.State)
		if s.State == SlotWinner {
			b.WriteString(`<circle cx="` + itoa(x) + `" cy="` + itoa(y) + `" r="36" fill="#f2b632" opacity="0.28"/>`)
		}
		b.WriteString(`<circle cx="` + itoa(x) + `" cy="` + itoa(y) + `" r="` + itoa(seatR) + `" fill="` + st.fill + `" stroke="` + st.stroke + `" stroke-width="3"/>`)
		b.WriteString(`<text x="` + itoa(x) + `" y="` + itoa(y+6) + `" text-anchor="middle" font-size="17" font-weight="700" fill="` + st.text + `">` + esc(clip(s.Label, 3)) + `</text>`)
		if s.Caption != "" {
			ty := y + seatR + 15
			if y < cy-ring/2 {
				ty = y - seatR - 7 // top seats: caption above
			}
			b.WriteString(`<text x="` + itoa(x) + `" y="` + itoa(ty) + `" text-anchor="middle" font-size="11" fill="#e9dccf">` + esc(clip(s.Caption, 14)) + `</text>`)
		}
	}
	if n == 0 {
		b.WriteString(`<text x="210" y="80" text-anchor="middle" font-size="13" fill="#e9dccf">no members yet</text>`)
	}
	// legend
	legend := []struct {
		st    SlotState
		label string
	}{{SlotWaiting, "belum bayar"}, {SlotPaid, "sudah bayar"}, {SlotWon, "sudah dapat"}, {SlotWinner, "pemenang"}, {SlotLate, "utang"}}
	lx := 22
	for _, l := range legend {
		st := styleOf(l.st)
		b.WriteString(`<circle cx="` + itoa(lx) + `" cy="440" r="7" fill="` + st.fill + `" stroke="` + st.stroke + `" stroke-width="2"/>`)
		b.WriteString(`<text x="` + itoa(lx+12) + `" y="444" font-size="11" fill="#e9dccf">` + l.label + `</text>`)
		lx += 80
	}
	_ = w
	_ = h
	b.WriteString(`</svg>`)
	return b.String()
}

// WheelImage wraps Wheel in a markdown image with an SVG data URI, which
// gnoweb renders inline.
func WheelImage(alt string, slots []Slot, title, subtitle string) string {
	svg := Wheel(slots, title, subtitle)
	return "![" + strings.ReplaceAll(alt, "]", "") + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg)) + ")"
}

func itoa(i int) string { return strconv.Itoa(i) }

func max1(n int) int {
	if n < 1 {
		return 1
	}
	return n
}

func esc(s string) string { return html.EscapeString(s) }

// clip cuts s to at most n runes, adding an ellipsis when it had to cut.
func clip(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	if n <= 1 {
		return string(r[:n])
	}
	return string(r[:n-1]) + "…"
}

// Package arisanku is a trustless arisan (rotating savings circle, ROSCA) on
// Gno.land.
//
// An arisan is how millions of Indonesians save together: a group agrees on a
// fixed contribution (iuran), every round each member pays in, and one member
// who has not won yet takes the whole pot home. After N rounds every one of
// the N members has received the pot exactly once.
//
// Off-chain, an arisan runs on trust in the organiser (bandar) who holds the
// cash and "shakes the jar" (kocok). ArisanKu replaces the bandar with a realm:
//
//   - the realm holds each round's pot and pays the winner in the same tx
//     that decides the round, so nobody can run away with it;
//   - the winner is chosen by a public rule: Giliran (fixed turns by join
//     order) or Kocok (a draw from entropy mixed by every payment);
//   - a member who misses a payment does not stall the circle: after the
//     deadline the round is decided anyway, the missed contribution becomes a
//     public debt (utang) owed directly to that round's winner, and the
//     debtor cannot win until it is settled;
//   - every member builds a portable reputation (on-time, late, missed,
//     settled) that any circle can read before letting someone in.
//
// Lifecycle: CreateCircle -> Join ... (auto-start when full, or Start) ->
// each round: Pay by every member -> Draw -> ... -> Finished.
package arisandev1

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y/arisan"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	denom = "ugnot"

	// MinContribution is the smallest iuran per member per round (0.1 GNOT).
	MinContribution int64 = 100_000
	// MaxContribution caps the iuran (1,000,000 GNOT) to keep pots sane.
	MaxContribution int64 = 1_000_000_000_000
	// MinMembers and MaxMembers bound the size of a circle.
	MinMembers = 2
	MaxMembers = 12
	// MinPeriodMinutes / MaxPeriodMinutes bound the length of a round.
	MinPeriodMinutes = 1
	MaxPeriodMinutes = 31 * 24 * 60

	maxNameLen = 40
	maxNickLen = 16
)

// Status of a circle.
type Status int

const (
	StatusOpen      Status = iota // recruiting members
	StatusRunning                 // rounds in progress
	StatusFinished                // every member received the pot once
	StatusCancelled               // cancelled by the creator before start
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusRunning:
		return "running"
	case StatusFinished:
		return "finished"
	case StatusCancelled:
		return "cancelled"
	}
	return "unknown"
}

// Member is one seat in a circle.
type Member struct {
	Addr      address
	Nick      string
	JoinedAt  time.Time
	WonRound  int  // 0 = not won yet
	Paid      bool // paid in the current round
	OpenDebts int  // unsettled debts in this circle
}

// RoundResult is the public record of one decided round.
type RoundResult struct {
	Round    int
	Winner   address // empty when the round was rolled over
	Pot      int64
	Payers   int
	Missed   []address
	Refunded bool // nobody was eligible: payers were refunded, round repeats
	At       time.Time
	Height   int64
}

// Circle is one arisan group.
type Circle struct {
	ID           int
	Name         string
	Creator      address
	Contribution int64 // ugnot per member per round
	Size         int   // target number of members (= number of rounds)
	Period       time.Duration
	Mode         arisan.Mode
	Status       Status
	Members      []*Member
	CreatedAt    time.Time
	Round        int // current round, 1-based, 0 before start
	Deadline     time.Time
	Held         int64 // ugnot paid in for the current round, held by the realm
	Entropy      []byte
	History      []RoundResult
}

// Debt is a missed contribution, owed by Debtor directly to Creditor (the
// winner of the round that was missed).
type Debt struct {
	ID        int
	CircleID  int
	Round     int
	Debtor    address
	Creditor  address
	Amount    int64
	Settled   bool
	SettledBy address
	SettledAt time.Time
}

// Reputation is a member's track record across every circle.
type Reputation struct {
	Circles     int   // circles joined
	OnTime      int   // payments before the deadline
	Late        int   // payments after the deadline (before the draw)
	Missed      int   // rounds decided without their payment
	Settled     int   // debts settled
	Wins        int   // pots received
	Contributed int64 // ugnot paid into pots and debts
	Received    int64 // ugnot received from pots and debts
}

var (
	circles      avl.Tree // padID -> *Circle
	debts        avl.Tree // padID -> *Debt
	reps         avl.Tree // address string -> *Reputation
	memberships  avl.Tree // address string -> []int (circle ids)
	nextCircleID int
	nextDebtID   int
	totalPaidOut int64
	totalRounds  int
)

// ---------------------------------------------------------------------------
// Crossing (transaction) functions

// CreateCircle starts a new arisan and seats the caller as its first member.
//
//   - name: circle name (letters, digits, spaces and - _ . , ' & ! only)
//   - nickname: how you appear on the wheel (optional, same charset)
//   - contribution: iuran per member per round in GNOT, e.g. "1" or "0.5"
//   - members: circle size, 2..12 (also the number of rounds)
//   - periodMinutes: length of each round (1 minute .. 31 days)
//   - mode: "giliran" (fixed turns) or "kocok" (random draw)
//
// It returns the new circle id.
func CreateCircle(cur realm, name, nickname, contribution string, members, periodMinutes int, mode string) int {
	caller := callerOf(cur)

	name = strings.TrimSpace(name)
	mustValidText("name", name, 1, maxNameLen)
	nickname = strings.TrimSpace(nickname)
	mustValidText("nickname", nickname, 0, maxNickLen)
	amount, err := parseGNOT(contribution)
	if err != "" {
		panic("invalid contribution: " + err)
	}
	if amount < MinContribution || amount > MaxContribution {
		panic("contribution must be between " + arisan.FormatGNOT(MinContribution) + " and " + arisan.FormatGNOT(MaxContribution))
	}
	if members < MinMembers || members > MaxMembers {
		panic(ufmt.Sprintf("members must be between %d and %d", MinMembers, MaxMembers))
	}
	if periodMinutes < MinPeriodMinutes || periodMinutes > MaxPeriodMinutes {
		panic(ufmt.Sprintf("periodMinutes must be between %d and %d", MinPeriodMinutes, MaxPeriodMinutes))
	}
	m, ok := arisan.ParseMode(mode)
	if !ok {
		panic(`mode must be "giliran" or "kocok"`)
	}

	nextCircleID++
	now := time.Now()
	c := &Circle{
		ID:           nextCircleID,
		Name:         name,
		Creator:      caller,
		Contribution: amount,
		Size:         members,
		Period:       time.Duration(periodMinutes) * time.Minute,
		Mode:         m,
		Status:       StatusOpen,
		CreatedAt:    now,
	}
	c.Entropy = arisan.MixEntropy(nil, "arisanku", strconv.Itoa(c.ID), caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10))
	circles.Set(padID(c.ID), c)
	c.addMember(caller, nickname, now)

	chain.Emit("CircleCreated", "id", strconv.Itoa(c.ID), "creator", caller.String(), "contribution", strconv.FormatInt(amount, 10), "members", strconv.Itoa(members), "mode", m.String())
	return c.ID
}

// Join takes a seat in an open circle. The circle starts automatically when
// the last seat is taken.
func Join(cur realm, circleID int, nickname string) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("circle is not open for new members")
	}
	if c.memberIndex(caller) >= 0 {
		panic("you are already a member of this circle")
	}
	if len(c.Members) >= c.Size {
		panic("circle is full")
	}
	nickname = strings.TrimSpace(nickname)
	mustValidText("nickname", nickname, 0, maxNickLen)

	now := time.Now()
	c.addMember(caller, nickname, now)
	c.Entropy = arisan.MixEntropy(c.Entropy, "join", caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10))
	chain.Emit("Joined", "id", strconv.Itoa(c.ID), "member", caller.String())
	if len(c.Members) == c.Size {
		c.start(now)
	}
}

// Leave gives up a seat in a circle that has not started. The creator cannot
// leave; use Cancel instead.
func Leave(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("can only leave a circle before it starts")
	}
	if caller == c.Creator {
		panic("the creator cannot leave; cancel the circle instead")
	}
	i := c.memberIndex(caller)
	if i < 0 {
		panic("you are not a member of this circle")
	}
	c.Members = append(c.Members[:i], c.Members[i+1:]...)
	removeMembership(caller, c.ID)
	rep := repOf(caller)
	rep.Circles--
	chain.Emit("Left", "id", strconv.Itoa(c.ID), "member", caller.String())
}

// Start begins a circle early with the members it has (at least 2). Only the
// creator can start it. The circle size shrinks to the current member count.
func Start(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("circle is not open")
	}
	if caller != c.Creator {
		panic("only the creator can start the circle")
	}
	if len(c.Members) < MinMembers {
		panic(ufmt.Sprintf("need at least %d members to start", MinMembers))
	}
	c.Size = len(c.Members)
	c.start(time.Now())
}

// Cancel closes an open circle before it starts. No funds are held before
// the start, so nothing needs refunding. Only the creator can cancel.
func Cancel(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("only an open circle can be cancelled")
	}
	if caller != c.Creator {
		panic("only the creator can cancel the circle")
	}
	c.Status = StatusCancelled
	chain.Emit("Cancelled", "id", strconv.Itoa(c.ID))
}

// Pay deposits your contribution for the current round. Attach exactly the
// circle's iuran, e.g. `-send 1000000ugnot` for 1 GNOT.
//
// It must be called directly by a user (gnokey maketx call / a wallet): coins
// sent through an intermediate realm or a `maketx run` script are rejected,
// because only then is OriginSend guaranteed to have reached this realm.
func Pay(cur realm, circleID int) {
	// The two guards below are a pair (see docs: effective-gno, "Verifying
	// inbound Coin payments"): IsUserCall guarantees the -send coins landed
	// on this realm, and the amount check verifies how much.
	if !cur.Previous().IsUserCall() {
		panic("Pay must be called directly by a user (maketx call)")
	}
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusRunning {
		panic("circle is not running")
	}
	i := c.memberIndex(caller)
	if i < 0 {
		panic("you are not a member of this circle")
	}
	m := c.Members[i]
	if m.Paid {
		panic("you already paid this round")
	}
	mustReceiveExactly(c.Contribution)

	now := time.Now()
	m.Paid = true
	c.Held += c.Contribution
	c.Entropy = arisan.MixEntropy(c.Entropy, "pay", caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10), strconv.FormatInt(now.UnixNano(), 10))
	rep := repOf(caller)
	rep.Contributed += c.Contribution
	late := now.After(c.Deadline)
	if late {
		rep.Late++
	} else {
		rep.OnTime++
	}
	chain.Emit("Paid", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round), "member", caller.String(), "late", strconv.FormatBool(late))
}

// Draw decides the current round and pays the pot to its winner. Anyone can
// call it once every member has paid, or once the round deadline has passed.
//
// Eligible winners are members who paid this round, have not won before and
// have no unsettled debt in this circle. Members who did not pay get a debt
// owed to the winner. If nobody is eligible, every payer is refunded and the
// round is repeated with a new deadline. It returns the winner's address
// (empty if the round was rolled over).
func Draw(cur realm, circleID int) address {
	callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusRunning {
		panic("circle is not running")
	}
	now := time.Now()
	if !c.allPaid() && !now.After(c.Deadline) {
		panic("round is still open: wait until everyone paid or the deadline passed")
	}

	height := runtime.ChainHeight()
	seed := arisan.MixEntropy(c.Entropy, "draw", strconv.Itoa(c.Round), strconv.FormatInt(height, 10), strconv.FormatInt(now.UnixNano(), 10))
	c.Entropy = seed

	var candidates []int
	var payers []int
	var missed []address
	for i, m := range c.Members {
		if m.Paid {
			payers = append(payers, i)
			if m.WonRound == 0 && m.OpenDebts == 0 {
				candidates = append(candidates, i)
			}
		} else {
			missed = append(missed, m.Addr)
		}
	}

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()

	if len(candidates) == 0 {
		// Nobody can take the pot: give everyone their money back and repeat.
		for _, i := range payers {
			bk.SendCoins(self, c.Members[i].Addr, coins(c.Contribution))
			repOf(c.Members[i].Addr).Contributed -= c.Contribution
		}
		for _, a := range missed {
			repOf(a).Missed++
		}
		c.History = append(c.History, RoundResult{Round: c.Round, Pot: c.Held, Payers: len(payers), Missed: missed, Refunded: true, At: now, Height: height})
		c.resetRound(now)
		chain.Emit("RoundRolledOver", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round))
		return ""
	}

	wi := arisan.PickWinner(c.Mode, candidates, seed)
	winner := c.Members[wi]
	pot := c.Held
	winner.WonRound = c.Round
	bk.SendCoins(self, winner.Addr, coins(pot))
	wrep := repOf(winner.Addr)
	wrep.Wins++
	wrep.Received += pot
	totalPaidOut += pot
	totalRounds++

	for _, a := range missed {
		nextDebtID++
		d := &Debt{ID: nextDebtID, CircleID: c.ID, Round: c.Round, Debtor: a, Creditor: winner.Addr, Amount: c.Contribution}
		debts.Set(padID(d.ID), d)
		c.Members[c.memberIndex(a)].OpenDebts++
		repOf(a).Missed++
		chain.Emit("DebtRecorded", "debt", strconv.Itoa(d.ID), "id", strconv.Itoa(c.ID), "debtor", a.String(), "creditor", winner.Addr.String())
	}

	c.History = append(c.History, RoundResult{Round: c.Round, Winner: winner.Addr, Pot: pot, Payers: len(payers), Missed: missed, At: now, Height: height})
	chain.Emit("Drawn", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round), "winner", winner.Addr.String(), "pot", strconv.FormatInt(pot, 10))

	if c.winners() == len(c.Members) {
		c.Status = StatusFinished
		c.Held = 0
		for _, m := range c.Members {
			m.Paid = false
		}
		chain.Emit("Finished", "id", strconv.Itoa(c.ID))
		return winner.Addr
	}
	c.Round++
	c.resetRound(now)
	return winner.Addr
}

// PayDebt settles a debt. Attach exactly the debt amount; it is forwarded to
// the creditor in the same transaction. Anyone may settle a debt on the
// debtor's behalf (family often does), the debtor gets the credit.
func PayDebt(cur realm, debtID int) {
	// Paired payment guards, see Pay.
	if !cur.Previous().IsUserCall() {
		panic("PayDebt must be called directly by a user (maketx call)")
	}
	caller := callerOf(cur)
	v := debts.Get(padID(debtID))
	if v == nil {
		panic("debt not found")
	}
	d := v.(*Debt)
	if d.Settled {
		panic("debt already settled")
	}
	mustReceiveExactly(d.Amount)

	d.Settled = true
	d.SettledBy = caller
	d.SettledAt = time.Now()
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), d.Creditor, coins(d.Amount))

	if c := getCircle(d.CircleID); c != nil {
		if i := c.memberIndex(d.Debtor); i >= 0 && c.Members[i].OpenDebts > 0 {
			c.Members[i].OpenDebts--
		}
	}
	drep := repOf(d.Debtor)
	drep.Settled++
	repOf(caller).Contributed += d.Amount
	repOf(d.Creditor).Received += d.Amount
	chain.Emit("DebtSettled", "debt", strconv.Itoa(d.ID), "by", caller.String())
}

// ---------------------------------------------------------------------------
// Read-only helpers (safe to call with vm/qeval; return copies only)

// CircleCount returns how many circles were ever created.
func CircleCount() int { return nextCircleID }

// TotalPaidOut returns the ugnot paid to winners across all circles.
func TotalPaidOut() int64 { return totalPaidOut }

// TrustScore returns a 0..100 score for an address from its track record.
// New members start at 50.
func TrustScore(addr address) int {
	v := reps.Get(addr.String())
	if v == nil {
		return 50
	}
	return scoreOf(v.(*Reputation))
}

// CircleJSON returns a JSON summary of a circle for wallets, bots and
// frontends. It returns "null" if the circle does not exist.
func CircleJSON(circleID int) string {
	c := getCircle(circleID)
	if c == nil {
		return "null"
	}
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(`"id":` + strconv.Itoa(c.ID))
	b.WriteString(`,"name":` + strconv.Quote(c.Name))
	b.WriteString(`,"status":` + strconv.Quote(c.Status.String()))
	b.WriteString(`,"mode":` + strconv.Quote(c.Mode.String()))
	b.WriteString(`,"creator":` + strconv.Quote(c.Creator.String()))
	b.WriteString(`,"contribution_ugnot":` + strconv.FormatInt(c.Contribution, 10))
	b.WriteString(`,"size":` + strconv.Itoa(c.Size))
	b.WriteString(`,"round":` + strconv.Itoa(c.Round))
	b.WriteString(`,"held_ugnot":` + strconv.FormatInt(c.Held, 10))
	b.WriteString(`,"period_seconds":` + strconv.FormatInt(int64(c.Period/time.Second), 10))
	if c.Status == StatusRunning {
		b.WriteString(`,"deadline_unix":` + strconv.FormatInt(c.Deadline.Unix(), 10))
	}
	b.WriteString(`,"members":[`)
	for i, m := range c.Members {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"address":` + strconv.Quote(m.Addr.String()) + `,"nick":` + strconv.Quote(m.Nick) + `,"paid":` + strconv.FormatBool(m.Paid) + `,"won_round":` + strconv.Itoa(m.WonRound) + `,"open_debts":` + strconv.Itoa(m.OpenDebts) + `}`)
	}
	b.WriteString("]}")
	return b.String()
}

// ---------------------------------------------------------------------------
// internals

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return cur.Previous().Address()
}

// mustReceiveExactly checks the coins attached to the transaction. Callers
// MUST have asserted cur.Previous().IsUserCall() first.
func mustReceiveExactly(amount int64) {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent.AmountOf(denom) != amount {
		panic("attach exactly " + strconv.FormatInt(amount, 10) + denom + " (" + arisan.FormatGNOT(amount) + "), got " + sent.String())
	}
}

func coins(amount int64) chain.Coins {
	return chain.Coins{chain.NewCoin(denom, amount)}
}

func padID(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func getCircle(id int) *Circle {
	v := circles.Get(padID(id))
	if v == nil {
		return nil
	}
	return v.(*Circle)
}

func mustCircle(id int) *Circle {
	c := getCircle(id)
	if c == nil {
		panic("circle " + strconv.Itoa(id) + " not found")
	}
	return c
}

func repOf(a address) *Reputation {
	v := reps.Get(a.String())
	if v != nil {
		return v.(*Reputation)
	}
	r := &Reputation{}
	reps.Set(a.String(), r)
	return r
}

func scoreOf(r *Reputation) int {
	s := 50 + 5*r.OnTime + 2*r.Late + 4*r.Settled - 15*r.Missed
	if s < 0 {
		s = 0
	}
	if s > 100 {
		s = 100
	}
	return s
}

func addMembership(a address, id int) {
	var ids []int
	if v := memberships.Get(a.String()); v != nil {
		ids = v.([]int)
	}
	ids = append(ids, id)
	memberships.Set(a.String(), ids)
}

func removeMembership(a address, id int) {
	v := memberships.Get(a.String())
	if v == nil {
		return
	}
	ids := v.([]int)
	out := make([]int, 0, len(ids))
	for _, x := range ids {
		if x != id {
			out = append(out, x)
		}
	}
	memberships.Set(a.String(), out)
}

func (c *Circle) addMember(a address, nick string, now time.Time) {
	c.Members = append(c.Members, &Member{Addr: a, Nick: nick, JoinedAt: now})
	addMembership(a, c.ID)
	repOf(a).Circles++
}

func (c *Circle) memberIndex(a address) int {
	for i, m := range c.Members {
		if m.Addr == a {
			return i
		}
	}
	return -1
}

func (c *Circle) start(now time.Time) {
	c.Status = StatusRunning
	c.Round = 1
	c.Deadline = now.Add(c.Period)
	chain.Emit("Started", "id", strconv.Itoa(c.ID), "members", strconv.Itoa(len(c.Members)))
}

func (c *Circle) resetRound(now time.Time) {
	for _, m := range c.Members {
		m.Paid = false
	}
	c.Held = 0
	c.Deadline = now.Add(c.Period)
}

func (c *Circle) allPaid() bool {
	for _, m := range c.Members {
		if !m.Paid {
			return false
		}
	}
	return len(c.Members) > 0
}

func (c *Circle) paidCount() int {
	n := 0
	for _, m := range c.Members {
		if m.Paid {
			n++
		}
	}
	return n
}

func (c *Circle) winners() int {
	n := 0
	for _, m := range c.Members {
		if m.WonRound > 0 {
			n++
		}
	}
	return n
}

// mustValidText keeps user text safe to embed in markdown and SVG: a short
// whitelist instead of escaping every renderer's syntax.
func mustValidText(field, s string, min, max int) {
	n := len([]rune(s))
	if n < min || n > max {
		panic(ufmt.Sprintf("%s must be %d to %d characters", field, min, max))
	}
	for _, r := range s {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.' || r == ',' || r == '\'' || r == '&' || r == '!'
		if !ok {
			panic(field + " may only use letters, digits, spaces and - _ . , ' & !")
		}
	}
}

// parseGNOT parses a decimal GNOT amount ("1", "0.5", "2.000001") into ugnot.
// It returns a non-empty error string on failure.
func parseGNOT(s string) (int64, string) {
	s = strings.TrimSpace(s)
	s = strings.TrimSuffix(strings.TrimSuffix(s, "GNOT"), "gnot")
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, "empty amount"
	}
	whole, frac := s, ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	if whole == "" {
		whole = "0"
	}
	if len(frac) > 6 {
		return 0, "at most 6 decimals"
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, "not a number"
		}
	}
	if len(whole) > 9 {
		return 0, "too large"
	}
	for len(frac) < 6 {
		frac += "0"
	}
	w, _ := strconv.ParseInt(whole, 10, 64)
	f, _ := strconv.ParseInt(frac, 10, 64)
	return w*1_000_000 + f, ""
}

package arisandev1

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y/arisan"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render serves the gnoweb UI.
//
//	""                 home: stats, open / running / finished circles
//	"circle/{id}"      one circle: wheel, actions, members, history, debts
//	"member/{address}" a member's reputation and circles
//	"new"              form to start a circle
//	"how"              how arisan and ArisanKu work (EN + ID)
func Render(path string) string {
	path = strings.Trim(path, "/")
	if i := strings.IndexByte(path, '?'); i >= 0 {
		path = path[:i]
	}
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case parts[0] == "circle" && len(parts) == 2:
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return renderNotFound()
		}
		return renderCircle(id)
	case parts[0] == "member" && len(parts) == 2:
		return renderMember(address(parts[1]))
	case path == "new":
		return renderNew()
	case path == "how":
		return renderHow()
	}
	return renderNotFound()
}

func realmPath() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func link(sub string) string {
	if sub == "" {
		return realmPath()
	}
	return realmPath() + ":" + sub
}

func header(b *strings.Builder) {
	b.WriteString("# 🫙 ArisanKu\n")
	b.WriteString("*Arisan tanpa bandar — trustless rotating savings circles on Gno.land*\n\n")
	b.WriteString("[Home](" + link("") + ") · [Start a circle](" + link("new") + ") · [How it works](" + link("how") + ")\n\n")
}

func renderHome() string {
	var b strings.Builder
	header(&b)

	var open, running, done []*Circle
	members := 0
	circles.ReverseIterate("", "", func(_ string, v any) bool {
		c := v.(*Circle)
		switch c.Status {
		case StatusOpen:
			open = append(open, c)
		case StatusRunning:
			running = append(running, c)
		case StatusFinished:
			done = append(done, c)
		}
		if c.Status != StatusCancelled {
			members += len(c.Members)
		}
		return false
	})

	b.WriteString("<gno-columns>\n")
	stat(&b, strconv.Itoa(nextCircleID), "circles created")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(reps.Size()), "unique members")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(totalRounds), "rounds decided")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, arisan.FormatGNOT(totalPaidOut), "paid to winners")
	b.WriteString("</gno-columns>\n\n")

	b.WriteString("> [!TIP] What is arisan?\n")
	b.WriteString("> A group agrees on a fixed contribution. Every round everyone pays in and one member takes the whole pot home, until each member has won once. Here the realm holds the pot, picks the winner by a public rule and pays out instantly — no organiser to trust.\n\n")
	b.WriteString(`<gno-button href="` + link("new") + `" label="Start a circle" variant="success" /> <gno-button href="` + link("how") + `" label="How it works" variant="outline" />` + "\n\n")

	b.WriteString("## 🟢 Open circles — join now\n\n")
	if len(open) == 0 {
		b.WriteString("*No circle is recruiting right now. [Start one](" + link("new") + ").*\n\n")
	} else {
		b.WriteString("| Circle | Iuran / round | Mode | Seats | |\n|---|---|---|---|---|\n")
		for _, c := range open {
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %s | %s %d/%d | [Join](%s) |\n",
				c.Name, link("circle/"+strconv.Itoa(c.ID)), arisan.FormatGNOT(c.Contribution), c.Mode.Label(),
				arisan.ProgressBar(len(c.Members), c.Size, 6), len(c.Members), c.Size,
				txlink.NewLink("Join").AddArgs("circleID", strconv.Itoa(c.ID), "nickname", "").URL()))
		}
		b.WriteString("\n")
	}

	b.WriteString("## 🔄 Running circles\n\n")
	if len(running) == 0 {
		b.WriteString("*None yet.*\n\n")
	} else {
		b.WriteString("| Circle | Pot | Round | Paid this round | Deadline |\n|---|---|---|---|---|\n")
		for _, c := range running {
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %d / %d | %s %d/%d | %s |\n",
				c.Name, link("circle/"+strconv.Itoa(c.ID)), arisan.FormatGNOT(c.Contribution*int64(len(c.Members))),
				c.Round, len(c.Members), arisan.ProgressBar(c.paidCount(), len(c.Members), 6), c.paidCount(), len(c.Members), relTime(c.Deadline)))
		}
		b.WriteString("\n")
	}

	if len(done) > 0 {
		b.WriteString("## 🏁 Finished circles\n\n")
		b.WriteString("| Circle | Members | Total paid out |\n|---|---|---|\n")
		for _, c := range done {
			var sum int64
			for _, h := range c.History {
				if !h.Refunded {
					sum += h.Pot
				}
			}
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %d | %s |\n", c.Name, link("circle/"+strconv.Itoa(c.ID)), len(c.Members), arisan.FormatGNOT(sum)))
		}
		b.WriteString("\n")
	}

	footer(&b)
	return b.String()
}

func stat(b *strings.Builder, value, label string) {
	b.WriteString("<gno-frame>\n\n### " + value + "\n" + label + "\n\n</gno-frame>\n")
}

func renderCircle(id int) string {
	c := getCircle(id)
	if c == nil {
		return renderNotFound()
	}
	var b strings.Builder
	header(&b)
	idS := strconv.Itoa(c.ID)
	pot := c.Contribution * int64(len(c.Members))
	if c.Status == StatusOpen {
		pot = c.Contribution * int64(c.Size)
	}

	b.WriteString("## " + c.Name + "  " + statusBadge(c.Status) + "\n\n")

	// wheel + facts side by side
	slots := make([]arisan.Slot, 0, len(c.Members))
	var lastWinner address
	if n := len(c.History); n > 0 {
		lastWinner = c.History[n-1].Winner
	}
	for i, m := range c.Members {
		st := arisan.SlotWaiting
		switch {
		case m.OpenDebts > 0:
			st = arisan.SlotLate
		case m.Addr == lastWinner && m.WonRound > 0:
			st = arisan.SlotWinner
		case m.WonRound > 0:
			st = arisan.SlotWon
		case m.Paid:
			st = arisan.SlotPaid
		}
		slots = append(slots, arisan.Slot{Label: strconv.Itoa(i + 1), Caption: displayName(m), State: st})
	}
	sub := "recruiting " + strconv.Itoa(len(c.Members)) + "/" + strconv.Itoa(c.Size)
	switch c.Status {
	case StatusRunning:
		sub = "Putaran " + strconv.Itoa(c.Round) + " / " + strconv.Itoa(len(c.Members))
	case StatusFinished:
		sub = "selesai · finished"
	case StatusCancelled:
		sub = "cancelled"
	}

	b.WriteString("<gno-columns>\n")
	b.WriteString(arisan.WheelImage("Arisan wheel of "+c.Name, slots, arisan.FormatGNOT(pot), sub) + "\n")
	b.WriteString("<gno-columns-sep>\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| **Iuran** (per member, per round) | " + arisan.FormatGNOT(c.Contribution) + " |\n")
	b.WriteString("| **Pot** (paid to each winner) | " + arisan.FormatGNOT(pot) + " |\n")
	b.WriteString("| **Mode** | " + c.Mode.Label() + " |\n")
	b.WriteString("| **Members** | " + strconv.Itoa(len(c.Members)) + " / " + strconv.Itoa(c.Size) + " |\n")
	b.WriteString("| **Round length** | " + durStr(c.Period) + " |\n")
	if c.Status == StatusRunning {
		b.WriteString("| **Round** | " + strconv.Itoa(c.Round) + " of " + strconv.Itoa(len(c.Members)) + " |\n")
		b.WriteString("| **Paid this round** | " + arisan.ProgressBar(c.paidCount(), len(c.Members), 8) + " " + strconv.Itoa(c.paidCount()) + "/" + strconv.Itoa(len(c.Members)) + " |\n")
		b.WriteString("| **Held in realm** | " + arisan.FormatGNOT(c.Held) + " |\n")
		b.WriteString("| **Deadline** | " + c.Deadline.UTC().Format("02 Jan 2006 15:04 UTC") + " (" + relTime(c.Deadline) + ") |\n")
	}
	b.WriteString("| **Created by** | " + addrLink(c.Creator) + " |\n")
	b.WriteString("\n</gno-columns>\n\n")

	// actions
	b.WriteString("### Actions\n\n")
	switch c.Status {
	case StatusOpen:
		b.WriteString(`<gno-button href="` + txlink.NewLink("Join").AddArgs("circleID", idS, "nickname", "").URL() + `" label="Join this circle" variant="success" />`)
		if len(c.Members) >= MinMembers {
			b.WriteString(` <gno-button href="` + txlink.NewLink("Start").AddArgs("circleID", idS).URL() + `" label="Start now (creator)" variant="outline" />`)
		}
		b.WriteString(` <gno-button href="` + txlink.NewLink("Cancel").AddArgs("circleID", idS).URL() + `" label="Cancel (creator)" variant="caution outline" />` + "\n\n")
		b.WriteString("*The circle starts by itself when the last seat is taken. Share this page to invite friends.*\n\n")
	case StatusRunning:
		send := strconv.FormatInt(c.Contribution, 10) + denom
		b.WriteString(`<gno-button href="` + txlink.NewLink("Pay").AddArgs("circleID", idS).SetSend(send).URL() + `" label="Pay ` + arisan.FormatGNOT(c.Contribution) + `" variant="success" />`)
		ready := c.allPaid() || time.Now().After(c.Deadline)
		if ready {
			b.WriteString(` <gno-button href="` + txlink.NewLink("Draw").AddArgs("circleID", idS).URL() + `" label="🎲 Draw round ` + strconv.Itoa(c.Round) + `" variant="warning" />` + "\n\n")
			b.WriteString("> [!SUCCESS] Ready to draw\n> " + readyReason(c) + " Anyone can call **Draw** to decide the round and pay the winner.\n\n")
		} else {
			b.WriteString("\n\n> [!NOTE] Waiting for payments\n> " + strconv.Itoa(len(c.Members)-c.paidCount()) + " member(s) still need to pay. Draw opens when everyone has paid or at the deadline (" + relTime(c.Deadline) + ").\n\n")
		}
	case StatusFinished:
		b.WriteString("> [!SUCCESS] Arisan complete\n> Every member received the pot once. Terima kasih semuanya!\n\n")
	case StatusCancelled:
		b.WriteString("> [!CAUTION] This circle was cancelled before it started. No funds were held.\n\n")
	}

	// members
	b.WriteString("### Members\n\n| # | Member | Trust | This round | Won |\n|---|---|---|---|---|\n")
	for i, m := range c.Members {
		paid := "⏳ unpaid"
		if c.Status != StatusRunning {
			paid = "—"
		} else if m.Paid {
			paid = "✅ paid"
		}
		won := "—"
		if m.WonRound > 0 {
			won = "🏆 round " + strconv.Itoa(m.WonRound)
		}
		if m.OpenDebts > 0 {
			won += " · ⚠️ " + strconv.Itoa(m.OpenDebts) + " debt"
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | %s |\n", i+1, memberCell(m), trustCell(m.Addr), paid, won))
	}
	b.WriteString("\n")

	// history
	if len(c.History) > 0 {
		b.WriteString("### Round history\n\n| Round | Winner | Pot | Paid | Missed | Block |\n|---|---|---|---|---|---|\n")
		for i := len(c.History) - 1; i >= 0; i-- {
			h := c.History[i]
			winner := "↩️ rolled over, payers refunded"
			if !h.Refunded {
				winner = "🏆 " + nameOf(c, h.Winner)
			}
			missed := "—"
			if len(h.Missed) > 0 {
				names := make([]string, 0, len(h.Missed))
				for _, a := range h.Missed {
					names = append(names, nameOf(c, a))
				}
				missed = strings.Join(names, ", ")
			}
			b.WriteString(ufmt.Sprintf("| %d | %s | %s | %d/%d | %s | #%d |\n", h.Round, winner, arisan.FormatGNOT(h.Pot), h.Payers, len(c.Members), missed, h.Height))
		}
		b.WriteString("\n")
	}

	// debts
	var rows []string
	debts.Iterate("", "", func(_ string, v any) bool {
		d := v.(*Debt)
		if d.CircleID != c.ID {
			return false
		}
		state := `<gno-button href="` + txlink.NewLink("PayDebt").AddArgs("debtID", strconv.Itoa(d.ID)).SetSend(strconv.FormatInt(d.Amount, 10)+denom).URL() + `" label="Settle" variant="warning outline" />`
		if d.Settled {
			state = "✅ settled"
		}
		rows = append(rows, ufmt.Sprintf("| %d | %d | %s | %s | %s | %s |", d.ID, d.Round, nameOf(c, d.Debtor), nameOf(c, d.Creditor), arisan.FormatGNOT(d.Amount), state))
		return false
	})
	if len(rows) > 0 {
		b.WriteString("### Utang (debts)\n\nA missed payment is owed directly to the winner of that round. Members with open debts cannot win until they settle.\n\n")
		b.WriteString("| Debt | Round | Debtor | Owed to | Amount | |\n|---|---|---|---|---|---|\n")
		b.WriteString(strings.Join(rows, "\n") + "\n\n")
	}

	if c.Mode == arisan.ModeKocok {
		b.WriteString("> [!NOTE]- How the kocok draw works\n> Every join and payment is folded into a SHA-256 seed together with its block height and time; the draw adds its own height and time. The winner is `candidates[seed mod n]` among members who paid, have not won and have no debt. It is auditable and nobody controls it alone, but it is not a VRF: for high stakes use Giliran mode.\n\n")
	}
	b.WriteString("*Machine-readable: `CircleJSON(" + idS + ")`*\n\n")
	footer(&b)
	return b.String()
}

func readyReason(c *Circle) string {
	if c.allPaid() {
		return "Everyone has paid."
	}
	return "The deadline has passed; unpaid members will owe the winner."
}

func renderMember(a address) string {
	var b strings.Builder
	header(&b)
	if !a.IsValid() {
		b.WriteString("Invalid address.\n")
		return b.String()
	}
	b.WriteString("## 👤 " + arisan.ShortAddr(a.String()) + "\n\n`" + a.String() + "`\n\n")
	var r Reputation
	if v := reps.Get(a.String()); v != nil {
		r = *(v.(*Reputation))
	}
	score := TrustScore(a)
	b.WriteString("<gno-columns>\n")
	stat(&b, strconv.Itoa(score)+"/100", "trust score · skor amanah")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(r.OnTime)+" / "+strconv.Itoa(r.Late)+" / "+strconv.Itoa(r.Missed), "on time / late / missed")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(r.Wins), "pots received")
	b.WriteString("</gno-columns>\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Circles joined | " + strconv.Itoa(r.Circles) + " |\n")
	b.WriteString("| Debts settled | " + strconv.Itoa(r.Settled) + " |\n")
	b.WriteString("| Contributed | " + arisan.FormatGNOT(r.Contributed) + " |\n")
	b.WriteString("| Received | " + arisan.FormatGNOT(r.Received) + " |\n\n")
	b.WriteString("*Score: starts at 50; +5 per on-time payment, +2 per late payment, +4 per settled debt, −15 per missed round (0–100).*\n\n")

	if v := memberships.Get(a.String()); v != nil {
		ids := v.([]int)
		if len(ids) > 0 {
			b.WriteString("### Circles\n\n| Circle | Status | Iuran |\n|---|---|---|\n")
			for i := len(ids) - 1; i >= 0; i-- {
				if c := getCircle(ids[i]); c != nil {
					b.WriteString("| [" + c.Name + "](" + link("circle/"+strconv.Itoa(c.ID)) + ") | " + statusBadge(c.Status) + " | " + arisan.FormatGNOT(c.Contribution) + " |\n")
				}
			}
			b.WriteString("\n")
		}
	}
	var open []string
	debts.Iterate("", "", func(_ string, v any) bool {
		d := v.(*Debt)
		if d.Debtor == a && !d.Settled {
			open = append(open, ufmt.Sprintf("| %d | [circle %d](%s) | %s | [Settle](%s) |", d.ID, d.CircleID, link("circle/"+strconv.Itoa(d.CircleID)), arisan.FormatGNOT(d.Amount),
				txlink.NewLink("PayDebt").AddArgs("debtID", strconv.Itoa(d.ID)).SetSend(strconv.FormatInt(d.Amount, 10)+denom).URL()))
		}
		return false
	})
	if len(open) > 0 {
		b.WriteString("### Open debts\n\n| Debt | Circle | Amount | |\n|---|---|---|---|\n" + strings.Join(open, "\n") + "\n\n")
	}
	footer(&b)
	return b.String()
}

