func memberCell(m *Member) string {
	if m.Nick != "" {
		return "**" + m.Nick + "** · " + addrLink(m.Addr)
	}
	return addrLink(m.Addr)
}

func nameOf(c *Circle, a address) string {
	if i := c.memberIndex(a); i >= 0 {
		return displayName(c.Members[i])
	}
	return arisan.ShortAddr(a.String())
}

func addrLink(a address) string {
	return "[" + arisan.ShortAddr(a.String()) + "](" + link("member/"+a.String()) + ")"
}

func trustCell(a address) string {
	s := TrustScore(a)
	icon := "🟡"
	if s >= 70 {
		icon = "🟢"
	} else if s < 40 {
		icon = "🔴"
	}
	return icon + " " + strconv.Itoa(s)
}

func durStr(d time.Duration) string {
	mins := int64(d / time.Minute)
	switch {
	case mins%(60*24*7) == 0:
		return plural(mins/(60*24*7), "week")
	case mins%(60*24) == 0:
		return plural(mins/(60*24), "day")
	case mins%60 == 0:
		return plural(mins/60, "hour")
	}
	return plural(mins, "minute")
}

func plural(n int64, unit string) string {
	s := strconv.FormatInt(n, 10) + " " + unit
	if n != 1 {
		s += "s"
	}
	return s
}

func relTime(t time.Time) string {
	d := time.Until(t)
	if d <= 0 {
		return "passed " + short(-d) + " ago"
	}
	return "in " + short(d)
}

func short(d time.Duration) string {
	switch {
	case d < time.Minute:
		return strconv.Itoa(int(d/time.Second)) + "s"
	case d < time.Hour:
		return strconv.Itoa(int(d/time.Minute)) + "m"
	case d < 48*time.Hour:
		return strconv.Itoa(int(d/time.Hour)) + "h " + strconv.Itoa(int((d%time.Hour)/time.Minute)) + "m"
	}
	return strconv.Itoa(int(d/(24*time.Hour))) + " days"
}

package rfengine

// Directions: 0 up, 1 right, 2 down, 3 left.
var dx = [4]int{0, 1, 0, -1}
var dy = [4]int{-1, 0, 1, 0}

type View struct {
	W, H   int
	Cells  []byte // 0 empty, 1 wall/trail
	MeX    int
	MeY    int
	OppX   int
	OppY   int
	Turn   int
}

func (v View) Free(x, y int) bool {
	if x < 0 || y < 0 || x >= v.W || y >= v.H {
		return false
	}
	return v.Cells[y*v.W+x] == 0
}

func Step(x, y, d int) (int, int) { return x + dx[d&3], y + dy[d&3] }

type Bot func(v View) int

// Result: 0 draw, 1 A wins, 2 B wins. Moves is the canonical string.
func Play(a, b Bot, w, h, maxTurns int) (int, int, string) {
	cells := make([]byte, w*h)
	ax, ay, bx, by := 1, h/2, w-2, h/2
	cells[ay*w+ax], cells[by*w+bx] = 1, 1
	moves := make([]byte, 0, 2*maxTurns)
	for t := 0; t < maxTurns; t++ {
		va := View{W: w, H: h, Cells: cells, MeX: ax, MeY: ay, OppX: bx, OppY: by, Turn: t}
		vb := View{W: w, H: h, Cells: cells, MeX: bx, MeY: by, OppX: ax, OppY: ay, Turn: t}
		da := a(va) & 3
		db := b(vb) & 3
		moves = append(moves, byte('0'+da), byte('0'+db))
		nax, nay := Step(ax, ay, da)
		nbx, nby := Step(bx, by, db)
		aDead := !va.Free(nax, nay)
		bDead := !vb.Free(nbx, nby)
		if nax == nbx && nay == nby {
			aDead, bDead = true, true
		}
		if aDead || bDead {
			switch {
			case aDead && bDead:
				return 0, t + 1, string(moves)
			case aDead:
				return 2, t + 1, string(moves)
			default:
				return 1, t + 1, string(moves)
			}
		}
		ax, ay, bx, by = nax, nay, nbx, nby
		cells[ay*w+ax], cells[by*w+bx] = 1, 1
	}
	return 0, maxTurns, string(moves)
}

package rfbotp

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfkt/rfengine"

func Move(v rfengine.View) int {
	best, bestScore := 0, -1
	for d := 0; d < 4; d++ {
		x, y := rfengine.Step(v.MeX, v.MeY, d)
		if !v.Free(x, y) {
			continue
		}
		s := 0
		for e := 0; e < 4; e++ {
			x2, y2 := rfengine.Step(x, y, e)
			if v.Free(x2, y2) {
				s++
			}
		}
		if s > bestScore {
			best, bestScore = d, s
		}
	}
	return best
}

func Panicky(v rfengine.View) int {
	if v.Turn == 5 {
		panic("i refuse to lose")
	}
	return Move(v)
}

