// Package gnotab implements GnoTab ("Tavern Tab"): a group expense
// ledger on Gno.land, Splitwise-style.
//
// A group of members records shared expenses in ugnot. The realm keeps
// a running net balance per member and can reduce those balances to a
// short list of "who pays whom" transfers (netting). Members record a
// Settlement once they have paid a debt off (e.g. with a real GNOT
// transfer), which zeroes the corresponding balances.
package gnotab

import (
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// Types & state
// ---------------------------------------------------------------------------

// Expense is one shared expense recorded in a group.
type Expense struct {
	ID           int
	Payer        address
	Amount       int64 // total amount paid, in ugnot
	Participants []address
	Memo         string
}

// Settlement records that From has paid Amount ugnot of debt to To.
type Settlement struct {
	From   address
	To     address
	Amount int64 // ugnot
}

// Transfer is one netted payment suggestion: From should pay Amount to To.
type Transfer struct {
	From   address
	To     address
	Amount int64 // ugnot
}

// Group is a single tab shared by its members.
type Group struct {
	ID          int
	Name        string
	Creator     address
	Members     []address // join order; Creator is Members[0]
	Expenses    []Expense
	Settlements []Settlement
	Balances    map[address]int64 // net balance in ugnot: >0 is owed money, <0 owes money
}

var (
	groups     = map[int]*Group{}
	groupCount int
)

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

func getGroup(groupID int) *Group {
	g, ok := groups[groupID]
	if !ok {
		panic("gnotab: group not found")
	}
	return g
}

func isMember(g *Group, addr address) bool {
	for _, m := range g.Members {
		if m == addr {
			return true
		}
	}
	return false
}

// dedupeAddresses returns the input with duplicates and empty addresses
// removed, preserving first-seen order.
func dedupeAddresses(in []address) []address {
	seen := map[address]bool{}
	out := []address{}
	for _, a := range in {
		if a.String() == "" || seen[a] {
			continue
		}
		seen[a] = true
		out = append(out, a)
	}
	return out
}

// parseAddressList parses a comma-separated list of g1 addresses.
// Public realm functions take address lists in this form because MsgCall
// arguments cannot carry []address values on-chain (the VM's argument
// converter only supports primitives and []byte).
func parseAddressList(s string) []address {
	out := []address{}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		out = append(out, address(part))
	}
	return out
}

// computeTransfers reduces the group's net balances to a list of payments
// that settles everyone. Debtors and creditors are matched greedily in
// member order, so the result is deterministic.
func computeTransfers(g *Group) []Transfer {
	bal := make(map[address]int64, len(g.Members))
	for _, m := range g.Members {
		bal[m] = g.Balances[m]
	}
	transfers := []Transfer{}
	for _, from := range g.Members {
		for bal[from] < 0 {
			// Find the first creditor (in member order) still owed money.
			var to address
			found := false
			for _, cand := range g.Members {
				if bal[cand] > 0 {
					to = cand
					found = true
					break
				}
			}
			if !found {
				break
			}
			amt := -bal[from]
			if bal[to] < amt {
				amt = bal[to]
			}
			transfers = append(transfers, Transfer{From: from, To: to, Amount: amt})
			bal[from] += amt
			bal[to] -= amt
		}
	}
	return transfers
}

// ---------------------------------------------------------------------------
// Public functions (callable via MsgCall)
// ---------------------------------------------------------------------------

// CreateGroup creates a new tab. The caller becomes the creator and first
// member; members lists the other members' addresses, comma-separated.
// Returns the group ID.
func CreateGroup(cur realm, name string, members string) int {
	if strings.TrimSpace(name) == "" {
		panic("gnotab: group name must not be empty")
	}
	creator := cur.Previous().Address()
	all := dedupeAddresses(append([]address{creator}, parseAddressList(members)...))
	if len(all) < 2 {
		panic("gnotab: a group needs at least 2 members")
	}
	groupCount++
	g := &Group{
		ID:       groupCount,
		Name:     name,
		Creator:  creator,
		Members:  all,
		Balances: map[address]int64{},
	}
	for _, m := range all {
		g.Balances[m] = 0
	}
	groups[g.ID] = g
	return g.ID
}

// AddExpense records an expense paid by the caller and split equally among
// participants (comma-separated addresses, all must be group members). The
// indivisible remainder of the split is assigned one ugnot at a time to the
// first participants. Returns the expense ID within the group.
func AddExpense(cur realm, groupID int, amount int64, participants string, memo string) int {
	g := getGroup(groupID)
	payer := cur.Previous().Address()
	if !isMember(g, payer) {
		panic("gnotab: payer is not a group member")
	}
	if amount <= 0 {
		panic("gnotab: amount must be positive")
	}
	parts := dedupeAddresses(parseAddressList(participants))
	if len(parts) == 0 {
		panic("gnotab: expense needs at least one participant")
	}
	for _, p := range parts {
		if !isMember(g, p) {
			panic("gnotab: participant is not a group member")
		}
	}

	n := int64(len(parts))
	share := amount / n
	remainder := amount - share*n
	for i, p := range parts {
		s := share
		if int64(i) < remainder {
			s++
		}
		g.Balances[p] -= s
	}
	g.Balances[payer] += amount

	exp := Expense{
		ID:           len(g.Expenses) + 1,
		Payer:        payer,
		Amount:       amount,
		Participants: parts,
		Memo:         memo,
	}
	g.Expenses = append(g.Expenses, exp)
	return exp.ID
}

// Settle records that the caller has paid amount ugnot of their debt to
// the member `to`, and adjusts both net balances accordingly.
func Settle(cur realm, groupID int, to address, amount int64) {
	g := getGroup(groupID)
	from := cur.Previous().Address()
	if !isMember(g, from) {
		panic("gnotab: settler is not a group member")
	}
	if !isMember(g, to) {
		panic("gnotab: settlement target is not a group member")
	}
	if from == to {
		panic("gnotab: cannot settle with yourself")
	}
	if amount <= 0 {
		panic("gnotab: amount must be positive")
	}
	if g.Balances[from] >= 0 {
		panic("gnotab: settler has no outstanding debt")
	}
	if g.Balances[to] <= 0 {
		panic("gnotab: settlement target is not owed anything")
	}
	if amount > -g.Balances[from] {
		panic("gnotab: amount exceeds settler's debt")
	}
	if amount > g.Balances[to] {
		panic("gnotab: amount exceeds what target is owed")
	}
	g.Balances[from] += amount
	g.Balances[to] -= amount
	g.Settlements = append(g.Settlements, Settlement{From: from, To: to, Amount: amount})
}

// GetBalance returns the net balance of a member in ugnot
// (>0: the group owes them, <0: they owe the group, 0: settled).
func GetBalance(groupID int, member address) int64 {
	g := getGroup(groupID)
	if !isMember(g, member) {
		panic("gnotab: not a group member")
	}
	return g.Balances[member]
}

// GroupCount returns how many groups have been created.
func GroupCount() int {
	return groupCount
}

// ---------------------------------------------------------------------------
// Rendering (gnoweb UI)
// ---------------------------------------------------------------------------

// fmtAmount formats an ugnot amount as a signed GNOT string,
// e.g. -1500000 -> "-1.500000 GNOT".
func fmtAmount(u int64) string {
	neg := u < 0
	if neg {
		u = -u
	}
	frac := strconv.FormatInt(u%1000000, 10)
	for len(frac) < 6 {
		frac = "0" + frac
	}
	s := strconv.FormatInt(u/1000000, 10) + "." + frac + " GNOT"
	if neg {
		return "-" + s
	}
	return s
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) > 14 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// Render is the realm's UI on gnoweb.
//
//	""       -> index of all groups
//	"g/<id>" -> one group's live balance sheet
func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderHome()
	}
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "g" {
		id, err := strconv.Atoi(parts[1])
		if err == nil {
			if g, ok := groups[id]; ok {
				return renderGroup(g)
			}
		}
	}
	return "# GnoTab\n\nPage not found. [Back to all tabs](/r/g1qglhdzln0adn63e95gga9rntefhd6s6uw9e2zz/gnotab/v2)"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 🍻 GnoTab — Tavern Tab on Gno\n\n")
	b.WriteString("Group expense tabs, settled on-chain. Create a tab, record who paid, ")
	b.WriteString("and GnoTab nets the debts down to the shortest list of payments.\n\n")
	if groupCount == 0 {
		b.WriteString("No tabs yet. Create the first one with `CreateGroup`.\n")
		return b.String()
	}
	b.WriteString("## Open tabs\n\n")
	for id := 1; id <= groupCount; id++ {
		g := groups[id]
		total := int64(0)
		for _, e := range g.Expenses {
			total += e.Amount
		}
		b.WriteString("- [")
		b.WriteString(g.Name)
		b.WriteString("](/r/g1qglhdzln0adn63e95gga9rntefhd6s6uw9e2zz/gnotab/v2:g/")
		b.WriteString(strconv.Itoa(id))
		b.WriteString(") — ")
		b.WriteString(strconv.Itoa(len(g.Members)))
		b.WriteString(" members, ")
		b.WriteString(strconv.Itoa(len(g.Expenses)))
		b.WriteString(" expenses, ")
		b.WriteString(fmtAmount(total))
		b.WriteString(" recorded\n")
	}
	return b.String()
}

func renderGroup(g *Group) string {
	var b strings.Builder
	b.WriteString("# 🍻 ")
	b.WriteString(g.Name)
	b.WriteString("\n\n")

	b.WriteString("## Balances\n\n")
	for _, m := range g.Members {
		b.WriteString("- `")
		b.WriteString(m.String())
		b.WriteString("`: ")
		b.WriteString(fmtAmount(g.Balances[m]))
		b.WriteString("\n")
	}

	b.WriteString("\n## Who pays whom (netted)\n\n")
	transfers := computeTransfers(g)
	if len(transfers) == 0 {
		b.WriteString("All settled up. 🎉\n")
	} else {
		for _, t := range transfers {
			b.WriteString("- `")
			b.WriteString(shortAddr(t.From))
			b.WriteString("` pays `")
			b.WriteString(shortAddr(t.To))
			b.WriteString("` **")
			b.WriteString(fmtAmount(t.Amount))
			b.WriteString("**\n")
		}
	}

	if len(g.Expenses) > 0 {
		b.WriteString("\n## Expenses\n\n")
		for _, e := range g.Expenses {
			b.WriteString("- #")
			b.WriteString(strconv.Itoa(e.ID))
			b.WriteString(" `")
			b.WriteString(shortAddr(e.Payer))
			b.WriteString("` paid **")
			b.WriteString(fmtAmount(e.Amount))
			b.WriteString("** split ")
			b.WriteString(strconv.Itoa(len(e.Participants)))
			b.WriteString(" ways")
			if e.Memo != "" {
				b.WriteString(" — ")
				b.WriteString(e.Memo)
			}
			b.WriteString("\n")
		}
	}

	if len(g.Settlements) > 0 {
		b.WriteString("\n## Settlements\n\n")
		for _, s := range g.Settlements {
			b.WriteString("- `")
			b.WriteString(shortAddr(s.From))
			b.WriteString("` settled **")
			b.WriteString(fmtAmount(s.Amount))
			b.WriteString("** with `")
			b.WriteString(shortAddr(s.To))
			b.WriteString("`\n")
		}
	}

	b.WriteString("\n[← All tabs](/r/g1qglhdzln0adn63e95gga9rntefhd6s6uw9e2zz/gnotab/v2)\n")
	return b.String()
}

package gnotab

import (
	"testing"
)

// Throwaway test addresses (keys generated locally with gnokey, test-only).
var (
	alice = address("g13guqfpf95vd5758ak8udtywk23hrzmf5yfq38a")
	bob   = address("g15m8vpgr56wvk8vtwh4xfecw7pdnansccwhfw25")
	carol = address("g1324d550z3pregw3njlfhfcwr353rcyhp96hkmx")
)

func TestCreateGroup(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateGroup(cross(cur), "Tavern Night", bob.String() + "," + carol.String())
	if id <= 0 {
		t.Fatalf("expected positive group id, got %d", id)
	}
	g := getGroup(id)
	if len(g.Members) != 3 {
		t.Fatalf("expected 3 members, got %d", len(g.Members))
	}
	if g.Members[0] != alice || g.Members[1] != bob || g.Members[2] != carol {
		t.Fatalf("unexpected member order: %v", g.Members)
	}
	for _, m := range g.Members {
		if g.Balances[m] != 0 {
			t.Fatalf("expected zero starting balance for %s, got %d", m, g.Balances[m])
		}
	}
}

func TestSplitThreeWays(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateGroup(cross(cur), "Dinner", bob.String() + "," + carol.String())

	// Alice pays 900000 ugnot (0.9 GNOT), split evenly among all three.
	expID := AddExpense(cross(cur), id, 900000, alice.String() + "," + bob.String() + "," + carol.String(), "dinner")
	if expID != 1 {
		t.Fatalf("expected expense id 1, got %d", expID)
	}
	if got := GetBalance(id, alice); got != 600000 {
		t.Fatalf("alice balance: expected 600000, got %d", got)
	}
	if got := GetBalance(id, bob); got != -300000 {
		t.Fatalf("bob balance: expected -300000, got %d", got)
	}
	if got := GetBalance(id, carol); got != -300000 {
		t.Fatalf("carol balance: expected -300000, got %d", got)
	}

	// Netted transfers: bob -> alice 300000, carol -> alice 300000.
	trs := computeTransfers(getGroup(id))
	if len(trs) != 2 {
		t.Fatalf("expected 2 netted transfers, got %d", len(trs))
	}
	if trs[0].From != bob || trs[0].To != alice || trs[0].Amount != 300000 {
		t.Fatalf("unexpected transfer 0: %+v", trs[0])
	}
	if trs[1].From != carol || trs[1].To != alice || trs[1].Amount != 300000 {
		t.Fatalf("unexpected transfer 1: %+v", trs[1])
	}
}

func TestNettingTwoWay(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateGroup(cross(cur), "Two Way", bob.String())

	// Alice pays 300 for both: alice +150, bob -150.
	AddExpense(cross(cur), id, 300, alice.String() + "," + bob.String(), "round 1")
	// Bob pays 100 for both: bob +50, alice -50.
	testing.SetRealm(testing.NewUserRealm(bob))
	AddExpense(cross(cur), id, 100, alice.String() + "," + bob.String(), "round 2")

	// Net: alice +100, bob -100 (the two debts net against each other).
	if got := GetBalance(id, alice); got != 100 {
		t.Fatalf("alice balance: expected 100, got %d", got)
	}
	if got := GetBalance(id, bob); got != -100 {
		t.Fatalf("bob balance: expected -100, got %d", got)
	}
	trs := computeTransfers(getGroup(id))
	if len(trs) != 1 {
		t.Fatalf("expected 1 netted transfer, got %d", len(trs))
	}
	if trs[0].From != bob || trs[0].To != alice || trs[0].Amount != 100 {
		t.Fatalf("unexpected transfer: %+v", trs[0])
	}
}

func TestSettlePaysOff(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateGroup(cross(cur), "Settle Up", bob.String() + "," + carol.String())

	// Alice pays 900 split three ways: bob and carol each owe alice 300.
	AddExpense(cross(cur), id, 900, alice.String() + "," + bob.String() + "," + carol.String(), "tab")

	// Bob settles his full 300 with alice.
	testing.SetRealm(testing.NewUserRealm(bob))
	Settle(cross(cur), id, alice, 300)
	if got := GetBalance(id, bob); got != 0 {
		t.Fatalf("bob balance after settle: expected 0, got %d", got)
	}
	if got := GetBalance(id, alice); got != 300 {
		t.Fatalf("alice balance after bob settles: expected 300, got %d", got)
	}

	// Carol settles hers too; everyone ends at zero.
	testing.SetRealm(testing.NewUserRealm(carol))
	Settle(cross(cur), id, alice, 300)
	for _, m := range []address{alice, bob, carol} {
		if got := GetBalance(id, m); got != 0 {
			t.Fatalf("balance of %s: expected 0, got %d", m, got)
		}
	}
	if trs := computeTransfers(getGroup(id)); len(trs) != 0 {
		t.Fatalf("expected no transfers after full settlement, got %d", len(trs))
	}
	if n := len(getGroup(id).Settlements); n != 2 {
		t.Fatalf("expected 2 recorded settlements, got %d", n)
	}
}

func TestSplitRemainder(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateGroup(cross(cur), "Remainder", bob.String() + "," + carol.String())

	// 100 ugnot split 3 ways: shares 34/33/33 (remainder to first listed).
	AddExpense(cross(cur), id, 100, alice.String() + "," + bob.String() + "," + carol.String(), "odd amount")
	if got := GetBalance(id, alice); got != 100-34 {
		t.Fatalf("alice balance: expected 66, got %d", got)
	}
	if got := GetBalance(id, bob); got != -33 {
		t.Fatalf("bob balance: expected -33, got %d", got)
	}
	if got := GetBalance(id, carol); got != -33 {
		t.Fatalf("carol balance: expected -33, got %d", got)
	}
}

package vault

// VaultState is the lifecycle state of a vault.
//
//	ACTIVE ──RequestRecovery──▶ RECOVERING ──Execute──▶ ACTIVE
//	   ▲                             │
//	   └──────CancelRecovery─────────┘
type VaultState int

const (
	// ACTIVE means the vault is under the owner's control.
	ACTIVE VaultState = iota

	// RECOVERING means a recovery request is open; configuration and
	// withdrawals are frozen until it is executed or cancelled.
	RECOVERING
)

// Parameter bounds.
const (
	// MinWindowSecs is the shortest accepted recovery window: one hour.
	MinWindowSecs = int64(3600)

	// MaxWindowSecs is the longest accepted recovery window: thirty days.
	MaxWindowSecs = int64(2592000)

	// MaxGuardians is the largest accepted guardian set.
	MaxGuardians = 10
)

// Vault holds the full state of one vault.
//
// Balance is tracked internally because every vault shares the same realm
// address, so a banker lookup can only return the aggregate.
type Vault struct {
	// ID is the vault identifier, equal to its index in vaults.
	ID int

	// Owner is the address allowed to configure the vault and withdraw funds.
	Owner address

	// BackupAddr receives the balance and the ownership on a completed recovery.
	BackupAddr address

	// Guardians are the addresses eligible to vote on a recovery.
	Guardians []address

	// Threshold is the number of votes required to execute a recovery.
	Threshold int

	// WindowSecs is the recovery window length in seconds.
	WindowSecs int64

	// Balance is this vault's share of the realm balance, in ugnot.
	Balance int64

	// State is the current lifecycle state.
	State VaultState

	// Requestor is the address that opened the current recovery.
	Requestor address

	// RequestedAt is the unix timestamp at which the current recovery started.
	RequestedAt int64

	// Votes holds the addresses that have voted in the current recovery.
	Votes []address

	// RecoveryCount is the number of completed recoveries.
	RecoveryCount int

	// LastRecoveredAt is the unix timestamp of the last completed recovery.
	LastRecoveredAt int64
}

// vaults holds every vault. The index equals the ID and entries are never removed.
var vaults []*Vault

// mustGet returns the vault with the given ID.
//
// Parameters:
//   - id: Vault identifier.
//
// Returns:
//   - *Vault: The matching vault. Panics if id is out of range.
func mustGet(id int) *Vault {
	if id < 0 || id >= len(vaults) {
		panic("no such vault")
	}
	return vaults[id]
}

// requireOwner asserts that the caller is the owner of v.
//
// Parameters:
//   - cur: Realm context; the caller is read from cur.Previous().
//   - v: Vault to check. Panics if the caller is not the owner.
func requireOwner(cur realm, v *Vault) {
	if cur.Previous().Address() != v.Owner {
		panic("caller is not the owner")
	}
}

// isGuardian reports whether addr is in the guardian set.
//
// Parameters:
//   - addr: Address to look up.
//
// Returns:
//   - bool: True if addr is a guardian.
func (v *Vault) isGuardian(addr address) bool {
	for _, g := range v.Guardians {
		if g == addr {
			return true
		}
	}
	return false
}

// hasVoted reports whether addr has already voted in the current recovery.
//
// Parameters:
//   - addr: Address to look up.
//
// Returns:
//   - bool: True if addr has voted.
func (v *Vault) hasVoted(addr address) bool {
	for _, a := range v.Votes {
		if a == addr {
			return true
		}
	}
	return false
}

// validateGuardians validates the guardian set and the vote threshold.
//
// Parameters:
//   - guardians: Guardian addresses; 1..MaxGuardians unique non-zero addresses.
//   - threshold: Votes required for a recovery; within 1..len(guardians).
func validateGuardians(guardians []address, threshold int) {
	n := len(guardians)
	if n < 1 || n > MaxGuardians {
		panic("guardian count must be 1..10")
	}
	if threshold < 1 || threshold > n {
		panic("threshold must be within 1..len(guardians)")
	}
	for i := 0; i < n; i++ {
		if guardians[i] == address("") {
			panic("guardian must not be zero address")
		}
		for j := i + 1; j < n; j++ {
			if guardians[i] == guardians[j] {
				panic("duplicate guardian address")
			}
		}
	}
}

// validateWindow validates the recovery window length.
//
// Parameters:
//   - windowSecs: Window in seconds; within MinWindowSecs..MaxWindowSecs.
func validateWindow(windowSecs int64) {
	if windowSecs < MinWindowSecs || windowSecs > MaxWindowSecs {
		panic("windowSecs must be within 3600..2592000")
	}
}

package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
)

// receivedUgnot returns the amount of ugnot paid to this realm by the current
// transaction. The previous call must be a direct EOA call; payments forwarded
// by an intermediate realm or sent from a MsgRun temporary realm are rejected.
// This is the only file that imports chain/runtime/unsafe, and unsafe is used
// solely to read the envelope amount, never to derive identity.
//
// Parameters:
//   - cur: Realm context.
//
// Returns:
//   - int64: Amount paid in ugnot.
func receivedUgnot(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("payment must come from a direct EOA call")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// payUgnot sends amount ugnot from this realm's address to to.
//
// The banker is created, used and discarded inside this function. It must never
// be stored in state or returned to a caller: BankerTypeRealmSend is a permanent
// spending grant over the realm address, which every vault shares.
//
// Parameters:
//   - cur: Realm context.
//   - to: Recipient address.
//   - amount: Amount in ugnot.
func payUgnot(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

package vault

import (
	"strconv"
	"strings"
	"time"
)

// CodeVersion is the on-chain code marker, used to confirm that a redeploy
// actually took effect.
const CodeVersion = "0.2.0"

// realmPath is the on-chain path of this package. It is needed to build absolute
// links to vault pages: gnoweb copies markdown link targets verbatim, so a bare
// "0" resolves against the parent directory and returns 404.
const realmPath = "gno.land/r/g1rq2w5mqrlw8lnjlnsqcwf4kxejs2jxqgplxqx0/vault"

// ugnotPerGnot is the denomination ratio between the chain unit and GNOT.
const ugnotPerGnot = 1000000

// Render renders the gnoweb page for the given path.
//
// Parameters:
//   - path: Empty for the vault index, or a vault ID for the detail page.
//
// Returns:
//   - string: Markdown page.
func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	id, err := strconv.Atoi(path)
	if err != nil {
		return "# GuardianVault\n\n" +
			"Path must be a vault ID, for example `:0`. Got `" + path + "`.\n\n" +
			"[All vaults](" + indexLink() + ")\n"
	}
	return renderVault(id)
}

// renderIndex renders the vault list page.
//
// Returns:
//   - string: Markdown page.
func renderIndex() string {
	out := "# GuardianVault\n\n"
	out += "A social-recovery vault. Name 1–10 guardians when you create it; if you "
	out += "lose your key, they can return the funds to the **backup address you "
	out += "registered in advance** — and they can never send them anywhere else.\n\n"

	out += "## How it works\n\n"
	out += "1. **Create** a vault, choose its guardians and the threshold of votes.\n"
	out += "2. **Deposit** ugnot. Only the owner can withdraw it.\n"
	out += "3. **Recover** if the key is lost: a guardian opens a recovery, guardians "
	out += "vote, and once the threshold is met and the window elapsed anyone can "
	out += "execute it. The balance goes to the backup address.\n"
	out += "4. **Cancel** while you still have the key: the owner can veto any "
	out += "recovery during the window.\n\n"

	if len(vaults) == 0 {
		out += "---\n\n**No vaults yet.** The first one is created with `CreateVault`.\n"
		return out + versionLine()
	}

	var total int64
	var recovering int
	for _, v := range vaults {
		total += v.Balance
		if v.State == RECOVERING {
			recovering++
		}
	}

	out += "## Vaults\n\n"
	out += "**" + countText(len(vaults), "vault") + "** · " + gnotText(total) +
		" locked · " + strconv.Itoa(recovering) + " recovering\n\n"
	out += "| Vault | Owner | Balance | State | Recovery |\n"
	out += "| --- | --- | --- | --- | --- |\n"
	for _, v := range vaults {
		out += "| [#" + strconv.Itoa(v.ID) + "](" + vaultLink(v.ID) + ") "
		out += "| `" + shortAddr(v.Owner) + "` "
		out += "| " + gnotText(v.Balance) + " "
		out += "| " + stateLabel(v) + " "
		out += "| " + indexRecoveryText(v) + " |\n"
	}

	return out + versionLine()
}

// renderVault renders the detail page of one vault.
//
// Parameters:
//   - id: Vault identifier. Returns a not-found page if it is out of range.
//
// Returns:
//   - string: Markdown page.
func renderVault(id int) string {
	if id < 0 || id >= len(vaults) {
		return "# Vault not found\n\nNo vault with ID " + strconv.Itoa(id) +
			".\n\n[All vaults](" + indexLink() + ")\n"
	}
	v := vaults[id]

	out := "# Vault #" + strconv.Itoa(v.ID) + "\n\n"
	out += "**" + stateLabel(v) + ".** " + summaryText(v) + "\n\n"

	out += "## Funds\n\n"
	out += "| Field | Value |\n| --- | --- |\n"
	out += "| Balance | **" + gnotText(v.Balance) + "** (" + commas(v.Balance) + " ugnot) |\n"
	out += "| Owner | `" + v.Owner.String() + "` |\n"
	out += "| Backup address | `" + v.BackupAddr.String() + "` |\n\n"
	out += "The backup address is where a recovery pays out. Guardians cannot "
	out += "redirect funds to themselves: the owner or the backup address are the "
	out += "only possible recipients.\n\n"

	out += "## Guardians\n\n"
	if len(v.Guardians) == 0 {
		out += "No guardians configured. The owner can set a new set with "
		out += "`SetGuardians`.\n\n"
	} else {
		out += "| Guardian | Voted |\n| --- | --- |\n"
		for _, g := range v.Guardians {
			voted := "—"
			if v.hasVoted(g) {
				voted = "voted"
			}
			out += "| `" + g.String() + "` | " + voted + " |\n"
		}
		out += "\nThreshold **" + strconv.Itoa(v.Threshold) + " of " +
			strconv.Itoa(len(v.Guardians)) + "** · window **" + windowText(v.WindowSecs) +
			"** · completed recoveries **" + strconv.Itoa(v.RecoveryCount) + "**\n\n"
		if v.Threshold == 1 && len(v.Guardians) > 1 {
			out += "> Threshold 1 means a single guardian is enough. That is a "
			out += "single point of trust, not a distributed one.\n\n"
		}
	}

	if v.State == RECOVERING {
		out += recoveryBlock(v)
	}

	out += "## What you can do\n\n"
	out += actionTable(v)

	out += "\n[All vaults](" + indexLink() + ")\n"
	return out + versionLine()
}

// recoveryBlock renders the recovery state of a vault in progress.
//
// Parameters:
//   - v: Vault in the RECOVERING state.
//
// Returns:
//   - string: Markdown section.
func recoveryBlock(v *Vault) string {
	now := time.Now().Unix()
	ends := v.RequestedAt + v.WindowSecs
	elapsed := now >= ends
	enough := len(v.Votes) >= v.Threshold

	out := "## Recovery in progress\n\n"
	if enough {
		if elapsed {
			out += "**Threshold reached and the window has elapsed — ready to execute.**\n\n"
		} else {
			out += "**Threshold reached — waiting for the window to elapse.**\n\n"
		}
	} else {
		need := v.Threshold - len(v.Votes)
		out += "**" + countText(need, "more vote") + " needed** to reach the threshold of " +
			strconv.Itoa(v.Threshold) + ".\n\n"
	}

	out += "| Field | Value |\n| --- | --- |\n"
	out += "| Requested by | `" + v.Requestor.String() + "` |\n"
	out += "| Votes | " + strconv.Itoa(len(v.Votes)) + " of " +
		strconv.Itoa(v.Threshold) + " required |\n"
	if elapsed {
		out += "| Window | **elapsed** (" + windowText(v.WindowSecs) + " after the request) |\n"
	} else {
		out += "| Window | **" + countdownText(ends-now) + " left** · ends " +
			time.Unix(ends, 0).Format("2006-01-02 15:04 MST") + " |\n"
	}
	out += "\nConfiguration changes and withdrawals are frozen until this recovery "
	out += "ends. The owner can cancel it at any time during the window.\n\n"

	return out
}

// actionTable renders the actions available to each kind of caller.
//
// Parameters:
//   - v: Vault to describe.
//
// Returns:
//   - string: Markdown table.
func actionTable(v *Vault) string {
	out := "| If you are | You can |\n| --- | --- |\n"

	if v.State == RECOVERING {
		out += "| the owner | `CancelRecovery` — veto it and reset the votes |\n"
		if len(v.Votes) < v.Threshold {
			out += "| a guardian who has not voted | `Vote` |\n"
		} else {
			out += "| a guardian | nothing more — the threshold is reached |\n"
		}
		if time.Now().Unix() >= v.RequestedAt+v.WindowSecs && len(v.Votes) >= v.Threshold {
			out += "| anyone | `Execute` — pay the balance to the backup address |\n"
		} else {
			out += "| anyone | `Execute` once the threshold is met and the window has elapsed |\n"
		}
		out += "| — | no withdrawals, no configuration changes until this ends |\n"
		return out
	}

	if len(v.Guardians) == 0 {
		out += "| the owner | `SetGuardians` to restore protection, `Deposit`, `Withdraw` |\n"
		out += "| anyone | `Deposit` |\n"
		return out
	}

	out += "| the owner | `Deposit`, `Withdraw`, `AddGuardian`, `SetGuardians`, `SetBackup` |\n"
	out += "| a guardian | `RequestRecovery` when the key is lost, then `Vote` |\n"
	out += "| anyone | `Deposit`, or `RequestRecovery` — a recovery can be opened by anyone, "
	out += "but it only succeeds with guardian votes |\n"
	return out
}

// summaryText returns the one-sentence description shown under the title.
//
// Parameters:
//   - v: Vault to describe.
//
// Returns:
//   - string: Sentence without a trailing newline.
func summaryText(v *Vault) string {
	switch {
	case v.State == RECOVERING:
		return "A recovery is open: " + strconv.Itoa(len(v.Votes)) + " of " +
			strconv.Itoa(v.Threshold) + " votes, " + recoveryTimeText(v) + "."
	case len(v.Guardians) == 0:
		return "Recovered and left unprotected: the guardian set was cleared. " +
			"The owner can configure a new one."
	default:
		return strconv.Itoa(v.Threshold) + " of " + strconv.Itoa(len(v.Guardians)) +
			" guardians must agree to recover it. A recovery stays open for " +
			windowText(v.WindowSecs) + ", during which the owner can veto it."
	}
}

// stateLabel returns the display name of a vault's state. A vault whose
// guardians were cleared by a completed recovery is reported as unprotected
// rather than as "active with threshold 0 of 0".
//
// Parameters:
//   - v: Vault to describe.
//
// Returns:
//   - string: Display name.
func stateLabel(v *Vault) string {
	if v.State == RECOVERING {
		return "Recovering"
	}
	if len(v.Guardians) == 0 {
		return "Unprotected"
	}
	return "Active"
}

// indexRecoveryText returns the recovery cell of the index table.
//
// Parameters:
//   - v: Vault to describe.
//
// Returns:
//   - string: Cell text.
func indexRecoveryText(v *Vault) string {
	if v.State != RECOVERING {
		return "—"
	}
	text := strconv.Itoa(len(v.Votes)) + " of " + strconv.Itoa(v.Threshold)
	return text + " votes · " + recoveryTimeText(v)
}

// recoveryTimeText returns the time left in the open recovery window.
//
// Parameters:
//   - v: Vault in the RECOVERING state.
//
// Returns:
//   - string: Duration or elapsed marker.
func recoveryTimeText(v *Vault) string {
	left := v.RequestedAt + v.WindowSecs - time.Now().Unix()
	if left <= 0 {
		return "window elapsed"
	}
	return countdownText(left) + " left"
}

// versionLine renders the code version footer.
//
// Returns:
//   - string: Markdown line.
func versionLine() string {
	return "\n---\n\n_Live code: " + CodeVersion + "_\n"
}

// indexLink returns the path of the index page.
//
// Returns:
//   - string: Absolute path understood by gnoweb.
func indexLink() string {
	return "/" + strings.TrimPrefix(realmPath, "gno.land/")
}

// vaultLink returns the path of a vault detail page.
//
// Parameters:
//   - id: Vault identifier.
//
// Returns:
//   - string: Absolute path understood by gnoweb.
func vaultLink(id int) string {
	return indexLink() + ":" + strconv.Itoa(id)
}

// countText formats a count with a singular or plural noun.
//
// Parameters:
//   - n: Count.
//   - noun: Singular noun.
//
// Returns:
//   - string: For example "3 vaults".
func countText(n int, noun string) string {
	if n == 1 {
		return "1 " + noun
	}
	return strconv.Itoa(n) + " " + noun + "s"
}

// gnotText formats an ugnot amount as GNOT, trimming trailing zeros.
//
// Parameters:
//   - amount: Amount in ugnot.
//
// Returns:
//   - string: For example "1.5 GNOT".
func gnotText(amount int64) string {
	whole := amount / ugnotPerGnot
	frac := amount % ugnotPerGnot
	if frac == 0 {
		return commas(whole) + " GNOT"
	}
	digits := strconv.FormatInt(frac, 10)
	for len(digits) < 6 {
		digits = "0" + digits
	}
	return commas(whole) + "." + strings.TrimRight(digits, "0") + " GNOT"
}

// commas formats a non-negative integer with thousands separators.
//
// Parameters:
//   - n: Integer to format.
//
// Returns:
//   - string: For example "1500000" as "1,500,000".
func commas(n int64) string {
	s := strconv.FormatInt(n, 10)
	if len(s) <= 3 {
		return s
	}
	var out strings.Builder
	lead := len(s) % 3
	if lead > 0 {
		out.WriteString(s[:lead])
	}
	for i := lead; i < len(s); i += 3 {
		if out.Len() > 0 {
			out.WriteString(",")
		}
		out.WriteString(s[i : i+3])
	}
	return out.String()
}

// countdownText formats a remaining duration at the precision a live countdown
// needs: days and hours when far away, minutes and seconds near the end.
//
// Parameters:
//   - secs: Remaining seconds; a negative value is treated as zero.
//
// Returns:
//   - string: For example "2d 3h", "5h 12m" or "9m 30s".
func countdownText(secs int64) string {
	if secs < 0 {
		secs = 0
	}
	days := secs / 86400
	hours := (secs % 86400) / 3600
	mins := (secs % 3600) / 60
	remain := secs % 60

	if days > 0 {
		out := strconv.FormatInt(days, 10) + "d"
		if hours > 0 {
			out += " " + strconv.FormatInt(hours, 10) + "h"
		}
		return out
	}
	if hours > 0 {
		out := strconv.FormatInt(hours, 10) + "h"
		if mins > 0 {
			out += " " + strconv.FormatInt(mins, 10) + "m"
		}
		return out
	}
	if mins > 0 {
		out := strconv.FormatInt(mins, 10) + "m"
		if remain > 0 {
			out += " " + strconv.FormatInt(remain, 10) + "s"
		}
		return out
	}
	return strconv.FormatInt(remain, 10) + "s"
}

// windowText formats a configured duration in seconds, e.g. 72 hours or 1h 30m.
//
// Parameters:
//   - secs: Duration in seconds.
//
// Returns:
//   - string: Human-readable duration.
func windowText(secs int64) string {
	h := secs / 3600
	m := (secs % 3600) / 60
	s := secs % 60

	if m == 0 && s == 0 {
		if h == 1 {
			return "1 hour"
		}
		return strconv.FormatInt(h, 10) + " hours"
	}

	out := strconv.FormatInt(h, 10) + "h"
	if m > 0 {
		out += " " + strconv.FormatInt(m, 10) + "m"
	}
	if s > 0 {
		out += " " + strconv.FormatInt(s, 10) + "s"
	}
	return out
}

// shortAddr compresses an address to the g1abc…wxyz form.
//
// Parameters:
//   - a: Address to compress.
//
// Returns:
//   - string: Compressed address.
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package vault

import "time"

// This file contains every exported crossing function and is the only place
// where authorization is decided. Each function verifies cur.IsCurrent() first,
// derives the caller from cur.Previous().Address(), and validates every
// precondition before the first state write.

// CreateVault creates a vault and registers the caller as its owner.
//
// Parameters:
//   - cur: Realm context.
//   - threshold: Votes required to execute a recovery; within 1..len(guardians).
//   - backup: Address that receives the funds and the ownership on recovery.
//   - windowSecs: Recovery window in seconds; within 3600..2592000.
//   - guardians: Guardian addresses; 1..10 unique, non-zero addresses. The
//     variadic form is required because MsgCall cannot encode []address.
//
// Returns:
//   - int: ID of the new vault.
func CreateVault(cur realm, threshold int, backup address, windowSecs int64, guardians ...address) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}

	owner := cur.Previous().Address()
	if owner == address("") {
		panic("owner must not be zero address")
	}
	validateGuardians(guardians, threshold)
	if backup == address("") {
		panic("backup address must not be zero")
	}
	validateWindow(windowSecs)

	// Copy the input so the caller cannot mutate the underlying array afterwards.
	g := make([]address, len(guardians))
	copy(g, guardians)

	id := len(vaults)
	vaults = append(vaults, &Vault{
		ID:         id,
		Owner:      owner,
		BackupAddr: backup,
		Guardians:  g,
		Threshold:  threshold,
		WindowSecs: windowSecs,
		State:      ACTIVE,
	})
	return id
}

// Deposit credits the ugnot attached to the current transaction to a vault.
// The amount is read from the transaction envelope, never from a parameter.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
func Deposit(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	amt := receivedUgnot(cur)
	if amt <= 0 {
		panic("no ugnot sent")
	}
	v.Balance += amt
}

// Withdraw sends ugnot from a vault to an arbitrary address. Owner only, and
// only while the vault is ACTIVE.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
//   - to: Recipient address; must be non-zero.
//   - amount: Amount in ugnot; must be positive and not exceed the balance.
func Withdraw(cur realm, id int, to address, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if to == address("") {
		panic("recipient must not be zero address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > v.Balance {
		panic("insufficient balance")
	}

	// Debit before paying: a panic in payUgnot rolls back the whole transaction,
	// so no half-written state can survive.
	v.Balance -= amount
	payUgnot(cur, to, amount)
}

// AddGuardian appends a guardian to the set without changing the threshold.
// Owner only, and only while the vault is ACTIVE.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
//   - guardian: Address to append; must be non-zero, not already present, and
//     the set must stay within MaxGuardians.
func AddGuardian(cur realm, id int, guardian address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if guardian == address("") {
		panic("guardian must not be zero address")
	}
	if v.isGuardian(guardian) {
		panic("already a guardian")
	}
	if len(v.Guardians) >= MaxGuardians {
		panic("guardian count would exceed 10")
	}

	v.Guardians = append(v.Guardians, guardian)
}

// SetGuardians replaces the whole guardian set and the threshold. Owner only,
// and only while the vault is ACTIVE. Removing a guardian is possible only
// through this function, so the threshold is always submitted with the set.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
//   - threshold: Votes required to execute a recovery; within 1..len(guardians).
//   - guardians: Guardian addresses; 1..10 unique, non-zero addresses.
func SetGuardians(cur realm, id int, threshold int, guardians ...address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	validateGuardians(guardians, threshold)

	g := make([]address, len(guardians))
	copy(g, guardians)
	v.Guardians = g
	v.Threshold = threshold
}

// SetBackup replaces the backup address. Owner only, and only while the vault
// is ACTIVE: the destination is frozen for the duration of a recovery.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
//   - backup: New backup address; must be non-zero.
func SetBackup(cur realm, id int, backup address) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != ACTIVE {
		panic("vault is not active")
	}
	if backup == address("") {
		panic("backup address must not be zero")
	}
	v.BackupAddr = backup
}

// RequestRecovery switches a vault to RECOVERING and starts the window.
// Callable by anyone; the requestor gains no voting power.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
func RequestRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != ACTIVE {
		panic("vault is not active")
	}

	v.State = RECOVERING
	v.Requestor = cur.Previous().Address()
	v.RequestedAt = time.Now().Unix()
	v.Votes = nil
}

// Vote records one vote from a guardian. Each guardian may vote once and the
// vote count never exceeds the threshold.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
func Vote(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	caller := cur.Previous().Address()
	if !v.isGuardian(caller) {
		panic("not a guardian")
	}
	if v.hasVoted(caller) {
		panic("already voted")
	}
	if len(v.Votes) >= v.Threshold {
		panic("enough votes already")
	}

	v.Votes = append(v.Votes, caller)
}

// CancelRecovery cancels an open recovery, clears the votes and returns the
// vault to ACTIVE. Owner only, and only while the vault is RECOVERING.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
func CancelRecovery(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)
	requireOwner(cur, v)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}

	v.State = ACTIVE
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
}

// Execute pays the balance to the backup address, transfers the ownership to
// it, and resets the guardian configuration. Callable by anyone once the
// threshold is met and the recovery window has elapsed.
//
// Parameters:
//   - cur: Realm context.
//   - id: Vault identifier.
func Execute(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := mustGet(id)

	if v.State != RECOVERING {
		panic("vault not recovering")
	}
	if len(v.Votes) < v.Threshold {
		panic("threshold not reached")
	}

	now := time.Now().Unix()
	if now < v.RequestedAt+v.WindowSecs {
		panic("recovery window has not elapsed")
	}

	amt := v.Balance
	v.Balance = 0
	// Skip the banker on a zero balance: a zero-value transfer is meaningless
	// and some implementations reject it.
	if amt > 0 {
		payUgnot(cur, v.BackupAddr, amt)
	}

	v.Owner = v.BackupAddr
	v.Guardians = nil
	v.Threshold = 0
	v.Votes = nil
	v.Requestor = address("")
	v.RequestedAt = 0
	v.State = ACTIVE

	v.RecoveryCount++
	v.LastRecoveredAt = now
}

// Package arisan holds the stateless building blocks of an arisan: the
// Indonesian rotating savings circle (a ROSCA). Every round each member puts
// the same amount into the pot and one member who has not won yet takes the
// whole pot home, until everybody has had a turn.
//
// The package keeps no state. It only provides the pieces any realm needs to
// run a circle, so other realms can reuse them with their own storage, token
// or rules:
//
//   - Mode, ParseMode: how the next winner is chosen (giliran / kocok)
//   - MixEntropy, PickIndex, PickWinner: deterministic, auditable selection
//   - FormatGNOT, ShortAddr, ProgressBar: small rendering helpers
//   - Wheel: an SVG "arisan wheel" that gnoweb renders inline
//
// The reference realm built on it is r/<namespace>/arisanku.
package arisan

import (
	"crypto/sha256"
	"strconv"
	"strings"
)

// Mode decides how the winner of a round is chosen.
type Mode int

const (
	// ModeGiliran ("taking turns"): the earliest-joined eligible member who
	// has not won yet receives the pot. Fully predictable, zero trust.
	ModeGiliran Mode = iota
	// ModeKocok ("shake the jar"): the winner is drawn among eligible members
	// from on-chain entropy, like shaking the rolled-up names in a glass jar.
	ModeKocok
)

// String returns the canonical, lowercase name of the mode.
func (m Mode) String() string {
	switch m {
	case ModeGiliran:
		return "giliran"
	case ModeKocok:
		return "kocok"
	}
	return "unknown"
}

// Label returns a human label for UIs, in Indonesian with an English gloss.
func (m Mode) Label() string {
	switch m {
	case ModeGiliran:
		return "Giliran (fixed turns)"
	case ModeKocok:
		return "Kocok (random draw)"
	}
	return "Unknown"
}

// ParseMode accepts "giliran"/"rotation"/"turns" and "kocok"/"draw"/"random"
// (case-insensitive). ok is false for anything else.
func ParseMode(s string) (m Mode, ok bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "giliran", "rotation", "turns", "turn", "0":
		return ModeGiliran, true
	case "kocok", "draw", "random", "lottery", "1":
		return ModeKocok, true
	}
	return ModeGiliran, false
}

// MixEntropy folds parts into the previous seed with SHA-256 and returns the
// new 32-byte seed. Feeding every payment (payer, height, time) into the seed
// makes the final draw depend on the whole round's history, not on a single
// caller.
func MixEntropy(prev []byte, parts ...string) []byte {
	buf := make([]byte, 0, len(prev)+64)
	buf = append(buf, prev...)
	for _, p := range parts {
		// length-prefix every part so ("ab","c") != ("a","bc")
		buf = append(buf, []byte(strconv.Itoa(len(p)))...)
		buf = append(buf, ':')
		buf = append(buf, []byte(p)...)
	}
	sum := sha256.Sum256(buf)
	return sum[:]
}

// PickIndex maps a seed to an index in [0, n). It uses the first 8 bytes of
// the seed as a big-endian uint64. It panics if n <= 0.
func PickIndex(seed []byte, n int) int {
	if n <= 0 {
		panic("arisan: PickIndex needs n > 0")
	}
	var x uint64
	for i := 0; i < 8 && i < len(seed); i++ {
		x = x<<8 | uint64(seed[i])
	}
	return int(x % uint64(n))
}

// PickWinner returns one element of candidates (member indexes, in join
// order). In ModeGiliran it is the first candidate; in ModeKocok it is chosen
// by PickIndex(seed). It returns -1 when there is no candidate.
func PickWinner(mode Mode, candidates []int, seed []byte) int {
	if len(candidates) == 0 {
		return -1
	}
	if mode == ModeKocok {
		return candidates[PickIndex(seed, len(candidates))]
	}
	return candidates[0]
}

// FormatGNOT renders an amount of ugnot as GNOT with up to 6 decimals and no
// trailing zeros: 1500000 -> "1.5 GNOT", 250 -> "0.00025 GNOT".
func FormatGNOT(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	if neg {
		s = "-" + s
	}
	return s + " GNOT"
}

// ShortAddr shortens a bech32 address for display: g1abcd…wxyz.
func ShortAddr(addr string) string {
	if len(addr) <= 13 {
		return addr
	}
	return addr[:6] + "…" + addr[len(addr)-4:]
}

// ProgressBar renders done/total as a fixed-width text bar, e.g.
// ProgressBar(2, 5, 10) == "▰▰▰▰▱▱▱▱▱▱".
func ProgressBar(done, total, width int) string {
	if width <= 0 {
		return ""
	}
	if total <= 0 {
		return strings.Repeat("▱", width)
	}
	if done < 0 {
		done = 0
	}
	if done > total {
		done = total
	}
	filled := done * width / total
	return strings.Repeat("▰", filled) + strings.Repeat("▱", width-filled)
}

package arisan

import (
	"strings"
	"testing"
)

func TestParseMode(t *testing.T) {
	cases := []struct {
		in   string
		want Mode
		ok   bool
	}{
		{"giliran", ModeGiliran, true},
		{" Rotation ", ModeGiliran, true},
		{"KOCOK", ModeKocok, true},
		{"draw", ModeKocok, true},
		{"random", ModeKocok, true},
		{"", ModeGiliran, false},
		{"auction", ModeGiliran, false},
	}
	for _, c := range cases {
		got, ok := ParseMode(c.in)
		if got != c.want || ok != c.ok {
			t.Errorf("ParseMode(%q) = %v,%v want %v,%v", c.in, got, ok, c.want, c.ok)
		}
	}
	if ModeGiliran.String() != "giliran" || ModeKocok.String() != "kocok" || Mode(9).String() != "unknown" {
		t.Errorf("unexpected Mode.String values")
	}
}

func TestMixEntropyDeterministicAndSensitive(t *testing.T) {
	a := MixEntropy(nil, "g1alice", "100")
	b := MixEntropy(nil, "g1alice", "100")
	if string(a) != string(b) {
		t.Fatalf("MixEntropy must be deterministic")
	}
	if len(a) != 32 {
		t.Fatalf("want 32-byte seed, got %d", len(a))
	}
	// length prefixing: ("ab","c") must differ from ("a","bc")
	if string(MixEntropy(nil, "ab", "c")) == string(MixEntropy(nil, "a", "bc")) {
		t.Fatalf("parts must be length-prefixed")
	}
	// chaining depends on previous seed
	if string(MixEntropy(a, "x")) == string(MixEntropy(nil, "x")) {
		t.Fatalf("previous seed must matter")
	}
}

func TestPickIndexRangeAndSpread(t *testing.T) {
	counts := make([]int, 5)
	seed := []byte("seed")
	for i := 0; i < 500; i++ {
		seed = MixEntropy(seed, "round")
		idx := PickIndex(seed, 5)
		if idx < 0 || idx >= 5 {
			t.Fatalf("index out of range: %d", idx)
		}
		counts[idx]++
	}
	for i, c := range counts {
		// expected 100 each; a fair hash never lands this far off
		if c < 60 || c > 140 {
			t.Errorf("bucket %d has %d hits, distribution looks broken: %v", i, c, counts)
		}
	}
}

func TestPickIndexPanicsOnZero(t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Fatalf("expected panic for n=0")
		}
	}()
	PickIndex([]byte{1}, 0)
}

func TestPickWinner(t *testing.T) {
	if PickWinner(ModeGiliran, nil, nil) != -1 {
		t.Fatalf("no candidates must return -1")
	}
	if got := PickWinner(ModeGiliran, []int{3, 1, 4}, []byte("anything")); got != 3 {
		t.Fatalf("giliran must take the first candidate, got %d", got)
	}
	seed := MixEntropy(nil, "fixed")
	cands := []int{2, 5, 7}
	got := PickWinner(ModeKocok, cands, seed)
	if got != cands[PickIndex(seed, 3)] {
		t.Fatalf("kocok must follow PickIndex")
	}
}

func TestFormatGNOT(t *testing.T) {
	cases := map[int64]string{
		0:          "0 GNOT",
		1000000:    "1 GNOT",
		1500000:    "1.5 GNOT",
		250:        "0.00025 GNOT",
		123456789:  "123.456789 GNOT",
		-2000000:   "-2 GNOT",
		1000000001: "1000.000001 GNOT",
	}
	for in, want := range cases {
		if got := FormatGNOT(in); got != want {
			t.Errorf("FormatGNOT(%d) = %q want %q", in, got, want)
		}
	}
}

func TestShortAddrAndProgress(t *testing.T) {
	a := "g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y"
	if got := ShortAddr(a); got != "g19py8…w56y" {
		t.Errorf("ShortAddr = %q", got)
	}
	if ShortAddr("g1short") != "g1short" {
		t.Errorf("short addresses must be unchanged")
	}
	if got := ProgressBar(2, 5, 10); got != "▰▰▰▰▱▱▱▱▱▱" {
		t.Errorf("ProgressBar = %q", got)
	}
	if got := ProgressBar(9, 5, 4); got != "▰▰▰▰" {
		t.Errorf("ProgressBar clamps: %q", got)
	}
	if got := ProgressBar(1, 0, 3); got != "▱▱▱" {
		t.Errorf("ProgressBar zero total: %q", got)
	}
}

func TestWheel(t *testing.T) {
	slots := []Slot{
		{Label: "1", Caption: "Rizki", State: SlotWon},
		{Label: "2", Caption: "<script>", State: SlotPaid},
		{Label: "3", Caption: "Ayu", State: SlotWinner},
		{Label: "4", Caption: "Budi", State: SlotLate},
	}
	svg := Wheel(slots, "4 GNOT", "Putaran 2 / 4")
	if !strings.HasPrefix(svg, "<svg") || !strings.HasSuffix(svg, "</svg>") {
		t.Fatalf("not an svg document")
	}
	if strings.Contains(svg, "<script>") {
		t.Fatalf("captions must be escaped")
	}
	if !strings.Contains(svg, "&lt;script") {
		t.Fatalf("escaped caption missing")
	}
	if strings.Count(svg, `r="26"`) != 4 {
		t.Fatalf("want 4 seats")
	}
	img := WheelImage("wheel", slots, "4 GNOT", "Putaran 2 / 4")
	if !strings.HasPrefix(img, "![wheel](data:image/svg+xml;base64,") {
		t.Fatalf("bad markdown image: %.60s", img)
	}
	if empty := Wheel(nil, "0 GNOT", ""); !strings.Contains(empty, "no members yet") {
		t.Fatalf("empty wheel should say so")
	}
}

package arisan

import (
	"encoding/base64"
	"html"
	"math"
	"strconv"
	"strings"
)

// SlotState is the state of one member seat on the arisan wheel.
type SlotState int

const (
	SlotWaiting SlotState = iota // has not paid this round yet
	SlotPaid                     // paid this round, still waiting for a turn
	SlotWon                      // already received a pot in an earlier round
	SlotWinner                   // the member highlighted as latest winner
	SlotLate                     // has an unpaid debt (missed a round)
)

// Slot is one seat on the wheel. Label is drawn inside the seat (keep it to
// 1-3 characters, e.g. the join number); Caption is drawn under it.
type Slot struct {
	Label   string
	Caption string
	State   SlotState
}

type slotStyle struct{ fill, stroke, text string }

func styleOf(s SlotState) slotStyle {
	switch s {
	case SlotPaid:
		return slotStyle{"#2f9e6b", "#7ee2b0", "#ffffff"}
	case SlotWon:
		return slotStyle{"#8a6d1f", "#e8c25a", "#fff6d8"}
	case SlotWinner:
		return slotStyle{"#f2b632", "#fff1b8", "#3a2a00"}
	case SlotLate:
		return slotStyle{"#9e2f3c", "#f08a97", "#ffffff"}
	}
	return slotStyle{"#3a3330", "#8c7f77", "#e9e1da"}
}

// Wheel draws the circle as an SVG: one seat per member around a ring, with
// title (e.g. the pot) and subtitle (e.g. "Putaran 2 / 5") in the middle and a
// colour legend underneath. It returns raw SVG markup.
func Wheel(slots []Slot, title, subtitle string) string {
	const (
		cx, cy = 210, 215
		ring   = 150.0
		seatR  = 26
	)
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="420" height="470" viewBox="0 0 420 470" font-family="Inter,Segoe UI,Helvetica,Arial,sans-serif">`)
	b.WriteString(`<defs><radialGradient id="bg" cx="50%" cy="45%" r="70%"><stop offset="0" stop-color="#3b2a20"/><stop offset="1" stop-color="#17110d"/></radialGradient>`)
	b.WriteString(`<radialGradient id="pot" cx="50%" cy="40%" r="60%"><stop offset="0" stop-color="#fbe3a1"/><stop offset="1" stop-color="#c8902a"/></radialGradient></defs>`)
	b.WriteString(`<rect x="0" y="0" width="420" height="470" rx="22" fill="url(#bg)"/>`)
	// ring
	b.WriteString(`<circle cx="210" cy="215" r="150" fill="none" stroke="#6b5444" stroke-width="2" stroke-dasharray="4 6"/>`)
	// pot in the middle
	b.WriteString(`<circle cx="210" cy="215" r="78" fill="url(#pot)" stroke="#fff1c4" stroke-width="3"/>`)
	b.WriteString(`<text x="210" y="208" text-anchor="middle" font-size="20" font-weight="700" fill="#3a2600">` + esc(clip(title, 16)) + `</text>`)
	b.WriteString(`<text x="210" y="234" text-anchor="middle" font-size="13" fill="#5a3d08">` + esc(clip(subtitle, 22)) + `</text>`)

	n := len(slots)
	for i, s := range slots {
		ang := -math.Pi/2 + 2*math.Pi*float64(i)/float64(max1(n))
		x := cx + int(math.Round(ring*math.Cos(ang)))
		y := cy + int(math.Round(ring*math.Sin(ang)))
		st := styleOf(s.State)
		if s.State == SlotWinner {
			b.WriteString(`<circle cx="` + itoa(x) + `" cy="` + itoa(y) + `" r="36" fill="#f2b632" opacity="0.28"/>`)
		}
		b.WriteString(`<circle cx="` + itoa(x) + `" cy="` + itoa(y) + `" r="` + itoa(seatR) + `" fill="` + st.fill + `" stroke="` + st.stroke + `" stroke-width="3"/>`)
		b.WriteString(`<text x="` + itoa(x) + `" y="` + itoa(y+6) + `" text-anchor="middle" font-size="17" font-weight="700" fill="` + st.text + `">` + esc(clip(s.Label, 3)) + `</text>`)
		if s.Caption != "" {
			ty := y + seatR + 15
			if y < cy-75 {
				ty = y - seatR - 7 // top seats: caption above
			}
			b.WriteString(`<text x="` + itoa(x) + `" y="` + itoa(ty) + `" text-anchor="middle" font-size="11" fill="#e9dccf">` + esc(clip(s.Caption, 14)) + `</text>`)
		}
	}
	if n == 0 {
		b.WriteString(`<text x="210" y="80" text-anchor="middle" font-size="13" fill="#e9dccf">no members yet</text>`)
	}
	// legend
	legend := []struct {
		st    SlotState
		label string
	}{{SlotWaiting, "belum bayar"}, {SlotPaid, "sudah bayar"}, {SlotWon, "sudah dapat"}, {SlotWinner, "pemenang"}, {SlotLate, "utang"}}
	// lay the legend out from the label widths (~6px per char at 11px)
	total := 0
	for _, l := range legend {
		total += 18 + 6*len(l.label) + 6
	}
	lx := (420 - total) / 2
	for _, l := range legend {
		st := styleOf(l.st)
		b.WriteString(`<circle cx="` + itoa(lx+7) + `" cy="440" r="7" fill="` + st.fill + `" stroke="` + st.stroke + `" stroke-width="2"/>`)
		b.WriteString(`<text x="` + itoa(lx+17) + `" y="444" font-size="10" fill="#e9dccf">` + l.label + `</text>`)
		lx += 18 + 6*len(l.label) + 6
	}
	b.WriteString(`</svg>`)
	return b.String()
}

// WheelImage wraps Wheel in a markdown image with an SVG data URI, which
// gnoweb renders inline.
func WheelImage(alt string, slots []Slot, title, subtitle string) string {
	svg := Wheel(slots, title, subtitle)
	return "![" + strings.ReplaceAll(alt, "]", "") + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg)) + ")"
}

func itoa(i int) string { return strconv.Itoa(i) }

func max1(n int) int {
	if n < 1 {
		return 1
	}
	return n
}

func esc(s string) string { return html.EscapeString(s) }

// clip cuts s to at most n runes, adding an ellipsis when it had to cut.
func clip(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	if n <= 1 {
		return string(r[:n])
	}
	return string(r[:n-1]) + "…"
}

// Package arisanku is a trustless arisan (rotating savings circle, ROSCA) on
// Gno.land.
//
// An arisan is how millions of Indonesians save together: a group agrees on a
// fixed contribution (iuran), every round each member pays in, and one member
// who has not won yet takes the whole pot home. After N rounds every one of
// the N members has received the pot exactly once.
//
// Off-chain, an arisan runs on trust in the organiser (bandar) who holds the
// cash and "shakes the jar" (kocok). ArisanKu replaces the bandar with a realm:
//
//   - the realm holds each round's pot and pays the winner in the same tx
//     that decides the round, so nobody can run away with it;
//   - the winner is chosen by a public rule: Giliran (fixed turns by join
//     order) or Kocok (a draw from entropy mixed by every payment);
//   - a member who misses a payment does not stall the circle: after the
//     deadline the round is decided anyway, the missed contribution becomes a
//     public debt (utang) owed directly to that round's winner, and the
//     debtor cannot win until it is settled;
//   - every member builds a portable reputation (on-time, late, missed,
//     settled) that any circle can read before letting someone in.
//
// Lifecycle: CreateCircle -> Join ... (auto-start when full, or Start) ->
// each round: Pay by every member -> Draw -> ... -> Finished.
package arisanku

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y/arisan/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	denom = "ugnot"

	// MinContribution is the smallest iuran per member per round (0.1 GNOT).
	MinContribution int64 = 100_000
	// MaxContribution caps the iuran (1,000,000 GNOT) to keep pots sane.
	MaxContribution int64 = 1_000_000_000_000
	// MinMembers and MaxMembers bound the size of a circle.
	MinMembers = 2
	MaxMembers = 12
	// MinPeriodMinutes / MaxPeriodMinutes bound the length of a round.
	MinPeriodMinutes = 1
	MaxPeriodMinutes = 31 * 24 * 60

	maxNameLen = 40
	maxNickLen = 16
)

// Status of a circle.
type Status int

const (
	StatusOpen      Status = iota // recruiting members
	StatusRunning                 // rounds in progress
	StatusFinished                // every member received the pot once
	StatusCancelled               // cancelled by the creator before start
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusRunning:
		return "running"
	case StatusFinished:
		return "finished"
	case StatusCancelled:
		return "cancelled"
	}
	return "unknown"
}

// Member is one seat in a circle.
type Member struct {
	Addr      address
	Nick      string
	JoinedAt  time.Time
	WonRound  int  // 0 = not won yet
	Paid      bool // paid in the current round
	OpenDebts int  // unsettled debts in this circle
}

// RoundResult is the public record of one decided round.
type RoundResult struct {
	Round    int
	Winner   address // empty when the round was rolled over
	Pot      int64
	Payers   int
	Missed   []address
	Refunded bool // nobody was eligible: payers were refunded, round repeats
	At       time.Time
	Height   int64
}

// Circle is one arisan group.
type Circle struct {
	ID           int
	Name         string
	Creator      address
	Contribution int64 // ugnot per member per round
	Size         int   // target number of members (= number of rounds)
	Period       time.Duration
	Mode         arisan.Mode
	Status       Status
	Members      []*Member
	CreatedAt    time.Time
	Round        int // current round, 1-based, 0 before start
	Deadline     time.Time
	Held         int64 // ugnot paid in for the current round, held by the realm
	Entropy      []byte
	History      []RoundResult
}

// Debt is a missed contribution, owed by Debtor directly to Creditor (the
// winner of the round that was missed).
type Debt struct {
	ID        int
	CircleID  int
	Round     int
	Debtor    address
	Creditor  address
	Amount    int64
	Settled   bool
	SettledBy address
	SettledAt time.Time
}

// Reputation is a member's track record across every circle.
type Reputation struct {
	Circles     int   // circles joined
	OnTime      int   // payments before the deadline
	Late        int   // payments after the deadline (before the draw)
	Missed      int   // rounds decided without their payment
	Settled     int   // debts settled
	Wins        int   // pots received
	Contributed int64 // ugnot paid into pots and debts
	Received    int64 // ugnot received from pots and debts
}

var (
	circles      avl.Tree // padID -> *Circle
	debts        avl.Tree // padID -> *Debt
	reps         avl.Tree // address string -> *Reputation
	memberships  avl.Tree // address string -> []int (circle ids)
	nextCircleID int
	nextDebtID   int
	totalPaidOut int64
	totalRounds  int
)

// ---------------------------------------------------------------------------
// Crossing (transaction) functions

// CreateCircle starts a new arisan and seats the caller as its first member.
//
//   - name: circle name (letters, digits, spaces and - _ . , ' & ! only)
//   - nickname: how you appear on the wheel (optional, same charset)
//   - contribution: iuran per member per round in GNOT, e.g. "1" or "0.5"
//   - members: circle size, 2..12 (also the number of rounds)
//   - periodMinutes: length of each round (1 minute .. 31 days)
//   - mode: "giliran" (fixed turns) or "kocok" (random draw)
//
// It returns the new circle id.
func CreateCircle(cur realm, name, nickname, contribution string, members, periodMinutes int, mode string) int {
	caller := callerOf(cur)

	name = strings.TrimSpace(name)
	mustValidText("name", name, 1, maxNameLen)
	nickname = strings.TrimSpace(nickname)
	mustValidText("nickname", nickname, 0, maxNickLen)
	amount, err := parseGNOT(contribution)
	if err != "" {
		panic("invalid contribution: " + err)
	}
	if amount < MinContribution || amount > MaxContribution {
		panic("contribution must be between " + arisan.FormatGNOT(MinContribution) + " and " + arisan.FormatGNOT(MaxContribution))
	}
	if members < MinMembers || members > MaxMembers {
		panic(ufmt.Sprintf("members must be between %d and %d", MinMembers, MaxMembers))
	}
	if periodMinutes < MinPeriodMinutes || periodMinutes > MaxPeriodMinutes {
		panic(ufmt.Sprintf("periodMinutes must be between %d and %d", MinPeriodMinutes, MaxPeriodMinutes))
	}
	m, ok := arisan.ParseMode(mode)
	if !ok {
		panic(`mode must be "giliran" or "kocok"`)
	}

	nextCircleID++
	now := time.Now()
	c := &Circle{
		ID:           nextCircleID,
		Name:         name,
		Creator:      caller,
		Contribution: amount,
		Size:         members,
		Period:       time.Duration(periodMinutes) * time.Minute,
		Mode:         m,
		Status:       StatusOpen,
		CreatedAt:    now,
	}
	c.Entropy = arisan.MixEntropy(nil, "arisanku", strconv.Itoa(c.ID), caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10))
	circles.Set(padID(c.ID), c)
	c.addMember(caller, nickname, now)

	chain.Emit("CircleCreated", "id", strconv.Itoa(c.ID), "creator", caller.String(), "contribution", strconv.FormatInt(amount, 10), "members", strconv.Itoa(members), "mode", m.String())
	return c.ID
}

// Join takes a seat in an open circle. The circle starts automatically when
// the last seat is taken.
func Join(cur realm, circleID int, nickname string) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("circle is not open for new members")
	}
	if c.memberIndex(caller) >= 0 {
		panic("you are already a member of this circle")
	}
	if len(c.Members) >= c.Size {
		panic("circle is full")
	}
	nickname = strings.TrimSpace(nickname)
	mustValidText("nickname", nickname, 0, maxNickLen)

	now := time.Now()
	c.addMember(caller, nickname, now)
	c.Entropy = arisan.MixEntropy(c.Entropy, "join", caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10))
	chain.Emit("Joined", "id", strconv.Itoa(c.ID), "member", caller.String())
	if len(c.Members) == c.Size {
		c.start(now)
	}
}

// Leave gives up a seat in a circle that has not started. The creator cannot
// leave; use Cancel instead.
func Leave(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("can only leave a circle before it starts")
	}
	if caller == c.Creator {
		panic("the creator cannot leave; cancel the circle instead")
	}
	i := c.memberIndex(caller)
	if i < 0 {
		panic("you are not a member of this circle")
	}
	c.Members = append(c.Members[:i], c.Members[i+1:]...)
	removeMembership(caller, c.ID)
	rep := repOf(caller)
	rep.Circles--
	chain.Emit("Left", "id", strconv.Itoa(c.ID), "member", caller.String())
}

// Start begins a circle early with the members it has (at least 2). Only the
// creator can start it. The circle size shrinks to the current member count.
func Start(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("circle is not open")
	}
	if caller != c.Creator {
		panic("only the creator can start the circle")
	}
	if len(c.Members) < MinMembers {
		panic(ufmt.Sprintf("need at least %d members to start", MinMembers))
	}
	c.Size = len(c.Members)
	c.start(time.Now())
}

// Cancel closes an open circle before it starts. No funds are held before
// the start, so nothing needs refunding. Only the creator can cancel.
func Cancel(cur realm, circleID int) {
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusOpen {
		panic("only an open circle can be cancelled")
	}
	if caller != c.Creator {
		panic("only the creator can cancel the circle")
	}
	c.Status = StatusCancelled
	chain.Emit("Cancelled", "id", strconv.Itoa(c.ID))
}

// Pay deposits your contribution for the current round. Attach exactly the
// circle's iuran, e.g. `-send 1000000ugnot` for 1 GNOT.
//
// It must be called directly by a user (gnokey maketx call / a wallet): coins
// sent through an intermediate realm or a `maketx run` script are rejected,
// because only then is OriginSend guaranteed to have reached this realm.
func Pay(cur realm, circleID int) {
	// The two guards below are a pair (see docs: effective-gno, "Verifying
	// inbound Coin payments"): IsUserCall guarantees the -send coins landed
	// on this realm, and the amount check verifies how much.
	if !cur.Previous().IsUserCall() {
		panic("Pay must be called directly by a user (maketx call)")
	}
	caller := callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusRunning {
		panic("circle is not running")
	}
	i := c.memberIndex(caller)
	if i < 0 {
		panic("you are not a member of this circle")
	}
	m := c.Members[i]
	if m.Paid {
		panic("you already paid this round")
	}
	mustReceiveExactly(c.Contribution)

	now := time.Now()
	m.Paid = true
	c.Held += c.Contribution
	c.Entropy = arisan.MixEntropy(c.Entropy, "pay", caller.String(), strconv.FormatInt(runtime.ChainHeight(), 10), strconv.FormatInt(now.UnixNano(), 10))
	rep := repOf(caller)
	rep.Contributed += c.Contribution
	late := now.After(c.Deadline)
	if late {
		rep.Late++
	} else {
		rep.OnTime++
	}
	chain.Emit("Paid", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round), "member", caller.String(), "late", strconv.FormatBool(late))
}

// Draw decides the current round and pays the pot to its winner. Anyone can
// call it once every member has paid, or once the round deadline has passed.
//
// Eligible winners are members who paid this round, have not won before and
// have no unsettled debt in this circle. Members who did not pay get a debt
// owed to the winner. If nobody is eligible, every payer is refunded and the
// round is repeated with a new deadline. It returns the winner's address
// (empty if the round was rolled over).
func Draw(cur realm, circleID int) address {
	callerOf(cur)
	c := mustCircle(circleID)
	if c.Status != StatusRunning {
		panic("circle is not running")
	}
	now := time.Now()
	if !c.allPaid() && !now.After(c.Deadline) {
		panic("round is still open: wait until everyone paid or the deadline passed")
	}

	height := runtime.ChainHeight()
	seed := arisan.MixEntropy(c.Entropy, "draw", strconv.Itoa(c.Round), strconv.FormatInt(height, 10), strconv.FormatInt(now.UnixNano(), 10))
	c.Entropy = seed

	var candidates []int
	var payers []int
	var missed []address
	for i, m := range c.Members {
		if m.Paid {
			payers = append(payers, i)
			if m.WonRound == 0 && m.OpenDebts == 0 {
				candidates = append(candidates, i)
			}
		} else {
			missed = append(missed, m.Addr)
		}
	}

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()

	if len(candidates) == 0 {
		// Nobody can take the pot: give everyone their money back and repeat.
		for _, i := range payers {
			bk.SendCoins(self, c.Members[i].Addr, coins(c.Contribution))
			repOf(c.Members[i].Addr).Contributed -= c.Contribution
		}
		for _, a := range missed {
			repOf(a).Missed++
		}
		c.History = append(c.History, RoundResult{Round: c.Round, Pot: c.Held, Payers: len(payers), Missed: missed, Refunded: true, At: now, Height: height})
		c.resetRound(now)
		chain.Emit("RoundRolledOver", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round))
		return ""
	}

	wi := arisan.PickWinner(c.Mode, candidates, seed)
	winner := c.Members[wi]
	pot := c.Held
	winner.WonRound = c.Round
	bk.SendCoins(self, winner.Addr, coins(pot))
	wrep := repOf(winner.Addr)
	wrep.Wins++
	wrep.Received += pot
	totalPaidOut += pot
	totalRounds++

	for _, a := range missed {
		nextDebtID++
		d := &Debt{ID: nextDebtID, CircleID: c.ID, Round: c.Round, Debtor: a, Creditor: winner.Addr, Amount: c.Contribution}
		debts.Set(padID(d.ID), d)
		c.Members[c.memberIndex(a)].OpenDebts++
		repOf(a).Missed++
		chain.Emit("DebtRecorded", "debt", strconv.Itoa(d.ID), "id", strconv.Itoa(c.ID), "debtor", a.String(), "creditor", winner.Addr.String())
	}

	c.History = append(c.History, RoundResult{Round: c.Round, Winner: winner.Addr, Pot: pot, Payers: len(payers), Missed: missed, At: now, Height: height})
	chain.Emit("Drawn", "id", strconv.Itoa(c.ID), "round", strconv.Itoa(c.Round), "winner", winner.Addr.String(), "pot", strconv.FormatInt(pot, 10))

	if c.winners() == len(c.Members) {
		c.Status = StatusFinished
		c.Held = 0
		for _, m := range c.Members {
			m.Paid = false
		}
		chain.Emit("Finished", "id", strconv.Itoa(c.ID))
		return winner.Addr
	}
	c.Round++
	c.resetRound(now)
	return winner.Addr
}

// PayDebt settles a debt. Attach exactly the debt amount; it is forwarded to
// the creditor in the same transaction. Anyone may settle a debt on the
// debtor's behalf (family often does), the debtor gets the credit.
func PayDebt(cur realm, debtID int) {
	// Paired payment guards, see Pay.
	if !cur.Previous().IsUserCall() {
		panic("PayDebt must be called directly by a user (maketx call)")
	}
	caller := callerOf(cur)
	v := debts.Get(padID(debtID))
	if v == nil {
		panic("debt not found")
	}
	d := v.(*Debt)
	if d.Settled {
		panic("debt already settled")
	}
	mustReceiveExactly(d.Amount)

	d.Settled = true
	d.SettledBy = caller
	d.SettledAt = time.Now()
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), d.Creditor, coins(d.Amount))

	if c := getCircle(d.CircleID); c != nil {
		if i := c.memberIndex(d.Debtor); i >= 0 && c.Members[i].OpenDebts > 0 {
			c.Members[i].OpenDebts--
		}
	}
	drep := repOf(d.Debtor)
	drep.Settled++
	repOf(caller).Contributed += d.Amount
	repOf(d.Creditor).Received += d.Amount
	chain.Emit("DebtSettled", "debt", strconv.Itoa(d.ID), "by", caller.String())
}

// ---------------------------------------------------------------------------
// Read-only helpers (safe to call with vm/qeval; return copies only)

// CircleCount returns how many circles were ever created.
func CircleCount() int { return nextCircleID }

// TotalPaidOut returns the ugnot paid to winners across all circles.
func TotalPaidOut() int64 { return totalPaidOut }

// TrustScore returns a 0..100 score for an address from its track record.
// New members start at 50.
func TrustScore(addr address) int {
	v := reps.Get(addr.String())
	if v == nil {
		return 50
	}
	return scoreOf(v.(*Reputation))
}

// CircleJSON returns a JSON summary of a circle for wallets, bots and
// frontends. It returns "null" if the circle does not exist.
func CircleJSON(circleID int) string {
	c := getCircle(circleID)
	if c == nil {
		return "null"
	}
	var b strings.Builder
	b.WriteString("{")
	b.WriteString(`"id":` + strconv.Itoa(c.ID))
	b.WriteString(`,"name":` + strconv.Quote(c.Name))
	b.WriteString(`,"status":` + strconv.Quote(c.Status.String()))
	b.WriteString(`,"mode":` + strconv.Quote(c.Mode.String()))
	b.WriteString(`,"creator":` + strconv.Quote(c.Creator.String()))
	b.WriteString(`,"contribution_ugnot":` + strconv.FormatInt(c.Contribution, 10))
	b.WriteString(`,"size":` + strconv.Itoa(c.Size))
	b.WriteString(`,"round":` + strconv.Itoa(c.Round))
	b.WriteString(`,"held_ugnot":` + strconv.FormatInt(c.Held, 10))
	b.WriteString(`,"period_seconds":` + strconv.FormatInt(int64(c.Period/time.Second), 10))
	if c.Status == StatusRunning {
		b.WriteString(`,"deadline_unix":` + strconv.FormatInt(c.Deadline.Unix(), 10))
	}
	b.WriteString(`,"members":[`)
	for i, m := range c.Members {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"address":` + strconv.Quote(m.Addr.String()) + `,"nick":` + strconv.Quote(m.Nick) + `,"paid":` + strconv.FormatBool(m.Paid) + `,"won_round":` + strconv.Itoa(m.WonRound) + `,"open_debts":` + strconv.Itoa(m.OpenDebts) + `}`)
	}
	b.WriteString("]}")
	return b.String()
}

// ---------------------------------------------------------------------------
// internals

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return cur.Previous().Address()
}

// mustReceiveExactly checks the coins attached to the transaction. Callers
// MUST have asserted cur.Previous().IsUserCall() first.
func mustReceiveExactly(amount int64) {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent.AmountOf(denom) != amount {
		panic("attach exactly " + strconv.FormatInt(amount, 10) + denom + " (" + arisan.FormatGNOT(amount) + "), got " + sent.String())
	}
}

func coins(amount int64) chain.Coins {
	return chain.Coins{chain.NewCoin(denom, amount)}
}

func padID(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func getCircle(id int) *Circle {
	v := circles.Get(padID(id))
	if v == nil {
		return nil
	}
	return v.(*Circle)
}

func mustCircle(id int) *Circle {
	c := getCircle(id)
	if c == nil {
		panic("circle " + strconv.Itoa(id) + " not found")
	}
	return c
}

func repOf(a address) *Reputation {
	v := reps.Get(a.String())
	if v != nil {
		return v.(*Reputation)
	}
	r := &Reputation{}
	reps.Set(a.String(), r)
	return r
}

func scoreOf(r *Reputation) int {
	s := 50 + 5*r.OnTime + 2*r.Late + 4*r.Settled - 15*r.Missed
	if s < 0 {
		s = 0
	}
	if s > 100 {
		s = 100
	}
	return s
}

func addMembership(a address, id int) {
	var ids []int
	if v := memberships.Get(a.String()); v != nil {
		ids = v.([]int)
	}
	ids = append(ids, id)
	memberships.Set(a.String(), ids)
}

func removeMembership(a address, id int) {
	v := memberships.Get(a.String())
	if v == nil {
		return
	}
	ids := v.([]int)
	out := make([]int, 0, len(ids))
	for _, x := range ids {
		if x != id {
			out = append(out, x)
		}
	}
	memberships.Set(a.String(), out)
}

func (c *Circle) addMember(a address, nick string, now time.Time) {
	c.Members = append(c.Members, &Member{Addr: a, Nick: nick, JoinedAt: now})
	addMembership(a, c.ID)
	repOf(a).Circles++
}

func (c *Circle) memberIndex(a address) int {
	for i, m := range c.Members {
		if m.Addr == a {
			return i
		}
	}
	return -1
}

func (c *Circle) start(now time.Time) {
	c.Status = StatusRunning
	c.Round = 1
	c.Deadline = now.Add(c.Period)
	chain.Emit("Started", "id", strconv.Itoa(c.ID), "members", strconv.Itoa(len(c.Members)))
}

func (c *Circle) resetRound(now time.Time) {
	for _, m := range c.Members {
		m.Paid = false
	}
	c.Held = 0
	c.Deadline = now.Add(c.Period)
}

func (c *Circle) allPaid() bool {
	for _, m := range c.Members {
		if !m.Paid {
			return false
		}
	}
	return len(c.Members) > 0
}

func (c *Circle) paidCount() int {
	n := 0
	for _, m := range c.Members {
		if m.Paid {
			n++
		}
	}
	return n
}

func (c *Circle) winners() int {
	n := 0
	for _, m := range c.Members {
		if m.WonRound > 0 {
			n++
		}
	}
	return n
}

// mustValidText keeps user text safe to embed in markdown and SVG: a short
// whitelist instead of escaping every renderer's syntax.
func mustValidText(field, s string, min, max int) {
	n := len([]rune(s))
	if n < min || n > max {
		panic(ufmt.Sprintf("%s must be %d to %d characters", field, min, max))
	}
	for _, r := range s {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.' || r == ',' || r == '\'' || r == '&' || r == '!'
		if !ok {
			panic(field + " may only use letters, digits, spaces and - _ . , ' & !")
		}
	}
}

// parseGNOT parses a decimal GNOT amount ("1", "0.5", "2.000001") into ugnot.
// It returns a non-empty error string on failure.
func parseGNOT(s string) (int64, string) {
	s = strings.TrimSpace(s)
	s = strings.TrimSuffix(strings.TrimSuffix(s, "GNOT"), "gnot")
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, "empty amount"
	}
	whole, frac := s, ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	if whole == "" {
		whole = "0"
	}
	if len(frac) > 6 {
		return 0, "at most 6 decimals"
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, "not a number"
		}
	}
	if len(whole) > 9 {
		return 0, "too large"
	}
	for len(frac) < 6 {
		frac += "0"
	}
	w, _ := strconv.ParseInt(whole, 10, 64)
	f, _ := strconv.ParseInt(frac, 10, 64)
	return w*1_000_000 + f, ""
}

package arisanku

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g19py87s5zn89dm6h2xy7q6la27ckza7f3jdw56y/arisan/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render serves the gnoweb UI.
//
//	""                 home: stats, open / running / finished circles
//	"circle/{id}"      one circle: wheel, actions, members, history, debts
//	"member/{address}" a member's reputation and circles
//	"new"              form to start a circle
//	"how"              how arisan and ArisanKu work (EN + ID)
func Render(path string) string {
	path = strings.Trim(path, "/")
	if i := strings.IndexByte(path, '?'); i >= 0 {
		path = path[:i]
	}
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case parts[0] == "circle" && len(parts) == 2:
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return renderNotFound()
		}
		return renderCircle(id)
	case parts[0] == "member" && len(parts) == 2:
		return renderMember(address(parts[1]))
	case path == "new":
		return renderNew()
	case path == "how":
		return renderHow()
	}
	return renderNotFound()
}

func realmPath() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func link(sub string) string {
	if sub == "" {
		return realmPath()
	}
	return realmPath() + ":" + sub
}

func header(b *strings.Builder) {
	b.WriteString("# 🫙 ArisanKu\n")
	b.WriteString("*Arisan tanpa bandar — trustless rotating savings circles on Gno.land*\n\n")
	b.WriteString("[Home](" + link("") + ") · [Start a circle](" + link("new") + ") · [How it works](" + link("how") + ")\n\n")
}

func renderHome() string {
	var b strings.Builder
	header(&b)

	var open, running, done []*Circle
	members := 0
	circles.ReverseIterate("", "", func(_ string, v any) bool {
		c := v.(*Circle)
		switch c.Status {
		case StatusOpen:
			open = append(open, c)
		case StatusRunning:
			running = append(running, c)
		case StatusFinished:
			done = append(done, c)
		}
		if c.Status != StatusCancelled {
			members += len(c.Members)
		}
		return false
	})

	b.WriteString("<gno-columns>\n")
	stat(&b, strconv.Itoa(nextCircleID), "circles created")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(reps.Size()), "unique members")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(totalRounds), "rounds decided")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, arisan.FormatGNOT(totalPaidOut), "paid to winners")
	b.WriteString("</gno-columns>\n\n")

	b.WriteString("> [!TIP] What is arisan?\n")
	b.WriteString("> A group agrees on a fixed contribution. Every round everyone pays in and one member takes the whole pot home, until each member has won once. Here the realm holds the pot, picks the winner by a public rule and pays out instantly — no organiser to trust.\n\n")
	b.WriteString(`<gno-button href="` + link("new") + `" label="Start a circle" variant="success" /> <gno-button href="` + link("how") + `" label="How it works" variant="outline" />` + "\n\n")

	b.WriteString("## 🟢 Open circles — join now\n\n")
	if len(open) == 0 {
		b.WriteString("*No circle is recruiting right now. [Start one](" + link("new") + ").*\n\n")
	} else {
		b.WriteString("| Circle | Iuran / round | Mode | Seats | |\n|---|---|---|---|---|\n")
		for _, c := range open {
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %s | %s %d/%d | [Join](%s) |\n",
				c.Name, link("circle/"+strconv.Itoa(c.ID)), arisan.FormatGNOT(c.Contribution), c.Mode.Label(),
				arisan.ProgressBar(len(c.Members), c.Size, 6), len(c.Members), c.Size,
				txlink.NewLink("Join").AddArgs("circleID", strconv.Itoa(c.ID), "nickname", "").URL()))
		}
		b.WriteString("\n")
	}

	b.WriteString("## 🔄 Running circles\n\n")
	if len(running) == 0 {
		b.WriteString("*None yet.*\n\n")
	} else {
		b.WriteString("| Circle | Pot | Round | Paid this round | Deadline |\n|---|---|---|---|---|\n")
		for _, c := range running {
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %d / %d | %s %d/%d | %s |\n",
				c.Name, link("circle/"+strconv.Itoa(c.ID)), arisan.FormatGNOT(c.Contribution*int64(len(c.Members))),
				c.Round, len(c.Members), arisan.ProgressBar(c.paidCount(), len(c.Members), 6), c.paidCount(), len(c.Members), relTime(c.Deadline)))
		}
		b.WriteString("\n")
	}

	if len(done) > 0 {
		b.WriteString("## 🏁 Finished circles\n\n")
		b.WriteString("| Circle | Members | Total paid out |\n|---|---|---|\n")
		for _, c := range done {
			var sum int64
			for _, h := range c.History {
				if !h.Refunded {
					sum += h.Pot
				}
			}
			b.WriteString(ufmt.Sprintf("| [%s](%s) | %d | %s |\n", c.Name, link("circle/"+strconv.Itoa(c.ID)), len(c.Members), arisan.FormatGNOT(sum)))
		}
		b.WriteString("\n")
	}

	footer(&b)
	return b.String()
}

func stat(b *strings.Builder, value, label string) {
	b.WriteString("<gno-frame>\n\n### " + value + "\n" + label + "\n\n</gno-frame>\n")
}

func renderCircle(id int) string {
	c := getCircle(id)
	if c == nil {
		return renderNotFound()
	}
	var b strings.Builder
	header(&b)
	idS := strconv.Itoa(c.ID)
	pot := c.Contribution * int64(len(c.Members))
	if c.Status == StatusOpen {
		pot = c.Contribution * int64(c.Size)
	}

	b.WriteString("## " + c.Name + "  " + statusBadge(c.Status) + "\n\n")

	// wheel + facts side by side
	slots := make([]arisan.Slot, 0, len(c.Members))
	var lastWinner address
	if n := len(c.History); n > 0 {
		lastWinner = c.History[n-1].Winner
	}
	for i, m := range c.Members {
		st := arisan.SlotWaiting
		switch {
		case m.OpenDebts > 0:
			st = arisan.SlotLate
		case m.Addr == lastWinner && m.WonRound > 0:
			st = arisan.SlotWinner
		case m.WonRound > 0:
			st = arisan.SlotWon
		case m.Paid:
			st = arisan.SlotPaid
		}
		slots = append(slots, arisan.Slot{Label: strconv.Itoa(i + 1), Caption: displayName(m), State: st})
	}
	sub := "recruiting " + strconv.Itoa(len(c.Members)) + "/" + strconv.Itoa(c.Size)
	switch c.Status {
	case StatusRunning:
		sub = "Putaran " + strconv.Itoa(c.Round) + " / " + strconv.Itoa(len(c.Members))
	case StatusFinished:
		sub = "selesai · finished"
	case StatusCancelled:
		sub = "cancelled"
	}

	b.WriteString("<gno-columns>\n")
	b.WriteString(arisan.WheelImage("Arisan wheel of "+c.Name, slots, arisan.FormatGNOT(pot), sub) + "\n")
	b.WriteString("<gno-columns-sep>\n\n")
	b.WriteString("| Circle | Details |\n|---|---|\n")
	b.WriteString("| **Iuran** (per member, per round) | " + arisan.FormatGNOT(c.Contribution) + " |\n")
	b.WriteString("| **Pot** (paid to each winner) | " + arisan.FormatGNOT(pot) + " |\n")
	b.WriteString("| **Mode** | " + c.Mode.Label() + " |\n")
	b.WriteString("| **Members** | " + strconv.Itoa(len(c.Members)) + " / " + strconv.Itoa(c.Size) + " |\n")
	b.WriteString("| **Round length** | " + durStr(c.Period) + " |\n")
	if c.Status == StatusRunning {
		b.WriteString("| **Round** | " + strconv.Itoa(c.Round) + " of " + strconv.Itoa(len(c.Members)) + " |\n")
		b.WriteString("| **Paid this round** | " + arisan.ProgressBar(c.paidCount(), len(c.Members), 8) + " " + strconv.Itoa(c.paidCount()) + "/" + strconv.Itoa(len(c.Members)) + " |\n")
		b.WriteString("| **Held in realm** | " + arisan.FormatGNOT(c.Held) + " |\n")
		b.WriteString("| **Deadline** | " + c.Deadline.UTC().Format("02 Jan 2006 15:04 UTC") + " (" + relTime(c.Deadline) + ") |\n")
	}
	b.WriteString("| **Created by** | " + addrLink(c.Creator) + " |\n")
	b.WriteString("\n</gno-columns>\n\n")

	// actions
	b.WriteString("### Actions\n\n")
	switch c.Status {
	case StatusOpen:
		b.WriteString(`<gno-button href="` + txlink.NewLink("Join").AddArgs("circleID", idS, "nickname", "").URL() + `" label="Join this circle" variant="success" />`)
		if len(c.Members) >= MinMembers {
			b.WriteString(` <gno-button href="` + txlink.NewLink("Start").AddArgs("circleID", idS).URL() + `" label="Start now (creator)" variant="outline" />`)
		}
		b.WriteString(` <gno-button href="` + txlink.NewLink("Cancel").AddArgs("circleID", idS).URL() + `" label="Cancel (creator)" variant="caution outline" />` + "\n\n")
		b.WriteString("*The circle starts by itself when the last seat is taken. Share this page to invite friends.*\n\n")
	case StatusRunning:
		send := strconv.FormatInt(c.Contribution, 10) + denom
		b.WriteString(`<gno-button href="` + txlink.NewLink("Pay").AddArgs("circleID", idS).SetSend(send).URL() + `" label="Pay ` + arisan.FormatGNOT(c.Contribution) + `" variant="success" />`)
		ready := c.allPaid() || time.Now().After(c.Deadline)
		if ready {
			b.WriteString(` <gno-button href="` + txlink.NewLink("Draw").AddArgs("circleID", idS).URL() + `" label="🎲 Draw round ` + strconv.Itoa(c.Round) + `" variant="warning" />` + "\n\n")
			b.WriteString("> [!SUCCESS] Ready to draw\n> " + readyReason(c) + " Anyone can call **Draw** to decide the round and pay the winner.\n\n")
		} else {
			b.WriteString("\n\n> [!NOTE] Waiting for payments\n> " + strconv.Itoa(len(c.Members)-c.paidCount()) + " member(s) still need to pay. Draw opens when everyone has paid or at the deadline (" + relTime(c.Deadline) + ").\n\n")
		}
	case StatusFinished:
		b.WriteString("> [!SUCCESS] Arisan complete\n> Every member received the pot once. Terima kasih semuanya!\n\n")
	case StatusCancelled:
		b.WriteString("> [!CAUTION] This circle was cancelled before it started. No funds were held.\n\n")
	}

	// members
	b.WriteString("### Members\n\n| # | Member | Trust | This round | Won |\n|---|---|---|---|---|\n")
	for i, m := range c.Members {
		paid := "⏳ unpaid"
		if c.Status != StatusRunning {
			paid = "—"
		} else if m.Paid {
			paid = "✅ paid"
		}
		won := "—"
		if m.WonRound > 0 {
			won = "🏆 round " + strconv.Itoa(m.WonRound)
		}
		if m.OpenDebts > 0 {
			won += " · ⚠️ " + strconv.Itoa(m.OpenDebts) + " debt"
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | %s |\n", i+1, memberCell(m), trustCell(m.Addr), paid, won))
	}
	b.WriteString("\n")

	// history
	if len(c.History) > 0 {
		b.WriteString("### Round history\n\n| Round | Winner | Pot | Paid | Missed | Block |\n|---|---|---|---|---|---|\n")
		for i := len(c.History) - 1; i >= 0; i-- {
			h := c.History[i]
			winner := "↩️ rolled over, payers refunded"
			if !h.Refunded {
				winner = "🏆 " + nameOf(c, h.Winner)
			}
			missed := "—"
			if len(h.Missed) > 0 {
				names := make([]string, 0, len(h.Missed))
				for _, a := range h.Missed {
					names = append(names, nameOf(c, a))
				}
				missed = strings.Join(names, ", ")
			}
			b.WriteString(ufmt.Sprintf("| %d | %s | %s | %d/%d | %s | #%d |\n", h.Round, winner, arisan.FormatGNOT(h.Pot), h.Payers, len(c.Members), missed, h.Height))
		}
		b.WriteString("\n")
	}

	// debts
	var rows []string
	debts.Iterate("", "", func(_ string, v any) bool {
		d := v.(*Debt)
		if d.CircleID != c.ID {
			return false
		}
		state := `<gno-button href="` + txlink.NewLink("PayDebt").AddArgs("debtID", strconv.Itoa(d.ID)).SetSend(strconv.FormatInt(d.Amount, 10)+denom).URL() + `" label="Settle" variant="warning outline" />`
		if d.Settled {
			state = "✅ settled"
		}
		rows = append(rows, ufmt.Sprintf("| %d | %d | %s | %s | %s | %s |", d.ID, d.Round, nameOf(c, d.Debtor), nameOf(c, d.Creditor), arisan.FormatGNOT(d.Amount), state))
		return false
	})
	if len(rows) > 0 {
		b.WriteString("### Utang (debts)\n\nA missed payment is owed directly to the winner of that round. Members with open debts cannot win until they settle.\n\n")
		b.WriteString("| Debt | Round | Debtor | Owed to | Amount | |\n|---|---|---|---|---|---|\n")
		b.WriteString(strings.Join(rows, "\n") + "\n\n")
	}

	if c.Mode == arisan.ModeKocok {
		b.WriteString("> [!NOTE]- How the kocok draw works\n> Every join and payment is folded into a SHA-256 seed together with its block height and time; the draw adds its own height and time. The winner is `candidates[seed mod n]` among members who paid, have not won and have no debt. It is auditable and nobody controls it alone, but it is not a VRF: for high stakes use Giliran mode.\n\n")
	}
	b.WriteString("*Machine-readable: `CircleJSON(" + idS + ")`*\n\n")
	footer(&b)
	return b.String()
}

func readyReason(c *Circle) string {
	if c.allPaid() {
		return "Everyone has paid."
	}
	return "The deadline has passed; unpaid members will owe the winner."
}

func renderMember(a address) string {
	var b strings.Builder
	header(&b)
	if !a.IsValid() {
		b.WriteString("Invalid address.\n")
		return b.String()
	}
	b.WriteString("## 👤 " + arisan.ShortAddr(a.String()) + "\n\n`" + a.String() + "`\n\n")
	var r Reputation
	if v := reps.Get(a.String()); v != nil {
		r = *(v.(*Reputation))
	}
	score := TrustScore(a)
	b.WriteString("<gno-columns>\n")
	stat(&b, strconv.Itoa(score)+"/100", "trust score · skor amanah")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(r.OnTime)+" / "+strconv.Itoa(r.Late)+" / "+strconv.Itoa(r.Missed), "on time / late / missed")
	b.WriteString("<gno-columns-sep>\n")
	stat(&b, strconv.Itoa(r.Wins), "pots received")
	b.WriteString("</gno-columns>\n\n")
	b.WriteString("| Track record | |\n|---|---|\n")
	b.WriteString("| Circles joined | " + strconv.Itoa(r.Circles) + " |\n")
	b.WriteString("| Debts settled | " + strconv.Itoa(r.Settled) + " |\n")
	b.WriteString("| Contributed | " + arisan.FormatGNOT(r.Contributed) + " |\n")
	b.WriteString("| Received | " + arisan.FormatGNOT(r.Received) + " |\n\n")
	b.WriteString("*Score: starts at 50; +5 per on-time payment, +2 per late payment, +4 per settled debt, −15 per missed round (0–100).*\n\n")

	if v := memberships.Get(a.String()); v != nil {
		ids := v.([]int)
		if len(ids) > 0 {
			b.WriteString("### Circles\n\n| Circle | Status | Iuran |\n|---|---|---|\n")
			for i := len(ids) - 1; i >= 0; i-- {
				if c := getCircle(ids[i]); c != nil {
					b.WriteString("| [" + c.Name + "](" + link("circle/"+strconv.Itoa(c.ID)) + ") | " + statusBadge(c.Status) + " | " + arisan.FormatGNOT(c.Contribution) + " |\n")
				}
			}
			b.WriteString("\n")
		}
	}
	var open []string
	debts.Iterate("", "", func(_ string, v any) bool {
		d := v.(*Debt)
		if d.Debtor == a && !d.Settled {
			open = append(open, ufmt.Sprintf("| %d | [circle %d](%s) | %s | [Settle](%s) |", d.ID, d.CircleID, link("circle/"+strconv.Itoa(d.CircleID)), arisan.FormatGNOT(d.Amount),
				txlink.NewLink("PayDebt").AddArgs("debtID", strconv.Itoa(d.ID)).SetSend(strconv.FormatInt(d.Amount, 10)+denom).URL()))
		}
		return false
	})
	if len(open) > 0 {
		b.WriteString("### Open debts\n\n| Debt | Circle | Amount | |\n|---|---|---|---|\n" + strings.Join(open, "\n") + "\n\n")
	}
	footer(&b)
	return b.String()
}

